INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (14, 7, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=yVCQInkZhTo', '2026-04-19', 'हे कुन्तीपुत्र! रागरूपी रजोगुणलाई तिमी कामना र आसक्तिबाट उत्पन्न भएको भन्ने जान । यसले कर्म र कर्मफलप्रतिको आसक्तिद्वारा जीवात्मालाई बाँध्दछ अर्थात् जन्ममरणको चक्करमा पार्दछ ।
14.7 writeup
14.8
तमस्त्वज्ञानजं विद्धि, मोहनं(म्) सर्वदेहिनाम् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (14, 8, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=yVCQInkZhTo', '2026-04-19', 'हे भारत! सम्पूर्ण देहधारीहरूलाई मोहमा पार्ने तमोगुणलाई त तिमी अज्ञानबाट उत्पन्न भएको भन्ने जान । यसले प्रमाद, आलस्य र निद्राद्वारा जीवात्मालाई बाँध्दछ ।
यी तीन गुण हुन्- सत्त्वगुण, रजोगुण र तमोगुण । तमोगुणबाट आलस्य आउँछ । त्यसबाट निद्रा लाग्छ । धेरैजना निदाउनै सक्दैनन् । उनीहरूले निद्राको औषधि लिनुपर्छ । तपाईँहरूले प्राणायाम सुरु गर्नुभयो भने तपाईँको योगशक्ति बढ्न थाल्छ । तपाईँको शरीरको अक्सिजन स्तर स्वाभाविक रूपमा बढ्छ । त्यसैले योगीहरूलाई राति धेरै निन्द्राको आवश्यकता पर्दैन । उनीहरू बिहान चाँडै उठ्छन् किनकि उनीहरूको आराम, शरीरको विश्राम, स्नायुहरूको पुनर्गठन जस्ता क्रियाहरू थोरै समयमा सम्भव हुन्छ किनकि उनीहरू योगी हुन्, योगमार्गमा हिँडेका छन् । तर जसले कुनै योगाभ्यास गर्दैन, जसलाई यथोचित निन्द्रा लाग्दैन भने यसको अर्थ ऊ तनावमा छ । एक योगी र चिन्तित मनुष्यलाई निन्द्रा लाग्दैन । जसको मष्तिष्कमा निरन्तर केही न केही चलिरहन्छ, जसको दिमाग एक ठाउँमा केन्द्रित हुन सक्दैन, उसको एकाग्रता हराइसकेको हुन्छ । यो एकाग्रता हराउनुका विभिन्न कारणहरू छन् । आजको युगमा यसको सबैभन्दा ठूलो कारण हाम्रो मोबाइल फोन हो । हामी मोबाइल हेर्दा-हेर्दै रातको निन्द्रा बिगार्छौं । जसले हाम्रो ध्यानको क्षमता वा कुनै विषयमा केन्द्रित हुन सक्ने क्षमता घटाउँदछ ।
दस वर्षअघि एउटा विद्यालयका प्रधानाध्यापकले भने, “हामीले यहाँ आफ्ना विद्यार्थीहरूलाई पुस्तक र नोटबुकको सट्टा ट्याबलेट उपलब्ध गराएर नयाँ प्रणाली लागू गरेका छौँ” । त्यो प्रणाली उचित नभएको प्रतिक्रिया आउँदा समेत प्रधानाध्यापक यसमा कदापि सहमत भएनन् । पुस्तक-कापी बन्द गर्ने निर्णयको परिणाम स्वरूप तीन-चार वर्षमै त्यो विद्यालय नै बन्द भयो । यसको कारण नै अत्याधिक प्रबिधिको प्रयोग देखिन पुग्यो । विद्यार्थीहरूलाई ट्याबलेट दिइएपछि उनीहरूको स्क्रिन हेर्ने समय धेरै बढ्यो, जसले गर्दा विद्यार्थीहरूमा तनाव निकै बढ्यो । बच्चाहरूको स्क्रिन हेर्ने बानीले गर्दा दिमागमा दबाव बढ्ने र कार्यक्षमता घट्न पुग्यो । जीवनमा तनाव बढाउने विभिन्न कारणहरूमध्ये एक प्रमुख कारण हाम्रो स्क्रिन टाइम पनि हो । खासगरी बच्चाहरूलाई दिनभरिमा २० मिनेटभन्दा बढी मोबाइल हेर्न दिनुहुँदैन र हामीले पनि यसको समय कम गर्नुपर्छ नत्र हाम्रो जीवनशैली धराशायी हुनसक्छ । यसको कारण हाम्रो खानपिनको तरिका बदलिएको छ, हाम्रो निन्द्रा पनि बिग्रिएको छ । यी सबै कुराहरूको प्रत्यक्ष असर हरेक गतिविधिमा पर्दछ । भगवान्‌ले यो कुरा धेरै स्पष्ट रूपमा भन्नुभएको छ ।
युक्ताहारविहारस्य युक्तचेष्टस्य कर्मसु ।
युक्तस्वप्नावबोधस्य योगो भवति दुःखहा ।।
युक्त आहार, युक्त विहार, युक्त चेष्टा
र
कर्मसु
। आहार र विहार सँगै हाम्रो कर्म पनि सन्तुलित हुनुपर्छ । हामीले आठ घण्टा काम गर्ने र आठ घण्टा सुत्नुपर्छ ।
युक्त स्वप्ना वबोधस्य
- स्वप्न भनेको निन्द्रा अवस्था र बोध भनेको जागृत अवस्था । २४ घण्टामा आठ घण्टा हामीले राम्रोसँग सुत्नुपर्छ । यो अत्यन्त आवश्यक छ । यदि हामी निदाएनौँ भने हाम्रो जीवनमा तनाव बढ्न थाल्छ र निन्द्रा नपुग्नाले विभिन्न प्रकारका रोगहरू लाग्दछन् । जसले आफ्नो आहारलाई ठीक गर्‍यो, जसले आफ्नो विहार अर्थात् व्यायामलाई ठीक गर्‍यो, जसले आफ्नो कामलाई ठीक गर्‍यो, त्यसको स्वास्थ्य पनि ठिक हुन जान्छ । त्यसका लागि कामका आठ घण्टा, आराम आठ घण्टा र आठ घण्टामा आफ्नो उन्नयनका लागि केही प्रयास गर्नुपर्छ । बिहान एक घण्टा योगासन र प्राणायाम गर्नुहोस् । यो अत्यन्त आवश्यक हुन्छ । तमोगुणबाट निन्द्रा आउँछ । त्यसैले तमोगुण पनि मानव जीवनमा महत्त्वपूर्ण छ । हामी केवल भगवान्‌का सन्तान मात्र होइनौँ, हामी प्रकृतिका पनि पुत्र हौँ ।
ममैवांशो जीवलोके
- जीव भनेको भगवान्‌ वा परमात्माको अंश हो । यसले परमात्माको अंशको रूपमा प्रत्येक जीवमा वास गर्दछ र शरीर पञ्चमहाभूतबाट बनेको हो ।
अहं बीजप्रदः पिता
- म बीज प्रदान गर्ने पिता हुँ । यो प्रकृतिबाट प्राप्त शरीर जड छ तर गुणहरूले भरिएको छ । यी अन्तर्निहित समवायी छन् ।
योगो भवति दुःखहा
- योगमा आश्रित पुरूषले दुःखबाट मुक्ति पाउँछ ।
हामी भित्र विशुद्ध आत्मा भए पनि प्रकृतिबाट प्राप्त गुणको केही अंश शरीरमा नभएसम्म जीवन सम्भव छैन । तमोगुण धेरै बढ्यो भने हामी कुम्भकर्णजस्तै हुन्छौँ । सन्तुलन नै जीवन हो । कुम्भकर्ण छ महिनासम्म सुत्थ्यो । यो अत्यधिक तमोगुणी अवस्था हो ।
केही मानिस रावणजस्तो रजोगुणी हुन्छन् । पैसा कमाउने दौडमा जीवनका अन्य महत्वपूर्ण कुरा बिर्सिरहेका हुन्छन् । तपाईँहरू भाग्यशाली हुनुहुन्छ कि गीता मार्गमा आउनुभएको छ र दैनिक ४० मिनेट भएपनि जीवनलाई समग्र रूपमा बुझ्न समय निकाल्दै हुनुहुन्छ । रावणसँग मन्दोदरीजस्ती सुन्दरी पत्नी भए पनि उसले सीतालाई अपहरण गर्‍यो । यो रजोगुणको प्रभाव हो । रजोगुण बढ्दा मानिस सन्तुष्ट हुँदैन, उसलाई अझै चाहिन्छ । उसले कुबेरको पुष्पक विमान समेत खोस्यो । अत्यन्त शक्तिशाली, विद्वान्, संगीतज्ञ, वेदज्ञ रावणले शिवताण्डवस्तोत्र रचना गरेका थियो ।
अखर्व (अगर्व) सर्वमंगला कला कदम्ब मञ्जरी,
रस प्रवाह माधुरी विज्र्म्भणामधुव्र्तम।
स्मरान्तकं पुरान्तकं भवान्तकं मखान्तकं,
गजान्तकान्धकान्तकंतमन्तकान्तकं भजे ।।
जयत्वदभ्र्विभ्र्मभ्रमद्भुजन्गमश्वस,
द्विनिर्गमतक्रमस्फूरत्करालभालहव्यवाट ।
धिमिद्धिमिद्धिमिध्वनन्मृद्दंगतुंगमंगल,
ध्वनिक्रमप्रवर्तित प्रचण्डताण्डव: शिव: ।।
ज्ञानी र तपस्वी भएर पनि रजोगुणका कारण उसलाई संसारका सबै राम्रा चीज उसैलाई चाहिन्थ्यो । रावण भगवान्‌ महादेवका भक्त थिए । उनलाई चन्द्रहाँस नामको खड्ग वरदानस्वरूप प्राप्त थियो तर पनि रजोगुणका कारण उनको पतन भयो । कुम्भकर्ण तमोगुणको प्रतीक, रावण रजोगुणको प्रतीक र विभीषण सत्त्वगुणको प्रतीक हुन् । विभीषणले आफ्नो दाजुको गलत काम सहन सकेनन् र रामको शरणमा गए । सत्त्वगुणको प्रभावले मानिस सात्त्विक बन्छ । भगवान्‌ले भन्नुभयो,
