INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 44, 'ŚRĪ SRINIVAS WARNEKAR JI', 'https://www.youtube.com/watch?v=1Q34sE1YjQ0', '2026-03-29', 'यसकारण, हे प्रभो! म आफ्नो शरीर झुकाएर साष्टाङ्ग प्रणाम गर्दै स्तुति गर्नयोग्य परमेश्वर हजुरको प्रसन्नताको लागि प्रार्थना गर्दछु । हे देव! पिताले जसरी पुत्रको, मित्रले जसरी मित्रको र पतिले जसरी पत्नीको अपराधलाई क्षमा गर्दछन्, त्यसैगरी हजुरले पनि मद्वारा गरिएका गल्ती र अपराधहरूलाई अवश्य क्षमा गरिदिनुहुने छ ।
सन्त ज्ञानेश्वर महाराजले यस भावको निकै सुन्दर वर्णन गर्नुभएको छ । अर्जुनले भगवान्‌सँग मित्रवत् व्यवहार गरे, जसलाई ज्ञानेश्वर महाराजले भन्नुभएको छ- “हामीसँग अमृत थियो, तर हामीले त्यसको महत्त्व नबुझेर आँगन धुनका लागि पानी जस्तै प्रयोग गर्यौँ । हामीले पारसमणि पायौँ, तर त्यसलाई ढुङ्गा सम्झेर बाटोको जगमा हाल्यौँ” । अर्जुन भन्दछन्, “हे परमब्रह्म! तपाईँलाई मैले रथ हाँक्न लगाएर सारथि बनाएँ, यो मेरो अज्ञानता थियो । म तपाईँको चरण छोएर कसम खान्छु, यी सबै कुरा मैले नजानेरै गरेको हुँ” ।
यति भन्दै अर्जुनले भगवान्‌को पाउँमा दण्डवत् प्रणाम गरे । प्रणामका विभिन्न प्रकार भए पनि आफ्नो सम्पूर्ण शरीरलाई एउटा लौरो समान भुईँमा सुताएर पूर्ण शरणागति भावमा गरिने दण्डवत् प्रणाम नै सबैभन्दा उच्च मानिन्छ । अर्जुन भन्दछन्, “हे
ईड्य!
अर्थात् स्तुति गर्न योग्य प्रभु! तपाईँ मसँग प्रसन्न हुनुहोस् । जसरी पिताले आफ्नो पुत्रको गल्ती सहन्छन्, साथीले साथीको अपराधलाई क्षमा गर्छन् र प्रेमीले आफ्नो प्रियतमाका साना-तिना कुराहरूलाई सहन्छन्, त्यसरी नै तपाईँ पनि मेरा समस्त अपराधहरूलाई सहन गरिदिनुहोस्” ।
यस श्लोकमा तीन प्रकारका भक्ति भावहरू समाहित छन् : १.
लालन भाव
: पिताले पुत्रलाई गर्ने स्नेह र क्षमा । २.
सख्य भाव
: एक मित्रले अर्को मित्रप्रति राख्ने उदारता । ३.
माधुर्य भाव
: प्रेमी र प्रेमिका बीचको सहिष्णुता र प्रेम ।
ज्ञानेश्वर महाराज भन्नुहुन्छ कि अर्जुनको यो विनतीमा कति धेरै विनम्रता छ! उनी भन्दछन्, “प्रभु! तपाईँसँग बोल्ने मेरो योग्यता त छैन, तर बालकले पितासँग जिद्दी गरेझैँ म तपाईँसँग क्षमा मागिरहेको छु” । अर्जुनले आफूलाई भगवान्‌को शरणमा पूर्ण रूपमा सुम्पिएका छन् । मैले तपाईँको महिमालाई नचिनिकन जुन व्यवहार गरेँ, त्यसका लागि मलाई क्षमा गरिदिनुहोस् भन्दै अर्जुनले बारम्बार प्रार्थना गरे ।
प्रश्नोत्तर
प्रश्नकर्ता
:- आदर्श दाजु ।
प्रश्न:-
अर्जुनले विश्वरूप दर्शन गर्दा भीष्म र द्रोणजस्ता सबै महारथी भगवान्‌को दाँतले पिसिएको देखे तर अभिमन्युलाई किन देखेनन्?
उत्तर:-
अर्जुनलाई युद्ध जितिन्छ भनी विश्वास दिलाउनु छ र यस्ता लीला भगवान्‌ले रचना गर्नुभएको हो । यहाँ भगवान्‌लाई को कहाँ छ र के गर्दै छ भन्ने स्पष्ट थाहा छ, सर्वत्र उहाँले देखिरहनुभएको छ । त्यसैले अर्जुनको मनमा अब लडाइँ लड्नुपर्छ र यी सबै ईश्वरीय कार्य हुन् भन्ने भावना विकास गराउन उहाँले हरतरहका दृष्य रचना गर्नुभएको हो ।
प्रति प्रश्न:-
हामी अर्जुनको भूमिकामा रहेमा यी सबै कुरा गर्न सक्छौँ त?
उत्तर:-
यदि हामी पनि अर्जुनजस्तै भूमिकामा रह्यौँ भने हामीले अर्जुनजस्तै शिष्यको रूपमा रहेर काम गर्नुपर्छ । हामीले सबै कर्म भगवान्‌ले अह्राएको सम्झेर र भगवान्‌को काम सम्झेर गर्नुपर्छ । हामी सबै काम कुशलतापूर्वक गर्न सक्छौँ ।
प्रश्नकर्ता:-
कमला दिदी ।
प्रश्न:-
गीता पढेकोमा मेरो घरका परिवार सबैले राम्रो कर्म गरेको भनेर भन्नुहुन्छ । तर आफैँ उहाँहरू पढ्ने रहर गर्नुहुन्न । किन होला, मैले उहाँहरूलाई कक्षामा जोड्न सकिरहेको छैन?
उत्तर:-
भगवान्‌ले अह्राएपछि र समय आएपछि उहाँहरू पनि आफैँ पढ्न थाल्नुहुन्छ । तपाईँ हामीले चाहेर मात्र हुँदैन, भगवान्‌ले नै चाहनुपर्छ ।
प्रश्नकर्ता:-
रमेश दाजु ।
प्रश्न:-
यसै अध्यायको श्लोक चालीसमा दृष्टि र व्यवहार फरक-फरक हो भनिएको छ, ती के-के हुन्? फेरि प्रस्ट पारिदिन आग्रह गर्दछु ।
उत्तर :
दृष्टि सबैमा समान हुनुपर्छ र व्यवहार हरेक जीव र व्यक्तिमा फरक-फरक हुन्छ । अध्याय पाँचको श्लोक १८ अनुसार :
विद्याविनयसम्पन्ने ब्राह्मणे गवि हस्तिनि । शुनि चैव श्वपाके च पण्डिताः समदर्शिनः ॥
ब्राह्मण, गाई, हात्ती र कुकुर सबैमा परमात्मा भएको देख्नु दृष्टि हो तर यी सबै जीवप्रति गरिने व्यवहार फरक-फरक हुन्छ । जस्तो एउटी आमाका दुई छोरा हुन्छन्, उनीहरू प्रति आमाको समान माया वा दृष्टि हुन्छ । तर उनीहरूले खाने कुराको चाहना अलग हुन्छ र सोही अनुसार उनले ती छोराहरूमा व्यवहार गर्छिन् । यो व्यवहार पक्षपातपूर्ण होइन, उनीहरूको इच्छाअनुसार हो ।
अन्तमा, हनुमान चालीसा भजन गायन सहित एघारौँ अध्यायको चौथो खण्डको विवेचन समापन गरियो ।
यो विवेचन पढेर तपाईँलाई अवश्य पनि राम्रो लाग्यो होला भन्ने हामीलाई विश्वास लागेको छ । कृपया तल दिएको लिङ्क प्रयोग गरी हामीलाई आफ्नो प्रतिक्रियाहरू दिनुहोला ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (9, 11, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=ryMjm7vTwPU', '2026-03-29', '“परम भाव नजान्ने मूर्ख मान्छेहरू मनुष्य शरीर धारण गर्ने म वा सम्पूर्ण भूतहरूको महेश्वरलाई सामान्य मनुष्य ठान्छन्” । यो स्वाभाविक पनि हो । हामी मनुष्यको रुपमा जन्मिएकाले भगवान्‌लाई पनि मनुष्य रूपमै देख्छौँ, त्यसैले हरेक देवता र भगवान्‌लाई मनुष्य रूपमा देख्न चाह्यौँ र मूर्तिहरू बनायौँ । यो एउटा अवलम्बन हो । अन्तिम गन्तव्यसम्म पुग्ने साधन हो । साधनको पनि महत्त्व छ, तर साधनमै अड्किनु हुँदैन । काठमाडौँबाट बढीमालिका पुग्नु छ, मर्सिडिजमा बसेर यात्रा गर्दैछौँ, कुनै कुनै बेला हिडेर पनि जान्छौ, सुन्दर दृश्य देखेर त्यहीँ रोकियौँ भने बढिमालिका कहिल्यै पुगिँदैन । साधन साध्य हुँदैन र अन्ततः साधन छाड्नैपर्छ ।
मूर्तिपूजा साधन हो । मुकुट धारण गरेका, पीताम्बर लगाएका, हातमा मुरली समाएका, पाउमा पाउजु बाँधेका, गहुँगोरा र नीलो रङको त्यस मूर्तिमा हाम्रो मन रम्छ । शृङ्गार गर्दा आनन्द आउँछ । त्यो पनि साधन हो । अन्ततः त्यो परमतत्त्व बुझ्नु आवश्यक छ ।
अहं बीजप्रदः पिता
- भगवान्‌ भन्नुहुन्छ म बीज प्रदान गर्ने पिता हुँ । त्यस पुरुषोत्तमलाई, त्यस परमपितालाई हामीले बुझेनौँ वा दुई हात दुई खुट्टा भएको मानिस ठान्यौँ । अर्जुनले पनि यस्तै ठाने, तर भगवान्‌ले अर्जुनलाई त्यो साध्यसम्म पुर्‍याउने भूमिका यहीँ आरम्भ गर्नुभयो । दशौँ अध्यायमा विभूतिहरू बताउनुहुनेछ । एघारौँ अध्यायमा आफ्नो विराट विश्वरूप प्रत्यक्ष देखाउनुहुनेछ । अर्जुन ठिक त्यस्तो ठाउँमा उभिएका छन्, जहाँबाट एउटा मात्र छलाङ मार्नु बाँकि छ ।
हामी कहिलेकाहीँ मूर्तिमै अड्किन्छौँ । मुरलीमनोहरको भजन गर्ने मान्छेलाई गोवर्धन गिरिधारी मन पर्दैन । स्वामी समर्थका पनि दुई पन्थ हुन्छन्: एउटामा उभिएका स्वामी र अर्कोमा बसेका स्वामी । उभिएका पन्थवालाहरू बसेका स्वामीको पूजा गर्दैनन् र बसेकाहरू उभिएकाको गर्दैनन् । स्वामी जिन्दगीभर उभिएर मात्र त बस्नुभएको थिएन, कहिले कहिँ त बस्नुभएकै थियो होला नि, तर दुई डुङ्गामा खुट्टा राखेर जान सकिँदैन । जसले अन्तिम गन्तव्य बुझ्यो, उसलाई कृष्ण पुजे पनि राम वा श्याम पुजे पनि सबै एकै हो । राम र श्याम बिच कुनै फरक छैन । भगवान्‌ यही भन्न चाहनुहुन्छ ।
हामीले भगवान्‌लाई मनुष्य रूप ठान्यौँ- जुन साँघुरो सोच हो । कमलपित्त रोग लाग्दा सबै पहेँलो देखिन्छ, ज्वरोमा मुख तितो भएपछि दूध पनि तितो हुन्छ । दूध तितो होइन, तर त्यस्तो बेला हाम्रो मुख तितो हुन्छ । मान्छे मोही पिएर अमृतको परिणाम चाहन्छ । पूर्व दिशामा हिँडेर पश्चिम पुग्न चाहेर सम्भव हुँदैन ।
9.12
मोघाशा मोघकर्माणो, मोघज्ञाना विचेतसः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (9, 12, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=ryMjm7vTwPU', '2026-03-29', 'व्यर्थ आशा, व्यर्थ कर्म र निष्फल ज्ञान भएका विक्षिप्त अज्ञानीजनहरूले आसुरी, राक्षसी र मोहिनी प्रकृतिको स्वभावलाई नै धारण गरिरहन्छन् ।
विवेचन-
व्यर्थ आशा, व्यर्थ कर्म र व्यर्थ ज्ञान भएका विक्षिप्त अज्ञानी मान्छेहरू मृगतृष्णाको पछि कस्तूरी मृग दौडिएझैँ राक्षसी-आसुरी-मोहिनी प्रकृति धारण गरिरहन्छन् र बदलिन चाहँदैनन् । मृगतृष्णा नाम गरेको कुनै चिज छैन, त्यो केवल एउटा आभास हो; क्षितिजमा बगेको पानीजस्तो देखिने भ्रम हो । मरुभूमिमा एउटा प्यासी मृग टाढाटाढासम्म हेर्छ, क्षितिजमा पानी बगेजस्तो देख्छ प्राप्तीको लागि दौडिन्छ, तर त्यहाँ केही हुँदैन । जति दौडिए पनि पानीको भ्रम झन् टाढा हुँदै जान्छ । माटोको घोडामा सवारी गर्न सकिँदैन । अन्धोको हातमा मोतीको दियो वा बाँदरको हातमा नरिवल परेझैँ तिनीहरू त्यसको स्वाद र सौन्दर्य बुझ्न सक्दैनन् । त्यसैगरी मूर्ख मान्छेहरूले
भागवत्तत्त्व
बुझ्दैनन् ।
कुनै एक रूपमा साधना गर्नु ठिकै हो, तर त्यो साधना पूरा भएपछि अझ एक कदम अगाडि बढ्नैपर्छ । अर्जुन ठिक त्यस्तो ठाउँमा छन्, जहाँबाट उनले एउटा मात्र कदम चाल्नु छ । सुरुमा उनी “मेरा-मेरा” भन्दै थिए - मेरा मान्छे, मेरा गुरु, मेरा दाजुभाइ, मेरा हजुरबुबा, मेरा ससुरा । दोस्रो अध्यायमा उनी ''म'' मा आए - उनीहरूलाई मार्दा मेरो के हुन्छ? त्यसपछि बिस्तारै उनी ''म र तँ'' मा आए र “हजुरले जे भन्नुहुन्छ, ठिक छ” भन्न थाले । तर अझै पनि ''म'' बाँकी थियो, त्यसैले उनले पूरा विश्वास गर्न सकिरहेका थिएनन् र प्रश्नमाथि प्रश्न गरिरहेका थिए । तर जीवनमा एक क्षण यस्तो आउँछ, जुन क्षण सारा मोह भङ्ग हुन्छ र कुनै प्रश्न बाँकी रहँदैन । जबसम्म ''म'' बाँकी रहन्छ, तबसम्म ''त्यो'' हुन सक्दैन । ''म'' को विसर्जन नभएसम्म त्यसको प्रकट हुँदैन ।
मोहित मान्छेहरू मोहिनीमा नै त्रस्त, व्यस्त र सन्तप्त रहन्छन् - उनीहरूले त्यस स्वरूपको वास्तविकता बुझ्दैनन् । भगवान्‌ चराचर सृष्टिमा व्याप्त हुनुहुन्छ- चरमा पनि र अचरमा पनि ।
एउटा कलेजको नयाँ छात्रावास बनाउन पर्ने थियो । जुन जमिनमा भवन निर्माण गर्नुपर्ने थियो, त्यहाँ एउटा बदामको रुख थियो । छात्रावास बनाउँदा त्यसलाई काट्नुपर्ने अवस्था आयो, तर आर्किटेक्टलाई रुख बचाउन निर्देशन दिइयो । भवन तीन फिट पछाडि बनाइयो, जसले गर्दा रुख बच्यो र छात्रावास निर्माण पनि सम्पन्न भयो ।
पाँच-सात वर्ष बितेपछि सरकारबाट त्यस भवनमा दुई तला थप्ने अनुदान आयो । निर्माणका क्रममा छत र त्यससँगै रहेको कौसी तोडियो । त्यस छात्रावासमा बस्ने एउटी युवती प्रतिदिन साँझ कौसीमा गएर लुगा सुकाउँथिन् । एक रात अँध्यारोमा माथि जाँदा उनलाई कौसी तोडिएको थाहै भएन । अँध्यारोमा केही नदेखिएकोले उनी लुगा राख्न जाँदा दुई तला माथिबाट सिधै तल खसिन् । तल त्यही बदामको रुख थियो र उनी त्यसैमा अड्किइन् । बदामको रुखका हाँगाहरू एकमुनि अर्को खुड्किलोजस्तै फैलिएका हुन्छन् । उनी माथिल्लो हाँगामा खसिन् र बिस्तारै सिँढीबाट झरेझैँ तल आइन् । एउटी छात्रा दुई तलाबाट खसिन् भन्ने खबर फैलिएपछि कलेजमा भइरहेको भजन सन्ध्याबाट डाक्टरसहित सबैजना दौडेर गए । डाक्टरले जाँच गर्दा शरीरको कुनै पनि भागमा कोतरिएको समेत थिएन । उनी बिल्कुल ठिक थिइन्, कुरा गरिरहेकी थिइन् र उनको नाडी एवं मुटुको धड्कन पनि सामान्य थियो । सबैले भगवान्‌लाई प्रणाम गर्दै भने, “भगवान्, तपाईँले बचाउनुभयो” । यदि त्यो रुख काटिएको भए आज के हुन्थ्यो, थाहा छैन ।
त्यस्तै, एउटा घरमा जामुनको रुख थियो । त्यसमा राम्रा र मिठा जामुन फल्थे, तर पाकेर धेरै तल खस्थे र कुहिन्थे । बाहिरको आँगन दुर्गन्धित र फोहोर हुने भएकाले सफा गर्न सधै हैरान भएर आमाले दुई-तीन पटक रुख काटिदिन भन्नुभयो । तर छोराले भने, “म रुख काट्दिनँ । यो हरित वृक्ष हो । हरित शब्दमा हर पनि छ र हरि पनि छ । हर र हरि दुवैको दर्शन हरित वृक्षमा हुन्छ । यो विष्णु पनि हो र शिव पनि हो” । उनले उल्टो छाताजस्तो जाली लगाए, जसले गर्दा जामुन जमिनमा खसेर फोहोर नहोस् र बिहान उठाएर खान मिलोस् । यसरी रुख सुरक्षित गरियो ।
केही समयपछि आमाको दुवै घुँडाको शल्यक्रिया भयो, जसले गर्दा उहाँलाई हिँड्न समस्या थियो । एक दिन उहाँ रुख छेउमा घुम्न जाँदा अचानक चक्कर आएर लड्न लाग्नुभयो । त्यही बेला उहाँले त्यसै रुखको हाँगा समाउनुभयो र लड्नु भएन । सबैजना दौडेर जाँदा आमाले भन्नुभयो, “यो रुख थियो र त बाँचेँ” । छोराले भने, “तपाईँले त यसलाई काट्न भन्नुभएको थियो, आज यसैले बचायो” ।
त्यो ईश्वरको साक्षात्कार हेर्नुहोस् ।
योगक्षेमं वहाम्यहम्-
एक पटक उहाँलाई प्रेम गर्नुभयो भने उहाँले
योगक्षेम
वहन गर्नुहुन्छ । त्यसैले प्रकृतिलाई प्रेम गर्न सिकौँ, किनभने
मयाध्यक्षेण प्रकृतिः सूयते सचराचरम्-
चराचर सृष्टिमा उहाँ व्याप्त हुनुहुन्छ र त्यसैको आश्रय लिएर भगवान्‌ मानव रूप धारण गर्नुहुन्छ ।
9.13
महात्मानस्तु मां(म्) पार्थ, दैवीं(म्) प्रकृतिमाश्रिताः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (9, 13, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=ryMjm7vTwPU', '2026-03-29', 'परन्तु हे पार्थ! दैवी प्रकृतिमा आश्रित महात्माजनले मलाई सम्पूर्ण प्राणीहरूको आदिस्थान (सनातन कारण) र अविनाशी अक्षरस्वरूप जानेर अनन्यमनले निरन्तर मेरो भजन गर्दछन् ।
विवेचन-
“जो अनन्य भावले मेरो भजन गर्छन् । दैवी प्रकृतिका महात्माहरू मलाई सबै भूतहरूको सनातन कारण ठान्छन् र मेरो अविनाशी अक्षर स्वरूपलाई जानेर अनन्य भावले मलाई भज्छन्” । जो दैवी प्रकृतिका महात्मा छन्, तिनीहरू यसरी भजन गर्दछन् । हामी महात्मा बन्न नसके पनि हामीमा पनि त्यही आत्मा छ, जसलाई हामीले दैवी बनाउन सक्छौँ । त्यसैले चराचर सृष्टिमा भगवान्‌लाई देख्ने प्रयास गरौँ ।
एक व्यापारी दैनिक आफ्नो पसलमा बसेर खाना खान्थ्यो । उसको भोजनको समयमा एउटा कुकुर खानाको आशामा त्यहाँ आउँथ्यो र व्यापारीले आफ्नो टिफिनबाट एक रोटी उसलाई दिन्थ्यो । कुकुरले पनि पुच्छर हल्लाएर आफ्नो आनन्द प्रकट गर्थ्यो । एक दिन बिहान व्यापारी पसलमा आउँदा ढोकाका ताल्चा फुटेका र शटर खोलेको देखियो । राति चोरहरू आएका रहेछन्, तर भित्रका सामान र नगद सबै सुरक्षित थिए । सिसिटिभी हेर्दा थाहा भयो कि ताल्चा फुटाउन थालेका चोरहरूलाई त्यही कुकुरले भुकेर र झम्टिएर भगाएको रहेछ । हामीले एक पैसा दिँदा त्यसको प्रतिफल स्वरूप दश लाख प्राप्त हुन्छ भन्ने भाव मनमा राख्नुपर्छ ।
हामीले सत्यलाई स्वीकार गर्नुपर्छ । अर्जुनले अहिले मानिरहेका छन्, तर अझै जानिसकेका छैनन् । मान्नु र जान्नुमा यही फरक छ: कानले सुन्दा मानिन्छ भने आँखाले देख्दा जानिन्छ । कृष्ण अर्जुनका घनिष्ठ मित्र पनि हुन्, जोसँग उनले बाल्यकालदेखि नै वनविहार, भोजन र शयन गरेका थिए । यस्तो निकटताका कारण उनले कृष्णलाई केवल सखा भावले मात्र देखेका छन् ;
भगवद्भाव
ले देखेका छैनन् । जबसम्म वास्तविकतालाई जानिँदैन, तबसम्म जीवनमा परिवर्तनकारी घटना घट्दैन । त्यसैले अर्जुनले यस तत्त्वलाई जानुन् भनी भगवान्‌ प्रयास गरिरहनुभएको छ ।
9.14
सततं(ङ्) कीर्तयन्तो मां(य्ँ), यतन्तश्च दृढव्रताः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (9, 14, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=ryMjm7vTwPU', '2026-03-29', 'ती दृढ निश्चयी भक्तजन निरन्तर मेरो नाम र गुणहरूको कीर्तन गर्दै तथा मेरो प्राप्‍तिका लागि यत्न गर्दै र मलाई बारम्बार प्रणाम गर्दै सदा मेरो ध्यानमा युक्त भएर अनन्य प्रेमले मेरो उपासना गर्दछन् ।
विवेचन- नित्ययुक्ता उपासते
- १२ औँ अध्यायमा पनि यही प्रसङ्ग आएको छ ।
परमतत्त्व
यति सस्तो विषय होइन र यो सजिलै प्राप्त हुँदैन । मीरा भन्छिन्,
पायो जी मैंने राम रतन धन पायो
। यसलाई पैसा खर्च गरेर पाउन सकिँदैन, यसका लागि त जीवन नै दाउमा लगाउनुपर्छ । मीराले आफ्नो जीवन दाउमा लगाइन् । उनलाई विषको प्याला दिइयो, तर उनले हाँस्दै पिइन् । उनी भित्रैदेखि यति पवित्र भइसकेकी थिइन् कि विषले पनि उनलाई केही गर्न सकेन । जब हामीभित्र परिवर्तन आउँछ र
भगवत्तत्त्व
मा पूर्ण समर्पण हुन्छ, तब विषको प्रभाव पनि शून्य हुन्छ । मीरा भक्तिमा लीन भई नाचिरहिन् ।
सतत कीर्तयन्तो मां
अर्थात् जो निरन्तर कीर्तन गर्छन् ।
यतन्तश्च दृढव्रताः
- कीर्तन पनि दृढ व्रतका साथ गर्नुपर्छ । शबरीले बाल्यकालदेखि वृद्धावस्थासम्म राम नाम लिइरहिन् । “राम! मेरा राम! मेरा राम! कहिले आउँछौ ?” भन्दै उनी प्रतीक्षा गरिरहन्थिन् । कहिलेकाहीँ उनलाई राम आएझैँ आभास हुन्थ्यो, तर जब राम वास्तविक रूपमै आए, तब उनलाई त्यो पनि आभास जस्तै लाग्यो । दौडेर ढोकातिर हेर्दा वास्तवमै राम र लक्ष्मण आएका थिए । उनी चरणमा परिन् र उनका आँखाबाट हर्षका आँसु बग्न थाले ।
हाम्रो पूजा गर्दाको ध्यान पनि प्रायः मोबाइलमा जान्छ । घण्टी बज्नेबित्तिकै हामी भगवान्‌लाई बिर्सन्छौँ ।
दृढ व्रत
यस्तो हुँदैन । भगवान्‌को पूजा गर्दा केवल भगवान्‌ र म हुनुपर्छ, जहाँ ‘म’ पनि हराएर केवल ‘तिमी’ मात्र बाँकी रहनुपर्छ ।
नमस्यन्तश्च मां भक्त्या
- यसरी नमस्कार गर्दै नित्ययुक्त भावमा रहनुपर्छ । हामी प्रायः सुविधा हुँदा वा दुःख पर्दा मात्र भगवान्‌लाई सम्झन्छौँ । हाम्रो प्रार्थना पनि मागले भरिएको हुन्छ र हामी भगवान्‌सँग व्यापार गर्छौँ । “भगवान्‌ यो काम गरिदिनुहोस्, म नरिवल चढाउँछु” भन्छौँ । के भगवान्‌लाई नरिवलको लोभ होला र? भगवान्‌कहाँ जानु भनेको त उहाँलाई धन्यवाद दिनु हो । “मेरो योग्यताभन्दा बढी दिनुभएको छ” भन्ने भावले नमस्कार गर्नुपर्छ । नमस्कारको अर्थ हृदय खोल्नु हो । हाम्रो हृदय मुट्ठी जत्रो हुन्छ, नमस्कार गर्दा त्यो मुट्ठी खोलिन्छ । “भगवान्‌ म आफ्नो हृदय खोल्दैछु, हजुरले पनि खोलिदिनुहोला ताकि हृदयसँग हृदय मिलोस्” भनी प्रार्थना गर्नुपर्छ । त्यसैले नै छातीको नजिक हात जोडिन्छ । यदि मनमा कुनै इच्छा छैन र केवल प्रेम छ भने भगवान्‌ दश कदम अघि बढेर तपाईँलाई अँगाल्न तयार हुनुहुन्छ । शबरी केवल एक कदम अघि बढिन्, तर भगवान्‌ले धेरै टाढाबाट आएर उनलाई दर्शन दिनुभएको थियो । कहिलेकाहीँ त लाग्छ, भगवान्‌ श्रीराम रावण मार्न होइन, बरु शबरीलाई भेट्न र अहिल्यालाई उद्धार गर्न आउनुभएको हो कि । रावण मार्न अरू पनि हुन सक्थे, तर भक्तलाई भेट्न भगवान्‌ आफैँ आउनुहुन्छ ।
केरालाका एक न्यायाधीशको कथा छ । एक साहूले भोला नामका नाविकमाथि मुद्दा हाले । भोलाले छोरीको विवाहका लागि ऋण लिएका थिए, तर साहूलाई फिर्ता गर्न सकेनन् । भोला सधैँ भन्थे, “मै क्या जानूँ? रघुनाथजी जाने” । उनी गाउँको रघुनाथ मन्दिरमा सधैँ जाने गर्थे । अदालतमा उनले आफूले ऋण तिरेको बयान दिए । न्यायाधीशले साक्षी माग्दा उनले भने, “रघुनाथजी हुनुहुन्छ” । अदालतले रघुनाथका नाममा पत्र पठायो । अर्को मितिमा एक वृद्ध अदालत आएर “म नै रघुनाथ हुँ” भनी बयान दिए र ऋण तिरेको रसिद पनि प्रस्तुत गरे । साहू लज्जित भए र ती वृद्ध अचानक गायब भए । न्यायाधीश मन्दिर गएर हेर्दा तिनै वृद्धको रूप मूर्तिमा देखे, जो अदालत आएका थिए । भगवान्‌ स्वयम्‌ आउनुभएको बुझेपछि उनले पश्चात्ताप गरे र जागिर छोडेर वृन्दावन गए । उनी जीवनभर मन्दिरबाहिर उभिएर प्रार्थना गरिरहे र अन्ततः एक सिद्ध पुरुष बने ।
सौतेनी आमाले ध्रुवलाई गरेको व्यवहारबाट निकाल्दा उनले एक स्थायी स्थानको इच्छा राखे । नारदमुनिले उनलाई
ॐ नमो भगवते वासुदेवाय
मन्त्र दिनुभयो । ध्रुवले कठोर तपस्या गरे; अन्न, जल र श्वास समेत रोके । यसले तीनै लोकमा हलचल पैदा गर्‍यो र भगवान्‌ गरुडमा सवार भएर आउनुभयो । उहाँले
दृढ निश्चयको नाम नै ध्रुव हो
भनी आशीर्वाद दिनुभयो । आज पनि ध्रुवतारा दिशादर्शकका रूपमा आकाशमा अटल छन् ।
सतत कीर्तयन्तो मां
- यदि हरेक सासमा भगवान्‌को नाम रह्यो भने उहाँको दर्शन कठिन छैन ।
9.15
ज्ञानयज्ञेन चाप्यन्ये, यजन्तो मामुपासते ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (9, 15, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=ryMjm7vTwPU', '2026-03-29', 'एकाथरी ज्ञानयोगीले म निर्गुण निराकार ब्रह्मलाई ज्ञानयज्ञद्वारा अभिन्नभावले पूजा गरेर मेरो उपासना पनि गर्दछन् भने अर्काथरी मानिस अनेक तरिकाले स्थित म सर्वतोमुख भएको विराटस्वरूप परमेश्वरको पृथक् भावले उपासना गर्दछन् ।
9.15 writeup
9.16
अहं(ङ्) क्रतुरहं(य्ँ) यज्ञः(स्), स्वधाहमहमौषधम् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (9, 16, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=ryMjm7vTwPU', '2026-03-29', 'क्रतु (वैदिक कर्म) मै हुँ, यज्ञ मै हुँ, स्वधा (श्राद्धमा पितृहरूलाई अर्पण गरिने अन्न) मै हुँ, औषधि (यज्ञमा चढाइने हवन सामग्री) मै हुँ, मन्त्र मै हुँ, हवनमा चढाइने आहूति- घिउ मै हुँ, अग्नि मै हुँ र हवनरूपी क्रिया पनि मै हुँ ।
9.16 writeup
9.17
पिताहमस्य जगतो, माता धाता पितामहः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (9, 17, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=ryMjm7vTwPU', '2026-03-29', 'यो सम्पूर्ण जगत्‌को धाता अर्थात् धारणकर्ता एवं कर्मफलको दाता अनि पिता, माता, पितामह मै हुँ र जान्नयोग्य पवित्र ॐकार, ऋग्वेद, सामवेद र यजुर्वेदमा पनि म नै छु ।
9.17 writeup
9.18
गतिर्भर्ता प्रभुः(स्) साक्षी, निवासः(श्) शरणं(म्) सुहृत् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (9, 18, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=ryMjm7vTwPU', '2026-03-29', 'प्राप्‍त हुनयोग्य परमधाम, भरणपोषण गर्ने, सबैका स्वामी, शुभाशुभ देख्ने, सबैका वासस्थान र शरण लिनयोग्य, प्रत्युपकारको चाहना नराखी हित गर्ने, उत्पत्ति-प्रलय-स्थिति सबैका आधार, निधान र अविनाशी कारण पनि मै हुँ ।
विवेचन-
भगवान्‌ नै यज्ञ, स्वधा, औषधी, मन्त्र, घृत, अग्नि र हवन हुनुहुन्छ । ऊहाँ नै जान्न योग्य
ॐकार, ऋग्वेद, सामवेद
र
यजुर्वेद
पनि हुनुहुन्छ । ऊहाँ नै सृष्टिको रचयिता माता, पिता, पितामह र अमृतदाता, पालनकर्ता, धारणकर्ता र विनाशकर्ता सहित सत्य र असत्य चारैतिर व्याप्त हुनुहुन्छ ।
9.19
तपाम्यहमहं(व्ँ) वर्षं(न्), निगृह्णाम्युत्सृजामि च ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (9, 19, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=ryMjm7vTwPU', '2026-03-29', 'मैले नै सूर्यको रूपमा ताप दिन्छु, पानीलाई ग्रहण गर्दछु र वर्षाको रूपमा बर्साउँछु । हे अर्जुन! म नै अमृत र मृत्यु हुँ तथा सत् (ननासिने) र असत् (नासिने) पनि म नै हुँ ।
9.19 writeup
9.20
त्रैविद्या मां(म्) सोमपाः(फ्) पूतपापा,
यज्ञैरिष्ट्वा स्वर्गतिं(म्) प्रार्थयन्ते ।
ते पुण्यमासाद्य सुरेन्द्रलोकम्,', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (9, 20, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=ryMjm7vTwPU', '2026-03-29', 'तीनै वेदहरूमा विधान गरिएका सकाम कर्महरूलाई गर्ने, सोमरस पिउने, पापरहित पुरुष मलाई यज्ञहरूमार्फत् पुजेर स्वर्गलाई प्राप्‍त गर्न चाहन्छन्, ती पुरुषले आफ्ना पुण्यका फलले स्वर्गलोकलाई प्राप्‍त गरी देवताहरूका अनेक दिव्य भोगहरूलाई भोग्दछन् ।
जो सोमपान गर्छन् यज्ञ गर्छन् स्वर्ग चाहन्छन् उनीहरू स्वर्ग पुग्छन्
9.21
ते तं(म्) भुक्त्वा स्वर्गलोकं(व्ँ) विशालं(ङ्),
क्षीणे पुण्ये मर्त्यलोकं(व्ँ) विशन्ति ।
एवं(न्) त्रयीधर्ममनुप्रपन्ना,', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (9, 21, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=ryMjm7vTwPU', '2026-03-29', 'तिनीहरू त्यस विशाल स्वर्गलोकलाई भोगेर पुण्य क्षीण भएपछि फेरि मृत्युलोक प्राप्‍त गर्दछन् । यसप्रकार, स्वर्गका साधनरूपी तीनै वेदहरूमा बताइएका सकाम कर्मको शरणमा परेकाहरू विषयभोगकै कामना गरिरहने हुँदा उनीहरू स्वर्गलोकमा जाने र मृत्युलोकमा आउने गरिरहन्छन् ।
﻿विवेचन-
तर पुण्य सकिएपछि फेरि मृत्युलोकमा आउँछन् ।
पुनरपि जननं पुनरपि मरणम्-
फेरि जन्म र फेरि मरण । यही चक्र चलिरहन्छ । जबसम्म यो चक्र चल्छ, तबसम्म दु:ख हुन्छ ।
यो विवेचन पढेर तपाईँलाई अवश्य पनि राम्रो लाग्यो होला भन्ने हामीलाई विश्वास लागेको छ । कृपया तल दिएको लिङ्क प्रयोग गरी हामीलाई आफ्नो प्रतिक्रियाहरू दिनुहोला ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (12, 11, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=CP7AS-GX7zs', '2026-03-28', 'मेरो प्राप्‍तिरूपी योगमा आश्रित भई उपरोक्त साधना गर्न पनि तिमी असमर्थ छौ भने, तिमीले मन-बुद्धि आदिमाथि विजय प्राप्‍त गर्ने बनेर सम्पूर्ण कर्मका फलहरूलाई त्याग गर ।
भ
गवान्‌ भन्नुहुन्छ– “यदि यो पनि कठिन छ र तिमी यो पनि गर्न असमर्थ छौ भने तिमी मेरो लागि कर्म गर, तर कर्म फलको अपेक्षा त्याग” ।
कर्मफलको अपेक्षा त्याग गर्नुको अर्थ फल प्राप्त हुँदैन भन्ने होइन । आँपको बीउ रोप्दा आँप फल्छ । आँप फल्न नि सक्छ, नफल्न नि सक्छ, धेरै फल्न नि सक्छ थोरै फल्न नि सक्छ तर फल मिले त राम्रो होला, र यदि मिलेन भने? त्यसैले फल प्राप्त नभए पनि मनमा कुनै असर नपर्ने, तर त्यो आँपको बोटप्रति भने प्रेमको अनुभूति पक्कै हुनुपर्छ । यति प्रयास त गर्नुहोस् !
सर्वकर्मफलत्यागं
तपाईँले फल त्याग गर्नुपर्छ, फलको अपेक्षा छोड्नुपर्छ । जब तपाईँ फलको आशाविना कर्म गर्नुहुन्छ, तब तपाईँ स्वतः नै भक्त बन्दै जानुहुनेछ । जब तपाईँ कुनै अपेक्षाविना नै कर्म गर्नुहुन्छ, तब तपाईँका लागि कठिन भनेको केही पनि हुनेछैन ।
यसपछि ‌भगवान्‌ले मन शान्त गर्ने विधि बताउनुभयो । यो मन बारम्बार उफ्रिन्छ, बारम्बार अशान्त हुन्छ र यसकारण निद्रा पनि लाग्दैन । यदि तपाईँले यो एउटा कुरा त्याग गर्नुभयो भने, तपाईँको मनमा पनि ठुलो शक्ति आउनेछ ।
12.12
श्रेयो हि ज्ञानमभ्यासाज्, ज्ञानाद्ध्यानं(व्ँ) विशिष्यते ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (12, 12, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=CP7AS-GX7zs', '2026-03-28', 'मर्म नबुझी गरिएका अभ्यासभन्दा ज्ञान श्रेष्ठ हुन्छ, ज्ञानभन्दा म परमेश्वर स्वरूपको ध्यान श्रेष्ठ हुन्छ र ध्यानभन्दा पनि सबै कर्महरूको फलको त्याग श्रेष्ठ हुन्छ, किनकि कर्मफल त्यागबाट नै तत्काल् परमशान्ति प्राप्‍त हुन्छ ।
भगवान्‌ भन्नुहुन्छ :
श्रेयो हि ज्ञानमभ्यासाज्-
मर्मलाई नजानी गरेको अभ्यासभन्दा ज्ञान श्रेष्ठ हुन्छ ।
ज्ञानाद्ध्यानं विशिष्यते-
त्यस ज्ञानभन्दा ध्यान श्रेष्ठ हुन्छ ।
ध्यानात्कर्मफलत्यागः
- ‌ ध्यानभन्दा पनि श्रेष्ठ कर्मफलको आसक्तिको त्याग गर्नु हो ।
ध्यानात्कर्मफलत्यागस्त्यागाच्छान्तिरनन्तरम्-
जतिबेला कर्मफलको इच्छा त्याग हु्छ, त्यतिबेला नै जीवनमा शान्तिले प्रवेश गर्नेछ ।
‌भगवान्‌ले यहाँ जीवनको सबैभन्दा ठुलो सूत्र प्रदान गर्नुभएको छ । यदि जीवनमा वास्तविक शान्ति चाहिन्छ भने कर्म-फलको इच्छा त्याग गर । हाम्रो जीवनमा व्याप्त सबै दुःख र अशान्तिको मूल कारण केवल अरूबाट या कर्मबाट गरिएको “अपेक्षा” नै हो ।
अपेक्षाको त्याग गरेलगत्तै तिमीले जीवनमा शान्तिको अनुभव गर्नेछौ । यदि तिमी फलको आशा छोड्छौ र त्यसपछि तिमीलाई केही प्राप्त हुन्छ भने, त्यसबेला प्राप्त हुने आनन्द अवर्णनीय हुनेछ । त्यसपश्चात् तिमी शान्ति नै शान्तिको अनुभूत गर्नेछौ र तिमीभित्र वास्तविक भक्तिभावको सञ्चार हुनेछ । जसै यो भक्तिभाव हृदयमा प्रवेश गर्छ, त्यो तिम्रो अनुहारमा, तिम्रो क्रियाकलापहरूमा, तिम्रो वाणीमा, तिम्रो वचनहरूमा र तिम्रो प्रत्येक कर्महरूमा स्पष्ट रूपमा झल्किनेछ । तब तिम्रो व्यक्तित्वमा ती सबै भक्तका लक्षणहरू स्वतः प्रकट हुन थाल्नेछन् ।
12.13
अद्वेष्टा सर्वभूतानां(म्), मैत्रः(ख्) करुण एव च ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (12, 13, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=CP7AS-GX7zs', '2026-03-28', 'जुन पुरुष सबै प्राणीहरूमा द्वेषभाव नराख्ने, सबैमा मैत्री र करुणाभाव राख्ने, साथै ममतारहित, अहङ्काररहित, सुख-दुःखमा समान भाव राख्दछ, क्षमावान् छ अर्थात् अपराध गर्नेलाई पनि अभय प्रदान गर्ने खालको छ, त्यस्तो भक्त मलाई प्रिय लाग्छ ।
12.14
सन्तुष्टः(स्) सततं(य्ँ) योगी, यतात्मा दृढनिश्चयः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (12, 14, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=CP7AS-GX7zs', '2026-03-28', 'जुन योगी निरन्तर सन्तुष्ट, मन-इन्द्रियसहित शरीरलाई वशमा राखेर ममा दृढ निश्चयभाव राख्दछ, त्यो ममा अर्पण गरिएको मन-बुद्धि भएको मेरो भक्त मलाई प्रिय लाग्छ ।
भगवान्‌ भक्तका लक्षणहरूको वर्णन गर्दै भन्नुहुन्छ कि जसको मनभित्र भक्तिभावको सञ्चार हुन्छ, उसको मनमा सम्पूर्ण प्राणीप्रति द्वेषरहित भाव जागृत हुन्छ ।
अद्वेष्टा-
पूर्णरूपले द्वेषरहित हुनु । जुनसुकै अवस्थामा साना-ठूला प्राणीहरूप्रति मनमा कत्ति पनि द्वेष नराख्नु।
वास्तवमा सन्त-महात्माहरूको अन्तरमनमा द्वेषले कहिल्यै प्रवेश गर्दैन । परम पूज्य स्वामीजी एकपटक कथा वाचनका लागि कुनै भक्तकहाँ जानुभयो । उहाँसँग केही सहयोगीहरू पनि थिए । स्वामीजीले कथा भन्नुभयो, तब कथा सुन्न आएका केही भक्तहरूले पोटलीमा केही पैसा राखिदिए । सहयोग रासी एउटा सहयोगीले सङ्कलन गरिरहेका थिए । उनले केही पैसा लुकायो पनि । त्यो घटना अरु कसैले देखिरहेको थियो । त्यो सहयोगी त चोर रहेछ भनी स्वामीजीलाई यो घटनाबारे सुनाइयो । तब स्वामीजीले उसलाई बोलाउनुभयो र भन्नुभयो- “बाबु! तिम्रो घरमा सबै ठिक त छ नि? पैसाको कुनै आवश्यकता त छैन नि? केही आवश्यकता छ भने भन है” । त्यसपछि स्वामीजीले त्यहाँ बाँकी जति पैसा सङ्कलन भएको थियो, त्यो पनि सबै उठाएर उसको हातमा राखिदिनुभयो र भन्नुभयो कि यो सबै तिमी नै राख र आफ्नो घरमा पठाइदेऊ, यो पैसा त्यहाँ काम लाग्नेछ । यो त अचम्मै लाग्ने कुरा भयो! हामीलाई लागिरहेको थियो कि अब उसलाई स्वामीले दण्ड दिनुहुनेछ, तर उल्टो उसलाई त सबै पैसा दिनुभयो । हामी र स्वामीजीबीच यही अन्तर छ कि उनीहरू द्वेषरहित हुन्छन् र हामीमा द्वेष भरिपूर्ण हुन्छ ।
अद्वेष्टा सर्वभूतानां मैत्रः करुण एव च ।
सर्वभूतानां-
‌भग
वान्‌ यहाँ
सर्वभूतानां
शब्दको प्रयोग गर्नुहुन्छ । यहाँ भूतको अर्थ संसारका प्रत्येक प्राणी भनिएको हो । हाम्रो मनमा कुनै पनि जीवप्रति, यहाँसम्म कि सानो कमिलाप्रति पनि घृणाको भाव राख्नुहुँदैन र सर्पप्रति द्वेष भाव पनि राख्नुहुँदैन ।
मैत्रः करुण एव च-
हाम्रो अन्तःकरणमा प्रत्येक पशु-पक्षी र प्राणीहरूप्रति अद्वेष्टता, मैत्री र करुणाको भावना जागृत हुनु पर्छ । हामीले व्यर्थैमा कुनै पनि जीवलाई दुःख दिनुहुँदैन । यदि बाटोमा हिँड्दा कुनै सानो कमिला अगाडि आयो भने पनि त्यसलाई नकुल्चिई अगाडि बढ्नुपर्छ, किनभने विधाताले उसलाई पनि बाँच्ने अधिकार दिनुभएको छ । हाम्रो व्यवहार, हाम्रो मन, हाम्रो कर्म र हाम्रा शब्दहरूले कुनै पनि प्राणी, पशु वा व्यक्तिलाई कत्ति पनि क्षति नपुर्‍याओस् ।
निर्मम निरहङ्कारः-
भक्तको जीवनमा निर्मम निरहङ्कारःको भावना हुनु पर्छ । “यो मेरो हो” र “यो मैले गरेको हो” भन्ने अहङ्कार पूर्ण रूपमा त्याग्नुपर्छ । जो व्यक्ति ममता र अहङ्कारबाट मुक्त हुन्छ, उसैले नै वास्तवमा सच्चा भक्तको स्थान प्राप्त गर्न सक्छ । जो पूर्ण रूपमा निरहङ्कारी हुन्छ, उही ‌भगवान्‌को नजिक पुग्छ ।
समदुःखसुखः क्षमी-
‌ भक्त त्यो हो जो सुख र दुःखको प्रत्येक परिस्थितिमा सधैँ समान रहन्छ र क्षमाशील रहन्छ । अब प्रश्न उठ्छ कि सुख र दुःखमा कसरी समान रहन सकिन्छ? यसको उत्तर निकै सरल छ कि सुख पनि बाहिरबाट आउँछ र दुःख पनि बाहिरबाट आउँछ । यसलाई एउटा सानो उदाहरणबाट बुझौँ- आज मलाई बिहानै चिसो पानीले नुहाउनुपर्‍यो । ‌भगवान्‌ले यस अध्यायमा स्पष्ट भन्नुभएको छ-
शीतोष्णसुखदुःखेषु
। सुरुमा त मलाई लाग्यो, पानी यति चिसो छ, कसरी नुहाउने? तर पाँच मिनेटपछि जब त्यो पानी निरन्तर मेरो जिउमा परिरह्यो, मलाई त्यसैमा आनन्द लाग्न थाल्यो । चिसो पानीको दुःख तुरुन्तै आनन्दमा परिणत भयो । यसरी हामी देख्छौँ कि दुःख वास्तवमा क्षणिक हुन्छ । यो संसारमा भएका सबै दुःखहरूमध्ये सबैभन्दा ठुलो दुःख आफ्नो प्रियजन गुमाउनु हो, तर त्यो दुःख पनि समयसँगै हल्का हुँदै जान्छ । विचार गर्नुहोस् त, यदि यति ठुलो दुःख दुई-तीन वर्षमा नै शान्त हुन्छ भने दुई वर्षपछि मेटिने दुःखलाई ज्ञानद्वारा दुई मिनेटमै चट् पार्न सकिन्छ । बस, मनमा पूर्ण स्वीकृतिको भाव हुनुपर्छ ।
सन्तुष्टः सततं योगी-
वास्तविक योगी सधैँ सन्तुष्ट हुन्छ । उसको जीवनमा असन्तोषको कुनै ठाउँ नै हुँदैन । एउटा सानो प्रयोग गरेर हेर्नुहोस्- दिनभर कुनै पनि नकारात्मक कुरा मुखबाट ननिकाल्नुहोस् । यो राम्रो थियो वा त्यो नराम्रो थियो भनेर नभन्नुहोस् । जे जस्तो छ, त्यसमा पूर्ण सन्तुष्ट हुनुहोस् । यदि खानामा नुन कम भए पनि सन्तुष्टपूर्वक खानुहोस् । एक दिन नुनविनाको तरकारी खाँदा कुनै हानि हुँदैन । ठिक छ, यदि कोही पाहुना आउँदै छन् भने शान्तसँग भान्सामा गएर तरकारीमा अलिकति नुन हाल्नका लागि भन्नुहोस्, तरकारी अझ स्वादिष्ट हुन्छ; तर नुनको अभावमा सन्तुलन गुमाउनु वा क्रोधित हुनु भनेको भक्तको लक्षण होइन ।
यतात्मा दृढनिश्चयः-
भक्त त्यो हो जो दृढनिश्चयी हुन्छ, जसको हृदयमा ‌भगवान्‌लाई प्राप्त गर्ने दृढ निश्चय हुन्छ, जस्तो कि माता शबरीको मनमा “‌भगवान्‌ले मलाई अवश्य भेट्नुहुनेछ” भन्ने दृढ निश्चय थियो ।
मय्यर्पितमनोबुद्धिः-
जो आफ्नो मन र बुद्धि दुवै ‌भगवान्‌को चरणमा अर्पण गर्दछ, ऊ नै सर्वश्रेष्ठ भक्त हो । जब मन र बुद्धिले एउटै दिशामा बसेर काम गर्न थाल्छ, तब विजय सुनिश्चित हुन्छ । ‌भगवान्‌लाई प्राप्त गर्नु भनेको विजय प्राप्त गर्नु हो । ‌भगवान्‌ अर्जुनलाई विजयी बनाउन चाहनुहुन्थ्यो, त्यसैले उहाँले मन र बुद्धि दुवैलाई एकाग्र गरेर युद्ध गर्ने सल्लाह दिनुभएको थियो ।
युद्धाय युज्यस्व नैवं पापमवाप्स्यसि-
युद्ध गर्नु तिम्रो धर्म हो, किनकि तिमी क्षत्री हौ, त्यसैले यसमा कुनै पाप हुँदैन । त्यसबेला अर्जुनको मन व्याकुल भइरहेको थियो र उनी मोहको प्रभावमा थिए । तब ‌भगवान्‌ले सजिलो मार्ग बताउनुभयो कि ममा आफ्नो मन र बुद्धि स्थिर गर, तब मात्र तिमीले मलाई प्राप्त गर्नेछौ र विजयको माला पहिरिनेछौ । ‌यस्ता अनन्य भक्तहरू नै मलाई प्रिय लाग्छन् ।
12.15
यस्मान्नोद्विजते लोको, लोकान्नोद्विजते च यः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (12, 15, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=CP7AS-GX7zs', '2026-03-28', 'जसबाट कुनै पनि जीव दुःखी हुँदैन र जुन स्वयं पनि कुनै जीवद्वारा दुःखी हुँदैन, अनि जुन हर्ष, अमर्ष (ईर्ष्या), भय र उद्वेग आदिबाट पनि मुक्त छ, त्यस्तो भक्त मलाई प्यारो लाग्छ ।
श्री‌भगवान्‌ भन्नुहुन्छ– “जसको कारणले कुनै जीवलाई पीडा हुँदैन र जसले कुनै प्राणीलाई घृणा गर्दैन, जो हर्ष, भय, क्रोध आदिभन्दा पर हुन्छन्, ती मानिसहरू मलाई प्रिय लाग्छन्” । अब सोच्नुहोस् त, जो व्यक्ति हरेक कुरामा क्रोधित हुन्छ, सानातिना कुरामा रिसाउने गर्छ वा अति प्रसन्न हुँदा पनि आफ्नो सन्तुलन गुमाउँछ भने त्यो मानिस कसरी भक्त हुन सक्छ? भक्तको लक्षण त समदृष्टि हुनु हो । ऊ सुख र दुःखमा समान रहन्छ । हर्ष भनेको चरम आनन्दको अवस्था हो र अमर्षको अर्थ गहिरो दुःखको अवस्था हो । जसले यी दुई अवस्थाको बीचमा समानता प्राप्त गर्छ, ऊ भय र क्रोधको चक्रबाट मुक्त हुन्छ । यस्तो स्थिरचित्त भक्त नै ‌भगवान्‌को प्रिय पात्र बन्न सक्छ ।
आज हाम्रो स्वभाव यति प्रतिक्रियामुखी भइसकेको छ कि कसैलाई देख्नेबित्तिकै मनमा रिस उठ्न थालिहाल्छ । हामीले आफ्नो मनलाई यस्तो बनाइसक्यौँ कि फलानो व्यक्ति मेरो अगाडि आयो भने मलाई रिस उठ्छ । यी सबै बेकारका कुराहरू छोड्नुहोस् र आजैदेखि अद्वेष्टा बन्ने सङ्कल्प गर्नुहोस् । मनबाट घृणाको भावनालाई पूर्णतया निकाल्नुहोस् । यो जीवन धेरै छोटो छ, यसमा माया गर्नका लागि पनि पर्याप्त समय छैन भने फेरि हामी घृणामा समय र शक्ति किन बर्बाद गर्ने ? यदि घृणाको काँडाले मनमा निरन्तर घोचिरह्यो भने अन्तिम समयमा धेरै कष्ट हुनेछ । मृत्युको समयमा तपाईँको आँखा अगाडि उही व्यक्ति देखा पर्नेछ, जसलाई तपाईँले घृणा गर्नुहुन्छ । एकजना व्यक्ति छ, ऊ दिनरात आफ्नो भाइलाई गाली गरिरहन्थ्यो । जतिबेला भेटे पनि “यसले मलाई लुट्यो”, “मलाई अन्याय गर्‍यो”, “मलाई अदालतसम्म लग्यो” भनेर गाली गरिरहन्थ्यो । सोच्नुहोस् त, यदि उसले त्यो भाइलाई थोरै पैसाका लागि माफ गरिदिएको भए उसको दिमागबाट कमसेकम त्यो पीडादायी काँडा त हट्ने थियो । मनबाट घृणाको निकाल्नु अति जरुरी हुन्छ ।
‌भगवान्‌ त रणभूमिमा युद्ध गर्दा पनि शत्रुता भाव त्याग गर्ने कुरा गर्नुहुन्छ । उहाँ अर्जुनलाई भन्नुहुन्छ- “हे अर्जुन! तिमीले युद्ध यसकारण गरिरहेका छैनौ कि दुर्योधन र दुःशासन तिम्रा शत्रु हुन् । तिनीहरू त आततायी हुन् । तिनीहरूले द्रौपदीको वस्त्रमा हात लगाएका छन् र यस्ता आततायीहरूको दमन गर्नु, तिनीहरूलाई शारीरिक दण्ड दिनु, क्षत्री भएको नाताले त्यो तिम्रो धर्म र कर्तव्य पनि हो । त्यसैले तिमी शत्रुको भावनाबाट होइन कि कर्तव्यको भावनाबाट युद्ध गर । मनबाट शत्रुभाव पूर्ण रूपमा निकालिदेऊ” । के हामी यसो गर्न सक्छौँ? हामी लर्नगीता परिवारसँग जोडिएका छौँ भने हामीले पनि यो गर्नैपर्ने हुन्छ, नत्र अनेक घृणा मनमा उल्झिरहनेछ र यस्सै अवस्थामा काल आउछ । काल कहिले आउछ यसको कुनै सङ्केत नै हुदैन । यदि मनमा कुनै पनि घृणा र शत्रुभाव बाँकी छ भने मृत्युपछि आत्मासँगै त्यो भाव पनि जानेछ र अर्को जन्ममा त्यसलाई बदला लिनका लागि आत्माले त्यही कोख र त्यही घरको खोजी गर्दछ । यस प्रकार कसैसँग घृणा गर्दा हामीले आफ्नै ठुलो हानि गरिरहेका हुन्छौँ ।
12.16
अनपेक्षः(श्) शुचिर्दक्ष, उदासीनो गतव्यथः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (12, 16, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=CP7AS-GX7zs', '2026-03-28', 'जो पुरुष आकाङ्क्षाले रहित, बाहिर-भित्रबाट पवित्र, चतुर, पक्षपातले रहित र दु:खहरूदेखि मुक्त छ साथै ती सबै आरम्भहरूलाई त्याग गर्दछ भने त्यस्तो भक्त मलाई प्यारो लाग्छ ।
श्री‌भगवान्‌ भन्नुहुन्छ– "“हे अर्जुन! आफ्नो अपेक्षाको बन्धनबाट बाहिर निस्क” । यी आशाहरू नै आज हाम्रो जीवनमा कष्ट निम्त्याउने सबैभन्दा ठुलो कारण हुन् ।
हामी सोच्छौँ- “मलाई आफ्नो छोरा, बुहारीबाट धेरै अपेक्षा छ । उसले मेरो यो काम गर्नैपर्छ । उनीहरू मेरो बुढेसकालको सहारा बन्नैपर्छ । मैले उनीहरूका लागि सबैथोक गरेको छु, तर उनीहरूले मेरो लागि के गरिरहेका छन्”? यस्ता सोचहरूलाई टाढै राख्दा राम्रो हुन्छ । तपाईँले आफ्नो कर्तव्य पूरा गर्नुभयो, तर अब उनीहरूले आफ्नो कर्तव्य आफैँ गर्नेछन् । यदि तपाईँ उनीहरूबाट सेवा पाउने अपेक्षामा बाँच्नुहुन्छ भने तपाईँ सधैँ दुःखी नै हुनुहुनेछ । युवावस्थामा नै आफ्नो बुढेसकालको उचित व्यवस्था गर्नुपर्छ, त्यसपछि यदि छोरा वा बुहारीले कुनै सेवा गरेनन् भने पनि त्यसलाई ‌भगवान्‌को प्रसादका रूपमा खुसीसाथ ग्रहण गर्नुपर्छ । आनन्दका साथ बाँच्न सिक्नुहोस्, जीवनमा आनन्दबाहेक अरू केही छैन र यो आनन्द केवल अरूबाट पाउने सेवाको अपेक्षालाई त्यागेर मात्र सम्भव हुन्छ ।
‌भगवान्‌ले द्वितीय अध्यायमै स्पष्ट गरिसक्नुभएको छ कि यदि
स्थितप्रज्ञ
बन्नु छ भने आनन्दको मार्गमा हिँड्न सिक । यही नै सबै दुःखहरूको एक मात्र औषधि हो । प्रसन्नताबाट संसारका ठुलाभन्दा ठुला दुःखहरू नष्ट गर्न सकिन्छ । ‌
प्रसन्नचेतसो ह्याशु बुद्धिः पर्यवतिष्ठते-
यदि मन प्रसन्न रहन्छ भने बुद्धि पनि स्थिर रहन्छ र जब बुद्धि स्थिर हुन्छ, तब निर्णय सटीक हुन्छ । सटीक निर्णयद्वारा नै जीवनमा विजय प्राप्त हुन्छ । श्रीमद्भगवद्गीता केवल उपदेश मात्र होइन, यो विजयको शास्त्र पनि हो । त्यसैले ‌भगवान्‌ भन्नुहुन्छ कि विना कुनै अपेक्षा, आन्तरिक र बाह्य शुद्धता, दक्षता, सावधानी र उदासीनताका साथ रहनुपर्छ ।
उदासीनो-
यहाँ उदासीनोको अर्थ उदास हुनु कदापि होइन, किनभने ‌भगवान्‌ सधैँ प्रसन्न रहन सिकाउनुहुन्छ । यहाँ उदासीनोको अर्थ तटस्थ हुनु हो, जीवनमा एउटा सुन्दर सन्तुलन र समभाव अपनाउनु हो ।
गतव्यथः-
व्यथा भन्नाले दुःख हो । जीवनको बाटोमा विभिन्न प्रकारका व्यथा र दुःख आउनेछन्, तर तिनीहरूलाई छिट्टै बिर्सेर अगाडि बढ्नु नै बुद्धिमानी हो । यदि हामीले दुःखको बोझलाई पोको पारेर सङ्गालेर राख्यौँ भने समस्या झन् विकराल हुँदै जान्छ । विधाताले हामीभित्र भुल्नका लागि एउटा जन्मजात मेट्ने कुरा राखिदिएका छन् । जुन कुरा याद गरेर कुनै लाभ हुँदैन भने तिनीहरूलाई भुल्नु नै कल्याण हुन्छ । त्यसैले ती व्यथाहरूबाट बाहिर निस्कनुहोस् ।
सर्वारम्भपरित्यागी-
“यो मैले गरेँ”, “यो सबै मेरो कारणले भयो” भन्ने यस्ता कर्तापनको अहङ्कारलाई पूर्ण रूपमा त्याग्नुहोस् । यस्तो अहङ्कार पाल्दा कुनै फाइदा हुनेछैन । सधैँ यही भावना राख्नुहोस् कि मलाई त केवल निमित्त मात्र बनाइएको छ ।
सर्वारम्भपरित्यागी यो मद्भक्तः स मे प्रियः -
जो यस समर्पण भावसहित आफ्नो कर्म गरिरहेका हुन्छन्, ‌यस्तै भक्तहरू मलाई अत्यन्त प्रिय लाग्छन् ।
12.17
यो न हृष्यति न द्वेष्टि, न शोचति न काङ्क्षति ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (12, 17, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=CP7AS-GX7zs', '2026-03-28', 'जो न कहिल्यै हर्षित हुन्छ, न द्वेष गर्दछ, न शोक गर्दछ, न कामना गर्दछ र जो शुभ-अशुभ सम्पूर्ण कर्महरूको फललाई त्याग्दछ, त्यो भक्तिमान् पुरुष मलाई प्यारो लाग्छ ।
यो न हृष्यति-
हर्षको अर्थ अत्यन्त आनन्दित हुनु र पागल हुनु हो । मानिसहरू अलिकति मात्र फाइदा देखियो कि अहङ्कारका साथ प्रदर्शन गर्न थालिहाल्छन्- “मेरो भव्य बङ्गला हेर, मेरो भव्य कार हेर” जो सच्चा भक्त छ, ऊ यी क्षणभङ्गुर उपलब्धिहरूको प्रदर्शनबाट माथि उठ्छ ।
न द्वेष्टि-
भक्तको हृदयमा कसैप्रति घृणाको भाव अलिकति पनि हुनुहुँदैन । ऊ वैरभावबाट पूर्णतया मुक्त भएको हुनुपर्छ ।
न शोचति-
जीवनमा स-साना कुरामा शोक गर्नु भक्तको स्वभाव होइन । ‌भगवान्‌ले त मृत्युजस्तो गम्भीर विषयमा पनि शोक गर्न निषेध गर्नुभएको छ । उहाँ अर्जुनसँग भन्नुहुन्छ- “हे अर्जुन! कसैको मृत्युप्रति शोक गर्नु पर्दैन, किनकि जो जन्मिन्छ, उसको मृत्यु निश्चित छ । त्यसैले यस्तो शोकको अन्धकारबाट तिमी बाहिर निस्क” ।
न काङ्क्षति-
जो सबै आकाङ्क्षा र इच्छाहरूबाट माथि उठ्छ, त्यही सच्चा भक्त हो ।
शुभाशुभपरित्यागी भक्तिमान्यः स मे प्रियः-
जो शुभ र अशुभ, दुवैको फल परित्याग गर्छ, त्यही सच्चा भक्त हो । त्यस्तो भक्त ‌भगवान्‌लाई अत्यन्त प्रिय लाग्छन् । ‌भगवान्‌ अर्जुनको मनको द्वन्द्वलाई शान्त पार्दै भन्नुहुन्छ- “यी योद्धाहरूलाई त मैले पहिले नै मारिसकेको छु, तिमी केवल निमित्त बनेर मात्र बाण चलाऊ” । एघारौँ अध्यायमा भगवान्‌ भन्नुहुन्छ-
द्रोणं च भीष्मं च जयद्रथं च
कर्णं तथाऽन्यानपि योधवीरान् ।
मया हतांस्त्वं जहि मा व्यथिष्ठा
युध्यस्व जेतासि रणे सपत्नान्।।११.३४।
‌तिमी यस विचारबाट बाहिर निस्क कि तिमीले हत्याजस्तो अशुभ कर्म गर्दैछौ । जब कर्म केवल कर्तव्य-बोध र बुद्धिद्वारा ‌भगवान्‌मा अर्पण गरिन्छ, तब त्यो शुभ-अशुभको बन्धनबाट मुक्त हुन्छ । कर्तव्यको पथमा बढ्दै जाँदा कर्मको बाह्य स्वरूपको चिन्ता छोड्नुपर्छ । जो यस प्रकार पूर्ण रूपले ‌भगवान्‌मा आसक्त हुन्छ, त्यो भक्त ‌भगवान्‌लाई प्रिय लाग्छ ।
12.18
समः(श्) शत्रौ च मित्रे च, तथा मानापमानयोः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (12, 18, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=CP7AS-GX7zs', '2026-03-28', 'जो शत्रु र मित्र तथा मान र अपमानलाई समान ठादन्छ एवं जाडो र गर्मी तथा सुख र दुःखलाई समानरूपले हेर्दछ र केहीमा पनि आसक्ति राख्दैन, त्यस्तो पुरुष मलाई प्यारो लाग्छ ।
श्रीमद्भगवद्गीताले हामीलाई पलायन हुन सिकाउँदैन, बरु रणभूमिमा डटेर लड्ने प्रेरणा दिन्छ । ‌भगवान्‌ भन्नुहुन्छ- “युद्ध गर, तर लड्दा मनमा कसैप्रति व्यक्तिगत वैरभाव राख्नुहुँदैन” । जब हामी आफ्नो अधिकार र धर्मको रक्षार्थ लड्छौँ भने त्यो लडाइँ कर्तव्य-बोधले प्रेरित हुनुपर्छ, शत्रुभावले होइन ।
यसलाई एउटा उदाहरणबाट बुझौँ- अदालतमा जब कुनै क्रुर अपराधीलाई मृत्युदण्डको आदेश दिइन्छ, त्यसबेला निर्णय सुनाउने न्यायाधीशको त्यो अपराधीप्रति कुनै व्यक्तिगत द्वेष हुँदैन । उनी त समाजको कल्याणका लागि यो कठोर निर्णय लिन बाध्य हुन्छन्, किनकि यदि त्यसलाई जीवित छोडिदियो भने त्यसले समाजमा झन् आतङ्क मच्चाउनेछ र धेरै निर्दोष मानिसहरूको ज्यान जानेछ । त्यसैले उसलाई मृत्युदण्ड दिनु अनिवार्य हुन्छ । ‌भगवान्‌ मृत्युदण्ड दिने न्यायाधीशलाई दोषी मान्नुहुन्न, किनकि उनको कार्य कर्तव्यपरायणताले प्रेरित हुन्छ । न्यायाधीशले कुनै द्वेषविना आफ्नो धर्म पूरा गर्छन्, त्यसैले उनी राति आरामले सुत्न सक्छन् । यसको विपरीत, यदि तपाईँ कसैसँग विनाकारण झगडा गरेर घरमा आउनुभयो भने तपाईँलाई राति निद्रा पर्दैन ।
तपाईँसँग कसैलाई सजाय दिने अधिकार नै छैन, त्यो अधिकार त विधि र शासनको हो । त्यसैले ‌भगवान्‌को शिक्षाबाट यो अर्थ कहिल्यै निकाल्नुहुँदैन कि धनुष-बाण उठाएर जसलाई मन लाग्यो, उसैलाई लक्ष्य बनायो । ‌भगवान्‌ले यस्तो उच्छृङ्खलताको पाठ कहिल्यै सिकाउनुभएको छैन । भगवान्‌ त स्पष्ट रूपमा यो भन्नुहुन्छ कि जसले जाडो-गर्मीमा, सुख-दुःखमा समान भाव राख्छ र जसले प्रत्येक वस्तु र सम्बन्धमा आसक्तिको त्याग गरेको हुन्छ, त्यही सन्तुलित भक्त मलाई प्रिय लाग्छ ।
12.19
तुल्यनिन्दास्तुतिर्मौनी, सन्तुष्टो येन केनचित् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (12, 19, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=CP7AS-GX7zs', '2026-03-28', 'जो निन्दा र स्तुतिलाई समान सम्झन्छ, मननशील एवं जुनसुकै प्रकारले पनि शरीरको निर्वाह मात्र हुँदा पनि सदा संतुष्ट रहन्छ र बस्ने स्थान पनि ममता र आसक्तिबाट टाढा राख्दछ, त्यस्तो स्थिरबुद्धि भक्तिमान् पुरुष मलाई प्रिय लाग्छ ।
भगवान्‌ भन्नुहुन्छ कि जो निन्दा र स्तुतिको द्वन्द्वबाट टाढा रहन्छ, त्यही भक्त मलाई प्रिय लाग्छ । जसको मति स्थिर भइसकेको छ, त्यस्ता सन्तुलित व्यक्तिहरू मात्र ‌भगवान्‌को धाममा बस्दछन् । विचार गर्नुहोस् त, यदि कसैले तपाईँको अभिनन्दन गर्‍यो, तपाईँलाई फूलको गुच्छा उपहार दियो, सल ओढाएर सम्मान गर्‍यो र तपाईँको प्रशंसामा राम्रा-राम्रा शब्दहरू भन्यो भने तपाईँ फुरुङ्ग नहुने कुरै छैन । यसको विपरीत, यदि कसैले तपाईँलाई गाली गर्‍यो वा तपाईँको आलोचना गर्‍यो भने तत्काल तपाईँ दुःखी हुनुहुन्छ । ‌भगवान्‌ भन्नुहुन्छ कि यी दुवै स्थितिमा जो तटस्थ रहन्छ, त्यो नै मेरो वास्तविक भक्त हो । कसैले तपाईँको निन्दा गरोस् तापनि तपाईँको प्रसन्नता टुट्नुहुँदैन ।
यसलाई एउटा सानो बालकको उदाहरणबाट बुझौँ- एकपटक एउटा बालक रुँदै आयो र भन्यो, “उसले मलाई गिज्यायो र हात्ती भन्यो”! उसलाई बुझाइयो कि यदि तिमी रिसायौ भने तिमी हार्छौ । यदि तिमी रिसाएनौ भने उसले तिमीलाई फेरि कहिल्यै गिज्याउने छैन । यदि तिमीलाई जित्नु छ भने तिमीले रिसाउनुहुँदैन । अर्कोपटक जब उसले तिमीलाई गिज्यायो भने केवल यति मात्र भन कि तिमी खानदानी घरको छोरो हौ । केही दिनपछि त्यो केटो फर्केर आयो र खुसी हुँदै भन्यो, “आज जब उसले मलाई गिज्यायो, मैले भनेँ कि म खानदानी घरको छोरो हुँ । यो सुनेर ऊ खिस्रिक्क पर्‍यो । उसले हार्‍यो र मैले जितेँ”! नबिर्सनुहोस् कि यदि तपाईँ निन्दाको कारणले मुर्मुरिरहनुभएको छ भने तपाईँ पराजित भइरहनुभएको छ । श्रीमद्भगवद्गीताले तपाईँलाई जीवनको हरेक परिस्थितिमा सदैव जित्न सिकाउँछ । जो हरेक परिस्थितिमा सन्तुष्ट रहन सिक्छ र जसलाई आफ्नो घर वा वैभवप्रति कुनै आसक्ति वा मोह हुँदैन, उसलाई
अनिकेत
भनिन्छ ।
‌भगवान्‌ शङ्करको उदाहरण हेर्नुहोस्- कैलाश पर्वतमा उनको यति भव्य स्वर्णमहल छ कि साक्षात् कुबेर पनि उहाँको सम्पत्ति देखेर अचम्ममा पर्छन् । यस्तो अथाह सम्पत्तिका मालिक हुँदा पनि देवाधिदेव महादेव महलमा होइन, श्मशानमा बस्नुहुन्छ; त्यसैले उहाँको एउटा नाम अनिकेत भएको हो । उहाँको सम्पूर्ण परिवारलाई हेर्नुहोस्, आमा पार्वती, श्रीगणपति र कार्तिकेय- सबै स्वर्णमुकुट र बहुमूल्य रत्नहरूको माला लगाएर सुसज्जित रहन्छन् । सबै परिवार वैभवको बीचमा हुन्छन् तर ‌भगवान्‌ शिव भने केवल रुद्राक्षको माला र मुण्डमाला लगाएर, खरानी धसेर विचरण गर्नुहुन्छ । शिवजीलाई भौतिक वस्तुप्रति कुनै आसक्ति नै छैन । उनी पूर्ण रूपले सन्तुष्ट र स्थिरचित्त छन् । यस्तै अनासक्त र सन्तुष्ट भक्तलाई ‌भगवान्‌ आफ्नो प्रिय भक्त मान्नुहुन्छ ।
12.20
ये तु धर्म्यामृतमिदं(य्ँ), यथोक्‍तं(म्) पर्युपासते ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (12, 20, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=CP7AS-GX7zs', '2026-03-28', 'जुन श्रद्धायुक्त पुरुषहरू ममा परायण भएर माथि बताइएको धर्ममय अमृतलाई निष्काम प्रेमभावले सेवन गर्दछन्, तिनीहरू मेरा लागि अत्यन्त प्रिय छन् ।
भगवान्‌ भन्नुहुन्छ कि जो भक्त ममा अटूट श्रद्धा राख्छ र ममा नै पूर्णरूपमा परायण भएर, यस धर्ममय अमृतको त्यसरी नै सेवन गर्छन् जसरी मैले अहिल्यै वर्णन गरेको छु, ती भक्तहरू मलाई अत्यन्त प्रिय लाग्छन् ।
धर्म्यामृतमिदं-
धर्मको अमृत
यथोक्तं-
जस्तो भनिएको छ, त्यस्तै
पर्युपासते-
भगवान्‌ले जुन गुणहरूको बारेमा भन्नुभएको छ- द्वेषरहित हुनु, सन्तुष्ट रहनु, सुख-दुःखमा सम रहनु र मान-अपमानबाट माथि उठ्नु, जसले यी गुणहरूलाई आफ्नो जीवनमा उतार्छ र त्यस मार्गमा हिँड्छ, त्यस्ता श्रद्धावान् मानिसहरू, जो ममा परायण भएका छन्, तिनीहरू श्री‌भगवान्‌‌लाई अत्यन्त प्रिय लाग्छन् ।
ॐ तत्सदिति श्रीमद्भगवद्गीतासु उपनिषत्सु ब्रह्मविद्यायां(य्ँ) योगशास्त्रे श्रीकृष्णार्जुनसंवादे भक्तियोगो नाम द्वादशोऽध्यायः ॥१२।।
यसप्रकार ॐ तत्सत्- यी भगवान्‌का नामहरूको उच्चारणपूर्वक ब्रह्मविद्या र योगशास्त्रमय श्रीमद्भगवद्गीताको उपनिषद्‌रूपी श्रीकृष्ण र अर्जुनको संवादस्वरूप ‘भक्तियोग’ नाम भएको बाह्रौँ अध्याय पूर्ण भयो ।
यो विवेचन पढेर तपाईँलाई अवश्य पनि राम्रो लाग्यो होला भन्ने हामीलाई विश्वास लागेको छ । कृपया तल दिएको लिङ्क प्रयोग गरी हामीलाई आफ्नो प्रतिक्रियाहरू दिनुहोला ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (16, 1, 'KAVITA JI VERMA ', 'https://www.youtube.com/watch?v=N5pk7FAKCyw', '2026-03-28', 'श्रीभगवान् भन्नुहुन्छ– भयको सर्वथा अभाव, अन्तःकरणको पूर्ण शुद्धता, तत्त्वज्ञानका लागि ज्ञानयोगको व्यवस्थापन, सात्त्विक दान, इन्द्रियहरूको दमन; भगवान्, देवता र गुरुजनहरूको पूजा; यज्ञ एवं वेदशास्त्रहरूको दैनिक पठनपाठन भगवान्‌का नाम एवं गुणहरूको कीर्तन, स्वधर्म पालनका लागि तपस्या;
भगवान् यहाँ
अभयम्
शब्दद्वारा दैवीय गुणहरूको प्रारम्भ गर्नुहुन्छ । यसै सन्दर्भमा आदि शङ्कराचार्यको भाष्य-
अभयम्, सत्त्वसंशुद्धिः, ज्ञानयोगव्यवस्थितिः
यी तीन प्रारम्भिक गुण अत्यन्त महत्वपूर्ण छन् । यी तीनलाई समष्टि रूपमा पनि हेर्न सकिन्छ र पृथक् रूपमा पनि बुझ्न सकिन्छ । बाँकी दैवीय गुणहरूको विकास यिनै तीन गुणहरूमा आधारित हुन्छ । जीवनमा जति धेरै यिनको अभ्यास गरिछन्, त्यति नै सहज रूपमा अन्य गुणहरू प्रकट हुँदै जान्छन् ।
अभयम्
- भयको अभाव । मानव जीवनमा विभिन्न प्रकारका भय उत्पन्न भइरहन्छन् । धेरैपटक बिना कारण पनि हृदयमा भय उत्पन्न हुन्छ, जसको कुनै स्पष्ट कारण थाहा हुँदैन । मनमा उत्पन्न हुने विचारहरूले स्वतः भयको अनुभूति गराउँछन् । पशु-पंक्षी, कीट-पतङ्ग वा अन्य परिस्थितिसँग सम्बन्धित भय पनि अनुभवमा आउँछन् । यसबाहेक परलोकसम्बन्धी चिन्तन पनि कहिलेकाहीँ भयको कारण बन्छ ।सावधानी र भयबीचको भेद बुझ्न आवश्यक छ । विपत्तिबाट बच्न गरिने प्रयास सावधानीको प्रतीक हो, जुन सकारात्मक हुन्छ । उदाहरणका लागि, सिंह वा सर्प अगाडि देखा परेमा त्यसबाट टाढा हट्नु वा सुरक्षित स्थान खोज्नु सावधानी हो । तर हृदयमा बिना कारण उत्पन्न हुने आशङ्का भाव भने भय हो, जसले नकारात्मक प्रवृत्ति वृद्धि गर्छ ।
भयको मूल कारण आत्मविश्वासको कमी हो । ज्ञानको विकासबाट आत्मविश्वास उत्पन्न हुन्छ र त्यसले आत्मविकासको मार्ग खोल्छ । श्रीमद्भगवद्गीताको द्वितीय अध्यायमा भगवान् अर्जुनलाई सम्बोधन गर्दै भन्नुहुन्छ-
क्लैब्यं मा स्म गमः पार्थ नैतत्त्वय्युपपद्यते।
क्षुद्रं हृदयदौर्बल्यं त्यक्त्वोत्तिष्ठ परन्तप॥२.३॥
त्यससमयमा अर्जुन भय र मोहले ग्रस्त भई आफ्नो कर्तव्यबाट विचलित भएका थिए । गुरुजन र स्वजनप्रति सम्मानभाव उनको अन्तःकरणमा थियो, जुन दैवी प्रवृत्तिको सूचक हो । कृतज्ञताको भाव सधैँ धारण गर्नुपर्ने हुन्छ, किनकि जसबाट ज्ञान वा सहयोग प्राप्त हुन्छ, त्यसप्रति सम्मान गर्नुपर्छ । अर्जुनको अन्तःकरणमा उत्पन्न मोह र भयका कारण उनको सकारात्मक दृष्टिकोण कमजोर भयो, जसका कारण उनी आफ्नो कर्तव्यबाट टाढा हुन थाले । भगवान्‌‌ले यसैकारण सर्वप्रथम अभयम् गुणको वर्णन गर्नुभयो, जुन जीवनमा अत्यन्त आवश्यक छ ।
अभयको उत्पत्ति भक्तिबाट हुन्छ । जब साधक पूर्णरूपमा ईश्वरमा आश्रित हुन्छ, तब भय क्रमशः समाप्त हुन थाल्छ । जसरी बालकले आफ्नी आमामा पूर्ण विश्वास राख्छ, त्यसैगरी भक्त यदि भगवान्‌मा आश्रित भयो भने जीवनका चिन्ताहरू स्वतः कम हुँदै जान्छन् । परमात्मासँगको निरन्तर सम्बन्धको अनुभव जति गहिरो हुँदै जान्छ, त्यति नै भय समाप्त हुँदै जान्छ । भयको अर्को कारण यो भ्रान्ति पनि हो, जीव आफूलाई केवल शरीर मान्छ र परमात्मालाई आफूभन्दा अलग ठान्छ । श्रीमद्भगवद्गीताको पन्ध्रौँ अध्यायमा भगवान् भन्नुहुन्छ-
ममैवांशो जीवलोके, जीवभूतः(स्) सनातनः ।
मनः(ष्) षष्ठानीन्द्रियाणि, प्रकृतिस्थानि कर्षति ।।१५.७।।
यस सत्यको अनुभूति भएपछि यो बोध जाग्छ कि जीव परमात्माकै अंश हो । यस भावको दृढताले आत्मबल र आत्मविश्वास बढाउँछ ।
भक्ति परम्पराका अनेक उदाहरणहरूले यस सत्यलाई प्रमाणित गर्छन् । भक्त प्रह्लादले प्रतिकूल परिस्थितिमा पनि ईश्वरसँगको सम्बन्धलाई अटुट बनाए । धेरै प्रयासपछि पनि उनको अहित हुन सकेन । ध्रुव बाल्यावस्थामै वनमा तपस्या गर्न गए, जहाँ अद्भुत निर्भयता देखिन्छ । मीराबाई, कबीरदास र ज्ञानेश्वर जी जस्ता सन्तहरूको जीवनमा पनि भयको अभाव स्पष्ट देखिन्थ्यो ।
अभयम्-
दैवीय गुणहरूको अत्यन्त महत्वपूर्ण आधार हो । भक्ति, ज्ञान वा आत्मबोधका माध्यमबाट यो गुण विकसित हुन्छ । साधकको अन्तःकरणमा यसको विकास भएपछि जीवनमा स्थिरता, शान्ति र आत्मविश्वास उत्पन्न हुन्छ, जसले सबै भय स्वतः घटाउँछ ।
सत्त्वसंशुद्धिः
को निरूपण भगवान् दैवीय गुणहरूको क्रममा दोस्रो गुणका रूपमा आउँँछ ।
सत्त्व
को अर्थ अन्तःकरण, विशेषतः मन हो । अन्तःकरणको शुद्धतालाई नै
सत्त्वसंशुद्धि
भनिन्छ । जब मन काम, क्रोध, लोभ, मोह, मद, मत्सर र ईर्ष्या जस्ता विकारहरूबाट मुक्त हुन थाल्छ, तब शुद्धीकरणको प्रक्रिया सुरु हुन्छ । शास्त्रहरूमा यी विकारहरूको धेरै स्थानमा वर्णन गरिएको छ । विशेषतः श्रीमद्भगवद्गीताको १६ अध्यायमा काम, क्रोध र लोभलाई नरकका तीन ढोका भनिएको छ । यी दोषहरूको उपस्थिति अधोगतिको कारण बन्छन् भने यिनको त्यागले उन्नतिको मार्ग खुल्छ ।
मानव जीवनमा यी विकारहरूको पूर्ण अभाव तुरुन्त सम्भव हुँदैन । प्रत्येक साधकमा यी कुनै न कुनै स्तरमा हुन्छन् । साधनाको उद्देश्य तिनीहरूको मात्रा क्रमशः घटाउनु हो ।
सात्त्विक
भावद्वारा मनलाई संयमित गर्दै जब यी दोषहरूको परिमार्जन गरिन्छ, तब अन्तःकरण क्रमशः शुद्ध र निर्मल हुँदै जान्छ । निर्मल अन्तःकरणविना ईश्वरको निकटताको अनुभव सम्भव हुँदैन । भक्ति पनि शुद्ध मनमा मात्र उत्पन्न हुन्छ ।
सत्त्वसंशुद्धि
भक्तिको आधार हो र भक्तिबाट नै
अभयम्
प्रकट हुन्छ । त्यसैले अन्तःकरणको शुद्धीकरण साधनाको अनिवार्य अङ्ग हो । जसरी अशुद्ध वा फोहोर आँगनमा पवित्र अतिथिको स्वागत गर्न सकिँदैन, त्यसैगरी अशुद्ध मनमा ईश्वरको अनुभव हुन सक्दैन ।
साधनाको निरन्तर अभ्यासले अन्तःकरणको शुद्धीकरण स्वतः हुन थाल्छ । जब साधकले आफ्नो समय, श्रम र मनलाई सत्कार्यमा लगाउँछ, तब उसको चित्त संसारका नकारात्मक प्रवृत्तिहरूबाट स्वतः टाढा हुन थाल्छ । सकारात्मक विचार, प्रेम, सौहार्द र भक्ति बाट अन्तःकरण परिपूर्ण हुन्छ । यस प्रकार
सत्त्वसंशुद्धिः
दैवीय गुणका रूपमा साधकको जीवनमा प्रकट भई उसलाई आध्यात्मिक उन्नतिको मार्गतर्फ अघि बढाउँछ ।
ज्ञानयोगव्यवस्थितिः
- केवल शास्त्रहरूको अध्ययन वा ज्ञान सङ्कलन गर्नु मात्र होइन । विभिन्न ग्रन्थहरू पढ्न सजिलो हुन्छ र ज्ञान प्राप्त गर्नु पनि सहज हुन्छ । तर वास्तविक साधना भनेको त्यस ज्ञानलाई जीवनमा धारण गर्नु, निरन्तर स्मरण गर्नु र व्यवहारमा उतार्नु हो । धेरै साधकहरू जप, पाठ वा अन्य साधना निरन्तर गरिरहन्छन्, बाह्य रूपमा साधनाको प्रचुरता पनि देखिन्छ । जप्दै गर्दा माला नै खिइन्छ, तर यदि मन त्यस जपमा एकाग्र भएन र अन्तःकरण शुद्ध भएन भने साधना अधूरो रहन्छ । जपको प्रारम्भ बाह्य साधनाबाट हुन्छ । औँलाले माला घुमाउनु प्रारम्भिक अभ्यास हो । त्यसपछि साधकले आफ्नो मनलाई त्यही जपमा स्थिर गर्न प्रयास गर्नुपर्छ । दैनिक अभ्यासद्वारा मनलाई भगवान्‌को चिन्तनमा स्थिर बनाउछ । जब यो अभ्यास परिपक्व हुन्छ, तब मन पूर्ण रूपमा त्यही जप, त्यही अर्थ र त्यही दिव्य स्वरू
﻿पमा
लीन हुन्छ ।
सत्त्वसंशुद्धि
र
ज्ञानयोगव्यवस्थितिः
दुवै गुण साधनाका मूल आधार हुन्, जसबाट साधकको अन्तःकरण शुद्ध भई ईश्वरानुभूतितर्फ अघि बढ्छ । भगवान्‌को नित्य पूजा, चन्दन, आरतीका माध्यमबाट साधक वरिपरि सकारात्मक वातावरण बन्छ, जसले साधनामा दृढता र स्थिरता विकास गर्छ । क्रमशः साधक उन्नतिको मार्गमा अघि बढ्छ । स-साना आचरणबाट सुरु गर्दै साधनालाई व्यापक बनाइयोस् । अन्तःकरणमा निरन्तर परमात्माको चिन्तन होस् ।
ज्ञानयोगव्यवस्थितिः -
को तात्पर्य ज्ञान र योगमा निरन्तर स्थिर रहनु हो । साधकले चित्त बारम्बार त्यही तत्त्वमा स्थिर हुने प्रयास गरिरहोस्, यही यस गुणको स्वरूप हो । पतञ्जलिद्वारा योगशास्त्रमा चित्तका पाँच अवस्थाहरूको वर्णन गरिएको छ- मूढ, क्षिप्त, विक्षिप्त, एकाग्र तथा निरुद्ध ।
विक्षिप्त
अवस्थामा चित्तको स्थिति अस्थिर रहन्छ । साधक केही समयसम्म भगवान्‌को चिन्तन गर्छ, तर तुरुन्तै मन पुनः संसारतर्फ प्रवृत्त हुन्छ । ध्यानको समयमा प्रारम्भमा एकाग्रताको अनुभव हुन्छ, तर केही समयपछि विभिन्न सांसारिक विचारहरू मनमा उत्पन्न हुन थाल्छन् । दैनिक कार्य, व्यवहार, सम्बन्ध र स्मृतिहरूले चित्तलाई विचलित गरिरहन्छन् । त्यसैले साधक निरन्तर अभ्यासद्वारा चित्तलाई पुनः-पुनः परमात्मामा स्थिर गर्ने प्रयास गरिरहोस् । यही अभ्यासले क्रमशः एकाग्रता विकास गर्छ र साधकलाई उच्च आध्यात्मिक अवस्थातर्फ अग्रसर गराउँछ ।
दानको विस्तृत विवरण भगवान् सत्रौँ अध्यायमा गर्नुहुन्छ । दानका विभिन्न प्रकार, उपयुक्त समय, योग्य पात्र, विधि र आन्तरिक भावनाहरूको स्वरूप त्यहाँ विस्तारपूर्वक वर्णन गरिएको छ । वर्तमान प्रसङ्गमा दानलाई एक अनिवार्य दैवी गुणका रूपमा प्रस्तुत गरिएको छ । मानव जीवनमा दानको विशेष महत्त्व छ । दानका माध्यमबाट यस लोकमा यश, कीर्ति र सम्मान प्राप्त हुन्छ । अन्तःकरणमा शान्ति र सन्तोषको उत्पत्ति हुन्छ । दानको प्रभाव केवल यस जीवनमा मात्र सीमित हुँदैन, बरु परलोकमा पनि शुभ फल प्रदान गर्छ । त्यसैले दानलाई जीवनको अभिन्न अङ्ग बनाउनु पर्छ । दैवीय गुणहरूको श्रेणीमा यसको स्थान अत्यन्त उच्च छ ।
अभयम्, सत्त्वसंशुद्धिः, ज्ञानयोगव्यवस्थितिः, दानम्, दमः, यज्ञः
यस क्रममा भगवान् दैवीय गुणहरूको निरूपण गर्दै साधकलाई उच्च जीवन मूल्यमातर्फ प्रेरित गर्नुहुन्छ ।
वेदान्त अध्ययनका लागि पात्रता
साधनचतुष्टयसम्पन्न
साधकका रूपमा निर्धारण गरिएको छ ।
साधनचतुष्टय
अन्तर्गत विवेक, वैराग्य, षट्सम्पत्ति र मुमुक्षुत्व पर्दछन् ।
षट्सम्पत्ति
मा शम, दम, उपरति, तितिक्षा, श्रद्धा र समाधानको निरूपण गरिएको छ ।
शम
को अर्थ मनको निग्रह हो ।
दम
को अर्थ इन्द्रियहरूको संयम हो । इन्द्रियहरूको प्रवृत्ति मनअधीन हुन्छ, त्यसैले मन संयमित भएपछि इन्द्रिय नियन्त्रण सम्भव हुन्छ । जब मन शुद्ध र संयमित हुन्छ, तब इन्द्रियहरू पनि मर्यादित आचरणमा बस्छन् ।
इन्द्रियहरूको प्रवृत्ति
सर्वभूतहितको
दिशामा नियोजित हुनुपर्छ । श्रीमद्भगवद्गीतामा भक्तका लक्षणहरूको वर्णन गर्दै
सर्वभूतहिते रताः
को सिद्धान्त प्रस्तुत गरिएको छ । यस्तो साधक सबै प्राणिहरूको कल्याणमा निरत रहन्छ । यस्तो अवस्था हुनका लागि इन्द्रिय निग्रह अनिवार्य छ ।
दम
को विशेष महत्त्व श्रेष्ठ कार्यको सिद्धिका लागि हुन्छ । महाभारतमा पनि आदर्श राजाका लागि इन्द्रियसंयम अनिवार्य गुण मानिएको छ । राज्यको सुशासन, समाजको कल्याण र व्यक्तिगत उन्नतिका लागि इन्द्रिय संयम आवश्यक छ ।
भौतिक समृद्धि र आध्यात्मिक उन्नति दुवैका लागि
दम
को पालन अनिवार्य छ । त्यसैले साधकले आफ्नो मन र इन्द्रियहरूलाई संयमित गर्दै दैवीय गुणहरूको मार्गमा अघि बढ्नुपर्छ ।
दानम्, दमः, यज्ञः
यस क्रममा दैवीय गुणहरूको निरूपणले साधकलाई संयम, त्याग र साधनाको मार्गतर्फ प्रेरित गर्छ । यज्ञको अर्थ अत्यन्त व्यापक छ । सामान्य रूपमा यज्ञलाई केवल हवन क्रिया मात्र बुझिन्छ, तर शास्त्रीय दृष्टिमा यज्ञको अर्थ कुनै पनि शुभ, निःस्वार्थ र लोककल्याणकारी कर्म हो ।
आत्मनमोक्षार्थं जगद्धिताय च
यो वैदिक वाक्यले यही भाव व्यक्त गर्छ, जसको उल्लेख स्वामी विवेकानन्दले पनि धेरैपटक गर्नुभएको छ । आफ्नो आत्मोद्धार र सम्पूर्ण जगतको हितका लागि गरिने प्रत्येक कर्म यज्ञ स्वरूप हुन्छ । भगवान्‌द्वारा श्रीमद्भगवद्गीताको चतुर्थ अध्यायमा विभिन्न प्रकारका यज्ञहरूको विस्तृत वर्णन गरिएको छ । यी यज्ञहरू केवल अग्निहोत्रसम्म मात्र सीमित छैनन्, बरु ज्ञान, तप, स्वाध्याय र कर्मद्वारा पनि यज्ञ सम्पन्न हुन्छ । शुद्ध अन्तःकरणबाट, निःस्वार्थ भावले, समाज र अन्य प्राणिहरूको कल्याणका लागि गरिने प्रत्येक कार्य यज्ञ हो । यस दृष्टिले जब साधक कुनै पनि सेवा, शिक्षण वा लोकहितकारी कार्यमा संलग्न हुन्छ, तब उसले यज्ञको स्वरूप धारण गर्छ । बाह्य दृष्टिले यो समाज सेवा जस्तो देखिन्छ, तर आन्तरिक रूपमा यो साधकको साधनाको एक रूप हो ।
दानम्, दमः, यज्ञः, स्वाध्यायः, तपः, आर्जवम्
यस क्रममा दैवीय गुणहरूको वर्णन गर्दै निःस्वार्थ भाव, संयम, लोककल्याण र आत्मशुद्धिका माध्यमबाट साधक आध्यात्मिक उन्नतितर्फ अघि बढ्छ ।
स्वाध्याय
को अर्थ शास्त्रहरूको पठन, मनन र आत्मचिन्तन हो । कुनै पनि दिव्य ग्रन्थको अध्ययन स्वाध्याय हो । आदि शंकराचार्यले पनि शास्त्र अध्ययनलाई स्वाध्याय भन्नुभएको छ । साथै आत्मनिरीक्षण पनि स्वाध्याय नै हो । साधकले निरन्तर विचार गरिरहोस् कि गीता उसको जीवनमा कति उत्रिएको छ, उसका विचारहरूमा कति परिवर्तन आएको छ र उसको आचरणमा कति परिष्कृत भएको छ ।
त्यसपछि
तप
को वर्णन आउँछ । तपको स्वरूप केवल बाह्य कठिन साधनासम्म मात्र सीमित छैन । शीत-उष्ण जस्ता द्वन्द्वहरूको सहन, मनको संयम, सहिष्णुता र क्षमा- यी सबै तपका रूप हुन् । कसैको कटु वाणी सहनु, द्वेष उत्पन्न हुन नदिनु र प्रतिकूल परिस्थितिमा धैर्य कायम राख्नु- यी सबै तप हुन् । क्षमा पनि तपकै एक रूप हो, किनकि आत्मसंयम बिना क्षमा सम्भव हुँदैन ।
आर्जवम्‌-
सरलता, निष्कपटता र साँचो । ज्ञान, विद्वत्ता र शास्त्र अध्ययनपछि पनि यदि हृदयमा सरलताको अभाव रह्यो भने आध्यात्मिक प्रगति अपूर्ण रहन्छ । यसको उत्कृष्ट उदाहरण शबरीको चरित्रमा देखिन्छ, जसको वर्णन रामायणमा छ ।
शबरीका पिता आफ्नो समुदायका अगुवा थिए । उनी मांसाहारी थिए । शबरीको विवाहको तयारीमा उनले धेरैवटा पाठाबोकाहरू जम्मा गरेका थिए । आठ वर्षीया शबरी ती पाठाहरूका साथ खेल्थिन् । एक दिन उनका बुवाले भने, “खेल् जति खेल्न मन लाग्छ तेत्ति खेल् । तेरो विवाहको दिन यी सबै पाठाहरू काटेर पकाइनेछ ।” शबरीको मनमा एउटा विचार आयो- “मेरो कारणले यदि यी निर्दोष प्राणीहरू मारिने हुन् भने, म विवाह गर्दिनँ।” त्यस रात उनी सुत्न सकिनन् । राति नै चुपचाप घरबाट भागिन् । बिहान उनलार्इ खोज्न मानिसहरू आए, उनले देखिन् र डरले रुखमा चढिन् । दिनभरि रुखमा बसिन्, रात परेपछि ती मानिसहरू फर्किए ।
त्यसपछि उनी त्यहाँबाट भाग्न थालिन् । यसरी भाग्दाभाग्दै एकदिन उनी माटोमा लतपतिएको शरीर, झुम्रिएको कपालसहित एउटा आश्रममा पुगिन् । त्यहाँ उनले अनेक प्रकारका धार्मिक कार्यहरूमा व्यस्त शिष्यहरू देखिन् । उनले सोधिन्, “के म यहाँ बस्न सक्छु?” शिष्यहरूले उनलाई मतङ्ग ऋषिकहाँ लगे । ऋषिले सोधे, “तिमी को हौ ?” उनले भनिन्, “म शबरी हुँ, तर कृपया मेरो बुवाको बारेमा केही नसोध्नुहोस् । यदि तपाईँहरूले मलाई मेरो बुवाको बारेमा सोध्नुभयो भने मेरा सबै पाठाबोकाहरू मर्नेछन् ।” ऋषि मतङ्गले उनको भावना बुझे र उनलाई आश्रममा बस्न अनुमति दिए । त्यहाँ शबरीले कुचो लगाउने, पानी ल्याउने, लुगा, भाँडा धोइदिने आदि सबै काम गरिन् ।
एकदिन ऋषिले सबै शिष्यहरूलाई भेला गरेर भने, “म आज समाधि लिन गइरहेको छु, कसैलाई केही प्रश्न सोध्नु छ भने, सोध ।” सबै शिष्यहरूले प्रश्न गरे । अन्त्यमा शबरीले पनि लजाउँदै सोधिन्, “गुरुजी, तपाईँ मलाई केवल यत्ति भन्नुहोस्, कि भगवान् कहाँ भेटिन्छन्?” ऋषिले हाँस्दै भने, “शबरी, तिमी अत्यन्त भाग्यशाली छौ । तिमीलाई कतै जानुपर्दैन, श्रीराम स्वयं तिमीलाई भेट्न यहीँ आउनुहुनेछ ।”
त्यसपछि मनमा कुनै शङ्का नगरिकन, शबरीले नित्य भगवान्‌को प्रतीक्षा गर्न थालिन् । ऋषिले समाधि लिए । समयक्रमले सबै शिष्यहरूले एक-एक गरी आश्रम छोडेर गए । केवल शबरी मात्र त्यहीँ रहिन् । दिनहुँ कुचो लगाउँथिन् । पहिला पूर्वतिर मात्र सफा गर्थिन्, पछि याद आयो कि भगवान् त जुनसुकै दिशाबाट आउन सक्नुहुन्छ, अनि चारैतिर सफा गर्न थालिन् । रामलाई अर्पण गर्न नदीबाट जल ल्याउँथिन्, बयरको फल ल्याउँथिन् र कुनै खराब नपरोस् भनेर प्रत्येक बयर चाखेर हेर्थिन् । शबरी बूढी भइन्, तर पनि उनको श्रद्धामा कुनै कमी आएको थिएन । उनले निद्रामा पनि रामलाई कहिल्यै गुमाउन चाहिनन् । दिनरात उनी ''मेरो राम आउनुहुन्छ'' भन्दै प्रतीक्षा गरिरहिन् ।
अन्ततः एकदिन हातमा धनुष लिएका दुईजना सुकुमार आए । आज पनि आभाष मात्रै रहेछ भनेर आफैंलाई चिमोटिन् । आँखा मिचिन् र उनी चिच्याइन्- “मेरो राम आउनुभयो ।” शबरीका आँखाबाट आँसु झर्दैथिए । उनले श्रीरामको चरण धुनका लागि जल ल्याउन जानलाग्दा श्रीरामले भन्नुभयो, “शबरी, तिमीले त आफ्ना आँसुले नै मेरा चरण पखालिसकेकी छौ।”
श्रीरामले शबरीले ल्याएको बयर खानुभयो । भक्त र भगवान् खुसीले पुलकित भए । यस्तो सौभाग्य केवल शबरीलाई मात्र मिल्यो । शबरीले सोधिन्, “हे प्रभु, भक्ति भनेको के हो?” श्रीरामले मुस्कुराउँदै भन्नुहुन्छ, “जसरी तिमीले जीवन बितायौ, त्यो नै सर्वोच्च भक्ति हो । तिमीले दिनरात आफूलाई जति समर्पण गर्‍यौ, त्यो भन्दामाथि अरू केही भक्ति छैन ।” त्यसपछि श्रीरामले उपस्थित अन्य वनवासीहरूलाई पनि नवधा भक्तिका नौ अङ्गहरूबारे बताउनुभयो ।
नवधाभक्ति (नौ प्रकारका भक्ति)
श्रवण
– भगवान्‌को कथा सुन्नु ।
कीर्तन
– भगवान्‌को नाम गाउनु, स्तुति गर्नु।
स्मरण
– निरन्तर भगवान्‌लाई सम्झनु ।
पादसेवन
– भगवान्‌का चरणको सेवा गर्नु ।
अर्चना
– पुष्प, माला आदि चढाएर पूजा गर्नु ।
वन्दन
– श्रद्धापूर्वक नमस्कार गर्नु, आँसु झारेर विनम्रता देखाउनु ।
दास्य भाव
– आफू दास र भगवान् स्वामी भन्ने भाव राख्नु ।
सख्य भाव
– भगवान्‌लाई अर्जुनले झैँ माया गर्नु र अभेद्य/आत्मीय सम्बन्ध राख्नु ।
आत्मनिवेदन
– आफूलाई पूर्ण रूपमा भगवान्‌मा समर्पण गर्नु ।
“शबरी महान् भक्त थिइन्, तैपनि उनले श्रीरामसँग नवधा भक्तिका बारेमा किन सोधिन्?” भनी स्वामी गोविन्ददेव गिरिजी महाराजलाई प्रश्न गर्दा, स्वामीजीको उत्तर थियो, “यो उपदेश होइन, सम्मान-पत्र हो। सम्पूर्ण वनवासीलार्इ श्रीरामले शबरीको माध्यमद्वारा श्रद्धा, भक्ति र प्रेमको परिभाषा प्रदान गरेको प्रमाण-पत्र हो।”
16.2
अहिंसा सत्यमक्रोध:(स्), त्यागः(श्) शान्तिरपैशुनम् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (16, 2, 'KAVITA JI VERMA ', 'https://www.youtube.com/watch?v=N5pk7FAKCyw', '2026-03-28', 'मन, वचन र शरीरले कुनै प्रकारले पनि कसैलाई कष्ट नदिनु, सत्य र प्रिय बोल्नु, आफ्नो कुभलो गर्नेप्रति पनि क्रोध नगर्नु, कर्मफललाई तथा कर्ममा कर्तापनको अभिमानको त्याग गर्नु, अन्तःकरणको उपरथि अर्थात् चित्तको चञ्चलताको अभाव, कसैको पनि निन्दा नगर्नु, सबै भूतप्राणीहरूमा दयाको भाव राख्नु, तृष्णा नराख्नु, इन्द्रियहरूको विषयसँग संयोग हुँदा पनि त्यसप्रति आसक्ति नहुनु, कोमलता, लोक र शास्त्रविरुद्ध आचरण गर्न लजाउनु र फजुल कर्महरूलाई छोड्नु;
भगवान् भन्नुहुन्छ कि अहिंसा को अर्थ केवल बाह्य रूपमा कसैलाई पीडा नदिनु मात्र होइन, बरु मन, वाणी र शरीर तीनै स्तरमा कुनै पनि प्रकारको हिंसाको पूर्ण अभाव हुनु नै अहिंसा हो । यस्तो धारणा छ कि हातले प्रहार गर्नु वा वाणीबाट कटु शब्द बोल्नु नै हिंसा हो । यो आंशिक सत्य हो । वास्तविकतामा मनमा उत्पन्न हुने कुविचार, दुष्चिन्तन र कसैप्रति दुर्भावना राख्नु पनि हिंसाका रूप हुन् । श्रीमद्भगवद्गीताको चिन्तनले अत्यन्त सूक्ष्म स्तरमा आत्मावलोकनको प्रेरणा दिन्छ । यहाँ प्रयोग भएका प्रत्येक शब्दका पछाडि गहिरो अर्थ छ ।
अहिंसा
को अर्थ केवल स्थूल क्रियामा मात्र सीमित छैन, बरु सूक्ष्म भावहरूको पवित्रतासँग पनि सम्बन्धित छ । कसैप्रति मनमा पनि अशुभ विचार उत्पन्न हुनु हिंसा नै हो ।
विना कारण नै कहिलेकाँही मनमा अशान्ति, क्रोध वा उद्वेग उत्पन्न हुन्छ । यो अवस्था अदृष्ट कारणहरूसँग सम्बन्धित हुन्छ । अघिल्लो जुनीमा गरिएका सूक्ष्म स्तरका नकारात्मक कर्महरू, विशेषतः मानसिक हिंसा, पुनः प्रतिक्रियाको रूपमा आउँछन् । यसकारण मनले मलिनताको अनुभव गर्छ र कारण स्पष्ट हुन सक्दैन । साधकले केवल बाह्य आचरण मात्र होइन, अन्तःकरणको पनि शुद्धीकरण गर्ने प्रयास गरोस् । मनमा उत्पन्न हुने प्रत्येक दुर्भावनालाई त्याग्दै शुभ, कल्याणकारी र करुणामय भावहरूको विकास गरोस् । यही नै वास्तविक अहिंसाको आचरण हो ।
भगवान् भन्नुहुन्छ कि सत्य त्यो हो जसमा वाणी, विचार र आचरणको पूर्ण एकरूपता छ । जे जस्तो छ, त्यसको त्यही रूपमा प्रस्तुतीकरण नै सत्य हो । सत्यको परिभाषा अत्यन्त व्यापक छ । शास्त्रकारहरू, वेदान्ताचार्यहरू र विभिन्न ग्रन्थहरूमा यसको अनेक प्रकारले व्याख्या गरिएको छ । असंख्य श्लोक, ग्रन्थ र विचारधाराबाट पनि सत्यको पूर्ण निरूपण हुन सक्दैन । सत्यको स्वरूप अत्यन्त गूढ, सूक्ष्म र अनन्त छ । यसका प्रत्येक आयामको गहिरो चिन्तन आवश्यक छ ।
दैवीगुणहरूप्रति सजगता कायम रहोस् । प्रत्येक साधकले आफ्नो अन्तःकरणमा निरन्तर परीक्षण गरिरहोस् । कति दैवी गुणहरू जीवनमा स्थिर भइरहेका छन् । सत्प्रवृत्तिहरूको वृद्धि भइरहुन् । यस आत्मचिन्तनबाट स्पष्ट हुन्छ कि साधक क्रमशः देवत्वतर्फ अग्रसर हुन्छ । दैवी गुणहरूको अभ्यासले जीवनमा पवित्रता, शुद्धता र आन्तरिक उन्नतिको मार्ग प्रशस्त गर्छ । त्यसैले प्रत्येक साधकको कर्तव्य हो कि उसले यी गुणहरूलाई आफ्नो आचरणमा ल्याउँदै निरन्तर आत्मविकासको दिशामा अघि बढिरहोस् ।
अन्तमा, हरि कीर्तन र हनुमान चालिसा श्रवण गर्दै सोह्रौँ अध्यायको पहिलो खण्डको विवेचन समापन गरियो ।
॥ॐ श्रीकृष्णार्पणमस्तु॥
यो विवेचन पढेर तपाईँलाई अवश्य पनि राम्रो लाग्यो होला भन्ने हामीलाई विश्वास लागेको छ । कृपया तल दिएको लिङ्क प्रयोग गरी हामीलाई आफ्नो प्रतिक्रियाहरू दिनुहोला ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 23, 'ŚRĪ SRINIVAS WARNEKAR JI', 'https://www.youtube.com/watch?v=VlV1RQdajs0', '2026-03-22', 'हे महाबाहो! हजुरका धेरै मुख र नेत्रहरू, धेरै हातहरू, धेरै जाँघ र खुट्टाहरू, धेरै पेट र धेरै नै दाह्राका कारण विकराल रूपलाई देखेर सबै लोकहरू व्याकुल भइरहेका छन् र साथै म पनि अति व्याकुल भइरहेको छु ।
अर्जुनले जुन विराटरूप देखे त्यस विराट रूपमा धेरै मुख, आँखा, हातहरू, जाँघ, पाऊ, ठूलो पेट (भुँडी), ठुलाठूला दाँतहरू (दाह्राहरू) थिए । जसलाई देखेर अर्जुन व्याकुल (डराइरहेका, डरले काँपिरहेका) भैरहेका थिए । ति दाह्राले सारा संसारका प्राणिहरूलाई चपाइरहेको थियो । अर्जुन आफू त डराए डराए उनि सारा लोक लोकान्तर नै त्यस डरमा परेको अनुभव गरि रहेका थिए । अर्जुनलाई लाग्यो यस्तो रूप देखेर म मात्र होइन संसारका सारा प्राणिहरू भयभित भैरहेका छन् । यस विषयमा ज्ञानेश्वर महाराज भन्नुहुन्छ, “अर्जुन यो भयङ्कर रूप देखेर म मात्र होइन सबै लोक डरले काँपिरहेको छ । तर अर्जुन कसैसँग नडराउने पात्र हुन्” ।
अर्जुनको परिक्षा लिन र अर्जुनलाई वरदान दिन भगवान शिव (पशुपति नाथ) स्वयम् भिल्ल (शिकारी) को रूप लिएर आउनु भयो । एउटा बदेल अर्जुनको तपस्या भङ्ग गर्न आयो र अर्जुनलाई दुःख दिन थाल्यो तब अर्जुनले त्यस बदेललाई शस्त्र चलाएर मार्नुभयो त्यहि समयमा भिल्लले पनि बाण चलाएको थियो । शिकारमा दुबै दावा गरी अर्जुन र भिल्लको लडाइभयो ।
जब साँझ पर्‍यो, तब अर्जुनले भने मेरो संध्याको समय भयो एकै झिन युद्ध रोकौँ । युद्ध रोकेर जुन फूल अर्जुनले शिवलाई चढाएका थिए त्यो त भिल्ल भए ठाउँमा पुग्थ्यो तब अर्जुनले थाहा पाए यि त साक्षतः शिव हुन् र भिल्लका पाउ परे तव शिव प्रशन्न हुनुभो र वरदान दिनुभो, पाशुपतास्त्र दिनुभयो । यस्ता वीर अर्जुन पनि भगवानको विश्वरूप देखेर तर्सिए ।
11.24
नभःस्पृशं(न्) दीप्तमनेकवर्णं(म्),
व्यात्ताननं(न्) दीप्तविशालनेत्रम् ।
दृष्ट्वा हि त्वां(म्) प्रव्यथितान्तरात्मा,', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 24, 'ŚRĪ SRINIVAS WARNEKAR JI', 'https://www.youtube.com/watch?v=VlV1RQdajs0', '2026-03-22', 'किनकि हे विष्णो! हजुर आकाशलाई स्पर्श गर्ने, देदीप्यमान, अनेक वर्णले युक्त तथा सबैतिर फैलिएका मुख र प्रकाशमान विशाल नेत्रहरूले युक्त हजुरलाई देखेर भयभीत अन्तःकरणसहितको मैले धैर्य र शान्ति अनुभव गर्न सकिरहेको छैन ।
त्यो विश्वरूप (विराटरूप) कस्तो थियो भने जसले आकाशलाई छोएको, देदिप्यमान (चम्किलो प्रकाशले प्रकाशित), अनेक वर्णलेयुक्त फराकिलो मुहार (अनुहार), चम्किला ठूला आँखाहरूले युक्त थियो । अर्जुन यहाँ भन्छन्, “हे विष्णु! हजुरको यस रूपलाई देखेर म डराइरहेको छु । मेरो अन्तःकरण काँपिरहेको छ । मैले धैर्य र शान्ति महसुस गर्न सकेको छैन” । अर्जुनले सोचेका थिए कि विराटरूपलाई देखेर आनन्द आउला तर
भयो उल्टो । त्यस रूपलाई देखेपछि उनको धैर्य उड्यो, शान्ति पनि प्राप्त भएन ।
11.25
दंष्ट्राकरालानि च ते मुखानि,
दृष्ट्वैव कालानलसन्निभानि ।
दिशो न जाने न लभे च शर्म,', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 25, 'ŚRĪ SRINIVAS WARNEKAR JI', 'https://www.youtube.com/watch?v=VlV1RQdajs0', '2026-03-22', 'भयङ्कर दाह्राका कारण विकराल प्रलयकालको अग्निजस्तै प्रज्वलित हजुरको मुखलाई देखेर म दिशाहरू पनि चिन्दिनँ र सुख पनि पाउँदिनँ । यसर्थ, हे देवेश! हे जगन्निवास! हजुर प्रसन्न हुनुहोस् ।
ठूलाठूला दाह्राका (दाँतका) कारण प्रलयकालको अग्नि झैँ दन्किरहेको हजुरको मुखलाई देखेर म भ्रमित भैसकेँ । हजुरको मुख कालरूपि अग्नि समान प्रज्वलित भैरहेको छ । यस्तो विकराल मुख्दा देखाए मैले दिशाहरू (पूर्व, पश्चिम, उत्तर, दक्षिण) छुट्याउन सकिन । तसर्थ हे देवेश (देवताका पति ईश्वर), हे जगत्‌को निवास-स्थान, हे जगत्‌मा व्याप्त प्रभु मसँग खुसी हुनुहोस्, मसँग प्रशन्न हुनुहोस् भनि अर्जुन प्रार्थना गर्न लागे ।
11.26
अमी च त्वां(न्) धृतराष्ट्रस्य पुत्राः(स्),
सर्वे सहैवावनिपालसङ्घैः ।
भीष्मो द्रोणः(स्) सूतपुत्रस्तथासौ,', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 26, 'ŚRĪ SRINIVAS WARNEKAR JI', 'https://www.youtube.com/watch?v=VlV1RQdajs0', '2026-03-22', 'धृतराष्ट्रका ती सबै पुत्रहरू, राजाहरूको समुदायसहित भीष्मपितामह, द्रोणाचार्य र कर्ण र हाम्रो पक्षका मुख्य-मुख्य योद्धाहरू पनि हजुरको विकराल र भयानक दाह्रायुक्त मुखमा बडो वेगले प्रवेश गरिरहेका छन् ।
11.26 writeup
11.27
वक्त्राणि ते त्वरमाणा विशन्ति,
दंष्ट्राकरालानि भयानकानि ।
केचिद्विलग्ना दशनान्तरेषु,', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 27, 'ŚRĪ SRINIVAS WARNEKAR JI', 'https://www.youtube.com/watch?v=VlV1RQdajs0', '2026-03-22', 'हजुरको विकराल र भयानक दाह्रायुक्त मुखमा बडो वेगले प्रवेश गरिरहेका ती सबै योद्धाहरूमा कति त चूर्ण भएका शिरहरूसहित हजुरका दाँतका बिचमा फँसेका पनि देखिन्छन् ।
अमी च त्वां(न्) धृतराष्ट्रस्य पुत्राः(स्), सर्वे सहैवावनिपालसङ्घैः
- अर्जुन देख्छन्, धृतराष्ट्रका सबै पुत्रहरू, भीष्मपितामह, द्रोणाचार्य, कर्ण, सबै राजाहरू- सबै भगवानको भयानक मुखमा पसिरहेका छन् केवल कौरव पक्षका मात्र होइन, पाण्डव पक्षका धेरै सेनापतिहरू पनि त्यसै मुखभित्र पसिरहेका देखिन्छन् ।
वक्त्राणि ते त्वरमाणा विशन्ति
- अर्जुन भन्छन् कि सबै मनुष्यहरू तीव्र गतिमा भयानक मुखहरूमा दौडिँदै प्रवेश गरिरहेका छन् ।
किचिद्विलग्नादशनान्तरेषु:
- हजुरको दाँतको अन्तरमा केही मनुष्यहरू अडकिएको देखिरहेको छु । हजुर सबैलाई चपाई-चपाई खाइराख्नुभएको छ ।
सन्दृश्यन्ते चुर्णितैरुत्तमाङ्गै:
- हजुरको दाँतको बीचमा उत्तम अङ्ग (टाउको) किचिएर अड्किएको पनि राम्रोसँग देखिरहेको छु ।
अर्जुनले देख्छन् कि भगवान्‌को विश्वरूपले सबैलाई आफ्नै आहारा जस्तो ग्रहण गरिरहेका छ र सबैलाई चूर्ण पारिरहेको छ, अब यहाँ प्रश्न उठ्छ कि सबै योद्धाहरू युद्धभूमिमा अझै जीवित छन्, भने यस्तो दृश्य कसरी देखियो?
इहैकस्थं(ञ्) जगत्कृत्स्नं(म्), पश्याद्य सचराचरम् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 7, 'ŚRĪ SRINIVAS WARNEKAR JI', 'https://www.youtube.com/watch?v=VlV1RQdajs0', '2026-03-22', 'हे अर्जुन! मैले यस विश्वरूपमा सम्पूर्ण चराचर जगतलाई एकै ठाउँमा देखेँ । तिमीले जे देख्न चाहन्छौ, भूत, वर्तमान र भविष्य-सबै यसै रूपभित्र देख्न सक्छौ । भगवान् स्पष्ट पार्नुहुन्छ कि सम्पूर्ण ब्रह्माण्ड चर- अचर सबै विश्वरूपमा समाहित छ । यो रूप समय र स्थानबाट माथि भएकाले नै अर्जुनले भूत वर्तमान र भविष्य सबै देख्न सके। अर्जुनले आफ्नो विजय पनि देख्न सक्थे । तर आफ्नै आफन्तहरूको विनाश देख्दा उनी दुःखी हुन्थे ।
11.28
यथा नदीनां(म्) बहवोऽम्बुवेगाः(स्),
समुद्रमेवाभिमुखा द्रवन्ति ।
तथा तवामी नरलोकवीरा,', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 28, 'ŚRĪ SRINIVAS WARNEKAR JI', 'https://www.youtube.com/watch?v=VlV1RQdajs0', '2026-03-22', 'जसरी नदीहरूका प्रशस्त जलका प्रवाहहरू स्वाभाविकरूपमा समुद्रकै मुखतिर दौडन्छन्, अर्थात् समुद्रमा प्रवेश गर्दछन्, त्यसैगरी ती नरलोकका वीरहरू पनि हजुरका प्रज्ज्वलित मुखहरूमा प्रवेश गरिरहेका छन् ।
अघिल्लो श्लोकमा अर्जुनले भनेका थिए, सबै आफन्तहरू तीव्र रूपमा भगवान्‌को मुखमा पसिरहेका छन् । यहाँ उनले त्यसलाई उदाहरणद्वारा स्पष्ट गर्दछन् । नदी र समुद्रको उदाहरण दिँदै धेरैजसो नदीहरू गुरुत्वाकर्षणका कारण तलतिर बग्छन् र अन्तत समुद्रमा गएर मिसिन्छन् । यो प्रवाह एकतर्फी हुन्छ । नदीको अन्तिम गन्तव्य नै समुद्रमा मिसिनु हो ।
जसरी नदीहरू समुद्रमा मिसिन्छन् त्यसरी नै ती महान योद्धाहरू तपाईँका ज्वालामुखिरूपि मुखहरूमा प्रवेश गरिरहेका छन् । यो प्रकृतिको एक अवश्यम्भावी प्रक्रिया हो ।
तथा तवामी नरलोकवीरा
- संसारका सबै वीर योद्धाहरू तपाईँको मुखमा प्रवेश गरिरहेका छन् ।
विशन्ति वक्त्राण्यभिविज्वलन्ति
- तपाईँका मुखहरू तेजस्वी र ज्वलन्त छन् र ती भित्र सबै समाहित भइरहेका छन् ।
11.29
यथा प्रदीप्तं(ञ्) ज्वलनं(म्) पतङ्गा,
विशन्ति नाशाय समृद्धवेगाः ।
तथैव नाशाय विशन्ति लोका:(स्),', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 29, 'ŚRĪ SRINIVAS WARNEKAR JI', 'https://www.youtube.com/watch?v=VlV1RQdajs0', '2026-03-22', 'जसरी पुतलीहरू मोहवश नष्ट हुनका लागि अति वेगले दौडँदै प्रज्वलित अग्निमा प्रवेश गर्दछन्, त्यसैगरी ती सबैजना पनि आफूलाई नष्ट पार्नका लागि अतिवेगले दौडँदै हजुरका मुखमा प्रवेश गर्दैछन् ।
अर्जुनले एउटा विचलित पार्ने दृश्य देखे । जसरी पतङ्गले दन्किरहेको आगोमा आफूलाई भस्म गर्छ, त्यसरी नै सम्पूर्ण सेनाका योद्धाहरू पनि परम् भगवानको विशाल मुखमा प्रवेश गरे । जसरी ज्वलन्त वनको ज्वालाले सबै रूखहरू र त्यसमा बस्ने जीव तथा किट-पतङ्गहरूलाई नष्ट गर्छ, त्यसरी नै अर्जुनले विराटरूपमा त्यस्तै दृश्य देखे ।
11.30
लेलिह्यसे ग्रसमानः(स्) समन्ताल्,
लोकान्समग्रान्वदनैर्ज्वलद्भिः ।
तेजोभिरापूर्य जगत्समग्रं(म्),', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 30, 'ŚRĪ SRINIVAS WARNEKAR JI', 'https://www.youtube.com/watch?v=VlV1RQdajs0', '2026-03-22', 'हजुरले आफ्नो प्रज्वलित मुखहरूले ती सम्पूर्ण लोकहरूलाई गाँस बनाएर सबैतिरबाट बारम्बार चाटिरहनुभएको छ । हे विष्णु! हजुरको उग्र प्रकाशले सम्पूर्ण जगत्‌लाई तेजका माध्यमले परिपूर्ण तुल्याई सन्तप्‍त गर्दैछ ।
भगवान् कृष्णले अर्जुनलाई आफ्नो विशाल रूप प्रकट गर्नुहुन्छ, तर त्यो दृश्य देख्दा उनलाई डर लाग्छ । भगवान् कृष्णको यस्तो विराटरूपको कल्पना पनि कसैले गर्न सक्दैन । यस्तो दृश्यको वर्णन गर्दै अर्जुन भन्छन् कि जसरी खाना खाँदा जसरी एक-एक गाँस मुखमा हालिन्छ त्यसरी नै भगवान् कृष्णले आफ्नो मुखमा हालेर सम्पूर्ण ब्रह्माण्डका जीवलाई निल्दै हुनुहुन्थ्यो । उहाँले आफ्नो ओठमा बाँकी रहेको अवशेषलाई पनि आफ्नो जिब्रोले चाट्दै हुनुहुन्थ्यो ।
तेजोभिरापूर्य जगत्समग्रं
- तपाईँको तेजले सम्पूर्ण ब्रह्माण्डलाई व्याप्त र तताएको छ ।
भासस्तवोग्राः प्रतपन्ति विष्णो:
- अर्जुनले हजारौँ सूर्यको तेज जस्तै भयंकर तेजको अनुभव र वर्णन गरिरहेका छन् ।
11.31
आख्याहि मे को भवानुग्ररूपो,
नमोऽस्तु ते देववर प्रसीद ।
विज्ञातुमिच्छामि भवन्तमाद्यं(न्),', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 31, 'ŚRĪ SRINIVAS WARNEKAR JI', 'https://www.youtube.com/watch?v=VlV1RQdajs0', '2026-03-22', 'मलाई कृपा गरेर बताउनोस् कि उग्ररूप भएका हजुर को हुनुहुन्छ? हे देवताहरूमा श्रेष्ठ! हजुरलाई नमस्कार छ । हजुर प्रसन्न हुनुहोस् । आदिपुरुष हजुरलाई म विशेषरूपले जान्न चाहन्छु, किनकि म हजुरको प्रवृत्तिलाई भलीभाँति जान्दिनँ ।
यस अत्यन्त भयावह दृश्यलाई देखेर श्रेष्ठ धनुर्धर अर्जुन पनि भयभीत हुन्छन् । उनी आफ्ना सखा र गुरु श्रीकृष्णको यस अपरिचित रूपलाई चिन्न सकिरहेका छैनन् । उनी प्रार्थना गर्दै सोध्छन्, “हे भगवान्! कृपा गरेर मलाई बताउनुहोस् कि यो उग्र रूप धारण गर्ने तपाईँ को हुनुहुन्छ? म तपाईँलाई सादर प्रणाम गर्दछु । हे देववर! ममाथि प्रसन्न हुनुहोस् । म तपाईँको यस
आद्यम्
(आदि रूप) लाई तत्त्वबाट जान्न चाहन्छु किनकि म तपाईँको यस संहारकारी
प्रवृत्तिम्
(चेष्टा) लाई बुझ्न असमर्थ छु” ।
आफ्नो व्याकुलतालाई शान्त पार्न अर्जुन भगवान्‌को शरणमा जान्छन् र प्रार्थना गर्छन्-
प्रसीद देवेश जगन्निवास, हे देववर प्रसीद ।
यहाँ प्रसीद शब्द अत्यन्त महत्त्वपूर्ण छ । यसको अर्थ हो- प्रसन्न हुनुहोस् । व्याकरणको दृष्टिले यो आज्ञार्थक शब्द हो जसलाई भक्तले भगवान्‌सँग कृपाको याचना गर्न वा विनम्र निवेदन गर्न प्रयोग गर्छ ।
अर्जुन भगवान् लाई
देवेश
(देवहरूका ईश्वर),
जगन्निवास
(जगतको आधार) र
देववर
(श्रेष्ठ देव) भनेर सम्बोधन गर्छन् । उनी भगवान्‌सँग आग्रह गर्छन् कि आफ्नो यस विकराल रूपलाई शान्त पार्नुहोस् र उनीमाथि आफ्नो कृपाको प्रसाद (अनुग्रह) वर्षाउनुहोस् । अर्जुन भगवान् को सामु आफ्नो जिज्ञासा व्यक्त गर्दै भन्छन्-
विज्ञातुमिच्छामि भवन्तमाद्यं न हि प्रजानामि तव प्रवृत्तिम् ॥
भवन्तम् आद्यम्
- तपाईँ यस विश्वका आदि पुरुष हुनुहुन्छ । अर्जुन सन्देहमा छन् कि के यो विकराल रूप धारण गर्ने उहाँ नै ती आदि पुरुष हुनुहुन्छ जसको महिमा वेदहरूमा गाइएको छ । उनी विनम्रतापूर्वक भन्छन्, “म तपाईँलाई तत्त्वबाट, पूर्ण रूपमा जान्न चाहन्छु ।
विज्ञातुम् इच्छामि
- तपाईँको यो वर्तमान स्वरूप मेरो बुद्धिको सीमाभन्दा बाहिर छ” ।
अर्जुन विचलित हुनुको मुख्य कारण भगवान्‌को
प्रवृत्ति
(चेष्टा) हो । उनी भन्छन्, “तपाईँ कुन उद्देश्यले यस संहारकारी कार्यमा प्रवृत्त हुनुभएको छ? तपाईँको यस गतिविधिको लक्ष्य के हो? यो सबै कुरा मैले बुझिरहेको छैन” । अर्जुन यहाँ त्यो कार्यकारण सम्बन्ध खोजिरहेका छन् जसको वशीभूत भएर प्रेममय श्रीकृष्ण आज साक्षात् कालको रूपमा उभिनुभएको छ । उनी भगवान्‌सँग प्रार्थना गर्छन् कि उहाँले उनलाई यस द्विविधाबाट मुक्त गर्नुहोस् र आफ्नो योजनाको स्पष्ट सङ्केत दिनुहोस् ।
11.32
श्रीभगवानुवाच
कालोऽस्मि लोकक्षयकृत्प्रवृद्धो,
लोकान् समाहर्तुमिह प्रवृत्तः ।
ऋतेऽपि त्वां(न्) न भविष्यन्ति सर्वे,', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 32, 'ŚRĪ SRINIVAS WARNEKAR JI', 'https://www.youtube.com/watch?v=VlV1RQdajs0', '2026-03-22', 'श्रीभगवान्‌ले भन्नुभयो- म सम्पूर्ण लोकको नाश गर्न अगाडि बढेको महाकाल हुँ र यतिबेला म यी लोकहरूलाई नष्ट गर्नकालागि प्रवृत्त भएको छु । तिम्रो प्रतिपक्षका सेनाहरूमा जो योद्धाहरू उभिएका छन्, ती सबै तिमी नभए पनि रहँदैनन् अर्थात् तिमीले युद्ध नगरे पनि ती सबैको नाश हुनेछ ।
भगवान् भन्नुहुन्छ- सम्पूर्णजगतलाई नष्ट गर्ने काल (भूत, वर्तमान र भविष्य) म नै हुँ । काल भनेको समय हो यो समयअनुसार सबैको नष्ट अवश्यम्भावी छ । मैले समय आएपछि सबैको नष्ट गर्दछु र अविनाशी केही र कोही पनि छैन । अर्जुन तिमीले कसैलाई नमारे पनि समय आएपछि ती सबै योद्धाहरू स्वत: मर्नेछन् ।
कालोऽस्मि
- काल म हुँ । सबैलार्इ समाप्त गर्ने काल मै हुँ । लोकक्षय गर्नका लागि नै यो विराट स्वरूप रहेको हो ।
श्रृतेपि त्वान् न भविष्यन्ति सर्वे
- यी भविष्यमा कुनै पनि रहनेवाला छैनन् ।
11.33
तस्मात्त्वमुत्तिष्ठ यशो लभस्व,
जित्वा शत्रून् भुङ्क्ष्व राज्यं(म्) समृद्धम् ।
मयैवैते निहताः(फ्) पूर्वमेव,', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 33, 'ŚRĪ SRINIVAS WARNEKAR JI', 'https://www.youtube.com/watch?v=VlV1RQdajs0', '2026-03-22', 'यसकारण, तिमी युद्धका निमित्त खडा होऊ र यश प्राप्‍त गरी शत्रुहरूलाई जितेर धनधान्यले सम्पन्न राज्यलाई भोग गर । यी सबै शूरवीरहरू मबाट पहिले नै मारिइसकेका छन् । हे सव्यसाचिन् (बायाँ हातले पनि बाण चलाउन सक्ने) अर्जुन! तिमी, यिनीहरूलाई मार्नकालागि केवल निमित्त मात्र बन ।
त्यसैले अर्जुन तिमी उठ र युद्धमा लाग । आफ्ना शत्रुलाई जित र यश प्राप्त गर । सम्पन्न राज्यको सुख भोग गर । हे
सव्यसाचिन्
- निसान नचुक्ने वीर योद्धा अर्जुन, तिमी यो युद्धमा माध्यम त बन किनकी मद्वारा सबै योद्धाहरू मारिईसकेका छन् । सबै मरेका छन् । तिमीले मारेको अहङ्कार नगर मैले सबैलाई मारिसकेको छु । यस सम्वन्धमा विज्ञानका छात्रहरू भन्छन् भविष्यका कुरा कसरी थाहा हुन्छ र पत्याउदैनन् । किनकि काल (समय) नै म हुँ । समय र प्रकाश सम्वन्धमा आइन्टाइनले रेलको उदाहरण दिएका छन् । एउटा यति लामो रेलको कल्पना गरिएको थियो जसको डिव्वामा प्रकाश पुग्न दुई महिना लाग्थ्यो ।
भगवान सर्वत्र हुनुहुन्छ यो भैरहेको छ र यो हुनेवाला छ भन्ने कुरा भगवान्‌लाई पहिले नै थाहा हुन्छ किनकी भगवान्‌ले सवैतिर देख्नुहुन्छ । यी सबै एकैपटक देख्न भगवत् शक्ति चाहिन्छ भगवान्‌लाई प्रकाश कहाँ छ र कसरी त्यो आउदैछ भन्ने भविष्यका कुरा थाहा हुन्छ । आकाशमा भएका कुनैकुनै ताराको प्रकाश पृथ्विमा आईपुग्न हजारौँ वर्ष लाग्नसक्छ । त्यसैले उहाँले भविष्यका कुरा पहिले नै थाहा पाएर सहि बताउनु भएको हो किनकी उहाँलाई ताराको प्रकाश पृथ्विमा आउदैछ भन्ने कुरा पहिले नै देखिसक्नु भएको हुन्छ ।
11.34
द्रोणं(ञ्) च भीष्मं(ञ्) च जयद्रथं(ञ्) च,
कर्णं(न्) तथान्यानपि योधवीरान् ।
मया हतांस्त्वं(ञ्) जहि मा व्यथिष्ठा,', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 34, 'ŚRĪ SRINIVAS WARNEKAR JI', 'https://www.youtube.com/watch?v=VlV1RQdajs0', '2026-03-22', 'द्रोणाचार्य र भीष्मपितामह तथा जयद्रथ र कर्ण तथा अरू पनि धेरै मद्वारा मारिएका शूरवीर योद्धाहरूलाई तिमी मार । तिमी नडराऊ; निःसन्देह युद्धमा तिमीले वैरीहरूलाई जित्नेछौ, त्यसैले युद्ध गर ।
अर्जुनको मनमा गहिरो सन्देह थियो कि धृतराष्ट्रका पुत्रहरूलाई जित्नु सम्भव भए पनि भीष्म पितामह, आचार्य द्रोण, कर्ण र जयद्रथजस्ता महारथीहरूलाई परास्त गर्नु असम्भव छ । भीष्मलाई इच्छा-मृत्युको वरदान प्राप्त थियो, द्रोणाचार्य अस्त्रविद्याका साक्षात् आचार्य थिए र कर्णसँग अमोघ अस्त्रहरू थिए । मानवीय दृष्टिले यी सबै अपराजेय थिए । भगवान् यस मानसिक बाधालाई तोड्दै स्पष्ट गर्नुहुन्छ कि यी सम्पूर्ण योद्धाहरू
मया हतान्
- मद्वारा पहिले नै मारिइसकेका छन् । जो कालको विधानमा मरेका छन्, तिनीहरूलाई केवल भूमिमा गिराउन अर्जुन निमित्त मात्र हुन् ।
मा व्यथिष्ठा
- व्यथा र भयको निवारण । भगवान् अर्जुनलाई आदेश दिनुहुन्छ- व्यथित नहोऊ । अर्जुनको व्यथा दोहोरो थियो; एकातिर आफ्नाहरूलाई गुमाउने शोक र अर्कोतिर गुरुजनमाथि बाण चलाउने पापबोध । भगवान् बोध गराउनुहुन्छ कि जसरी जादुगरले कठपुतलीका डोरी काटेपछि त्यो निश्चल हुन्छ, त्यसैगरी यी योद्धाहरूको जीवनसूत्र (चेतना) भगवान्‌ले पहिले नै काटिसक्नुभएको छ । अब यी केवल शरीर मात्र बाँकी छन् । शोक र भय त्यागेर युद्धका लागि तयार हुनु नै एकमात्र मार्ग हो ।
भगवान् उद्घोष गर्नुहुन्छ-
जेतासि रणे सपत्नान्
। तिमी निश्चित रूपमा रणभूमिमा आफ्ना शत्रुहरू (सपत्नान्) माथि विजय प्राप्त गर्नेछौ । जब संहारको आधार स्वयं परमात्माले तयार गरिसक्नुभएको छ, तब विजयको मार्गमा कुनै बाधा बाँकी रहँदैन । यही विश्वासले कर्मयोगीलाई अजेय बनाउँछ । सफलताको निश्चितताको यो भावले मानिसलाई समर्पण र निष्ठासहित आफ्नो कर्तव्य पूरा गर्ने ऊर्जा दिन्छ ।
जापानमा एक जना राजा थिए, उनको राज्यमाथि अचानक आक्रमण भयो । अत्यन्त ठूलो आक्रमण भयो र आक्रमण गर्ने राजा यति शक्तिशाली थिए कि उनलाई अब लाग्न थाल्यो कि हारिने भइयो । उनका मुख्य सेनापति पनि मारिए । अब उनलाई थाहा भयो कि अब त म केही गर्न सक्दिनँ । मेरो सेनापति पनि छैन । सम्पूर्ण सेना निराश भयो । उनी सोच्न थाले अब केही सम्भव छैन, हामी कसरी युद्ध गर्ने? जब राजाले आफ्नो सेनापतिलाई गुमाए र शत्रुको शक्तिशाली बलका अगाडि आफूलाई असहाय पाए, तब एक तेजस्वी संन्यासीको आगमन भयो । राजाको व्यथा सुनेर संन्यासीले शान्त भावले भने, “राजन्, तपाईँ चिन्ता नगर्नुहोस् । यदि तपाईँ अनुमति दिनुहुन्छ भने यस सेनाको नेतृत्व म गर्छु र विजय हाम्रो नै हुनेछ” ।
राजा सुरुमा अचम्ममा परे कि एक संन्यासीले युद्ध कसरी लड्लान्, तर उनीसँग अर्को विकल्प पनि थिएन । राजाको सहमति पाएपछि त्यस तेजस्वी संन्यासीले योद्धाको भेष धारण गरे । संन्यासीको त्यो ओजस्वी र तेजस्वी रूप देखेर राजाले सम्पूर्ण सेनाका सामु घोषणा गरे, “सैनिकहरू, हामीले यो युद्ध जित्नका लागि लड्नुपर्छ र हाम्रो विजय निश्चित छ!” निराश सैनिकहरूको मनमा सन्देह उत्पन्न भयो, “हाम्रो सेनापति त मारियो, अनि हाम्रो विजय कसरी सम्भव हुन्छ?”
संन्यासीले उनीहरूको द्विविधा बुझेर भने, “यदि तपाईँहरूलाई ममाथि विश्वास छैन भने आउनुहोस्, त्यो विशाल मन्दिरमा जाऔँ र साक्षात् भगवान्‌सँगै सोधौँ कि विजय कसको हुनेछ” । मन्दिरमा पुगेर संन्यासीले प्रार्थना गरे र एउटा सिक्का निकालेर सैनिकहरूलाई भने, “म यो सिक्का उछाल्छु र गाई कि त्रिशुल गर्छु । यदि यसमा गाई पर्‍यो भने बुझ्नु कि भगवान् हाम्रो साथमा हुनुहुन्छ र विजय हाम्रो नै हुनेछ” ।
संन्यासीले सिक्का उछाले र गाई पर्‍यो । सैनिकहरूको अनुहार उज्यालो भयो तर एकजनाले सन्देह गर्‍यो, “महाराज, एकपटकमै कसरी विश्वास गर्ने? के तपाईँ यसलाई दुईपटक अझै देखाउन सक्नुहुन्छ?” संन्यासीले फेरि सिक्का गाई कि त्रिशुल गरे, दोस्रोपटक पनि गाई पर्‍यो । सेनाको उत्साह बढ्न थाल्यो । जब तेस्रोपटक सिक्का उछालियो र फेरि पनि गाई नै पर्‍यो, तब सेनाको विश्वास झन् अडिग बन्यो कि अब त साक्षात् ईश्वर हाम्रो साथमा हुनुहुन्छ । यही प्रबल
वीजिगीषु वृत्ति
(विजयको अदम्य इच्छा) सँगै सेना शत्रुमाथि झम्टियो र जित हासिल गरे ।
सैनिकहरूको मनमा उठेको यो सन्देह हाम्रो विजय कसरी सम्भव हुन्छ? एक स्वाभाविक मानवीय दुर्बलता हो । संन्यासीले यस सन्देहलाई तर्कले होइन, श्रद्धाबाट समाधान गर्ने निर्णय गरे । मन्दिर जानु र भगवान्‌सँग सङ्केत माग्नु, सामूहिक चेतनालाई उच्च शक्तिसँग जोड्ने प्रयास थियो । यो यस कुराको प्रतीक हो कि जब मानिसको आफ्नै विश्वास डगमगाउँछ, तब उसलाई दैवीय आधारको आवश्यकता पर्छ ।
सिक्कालाई एकपटक होइन, तीनपटक उछाल्नु र तीनैपटक सकारात्मक परिणाम (गाई) आउनु, अनिश्चिततालाई दृढ विश्वासमा रूपान्तरण गर्ने प्रक्रिया थियो । साङ्ख्यिकीय दृष्टिले यो असम्भव देखिन सक्छ, तर सैनिकहरूका लागि यो ईश्वरको प्रत्यक्ष आशीर्वाद बन्यो । यही अटल विश्वासबाट उत्पन्न भएको विजयको अदम्य इच्छाले सेनाभित्र त्यस्तो साहस जागृत गर्‍यो, जसले अन्ततः अजेय शत्रुलाई पनि परास्त गर्‍यो । मानिसको जीवनमा सफलताका लागि एउटा ठूलो विश्वास आवश्यक हुन्छ- म जुन कार्य गरिरहेको छु, त्यसमा भगवान् मेरो साथमा हुनुहुन्छ । जब यो बोध हामीभित्र गहिरो र दृढ हुन्छ, तब कार्यसिद्धि निश्चित हुन्छ । हामीले आफ्ना प्रत्येक कर्मलाई व्यक्तिगत कार्य नसम्झी भगवत्-कार्यका रूपमा ग्रहण गर्नुपर्छ ।
यही भावलाई जीवनमा उतार्न स्वामीजी बिहान उठेर यस विशेष प्रार्थनालाई हृदयदेखि आत्मसात् गर्न निर्देशन दिनुहुन्छ:
कर प्रणाम तेरे चरणों में,
लगता हूँ अब तेरे काज।
पालन करने को आज्ञा तब,
मैं नियुक्त होता हूँ आज ।
यो पद्य शब्द मात्र होइन, शरणागतिको मन्त्र हो । जब हामी भगवान्‌को चरणमा प्रणाम गरेर यो स्वीकार गर्छौँ कि आज दिनभर म जे काम गर्नेछु, त्यो तपाईँकै काम हो र म तपाईँको आज्ञा पालन गर्न नियुक्त भएको छु, तब हाम्रो कर्मको गुणस्तर परिवर्तन हुन्छ । जब हामी आफूलाई भगवान्‌का निमित्त मान्छौँ, तब हाम्रो कर्ममा आउने दोष, अहङ्कार र त्रुटिहरू आफैँ हट्न थाल्छन् । यस्तो भाव हुँदा कुनै पनि अनुचित कार्य हामीबाट हुन सक्दैन ।
धेरैपटक यो प्रश्न उठ्छ कि यदि सबै कुरा ईश्वरले नै गर्ने हो भने मेरो आवश्यकता किन? यसको उत्तर यो हो कि यस दिव्य योजनालाई पूर्ण गर्न भगवान् ले हामीलाई छान्नुभएको छ । ईश्वरको महान् कार्यमा आफ्नो सानो पुष्प (योगदान) अर्पण गर्ने प्रयास नै वास्तविक आनन्द हो । जब हामी यस्तो समर्पण भावले कर्म गर्छौँ, तब हामी सच्चिदानन्दको साक्षात् अनुभूति प्राप्त गर्छौँ ।
प्रश्नोत्तर
प्रश्नकर्ताः
- सिमा दिदी
प्रश्नः-
भगवानले डरलाग्दो भयानक रूप किन देखाउनुभयो ?
उत्तरः-
जब अर्जुनले भगवानको बिश्वररूप दर्शन गर्ने इच्क्षा व्यक्त गरे तव उहाँले यो रूप देखाउनुभयो । अर्जुनको मनमा रहेका केही डर पिडा अहङ्कार र चिन्तको नाश गर्नका लागि पनि यो स्वरूप देखाउनु भएको हो ।
प्रश्नकर्ताः
- विद्यासागर भैया
प्रश्नः
- हामी पढ्छौँ कि अर्जुन भगवान्‌का अत्यन्त प्रिय मित्र थिए । उनी धेरै ठूला राजा थिए र भगवान्‌का प्रिय शिष्य थिए, उनी नरोत्तम थिए । उनले स्वयम् भगवान्‌का मुखबाट गीताजी सुनेका थिए । यति सबै हुँदाहुँदै पनि उनलाई गोलोकको प्राप्ति किन भएन?
उत्तरः
- भगवान्‌को लोकको प्राप्तिलाई यसरी बुझ्नुपर्छ कि भगवान् त यहीँ हाम्रो साथमा हुनुहुन्छ । मानिसलाई यो ज्ञान हुनु आवश्यक छ कि यो सम्पूर्ण संसार भगवान् कै हो । यस ज्ञानको अवस्थालाई प्राप्त गर्न हामीले भक्ति मार्गमा हिँड्नुपर्छ । हामी भगवान्‌ कै अँश हौँ र उहाँसँग एकरूप हुनका लागि हामीले प्रयास गर्नुपर्छ । अर्जुनलाई थाहा थिएन कि शत्रुपक्षमा उभिएका सबै राजा पहिले नै समाप्त भइसकेका थिए, तर उनीहरू पहिले नै मृत्यु प्राप्त गरिसकेका थिए जुन भगवान्‌लाई थाहा थियो ।
भगवद्गीताले हामीलाई भगवान् को सान्निध्यमा रहन सिकाउँछ । हामीले स्वर्गलोक, नर्कलोक र गोलोकको विचार मनबाट हटाउनुपर्छ । हामी डरभन्दा माथि उठ्नुपर्छ । यदि भगवान्‌को साथ प्राप्त भयो भने स्वर्गलोक होस् वा नर्कलोक, कुनै फरक पर्दैन । हामीले सबै कार्य भगवान्‌का कार्य ठानेर गर्नुपर्छ । यस्तो सोच्नु हुँदैन कि केही राम्रो गर्दा हामीलाई इहलोक वा गोलोक प्राप्त हुनेछ ।
जब हामी यो देह छोडेर जान्छौँ तब हामीलाई अर्को देह प्राप्त हुन्छ र त्यहाँ हामी भगवान्‌सँग रासलीलामा लाग्छौँ । यस्तो सोच्नु पर्दैन । हामी जे कार्य गरिरहेका छौँ, त्यो पनि भगवान्‌को रासलीला नै हो । यही माया हो र यस्तो विचार राख्नु सजिलो पनि छैन । हामी भगवान्‌को मायामा लिप्त हुन्छौँ र उहाँलाई कहिल्यै देख्न सक्दैनौँ । भगवद्गीताको अध्ययनबाट भगवान् लाई देख्ने प्रयास गर्दै जानुपर्छ । जब मानिसलाई भगवान्‌को अनन्य भक्ति प्राप्त हुन्छ तब उसलाई भगवान्‌को दर्शन हुन्छ ।
यो विवेचन पढेर तपाईँलाई अवश्य पनि राम्रो लाग्यो होला भन्ने हामीलाई विश्वास लागेको छ । कृपया तल दिएको लिङ्क प्रयोग गरी हामीलाई आफ्नो प्रतिक्रियाहरू दिनुहोला ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (9, 1, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=IvDiTwXt7HI', '2026-03-22', 'श्रीभगवान् भन्नुहुन्छ- तिमीजस्ता दोषदृष्टिरहित भक्तका लागि यस परमगोपनीय विज्ञानसहितको ज्ञानलाई म फेरि सविस्तार बताउँछु, जसलाई जानेर तिमी यस दुःखरूपी संसारदेखि मुक्त हुनेछौ ।
अनसूयवेको
अर्थ हो- दोषरहित दृष्टि । यदि दृष्टिमा दोष रह्यो भने मानिस भक्त बन्न सक्दैन; त्यसैले भक्त बन्नका लागि दोषको दृष्टि हटाउनै पर्छ । अर्जुनले यो अद्भुत कार्य गरिसकेका थिए । आठ अध्यायसम्मको उपदेश श्रवण गरेपछि अर्जुनमा प्रगाढ श्रद्धा उत्पन्न भइसकेको थियो र त्यसै श्रद्धाले गर्दा उनको दोष दृष्टि हटिसकेको थियो । जसको दृष्टि दोषरहित हुन्छ, उसले मात्र यो गुह्यतम ज्ञान बुझ्न सक्छ । भगवान्‌ भन्नुहुन्छ :
प्रवक्ष्याम्यनसूयवे
- त्यसैले, म तिमीलाई यो ज्ञान र विज्ञान बुझाइरहेको छु ।
ज्ञानं विज्ञानसहितं यज्ज्ञात्वा मोक्ष्यसेऽशुभात्
- म तिमीलाई यो रहस्य बुझाइरहेको छु, जसलाई जानिसकेपछि तिमी अशुभबाट मुक्त हुनेछौ । यो दुःखरूपी संसारबाट तिमीले मोक्ष प्राप्त गर्नेछौ । यस्तो ज्ञान र विज्ञान दुवै म तिमीलाई बुझाइरहेको छु, तिमी यसलाई बुझ ।
भगवान्‌ले आफ्नो अस्तित्वको चर्चा सुरु गर्नुभएको छ । ज्ञान र विज्ञान दुवैलाई आत्मसात् गरेपछि मात्र बोध पूर्ण हुन्छ । केवल विज्ञान बुझेर पुग्दैन, ज्ञान पनि जान्नु आवश्यक छ । विज्ञान र ज्ञान मा मूलभूत भिन्नता छ । विज्ञान भनेको विशेष ज्ञान हो, जुन समयअनुसार परिवर्तनशील हुन्छ । आजभन्दा बीस वर्ष पहिले मोबाइल फोनको यस्तो उपलब्धता थिएन; पहिले केवल कुरा मात्र हुन्थ्यो भने अहिले भिडियो कल सहज बनेको छ । 1G बाट सुरु भएको प्रविधि अहिले 5G सम्म पुगिसकेको छ । यसरी विज्ञान निरन्तर बदलिइरहन्छ । कुनै समय पृथ्वी चेप्टो छ भन्ने मान्यता थियो, पछि गोलो रहेको तथ्य प्रमाणित भयो । पहिले पृथ्वी स्थिर छ र सूर्यले परिक्रमा गर्छ भनिन्थ्यो, तर पछि वास्तविकता उल्टो देखियो । अहिले त सूर्य पनि स्थिर नरही अझ विशाल सूर्यको वरिपरि घुम्छ भन्ने कुरा पत्ता लागिसकेको छ ।
यसरी विज्ञान बदलिरहन्छ, तर ज्ञान कहिल्यै बदलिँदैन । ज्ञान आफूभित्रबाट प्रस्फुटित हुन्छ; यो अनुभवजन्य हुन्छ । विज्ञान बाहिरबाट प्राप्त गरिन्छ भने ज्ञान भित्रबाट उत्पन्न हुन्छ । विज्ञान सुनेर वा देखेर बुझ्न सकिन्छ, तर ज्ञानलाई स्वयम्‌ले अनुभव गर्नुपर्छ । यही नै यी दुईबीचको मुख्य अन्तर हो । यद्यपि, विज्ञान विना प्रगति सम्भव छैन; त्यसैले जीवनमा दुवैको आवश्यकता पर्दछ । भगवान्‌ भन्नुहुन्छ-
मोक्ष्यसेऽशुभात्
अर्थात् जब यो रहस्य बुझिन्छ, तब मानिस भित्रैबाट रूपान्तरित हुन्छ । अमृत लिएर भगवान्‌ स्वयम्‌ उभिनुभएको छ । जसरी भोकाएको व्यक्तिले फल देख्दा पनि रुख चढ्न नजान्दा समस्यामा पर्छ, त्यसरी नै सर्वसाधारणका लागि वेदको गहन अर्थ बुझ्न कठिन हुन्छ । तर, यहाँ भगवान्‌ स्वयम्‌ले ज्ञान र विज्ञान बताइदिन्छु भन्नुभएको छ । यसभन्दा सौभाग्यको कुरा अरू के हुन सक्छ? यो गुह्यतम ज्ञानबाट नै वास्तविक अमृत प्राप्त हुन्छ ।
9.2
राजविद्या राजगुह्यं(म्), पवित्रमिदमुत्तमम् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (9, 2, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=IvDiTwXt7HI', '2026-03-22', 'यो विज्ञानसहितको ज्ञान सबै विद्याहरूको राजा, सम्पूर्ण गोपनीयहरूको पनि राजा, अति पवित्र, अति उत्तम, प्रत्यक्ष फल दिने, धर्मयुक्त, साधना गर्नमा निकै सुगम र अविनाशी पनि छ ।
भगवान्‌ले भन्नुभयो कि विज्ञानसहितको यो ज्ञान सबै विद्याहरूको राजा
राजविद्या
हो । यो सबैभन्दा पवित्र र उत्तम ज्ञान हो । यो प्रत्यक्ष फल दिने धर्मयुक्त ज्ञान पनि हो ।
सुखं कर्तुमव्ययम् -
यो साधना गर्न अत्यन्त सजिलो र सुखद छ । यसको अभ्यास गर्न र यसलाई बुझ्न निकै सहज छ । साथै, यो अविनाशी ज्ञान हो । म तिमीलाई यही शाश्वत सत्य बताइरहेको छु ।
9.3
अश्रद्दधानाः(फ्) पुरुषा, धर्मस्यास्य परन्तप ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (9, 3, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=IvDiTwXt7HI', '2026-03-22', 'हे परन्तप! यस धर्ममा श्रद्धा नराख्ने पुरुषहरूले मलाई प्राप्‍त नगरी मृत्युरूपी संसारको चक्रमा घुमिरहन्छन् अर्थात् मोक्ष प्राप्‍त नगरी बारम्बार यस संसारमा जन्मने-मर्ने गरिरहन्छन् ।
जसमा श्रद्धा छैन, उसलाई भगवान्‌ प्राप्त हुने कुनै सम्भावना छैन । जो अश्रद्ध पुरुष वा मानिसहरू हुन्, यस धर्मप्रति श्रद्धा नभएकाहरूका लागि यो विद्या अप्राप्य नै रहन्छ र उनीहरू मृत्यु संसारको सागरबाट बाहिर निस्कन पनि असमर्थ हुन्छन् । जसले यसलाई बुझ्ने प्रयास नै गर्दैनन्, उनीहरूको अवस्था हिलोमा बस्ने भ्यागुतो जस्तै हो । हिलोमै फुलेको कमलको परागकणको आस्वादन गर्न भ्यागुतोलाई आउँदैन; ऊ त केवल हिलोमै रमाइरहन्छ । तर, टाढाबाट उडेर आउने भमराले कमलको परागकण चुम्ने सौभाग्य प्राप्त गर्दछ । त्यसरी नै, जसले देवनागरी बुझ्छन् र संस्कृत पढ्न सक्छन्, तर गीता बुझ्ने प्रयास गर्दैनन्, ती मानिसहरू हिलोमा अल्झिएका भ्यागुतो जस्तै हुन् । तपाईँहरू भने त्यो भमरा जस्तै हुनुहुन्छ, जसले युद्धको मैदानमा फुलेको कमल अर्थात् श्रीमद्भगवद्गीताका परागकणहरू चुम्ने अवसर पाइरहनुभएको छ ।
ती मानिसहरू वास्तवमै दुर्भाग्यशाली हुन्, जसको घरमुनि सुनको खानी छ तर उनीहरूलाई त्यसको ज्ञान छैन । उनीहरू बाहिर भने भिख माग्दै हिँडिरहेका छन् । समय बितेपछि मात्र उनीहरूलाई बोध हुन्छ कि जहाँ उनीहरू सुत्थे, त्यहाँ त करोडौँको सम्पत्ति थियो । त्यसैगरी, देवनागरी जान्ने तर गीता नपढ्नेहरू आफ्नै घरमा रहेको अमूल्य निधिलाई चिन्दैनन् । उनीहरू मुखमा भएको अमृत थुकेर मृगतृष्णाको पछाडि दौडिरहेका अभागी हुन् । मृगजलको लोभमा उनीहरूले हातको अमृत गुमाउँछन्, तर त्यो मृगजल कहिल्यै प्राप्त हुँदैन । यस्ता श्रद्धाहीन मानिसहरूले यो राजविद्या जान्ने प्रयास नै गर्दैनन्, त्यसैले यो ज्ञान गुह्यतम रहन गएको हो ।
जीवनको ज्ञान र विज्ञान नभएकै कारण उनीहरू आफ्नै जमिनमा खनिज भएर पनि उत्खनन गर्न नजान्ने भिखारी जस्तै बनेका छन् । यो एउटा यस्तो धन हो, जुन गोप्य छ र यसलाई खोल्ने एउटै उपाय यो सानो ग्रन्थ श्रीमद्भगवद्गीता हो । यसलाई खोल्नुहोस् र आफ्नो वास्तविक पूँजी प्राप्त गर्नुहोस् । आखिर भगवान्‌को अस्तित्व के हो त?
9.4
मया ततमिदं(म्) सर्वं(ञ्), जगदव्यक्‍तमूर्तिना ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (9, 4, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=IvDiTwXt7HI', '2026-03-22', 'म निराकार परमात्माद्वारा यो सम्पूर्ण जगत् पानीसित बरफजस्तै परिपूर्ण छ र सम्पूर्ण प्राणी मेरै अन्तर्गत सङ्कल्पका आधारमा स्थित छन् तर म तिनीहरूमा स्थित छैन ।
निराकार परमात्माबाट नै यो सम्पूर्ण जगत् परिपूर्ण छ । मया सर्वम जगत व्यक्त मूर्ति नाम- मेरो अव्यक्त स्वरूपबाट यो सारा जगत् व्याप्त छ ।
मत्स्थानि सर्वभूतानि
- समस्त प्राणीहरू मभित्रै रहेका छन् र मेरो सङ्कल्पको आधारमा स्थित छन्, तर वास्तवमा म तिनीहरूमा लिप्त छैन । यसलाई एउटा उदाहरणबाट बुझ्न सकिन्छ । तपाईँ बजारमा गएर फूलको बिरुवा उमार्न बीउ ल्याउनुहुन्छ, तर बीउभित्र तत्काल फूल देखिँदैन । जब त्यो बीउ रोपिन्छ र पानी हालिन्छ, तब मात्र बिरुवा अङ्कुरित भएर फूल फुल्दछ । एउटा सानो बीउभित्रै विशाल वृक्ष लुकेको हुन्छ, तर त्यसको प्रकटीकरणका लागि बीउले आफ्नो बाहिरी कठोर अस्तित्वलाई मेटाउनुपर्छ । जबसम्म बीउ फुट्दैन, तबसम्म अङ्कुरण सम्भव छैन ।
ठ्याक्कै त्यसरी नै, जबसम्म मानिसभित्रको अहङ्कार टुट्दैन र ‘म’ भन्ने संकुचित भावना हट्दैन, तबसम्म परमात्माको तत्त्व प्रकट हुँदैन । जहाँ ‘म’अर्थात् अहङ्कार छ, त्यहाँ ‘ऊ’ अर्थात् परमात्माको अनुभव हुँदैन; र जहाँ परमात्माको साक्षात्कार हुन्छ, त्यहाँ अहङ्कार बाँकी रहँदैन । त्यसैले परमात्माको दर्शनका लागि अहङ्कारलाई समाप्त गर्नै पर्छ । परमात्मा हाम्रै भित्र हुनुहुन्छ, तर उहाँ हामीमा लिप्त हुनुहुन्न । जसरी समुद्रको पानीबाट लहरहरू उठ्छन्, तर लहर स्वयम्‌मा पूर्ण समुद्र होइन; त्यसरी नै परमात्माबाट जीव उत्पन्न हुन्छ, तर जीव स्वयम्‌मा पूर्ण परमात्मा होइन । अन्त्यमा सबै लहरहरू समुद्रमै विलीन भएझैँ जीव पनि परमात्मामै मिल्दछ । यो सृष्टि भगवान्‌ बाटै बनेको हो, तर उहाँ यसमा लिप्त हुनुहुन्न- यो गहिरो रहस्य बुझ्न धैर्य र विवेकको आवश्यकता पर्दछ ।
9.5
न च मत्स्थानि भूतानि, पश्य मे योगमैश्वरम् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (9, 5, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=IvDiTwXt7HI', '2026-03-22', 'ती सबै प्राणीहरू ममा स्थित छैनन्, तर मेरो यो ईश्वरीय योगशक्तिलाई हेर, सम्पूर्ण प्राणीहरूलाई उत्पन्न गर्ने र तिनीहरूलाई धारण, पोषण गर्ने भएर पनि वास्तवमा मेरो आत्मा ती प्राणीहरूमा स्थित छैन ।
भूतानी मस्थानी नमे ऐश्वरम योगम पश्य
- सबै भूत ममा स्थित छैनन् । मेरो ईश्वरीय योग शक्ति हेर्नुहोस् । भूतहरूको धारण वा पोषण गर्ने र उत्पन्न गर्ने मेरो आत्मा वास्तवमा तिनीहरूमा स्थित छैन । जस्तै ऐनामा देखिएको प्रतिबिम्ब तपाईँ होइन तर तपाईँका कारण हो । त्यस्तै हामी भगवान्‌का कारण छौँ तर भगवान्‌ होइन । प्रतिध्वनि शब्द होइन प्रतिबिम्ब स्वरूप होइन । सूर्यको किरण सूर्य होइन । त्यस्तै हामी उत्पन्न भए पनि भगवान्‌ होइनौँ । माटोबाट भाँडो बन्छ तर माटो भाँडो होइन । त्यस्तै सृष्टि भगवान्‌ले बनाउनु भएको हो तर उहाँ त्यसमा हुनुहुन्न ।
9.6
यथाकाशस्थितो नित्यं(व्ँ), वायुः(स्) सर्वत्रगो महान् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (9, 6, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=IvDiTwXt7HI', '2026-03-22', 'जसरी आकाशबाट उत्पन्न भएर सर्वत्र विचरण गर्ने महान् वायु सर्वदा आकाशमा नै स्थित हुन्छ, त्यसरी नै मेरो सङ्कल्पद्वारा उत्पन्न हुने सम्पूर्ण प्राणीहरू ममा नै स्थित हुन्छन् भन्ने जान ।
वायु आकाशमा विचरण गर्छ तर आकाश वायुमा छैन । त्यस्तै सबै प्राणी ममा छन् तर म तिनीहरूमा छैन । अर्जुनका मनमा प्रश्न देखेर भगवान्‌ले अझ स्पष्ट पार्दै भन्नुभयो ।
9.7
सर्वभूतानि कौन्तेय, प्रकृतिं(य्ँ) यान्ति मामिकाम् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (9, 7, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=IvDiTwXt7HI', '2026-03-22', 'हे कुन्तीनन्दन! कल्पहरूको अन्त्यमा (प्रलयकालमा) सम्पूर्ण प्राणीहरू मेरै प्रकृतिमा लीन हुन्छन् र कल्पहरूको आरम्भमा (महासर्गकालमा) तिनीहरूलाई मैले नै पुनः सिर्जना गर्दछु ।
सबै प्राणी मेरो प्रकृतिबाट उत्पन्न हुन्छन् । कल्पको अन्त्यमा त्यसमै लीन हुन्छन् र फेरि सृष्टि हुन्छ । यो चक्र चलिरहन्छ जस्तै गर्मीमा बोट सुकेर वर्षामा फेरि उम्रिन्छ । जस्तै सुनारले पुरानो गहना पगालेर नयाँ बनाउँछ
। त्यस्तै सृष्टि नष्ट भएर पुनः बन्छ । आत्मा भने नष्ट हुँदैन । यो चक्र निरन्तर चलिरहन्छ ।
9.8
प्रकृतिं(म्) स्वामवष्टभ्य, विसृजामि पुनः(फ्) पुनः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (9, 8, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=IvDiTwXt7HI', '2026-03-22', 'आफ्नो प्रकृतिलाई अङ्गीकार गरेर स्वभावको बलमा परतन्त्र भएका यी सम्पूर्ण प्राणीसमुदायलाई, कल्पको शुरूआतमा, म तिनका कर्म अनुसार पटक-पटक सिर्जना गर्दछु ।
म आफ्नो मायाद्वारा बारम्बार सृष्टि उत्पन्न गर्छु र विसर्जन गर्छु । कर्म अनुसार जन्म हुन्छ । दूधमा जामुन हाल्दा दही बन्छ । बीउमा पानी पर्दा अङ्कुरण हुन्छ । त्यस्तै मेरो स्पर्शले सृष्टि चल्छ । चन्द्रको उपस्थितिले समुद्रमा लहर उठ्छ तर चन्द्रले मेहनत गर्दैन । त्यस्तै म केही गर्दिनँ तर केवल मेरो उपस्थितिले सृष्टि र प्रलय चलिरहन्छ । चुम्बकले फलामलाई आकर्षित गर्छ । त्यस्तै मेरो अस्तित्वले सृष्टि चल्छ । यो सबै माया जस्तै हो । सुन कहीं जाँदैन, केवल आभूषण बदलिन्छ । त्यसैगरी जीवको शरीर नाश हुन्छ, तर आत्मा रहिरहन्छ, त्यो नित्य र अविनाशी हुन्छ । यो कुरा सपना जस्तै हो । सबैकुरा बन्छ र बिग्रिन्छ पनि तर ममा कुनै श्रम छैन ।
9.9
न च मां(न्) तानि कर्माणि, निबध्नन्ति धनञ्जय ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (9, 9, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=IvDiTwXt7HI', '2026-03-22', 'हे धनञ्जय! ती कर्महरूमा आसक्तिरहित र उदासीन जस्तै रहेको म परमात्मालाई ती कर्महरूले कहिल्यै पनि बाँध्दैनन् ।
यी सबै कर्महरूबाट म बन्धनमा पर्दिनँ । म कर्म त गर्छु तर कुनै बन्धनमा छैन । यी कर्महरूले मलाई बाँध्न सक्दैनन् । यी कर्महरूमा
उदासीनम्
- उदासीन भाव भएकोले मलाई ती कर्महरूले बाँध्न सक्दैनन् ।
असक्त
- तिनीहरूप्रति मेरो कुनै आसक्ति छैन, त्यसैले मलाई तिनीहरूले बाँध्न सक्दैनन् । यो कुरा भगवान्‌ले बाह्रौँ अध्यायमा पनि भन्नुभएको थियो । हामी पनि कर्महरूबाट बाँधिने छैनौँ वा आसक्त हुने छैनौँ । त्यसैले भगवान्‌ले भन्नुभयो,''
कर्मण्येवाधिकारस्ते मा फलेषु कदाचन ।
सबै कर्म मलाई अर्पण गर्दै जाऊ र एकपटक मलाई अर्पण गरिसकेपछि त्यसमा नबाँधियौ । त्यसका परिणामहरूको चिन्ता नगर । कर्म गर्नु मेरो हातमा थियो, मैले गरेँ । जब म फलको चिन्ता गर्दिनँ, तब मात्र त्यो कर्ममा म लिप्त हुँदिनँ । भगवान्‌ स्वयम्‌ पनि सम्पूर्ण सृष्टि र कर्महरू त्यही अलिप्त भावले गरिरहनुभएको छ । यो विराट् सृष्टिको रचना गर्दा पनि उहाँमा पूर्ण अलिप्तता छ; त्यसैले ती कर्महरूले उहाँलाई कहिल्यै बाँध्न सक्दैनन् ।
यसलाई एउटा दीपकको उदाहरणबाट बुझ्न सकिन्छ । एउटा दीपले घरलाई प्रकाशित गर्छ, तर त्यहाँ के भइरहेको छ भन्ने कुरासँग दीपको कुनै सम्बन्ध हुँदैन । घरभित्र पुण्य कर्म भइरहेको छ वा पाप कर्म, दीपले त्यसप्रति कुनै प्रतिक्रिया दिँदैन । पुण्य कर्म गर्नेहरूले त्यही दीपबाट प्रकाशको अनुभूति गर्छन् भने पाप गर्नेहरूले त्यही प्रकाशमा असहजता महसुस गर्न सक्छन् । दीपको काम केवल प्रकाश दिने हो । त्यहाँ बसेर पाप गर्ने कि पुण्य गर्ने भन्ने कुरा मानिसको स्वविवेकमा निर्भर गर्छ ।
त्यसैगरी, भगवान्‌को अस्तित्व यो चराचर सृष्टिमा सर्वत्र व्याप्त छ । यो जगत् उहाँकै कारण प्रकाशित र सञ्चालित छ । हामी यस धर्तीमा रहेर के गरिरहेका छौँ, त्यो हाम्रो छनोट हो । हामी यहाँ पुण्य वा पाप जे गरे पनि भगवान्‌लाई त्यससँग कुनै सरोकार हुँदैन । भगवान्‌ले सृष्टिको रचना गर्नुभयो, तर उहाँ त्यसमा लिप्त हुनुहुन्न । उहाँकै सत्ताका कारण सबै कुरा भइरहेका छन्, तर ती घटना वा कर्महरूमा भगवान्‌ कहीँ पनि बाँधिनुहुन्न । यो रहस्य सुनेर अर्जुन अचम्मित हुन्छन् र सोध्छन्, “तपाईँ हुनुहुन्छ पनि र हुनुहुन्न पनि! तपाईँ सबै गर्नुहुन्छ तर लिप्त हुनुहुन्न! यसलाई अझ सहज गरी बताइदिनुहोस्” ।
9.10
मयाध्यक्षेण प्रकृतिः(स्), सूयते सचराचरम् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (9, 10, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=IvDiTwXt7HI', '2026-03-22', 'हे कुन्तीनन्दन! मेरो अध्यक्षतामा त्रिगुणमयी प्रकृतिले चराचरसहित सम्पूर्ण जगत्‌को रचना गर्दछिन् । त्यसै कारणले यो संसारचक्र घुमिरहेको छ ।
भगवान्‌ भन्नुहुन्छ कि यस प्रकृतिको अध्यक्ष म नै हुँ ।
मयाऽध्यक्षेण प्रकृतिः
- मेरो अधिष्ठानका कारण यो चराचर सृष्टि मेरो अध्यक्षतामा गतिशिल छ ।
सूयते सचराचरम्
-मेरै सङ्कल्पले यो संसारको चक्र घुमिरहेको छ र जगद्विपरिवर्तते अर्थात् यहाँ जन्म र मृत्युको परिवर्तन निरन्तर चलिरहन्छ ।
अध्यक्ष भएर पनि केही नगर्नु वा अलिप्त रहनु भनेको के होला त? यसलाई एउटा समसामयिक उदाहरणबाट बुझ्न सकिन्छ । स्वामी गोविन्ददेव गिरीजीको सूक्ष्म उपस्थिति र अध्यक्षतामा Learn Gitaको उपक्रम चलिरहेको छ । “घर- घरमा गीता पुगोस्, हरेकको हातमा गीता पुगोस्” भन्ने उहाँको पवित्र सङ्कल्प थियो, जसमा १६ हजारभन्दा बढी कार्यकर्ताहरू जोडिए र यो क्रम बढ्दो छ । स्वामीजी दैनिक रूपमा व्यवस्थापनका सबै काममा आफैँ संलग्न हुनुहुन्न, उहाँ केवल मार्गदर्शकका रूपमा रहनुहुन्छ; तापनि सबै कार्य उहाँकै सङ्कल्पका कारण सुचारु छन् । उहाँ ती कार्यहरूमा लिप्त हुनुहुन्न ।
त्यसैगरी, टाटा कम्पनीको नुन उत्पादन गर्न रतन टाटा आफैँ समुद्र किनारमा बसेर काम गर्दैनथे । उनले एउटा योजना बनाए र दक्ष मानिसहरूलाई जिम्मेवारी सुम्पे । आज रतन टाटा भौतिक रूपमा यस संसारमा नहुँदा पनि टाटा नुनको उत्पादन भइरहेकै छ, किनकि उनी त्यस संस्थाका अध्यक्ष हुन् र उनकै अध्यक्षतामा सम्पूर्ण कार्ययोजना तयार भएको थियो । उनी ती प्रक्रियामा प्रत्यक्ष लिप्त थिएनन् । ठ्याक्कै यसरी नै, यो सम्पूर्ण सृष्टिको निर्माण र विलयको प्रक्रिया भगवान्‌ कै अध्यक्षतामा चलिरहेको छ । यसका लागि विभिन्न देवताहरू नियुक्त गरिएका छन्, जसले आ- आफ्नो कार्य सम्पादन गरिरहेका छन् । भगवान्‌ भन्नुहुन्छ, “म यस सृष्टिको अध्यक्ष हुँ र मैले चाहेँ भने इन्द्रलाई पनि बदल्न सक्छु; देवताका राजालाई बदल्ने अधिकार ममै निहित छ” ।
जसरी एउटा राष्ट्रमा राष्ट्रपति बिहानदेखि बेलुकासम्म शासनको दैनिक कार्यमा अल्झिँदैनन्, उनी केवल आफ्नो गरिमामय स्थानमा रहन्छन् । प्रधानमन्त्री, विभिन्न मन्त्रालयका मन्त्रीहरू र कर्मचारीतन्त्रको एउटा ठूलो सञ्जालमार्फत राष्ट्र सञ्चालन हुन्छ, तर सबै काम राष्ट्रपतिकै नाममा गरिन्छ । त्यसैगरी मयाऽध्यक्षेण प्रकृतिः- परमात्माले सबै कुरा आफैँ नगरे तापनि उहाँकै अध्यक्षता र सत्ताका कारण यो सम्पूर्ण ब्रह्माण्ड सञ्चालित भइरहेको छ ।
9.11
अवजानन्ति मां(म्) मूढा, मानुषीं(न्) तनुमाश्रितम् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (9, 11, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=IvDiTwXt7HI', '2026-03-22', 'मेरो परमभावलाई नजान्ने मूर्खहरूले मनुष्यको शरीर धारण गर्ने मानेर मलाई तुच्छ ठान्दछन् अर्थात् संसारको उद्धारका लागि आफ्नो योगमायाले मनुष्यरूप धारण गरेकोले म परमेश्वरलाई सर्वसाधारण मानिस सम्झन्छन् ।
म अध्यक्ष हुँ, म नै सबै गरिरहेको छु तर म कतै छैन । म यसमा लिप्त छैन र मेरो यो वास्तविक स्वरूप नजान्नेहरू मूढ, मूर्ख र अज्ञानी हुन् । मानुषीं तनुमाश्रितम् मानव शरीरको आश्रय लिएका यी संकुचित दृष्टिका मानिसहरूले समस्त भूतप्राणीका महेश्वरलाई तुच्छ ठान्दछन् वा सामान्य मानिस मात्र मान्दछन् । हामीलाई लाग्छ- भगवान्‌ श्रीकृष्ण त केवल हातमा बाँसुरी लिएर उभिने एक गोठाला हुन्, तर त्यो त उहाँको एउटा रूप मात्र हो । जब श्रीकृष्णले श्रीमद्भगवद्गीताको उपदेश दिन सुरु गर्नुभयो, तब भगवान्‌ उवाच भनियो । उहाँको श्रीमुखबाट त्यो परमतत्त्वको आवाज निस्कियो; त्यो परम दिव्य गीत प्रकट भयो, जसलाई हामी गीता भन्दछौँ । हामीले त केवल बाँसुरी बजाउने, गाई चराउने, गोवर्द्धन पर्वत धारण गर्ने र यशोदा माताका प्यारा कृष्णलाई मात्र चिनेका छौँ । त्यो उहाँको सानो र साकार रूप हो, तर जो परमपरमात्मा हुनुहुन्छ, उहाँ यो सीमित आकारभन्दा निकै विशाल र भिन्न हुनुहुन्छ ।
जसरी कमलपित्त लाग्दा संसारका सबै वस्तु पहेँलो देखिन्छ र ज्वरो आउँदा मुखको स्वाद तीतो हुन्छ, त्यसरी नै दोषयुक्त दृष्टिले परमात्माको वास्तविक माधुर्य चाख्न सकिँदैन । मानव देह प्राप्त गरेर पनि भगवान्‌लाई केवल मानव शरीरमा मात्र सीमित देख्नेहरू अज्ञानी हुन् । भगवान्‌ले आफ्नो स्वरूपको विस्तृत वर्णन गर्नुभएको यो अद्भुत अध्यायलाई अझ गहिराइमा बुझ्न आवश्यक छ । यसलाई बारम्बार पढ्नुपर्छ, आवृत्ति गर्नुपर्छ, ध्यानपूर्वक सुन्नुपर्छ र आत्मसात् गर्ने प्रयत्न गर्नुपर्छ । तब मात्र यो राजविद्या हाम्रा लागि स्पष्ट हुनेछ र यो गुह्यतम ज्ञान सहज बन्नेछ ।
प्रश्नोत्तर
प्रश्नकर्ता:
- दुर्गा प्रसाद दाजु
प्रश्न:
- भगवान्‌ले ‘मैले नै सबै कुरा बनाएको हुँ तर म त्यसमा छैन’ भन्नुहुन्छ । फेरि भनिन्छ कि कण- कणमा भगवान्‌ हुनुहुन्छ । यी दुई कुरा बिरोधाभास भएन र?
उत्तर:-
टाटा नुनको कण- कणमा टाटा हुन्छ । टाटाले बनाएको हो तर रतन टाटा आफैँ प्याकिङ गर्न कारखानामा बसेका थिएनन् । त्यसरी नै भगवान्‌ले योजना बनाउनुभयो तर उहाँ त्यसमा लिप्त हुनुहुन्न । उहाँको योजना हो तर उहाँ संलग्न हुनुहुन्न ।
प्रश्नकर्ता:
- राकेश दाजु
प्रश्न:
- गीता परिवारमा जोडिनु अघि हामीले केवल अनुवादित पुस्तक पढ्थ्यौँ । संस्कृत पढ्न सकिन्छ भन्ने विश्वास थिएन तर अहिले संस्कृत श्लोक पढ्दा धेरै आनन्द आउँछ । यसरी पढ्दा के लाभ हुन्छ?
उत्तर:
- संस्कृत श्लोक पढेर त्यसको अर्थ बुझ्दा गीता गहिरो रूपमा अनुभव हुन्छ । केवल पढेर बन्द गर्ने होइन, अर्थ बुझेर अभ्यास गर्दा श्रद्धा बढ्छ । केहि रोगहरू समेत निको हुन्छ भन्ने विश्वास हुन्छ ।
प्रश्नकर्ता:
- मनिता दीदी
प्रश्न:
- सोह्रौँ अध्यायमा २६ वटा दैवीगुण भनिएको छ । के सबै मानिसमा यी गुण हुन्छन्?
उत्तर:
- सबैमा सबै गुण हुँदैनन् । केही गुण प्रबल हुन्छन्, केही कमजोर । आसुरी गुणलाई घटाउँदै दैवीगुणलाई बढाउन निरन्तर प्रयास गर्नुपर्छ ।
यो विवेचन पढेर तपाईँलाई अवश्य पनि राम्रो लाग्यो होला भन्ने हामीलाई विश्वास लागेको छ । कृपया तल दिएको लिङ्क प्रयोग गरी हामीलाई आफ्नो प्रतिक्रियाहरू दिनुहोला ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (5, 11, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=aFcdLpMQ0gQ', '2026-03-22', 'यसकारण, कर्मयोगीहरू ममत्वबुद्धिरहित भई इन्द्रिय, शरीर, मन र बुद्धिद्वारा आसक्तिलाई त्यागेर केवल अन्तःकरणको शुद्धिका लागि कर्म गरिरहन्छन् ।
के योगी केवल हिमालयको गुफामा मात्र बसिरहन्छन्? के उनिहरू केवल भगवान्‌को आराधना र तपस्यामा मात्र लीन रहन्छन्? हो, हिमालयमा आज पनि त्यस्ता योगीहरू छन् । योगी निरन्तर कर्मरत रहन्छन् । जसको प्रभावले त्यहाँको सम्पूर्ण वायुमण्डल पवित्र हुन्छ, अशुद्धिहरू हट्छन् र वातावरण शुद्ध हुन्छ । हामी संसारमा चार प्रकारका मानिसहरू देख्छौं:
१. जसले कर्म गर्नुपर्ने हो, तर गर्दैनन् ।
२. जसले कर्म गर्नुपर्ने हो र गरिरहन्छन् ।
३. जसका लागि अब कर्म आवश्यक छैन, त्यसैले गर्दैनन् ।
४. जसका लागि अब जीवनमा केही गर्न बाँकी छैन, तैपनि उनीहरू निरन्तर कर्मरत छन् ।
कायेन मनसा बुद्ध्या केवलैरिन्द्रियैरपि...
योगीहरू चार तहमा कर्म गर्छन्:
कायेन
(शरीर): शारीरिक स्तरमा हुने कर्महरू ।
मनसा
(मन): विचार र संकल्प-विकल्प गर्ने मानसिक कर्म ।
बुद्ध्या
(बुद्धि): निर्णय लिने, अध्ययन गर्ने र नयाँ कुरा सिक्ने बौद्धिक कर्म ।
इन्द्रियैः
(इन्द्रिय): आँखाले देख्ने, कानले सुन्ने, नाकले सुँघ्ने, छालाले स्पर्श गर्ने र जिब्रोले रस लिने इन्द्रियगत कर्म ।
योगीहरू यी सबै कर्महरु
सङ्गं त्यक्त्वा
- आसक्तिलाई त्यागेर गर्छन् । हाम्रो सामान्य मन कस्तो हुन्छ भने, हामी जे कर्म गर्छौं, त्यसको फल र प्रक्रिया दुवैसँग हाम्रो चित्त टाँसिन्छ (आसक्त हुन्छ) । जसरी सुगन्धित फूललाई कुनै भाँडोमा राखियो भने, त्यो भाँडो र हाम्रो हात दुवै सुगन्धित हुन्छन् । त्यो सुगन्धको प्रभाव भाँडोमा पर्नु नै सङ्ग हो । यदि फूलको सट्टा दुर्गन्धित वस्तु भए, त्यसको पनि प्रभाव पर्ने थियो । हाम्रो अन्तःकरण पनि त्यस्तै छ, जसले संसारका घटनाहरूलाई सोसेर बोझिलो बनाउँछ । हामी घटनाहरूलाई सङ्ग्रह गरेर राख्छौं । कसैको अन्तःकरण पेन्सिलले लेखेको जस्तो हुन्छ, जो मेटाउन सकिन्छ । कसैको पेनले लेखेको जस्तो हुन्छ, मेटाउन गाह्रो हुन्छ । अनि कसैको त मार्करले लेखेको जस्तो हुन्छ, कहिल्यै मेटिँदैन । तर योगीको अन्तःकरण पानीमा लेखेको जस्तो हुन्छ, जो तुरुन्तै मेटिन्छ र फेरि ताजा हुन्छ । सामान्य मानिसले वर्षौँ पुरानो अपमान वा दुर्घटनाको पीडा अझै बोकेर हिँडिरहेको हुन्छ, तर योगीले सङ्गं त्यक्त्वा- ती क्रियाकलापसँग कुनै नाता राख्दैन ।
आत्मशुद्धये कर्म कुर्वन्ति
- आफ्नो अन्तःकरणलाई शुद्ध गर्नका लागि योगीले कर्म गर्छ । जसरी बगिरहेको पानीमा कीटाणु हुँदैनन् र त्यो शुद्ध रहन्छ, तर एकै ठाउँमा जमेको पानी दूषित हुन्छ, त्यसैगरी योगी निरन्तर कर्मरत रहन्छन् त्यसैले उनीहरूको चित्त शुद्ध रहन्छ ।
जे. कृष्णमूर्तिले यसलाई Unscarred Mind (नकोरिएको मन) भन्नुभएको छ । यस्तो मन सधैँ ताजा हुन्छ, जसबाट नयाँ सृजना र आविष्कार सम्भव हुन्छ । गुरुदेवले यसको अर्थ बताउनु भएको छ - उनीहरू तथ्य (Facts) त याद राख्छन्, तर त्यसको मनोवैज्ञानिक परिणाम (Psychological Impact) बाट मुक्त हुन्छन् । उनीहरू भावनाको बोझबाट मुक्त हुन्छन्, तर वास्तविकतालाई भुल्दैनन् । यसरी योगीहरू आत्मशुद्धिका लागि कर्म गर्छन्, तर त्यसको परिणामको बन्धनबाट भने पूर्णतः मुक्त रहन्छन् ।
5.12
युक्तः(ख्) कर्मफलं(न्) त्यक्त्वा, शान्तिमाप्नोति नैष्ठिकीम् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (5, 12, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=aFcdLpMQ0gQ', '2026-03-22', 'कर्मयोगीले कर्मको फललाई त्यागेर भगवत् प्राप्‍तिरूपी शान्तिलाई प्राप्‍त गर्दछ, तर सकामी पुरुष भने कामको प्रेरणाले फलमा आसक्त भएर बाँधिन्छ ।
भगवान् भन्नुहुन्छ- हे अर्जुन ! जो कर्मयोगी छ, उसले कर्मको फललाई त्याग गरेपछि नैष्ठिकी शान्तिम् आप्नोति- त्यो परब्रह्म परमात्माको कहिल्यै नडगमगाउने शाश्वत शान्ति प्राप्त गर्दछ । संसारमा जतिसुकै उथलपुथल भए पनि उसको अन्तःकरण अविचल रहन्छ । शरीर, इन्द्रिय, मन र बुद्धिद्वारा हुने कर्महरूमा ऊ लिप्त हुँदैन । उसले ती कर्महरूलाई आफ्नो अन्तःकरणमा टाँसिन दिँदैन । जो चारैतिरबाट युक्त छ । युक्त को अर्थ हो- जोडिएको । परमात्मासँग जोडिएको उसको अन्तःकरणमा एउटा यस्तो कुचालक छ, जसले गर्दा संसारको प्रवाहले उसलाई छुन सक्दैन । जसरी इन्सुलेसनका कारण बिजुलीको तार बाहिरबाट सुरक्षित हुन्छ, त्यसरी नै उसको निर्लिप्त मनमा संसारको कुनै पनि लेप लाग्न पाउँदैन ।
तर, जो
अयुक्त
छ- जसले त्यो परमात्माको शान्तिलाई चिनेको छैन र जोडिएको छैन, ऊसले फलको आशामा निरन्तर कर्म गरिरहन्छ ।
फले सक्तो निबध्यते
- फलमा आसक्त हुनाले ऊ बन्धनमा पर्दछ । यस्तो बन्धनमा कुनै ताजगी हुँदैन । मान्छेले सोचेजस्तो फल सधैँ पाउँदेन र यदि पाइहाल्यो भने पनि ‘फेरि कहिले पाउँला?’ भन्ने चिन्ताले उसलाई सताइरहन्छ । त्यसैले ऊ फलको वास्तविक आनन्द पनि लिन सक्दैन । यो फलको इच्छा मानिसको मनमा भूत जस्तै सवार हुन्छ, जसले गर्दा उसले कहिल्यै शान्ति पाउँदैन । हामी अक्सर आफ्नो फललाई अरूको फलसँग तुलना गर्छौँ, जसले ईर्ष्या र अशान्ति निम्त्याउँछ ।
ज्ञानेश्वर महाराज भन्नुहुन्छ- हामीले आफ्नो वरिपरिका पशुपक्षी र वनस्पतिबाट सिक्नुपर्छ । एउटा वृक्ष फुल्छ र फल्छ तर ऊ ती फल र फूलहरूलाई समातेर बस्दैन । एकदिन ऊ ती सबैलाई छोडिदिन्छ । यदि वृक्षले- म आफ्नो फल छोड्दिनँ भनेर ढिपी गर्यो भने के होला?
पहिलो कुरा, उसले नयाँ सिर्जना गर्ने क्षमता गुमाउनेछ ।
दोस्रो कुरा, त्यो फल त्यहीँ टाँसिएर कुहिनेछ र दुर्गन्ध फैलाउनेछ ।
त्यसैले वृक्षले फल र फूल छोडिदिन्छ र कहिल्यै पनि सोच्दैन कि त्यो फल कसले खायो वा त्यो फूल कहाँ चढाइयो फूलको आफ्नो चाहना होला-
चाह नहीं मैं सुरबाला के गहनों में गूँथा जाऊँ
मुझे तोड़ लेना वनमाली, उस पथ पर देना तुम फेंक,
मातृभूमि पर शीश चढ़ाने, जिस पथ जाएँ वीर अनेक।
तर वृक्षको त त्यति पनि चाहना हुँदैन । ऊ त केवल फुल्छ, फल्छ र त्यागिदिन्छ । मानिस पनि यदि फलमा नअड्किएर त्यसको ‘सङ्ग’ छोडिदिन्छ भने, ऊ सधैँ नयाँ सिर्जनाका लागि तयार रहन्छ । ज्ञानेश्वर महाराजको एउटा सुन्दर छन्द छ-
वृक्ष कां वेली । लोटती फळे आलीं ।
तैसी सांडी निपजलीं । कमै सिद्धे ॥
जसरी वृक्ष र लहराहरूले फलेका फलहरूलाई सहजै त्यागिदिन्छन्, त्यसरी नै मुक्त पुरुषले सिद्ध भएका कर्महरूलाई छोडिदिन्छन् र नित्य नयाँ सिर्जनाका लागि जागरुक हुन्छन् ।
जो अयुक्त छ, ऊ ती पुराना फलहरूमै अड्किरहन्छ, जसबाट पछि दुर्गन्ध आउन थाल्छ । कसैको घरमा सासू-बुहारीको झगडा भयो भने उनीहरू वर्षौँसम्म त्यही एउटै कुरा दोहोर्याइरहन्छन् । कसैले कुनै समयमा स्वर्ण पदक पायो भने ऊ जीवनभर त्यही एउटै कथा सुनाइरहन्छ । यो फललाई समातिराख्ने बानीले मानिसको व्यक्तित्वलाई नै प्रभावित पार्छ र व्यक्तित्व विकार निम्त्याउँछ । हे अर्जुन! योगीको यो कलालाई बुझ । यदि तिमीले यो कला बुझ्यौ भने युद्धको परिणामले तिमीलाई छुने छैन । चाहे विजय होस् वा पराजय, तिमी आफ्नो अन्तःकरणलाई त्यसको प्रभावबाट मुक्त राख्न सक्नेछौ ।
5.13
सर्वकर्माणि मनसा, सन्न्यस्यास्ते सुखं(व्ँ) वशी ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (5, 13, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=aFcdLpMQ0gQ', '2026-03-22', 'जसको अन्तःकरण अर्थात् इन्द्रियहरू र मन वशमा छ, त्यस्तो साङ्ख्ययोगको आचरण गर्ने पुरुष केही नगर्दै र नगराउँदै पनि नौद्वार भएको यो शरीररूपी घरमा सम्पूर्ण कर्महरूलाई मनैदेखि त्यागेर सच्चिदानन्दघन परमात्माको स्वरूपमा आनन्दपूर्वक रहिरहन्छ ।
भगवान् भन्नुहुन्छ,
वशी
- जसले आफ्नो अन्तःकरणलाई वशमा राख्यो, नियन्त्रित गर्यो । जसलाई यो थाहा भयो कि अन्तःकरणमा प्रभाव पार्ने सारा घटनाहरूको परिणाम चित्तमा देहका द्वारहरूबाट भित्र प्रवेश गरिरहन्छ । जसरी कतै सर्ट सर्किट हुन लाग्यो भने हामीले स्वीच बन्द गरिदिन्छौँ, त्यसैगरी योगीले सारा संसारका लागि आफ्नो अन्तःकरणको ढोका बन्द गरिदिन्छ । त्यसपछि त्यो
वशी देही
- (वशमा भएको जीवात्मा) न केही गर्छ, न कसैलाई गराउँछ । नवद्वारे पुरे- यस देहलाई पुर वा सहर भनिन्छ (जस्तै- कान्तिपुर, टीकापुर) । यो देह पनि एउटा सहर हो जसमा नौवटा ढोकाहरू छन् ।
सर्वकर्माणि मनसा सन्न्यस्य
- देहबाट कर्म भइरहेका छन्, शरीर, इन्द्रिय र मनबाट कर्म भइरहेका छन्, तर एउटा योगी मनसा सन्न्यस्य- मनैबाट ती सारा क्रियाकलापहरूको संन्यास वा त्याग गर्छ । संन्यासको अर्थ हो अलग हुनु, र युक्तको अर्थ हो जोडिनु ।
युक्तः कर्मफलं त्यक्त्वा
- कर्मफललाई त्यागेर युक्त हुनु । ती सारा घटिरहेका क्रियाहरूको चिन्ता गर्ने होइन । मनैबाट ती सबैको त्याग गर्नु पर्छ ।
सुखमास्ते-
मनैबाट सन्न्यस्त भएपछि ऊ सुखपूर्वक बस्छ । हामी केवल भन्छौ, “भगवानले गराइरहनुभएको छ, मबाट भगवानले गराउनुभयो,” तर मनमा चाहिँ सोचिरहन्छौ, “मैले आज यति राम्रो काम गरेँ, मैले राम्रो प्रवचन दिएँ ।” यसो भयो भने हामी मनबाट अलग भएका हुँदैनौँ । परमात्माले त हाम्रो भित्री भाव हेर्नुहुन्छ । जो मनबाट अलग हुन्छ, ऊ मात्र सुखपूर्वक रहन्छ । प्रकृतिको खेल त आफ्नै संस्कारको परिणाम स्वरूप चलिरहन्छ । यो संसार जसमा हामी फसेका छौँ, त्यो हामीद्वारा नै निर्मित हो ।
गुरुदेव भन्नुहुन्छ- यहाँ दुई प्रकारका सृष्टि छन्-
ईश्वरकृत सृष्टि
र
जीवकृत सृष्टि
। ईश्वरले सृष्टि आनन्द लिनका लागि बनाउनुभयो- ती बग्ने सुन्दर झर्ना, वृक्ष, लहरा, हिमालयका कन्दरा, गंगाजीको जल; यी सबैले हामीलाई आनन्द दिन्छन्, यो प्रकृतिको नित्य स्वभाव हो । तर जीवकृत सृष्टि (मान्छेले बनाएको संसार) ले हामीलाई पीडा दिन्छ । ईर्ष्या, वैमनस्य, द्वेष र अनेक विकारहरूको आदानप्रदान गर्छ । आज ति सीमाहरूका कारण युद्ध भइरहेको छ, आफ्नो उपासना पद्धतिका कारण पनि युद्ध भइरहेको छ । यो भीषण संहार मानव-निर्मित सृष्टि हो ।
पंक्षी, नदियाँ, पवन के झोंके ।
कोई सरहद इन्हें न रोके ।।
यो सीमा त मान्छेले बनाएको हो । भगवान् भन्नुहुन्छ- योगी यस्तो संसारमा देही (चैतन्य) को रूपमा रहन्छ। जब हामी भन्छौँ,“भगवानले गर्नुहुन्छ, भगवानले गराउनुभयो,” यो त हाम्रो अन्तःकरणको शुद्धिका लागि भनिएको कुरा हो । यदि सबै कुरा भगवानले नै गराउने हो भने त भगवानले किन अपराधी बनाउनुहुन्थ्यो ? यदि उहाँको अनुमति बिना एउटा पात पनि हल्लिँदैन भने मान्छे किन अपराधी बन्छ त? के भगवानको इच्छा उसले अपराध गरोस् भन्ने हुन्छ र? यो त हाम्रो अन्तःकरणको कर्म र फलको जुन बोझ छ, त्यसलाई मेटाउनका लागि हो । शक्ति भगवानको हो, तर इच्छा जीवको हुन्छ ।
5.14
न कर्तृत्वं(न्) न कर्माणि, लोकस्य सृजति प्रभुः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (5, 14, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=aFcdLpMQ0gQ', '2026-03-22', 'परमेश्वरले मनुष्यका न कर्तापनको, न कर्महरूको, न त कर्मफलको संयोगको नै रचना गर्दछ; वास्तवमा उसको स्वभावले नै काम गरिरहेको हुन्छ ।
भगवान् भन्नुहुन्छ- त्यो परब्रह्म परमात्मा, त्यो चैतन्य तत्वले न कसैलाई केही गराउँछ, न आफैँ गर्छ, न त कर्मको फलसँग नै सम्बन्ध गराइदिन्छ । यो त एउटा ‘प्रोग्राम’ जस्तै हो, जो आफ्नै नियम अनुसार चलिरहन्छ । त्यो प्रभु अर्थात् परमेश्वर, जो सारा सृष्टिको नियन्ता हुनुहुन्छ, उहाँले लोकको न कर्तृत्व, न कर्म, न त कर्मफलको संयोग नै गर्नुहुन्छ ।
ज्ञानेश्वर महाराज भन्नुहुन्छ- उहाँ कसैको कर्म स्वीकार गर्नुहुन्न । साक्षी भावले रहनुहुन्छ । कर्म र कर्मफलको संयोग नियम अनुसार चलिरहन्छ । यो त
स्वभावस्तु प्रवर्तते
- स्वभाव वा प्रकृतिद्वारा भइरहेको छ । सत्व, रज र तम गुणहरूको मिश्रण र त्यसको अनुपातबाट नै यो सबै हुन्छ । यो प्रकृतिले नै सारा काम गराउँछ र यसको एउटा निश्चित नियम छ । हामी जे रोप्छौँ, त्यही उम्रिन्छ; यदि हामीले सिस्नु रोपेका छौँ भने सुन्तला फल्दैन ।
ईश्वरमाथि प्रायः दुईवटा आरोप लगाइन्छ- एउटा पक्षपाती र अर्को कठोर । भगवान् यी दुवै आरोप स्वीकार गर्नुहुन्न । त्यसैले हाम्रो शास्त्रमा भनिएको छ-
ईश्वरस्तु पर्जन्यवत् द्रष्टव्यः
-ईश्वरलाई पर्जन्य- (वर्षा) जस्तै मान्नु पर्छ । वर्षा सबैतिर समान रूपले हुन्छ, तर जमिनमा जे रोपिएको छ, त्यही मात्र फल्छ । ईश्वरको शक्ति सबैका लागि समान हुन्छ, तर मनुष्यले त्यसको उपयोग कसरी गर्छ, त्यसै अनुसारको कार्य उसको देहबाट प्रकट हुन्छ । जसरी हाम्रो घरमा एउटै तारबाट बिजुली आउँछ, तर हाम्रा उपकरण (इन्स्ट्रुमेन्ट्स) अनुसार त्यसको प्रभाव फरक हुन्छ- बल्ब वा ट्युबलाइटमा त्यही बिजुलीले प्रकाश दिन्छ, गिजरमा त्यही बिजुलीले गर्मी (ताप) उत्पन्न गर्छ, ए.सी. वा फ्रिजमा त्यही बिजुलीले चिसो उत्पन्न गर्छ । बिजुली एउटै हो, तर उपकरणको स्वभाव अनुसार काम फरक भयो । त्यसैगरी यो सारा सृष्टि कर्मको सिद्धान्त र नियम अनुसार चलिरहन्छ र मान्छेले आफ्नो कर्म अनुसार फल भोग्नुपर्छ । यो सबै स्वभावका कारण भइरहेको छ । जस्तो बल्बको वाटेज (३,५,७ वा १० वाट) हुन्छ, त्यस्तै अन्तःकरणको जस्तो स्वभाव छ, त्यस्तै कार्य हुन्छ ।
यो स्वभाव गुणहरूबाट बन्दछ । अंग्रेजीको ‘HABIT’ (बानी) शब्दबारे एउटा रोचक कुरा छ:
• ‘HABIT’ बाट ‘H’ हटाए पनि ‘ABIT’ (बानी) बाँकी रहन्छ ।
• ‘A’ हटाए पनि ‘BIT’ (अलिकति) बाँकी रहन्छ।
• ‘B’ हटाए पनि ‘IT’ (त्यो) बाँकी नै रहन्छ ।
यो ‘ह्याबिट’ वा स्वभाव नै हो जसका कारण कार्यहरू हुन्छन् । हामीले भगवानको भूमिकालाई बुझ्नुपर्छ- उहाँको भूमिका बिजुलीको समान छ, जो सक्रिय त छ तर निर्लिप्त छ ।
5.15
नादत्ते कस्यचित्पापं(न्), न चैव सुकृतं(व्ँ) विभुः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (5, 15, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=aFcdLpMQ0gQ', '2026-03-22', 'सर्वव्यापी परमात्माले न कसैको पापकर्म र न कसैको शुभकर्मलाई नै ग्रहण गर्दछ; तर जुन पुरुषको ज्ञान अज्ञानरूपी मायाद्वारा ढाकिएको छ, त्यसैबाट सबै जीव मोहित भइरहेका छन् ।
ईश्वरलाई हामीले कसरी बुझ्ने र कसरी हेर्ने भन्नेबारेमा भगवान्‌ले अर्जुनलाई निमित्त बनाएर बताउनुहुन्छ ।
विभु
-त्यो सर्वव्यापी परमात्माले न कसैको पाप ग्रहण गर्नुहुन्छ, न त पुण्य (सुकृत) नै । हामीले अर्पण गर्यौं र उहाँले लिइहाल्नुभयो भन्ने हुँदैन । उहाँले न कसैको राम्रो कर्म लिनुहुन्छ, न त नराम्रो नै । प्रायः हामी आफ्नो
दुष्कृत
- नराम्रो कर्म भगवानलाई अर्पण गर्न चाहन्छौं, तर
सुकृत
- राम्रो कर्म चाहिँ आफैसँग राख्न चाहन्छौं, किनकि त्यसको फल भोग्नु छ । त्यसैले गल्ती हुँदा अर्पण गरिदिएँ भन्ने र राम्रो काम हुँदा मैले गरेँ भनी आफूसँगै राख्ने गरिन्छ । तर वास्तविक शुद्धि तब हुन्छ जब दुवै अर्पण गरिन्छ । मनुष्यको अज्ञानका कारण मन भ्रमित भई ज्ञान ढाकिन्छ । अज्ञानेनावृतं ज्ञानं
- अज्ञानले ज्ञानलाई छोपिदिन्छ र त्यही कारणले अज्ञानी व्यक्ति मोहित हुन्छ र अनेक तर्क गर्दछ ।
वास्तविकता के हो भने- इच्छा जीवको हुन्छ, शक्ति परमात्माको हुन्छ । उदाहरणका लागि, यो हात उठाउने शक्ति परमात्माले दिनुभएको हो । यही हातले कुनै बिरामीको सेवा पनि गर्न सकिन्छ र यही हातले चोरी गर्न पनि सकिन्छ । यो त व्यक्तिको संस्कार मा भर पर्छ । यदि कुनै चोरले “यो भगवान्‌ले मबाट गराउनुभएको हो” भन्यो भने न्यायाधीशले पनि भन्न सक्छ- “मैले तिमीलाई सजाय दिएको होइन, तिमीभित्रको भगवान्‌लाई सजाय दिएको हुँ ।” तर सजाय त अन्ततः त्यो शरीरले नै भोग्नुपर्छ ।
भगवान् राम्रो वा नराम्रो कुनै पनि कर्म स्वीकार गर्नुहुन्न । हावा, पानी, वर्षा, चन्द्रमाको शीतलता र सूर्यको प्रकाश सबैका लागि समान हुन्छ । सन्त ज्ञानेश्वर महाराज भन्नुहुन्छ- नदीको जल कहिल्यै पक्षपाती हुँदैन ।
गाईची तृषा हरू । का व्याघ्रा विष होऊनी मारू ।
ऐसे नेणेची कां करू । तोय जैसे ।।
गाई प्यास मेटाउन आएकी छिन्, त्यसैले म उनको प्यास मेटाउँछु; तर बाघ आयो भने म उसको लागि विष बनिदिन्छु- भन्ने भेदभाव पानीले गर्दैन । पानीले त केवल प्यास मेटाउने आफ्नो धर्म निभाउँछ ।
कसैका तीन छोराहरू बुवाले उनीहरूलाई खर्चगर्न बराबर पैसा दिनुभयो र छोराहरूमा सत्व, रज र तम गुणको अलग-अलग मिश्रण छ भने उनीहरूले त्यो पैसा आफ्नै स्वभाव अनुसार खर्च गर्छन- तमोगुणी छोराले त्यो पैसा जुवा वा मदिरामा उडाउन सक्छ, रजोगुणी छोराले मनोरञ्जन वा भोजभतेरमा खर्च गर्न सक्छ र सत्वगुणी छोराले राम्रो पुस्तक किन्ला वा कसैको सेवामा लगाउला । यो सबै ती व्यक्तिहरूको स्वभाव अनुसार हुन्छ, त्यसैगरी ईश्वर कसैप्रति पनि पक्षपाती हुनुहुन्न ।
5.16
ज्ञानेन तु तदज्ञानं(य्ँ), येषां(न्) नाशितमात्मनः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (5, 16, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=aFcdLpMQ0gQ', '2026-03-22', 'तर जसको अज्ञानता परमात्माको तत्त्वज्ञानद्वारा नष्ट गरिएको छ, उसको त्यो ज्ञानले सूर्यले झैँ त्यस सच्चिदानन्दघन परमात्मालाई प्रकाशित पारिदिन्छ ।
भगवान् भन्नुहुन्छ- हे अर्जुन! अज्ञानका कारण मानिसहरू मोहित हुन्छन् र अनेक कुरा सोच्छन् । तर,
येषां तु अज्ञानं आत्मनः ज्ञानेन नाशितम्-
जसको त्यो अज्ञान आत्मज्ञानद्वारा नष्ट भएको छ, उनीहरूको अवस्था भिन्न हुन्छ । यहाँ अज्ञानका दुईवटा अर्थ छन्- एउटा
आवरण
- सत्य कुरा ढाकिनु र अर्को
विक्षेप
- गलत वा उल्टो अर्थ लगाउनु । जसको अन्तःकरणमा आत्मप्रकाशको उदय भएर अज्ञान नष्ट भएको छ,
तेषां ज्ञानं आदित्यवत् तत्परं प्रकाशयति
- उनीहरूको त्यो ज्ञान सूर्य (आदित्य) समान हुन्छ । जसरी सूर्यले सम्पूर्ण सृष्टिलाई प्रकाशित गर्दछ, त्यसरी नै उनीहरूको ज्ञानले त्यो परम तत्वलाई प्रकाशित गरिदिन्छ र उनीहरूले परमात्माको आभा प्राप्त गर्दछन् ।
सन्त ज्ञानेश्वर महाराज भन्नुहुन्छ - यो ज्ञान, जसले सारा आवरणहरूलाई छेड्छ, विक्षेपहरूलाई मेटाउँछ, भ्रान्तिबाट मुक्त गर्छ र सबै द्वन्द्वहरूबाट माथि उठाउँछ, यो केवल गुरुको कृपाबाट मात्र प्राप्त गर्न सम्भव छ ।
जेणें भ्रांतीपासूनि हिरतलें ।गुरुवाक्यें मन धुतले ।
मग आत्मस्वरूपीं घातलें । हारौनिया ।।
भ्रान्तिबाट मुक्त हुँदै जसले गुरुको वाक्य (मन्त्र) द्वारा आफ्नो मन धोयो र आत्मतत्वसँग नित्य सम्बन्ध स्थापित गर्‍यो, उसले मात्र यो प्राप्त गर्छ । रामकृष्ण परमहंसले सुनाउनुभएको कथामा एउटा बाख्राको सङ्गतमा हुर्केको सिंहको बच्चाले आफूलाई बाख्रा सम्झिएर म्याँम्याँ गर्दै कराइरहेको थियो र घाँस खाइरहेको थियो । जब अर्को सिंहले उसलाई राती उठाएर इनार वा पोखरीको पानीमा उसको प्रतिबिम्ब देखाइदियो र भन्यो, “हेर, तिमी बाख्रा होइनौ, तिमी त सिंह हौ!” तब मात्र उसले आफ्नो वास्तविक स्वरूप चिन्यो । गुरुले ठ्याक्कै यही गर्नुहुन्छ । गुरु भन्नुहुन्छ, “तिमी देह होइनौ, तिमी आत्मतत्व हौ, आफ्नो स्वरूपलाई चिन!” त्यसपछि अज्ञानको नाश हुन्छ ।
5.17
तद्बुद्धयस्तदात्मान:(स्), तन्निष्ठास्तत्परायणाः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (5, 17, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=aFcdLpMQ0gQ', '2026-03-22', 'जसको मन तद्रूप (उस्तै किसिमको) छ, जसको बुद्धि तद्रूप भइरहेको छ र जसको अन्तःकरण रमाएको छ, त्यस्ता सच्चिदानन्दघन परमात्मामा परायण भई एकै भाव भएका पुरुषहरूले ज्ञानका माध्यमद्वारा पापरहित भएर फेरि-फेरि जन्मनु-मर्नु नपर्ने परमगति प्राप्‍त गर्दछन् ।
बुद्धि र मन त सबैको हुन्छ भगवान्‌ले यहाँ ४ प्रकारका विशेषण प्रयोग गर्नुभएको छ-
१.
तद्बुद्धयस्
- जसको बुद्धि सधैँ परमात्मामा केन्द्रित हुन्छ, ऊ सधैँ भगवान्‌को बारेमा सोचिरहन्छ, ‘परमात्मा कस्तो होला?’ भनेर ज्ञानद्वारा बुझ्ने प्रयास गर्छ ।
२.
तदात्मानस्
- जसको मन/अन्तःकरण परमात्मासँग एकाकार भएको हुन्छ, उसको भित्री भावना (मन) सधैँ भगवान्‌मै डुबेको हुन्छ ।
३.
तन्निष्ठास्
- जसको अटल श्रद्धा र निष्ठा परमात्मामा हुन्छ, कुनै पनि परिस्थितिमा डगमगाउँदैन, पूर्ण विश्वास र समर्पण हुन्छ ।
४.
तत्परायणाः
- जो परमात्मामै एकाकार भएर परमात्माकै लागि काम गर्छ, उसको जीवनको लक्ष्य नै भगवान्‌ प्राप्त गर्नु हुन्छ, सबै कर्म परमात्मालाई समर्पित गर्छ ।
यस्तो योगी कर्ममा लागेको हुन्छ,
ज्ञाननिर्धूतकल्मषा:
- ज्ञानका कारण उसको सबै कल्मष (अन्तःकरणको मैला, भ्रम, द्वेष, सबै विकार) हटिसकेको हुन्छ ।
अपुनरावृत्तिं गच्छन्ति
- फेरि संसारको चक्र (जन्म-मृत्यु) मा फर्कँदैनन्, मोक्ष प्राप्त हुन्छ, त्यसैले उसको जीवन शुद्ध, शान्त र मुक्त हुन्छ । त्यही अवस्थामा यस योगीको चित्त सधैँ स्थिर रहन्छ ।
5.18
विद्याविनयसम्पन्ने, ब्राह्मणे गवि हस्तिनि ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (5, 18, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=aFcdLpMQ0gQ', '2026-03-22', 'ती ज्ञानी महापुरुषहरू विद्या र विनययुक्त ब्राह्मण तथा गाई, हात्ती, कुकुर र चण्डाललाई समेत समान दृष्टिले हेर्दछन् ।
ज्ञानको दृष्टि अत्यन्त महत्वपूर्ण हुन्छ । ज्ञानीले सबै प्राणीमा एउटै परमात्मा तत्त्वको दर्शन गर्छ । मानौँ उसलाई आध्यात्मिक एक्स-रे जस्तो दृष्टि प्राप्त भएको हुन्छ, जसले मन, बुद्धि, चित्त र अहंकारका तहहरू पार गरेर भित्रको आत्मतत्त्वसँग जोडिन सक्छ । हामी भने बाहिरी विकारहरूका कारण अरूमा मात्र होइन, आफ्नै भित्र पनि परमात्मा देख्न सक्दैनौँ । हाम्रो अन्तःकरणमा ईर्ष्या, निन्दा, स्तुति जस्ता विभिन्न वृत्तिहरू समुद्रका छाल झैँ उठिरहन्छन् । तर जो यी सबै लहरहरू पार गरेर भित्रको गहिराइमा पुग्छ, उसको दृष्टि समदृष्टि हुन्छ । भगवान्‌ समत्वका पक्षधर हुनुहुन्छ । उहाँ भन्नुहुन्छ-
विद्याविनयसंपन्ने ब्राह्मणे
- जसले ब्रह्मको प्राप्तिको लागि आफ्नो जीवनको कर्तव्य र आचरणलाई ब्रह्मतत्त्वको आफ्नो मूल स्वरूपलाई पाउन, बुझ्न र त्यस अवस्थामा पुग्न सक्ने बनाउँछ, उसलाई ब्राह्मण भनिन्छ । ब्राह्मण विद्यासँगै विनयमा पनि सम्पन्न हुनु पर्दछ, किनकि कहिलेकाहीँ ज्ञानसँग अहंकार आउँछ तर साँचो ज्ञानी नम्र हुन्छ ।
हनुमानजी विद्यावान् गुनी अति चातुर, राम काज करिवेको आतुर अत्यन्त विद्वान, गुणी र चतुर हुनुहुन्छ, तर उहाँ सधैँ प्रभु रामको काम गर्न आतुर हुनुहुन्छ, त्यसैगरी विद्या-विनय सम्पन्न साँचो पण्डित वा आत्मज्ञानी योगीले ब्राह्मण, गाई, हात्ती, कुकुर र चाण्डाल सबैमा एउटै चेतना देख्छ, समान दृष्टि राख्छ, जसलाई भगवान्‌ले
पण्डिताःसमदर्शिनः
भन्नुहुन्छ । यस्तो ज्ञानीले बोल्दैन, सबैमा एउटै परमात्मा अनुभव गर्छ र सबैप्रति समान प्रेम र भावना राख्छ । तर यहाँ समदृष्टि भनेको सबैसँग एउटै व्यवहार गर्नु होइन, किनकि भगवान्‌ले समदर्शी भन्नुभएको छ समवर्ती होइन । ज्ञानीको भावना सबैप्रति समान हुन्छ, तर व्यवहार अवस्था अनुसार फरक हुन्छ । जस्तै आमाले सबै सन्तानलाई समान माया गर्छिन् तर सानो, बिरामी र बलियो सन्तानलाई आवश्यकता अनुसार फरक-फरक व्यवहार गर्छिन् । त्यसैगरी कसैको कल्याणका लागि कहिलेकाहीँ सजाय पनि दिनु पर्छ । सन्तहरूको जीवनमा पनि यही देखिन्छ । नामदेवले कुकुरमा भगवान्‌ देखे र एकनाथले गधामा भगवान्‌ देखेर गंगाजल पिलाए । त्यसैले साँचो ज्ञानीको दृष्टिले सबैमा एउटै परमात्मा देख्छ, सबैप्रति समान भावना राख्छ तर अवस्था अनुसार फरक व्यवहार गर्छ ।
5.19
इहैव तैर्जितः(स्) सर्गो, येषां(म्) साम्ये स्थितं(म्) मनः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (5, 19, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=aFcdLpMQ0gQ', '2026-03-22', 'जुन पुरुषहरूको मन (अन्तःकरण) समभावमा स्थित छ, उनीहरूले जीवित अवस्थामा नै सम्पूर्ण संसारलाई जितिसकेको हुन्छ, किनकि ब्रह्म दोषरहित र सम छ; यसकारण साम्यबुद्धि भएका पुरुषहरू सधैँ परमात्मामा स्थित रहन्छन् ।
भगवान्‌ यहाँ भन्नुहुन्छ-
इहैव तैर्जितः सर्गो येषां मनः साम्ये स्थितम्
- जसको मन यसरी समत्वमा स्थित भएको हुन्छ, त्यसले साँचो समत्वको अर्थ बुझेको हुन्छ । समत्व भनेको केवल भन्ने कुरा होइन । कुकुरमा पनि एउटै चेतना छ भनेर उसलाई डाइनिङ टेबलमा राख्नु सही व्यवहार होइन । जहाँ उसको स्थान हो, त्यहीँ राखेर पनि अन्तःकरणबाट प्रेम प्रकट गर्नु नै साँचो समत्व हो । जसको मन समत्वमा स्थिर भएको छ,
तै इह एव
- यहि शरिरमा रहँदै उसले संसार जितिसकेको हुन्छ ।
ब्रह्म निर्दोषं समं
- ब्रह्म विद्या जसले यो सृष्टी चलाएको छ, नियन्त्रण गरेको छ, चैतन्य छ उसको स्वभाव निर्दोष छ । जसरी चन्द्रमाको चाँदनी, सूर्यको प्रकाश, हावा र पानी सबैका लागि समान हुन्छन्, त्यसैगरी ब्रह्म पनि सबैका लागि समान हुन्छ । यस समत्वलाई जसले बुझ्छ,
ते ते ब्रह्मणि स्थिताः
- ऊ सधैँ परमात्मामा स्थित हुन्छ । राम राज्याभिषेकका लागि सजिँदा जति प्रसन्न थिए, वनवास जाँदा पनि त्यत्तिकै प्रसन्न रहे । यही हो समत्व- जहाँ बाहिरी परिस्थितिले अन्तःकरणलाई बदल्न सक्दैन ।
5.20
न प्रहृष्येत्प्रियं(म्) प्राप्य, नोद्विजेत्प्राप्य चाप्रियम् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (5, 20, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=aFcdLpMQ0gQ', '2026-03-22', 'जुन पुरुष प्रिय वस्तु प्राप्‍त गर्दा हर्षित हुँदैन र अप्रियलाई प्राप्‍त गरेर खिन्न पनि हुँदैन, त्यस्तो स्थिरबुद्धि भएको, संशयरहित ब्रह्मवेत्ता पुरुष सच्चिदानन्दघन परब्रह्म परमात्मामा एकै भावले नित्य स्थित हुन्छ ।
प्रियं प्राप्य
- प्रिय कुरा प्राप्त हुँदा, अनुकूल अवस्था आउँदा
न प्रहृष्येत्
- जो व्यक्ति हर्षोल्लासित हुँदैन । प्रसन्न हुनु अलग कुरा हो, तर त्यसको प्रदर्शन गर्नु, देखाउनु आवश्यक हुँदैन, किनकि त्यसले अरूमा असन्तोष ल्याउन सक्छ । त्यसैगरी
अप्रियं प्राप्यं न उद्विजेत्
- प्रतिकूल कुरा हुँदा, अप्रिय अवस्था आउँदा पनि ऊ शोकाकुल वा विचलित हुँदैन । अचेल मानिसहरू अनुकूलतामा ‘युफोरिया’ (उन्माद) मा पुग्छन् र प्रतिकूलतामा ‘डिप्रेसन’ (नैरास्यता)मा झर्छन्, ज्ञानी व्यक्ति न अत्यधिक खुशीमा बहकिन्छ, न दुःखमा डुब्छ । यसको कारण के हो भने उसको अन्तःकरणमा स्थिरता हुन्छ । उसको बुद्धि स्थिर हुन्छ, ऊ समत्वमा स्थित हुन्छ ।
असम्मूढ-
जसको अज्ञान हटिसकेको छ, संशयरहित भएको छ,
ब्रह्मविद्ब्रह्मणि स्थितः
- त्यस्तो व्यक्ति ब्रह्मविद् भएर सधैँ परमात्मामा स्थित हुन्छ । ऊसले भगवान्‌को अनुभूति गरेको हुन्छ, तर त्यो आनन्दको पनि धेरै प्रदर्शन गर्दैन, र दुःखमा पनि डुब्दैन । यसरी उसको मन सन्तुलित रहन्छ, बाहिरी संसार बाहिर नै रहन्छ र उसलाई भित्रबाट विचलित गर्न सक्दैन ।
5.21
बाह्यस्पर्शेष्वसक्‍तात्मा, विन्दत्यात्मनि यत्सुखम् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (5, 21, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=aFcdLpMQ0gQ', '2026-03-22', 'जसको मन बाहिरका विषयभोगमा आसक्त हुँदैन, त्यस्ता पुरुषलाई नै आत्मामा स्थित सात्त्विक सुख प्राप्‍त हुन्छ । त्यसपछि त्यही सच्चिदानन्दघन परब्रह्म परमात्माको ध्यानरूपी योगमा अभिन्नभावले स्थित पुरुषले अक्षय सुख र आनन्दको अनुभव गर्दछ ।
बाह्य स्पर्शेषु असक्त आत्मा
– बाहिरका इन्द्रियका विषयहरू शब्द, स्पर्श, रूप, रस र गन्ध आदिका कारण हामी बाहिरी सृष्टिमा विचरण गर्छौँ । यो आवश्यक पनि छ किनकी जीवन निर्वाहका लागि विभिन्न वाणी, शब्द तथा ध्वनीहरु सुन्न; रूप, दृष्यादि हेर्न; सुगन्ध-दुर्गन्ध थाहा पाउन; खाद्यवस्तुहरुको स्वाद छुट्टयाउन; तातो-चिसो, दुखाइ पोलाई महसुस गराउन; ईन्द्रियहरूले आ-आफ्ना तरिकाले कार्य गर्छन् । बाहिरी स्पर्श नराम्रो होइन, तर त्यसमा टाँसिनु चैँ नराम्रो हो । तसर्थ असक्त आत्मा हुनु महत्त्वपूर्ण छ । किनकी असक्तआत्मा त्यसमा टाँसिदैन, त्यसमा लिप्त हुँदैन ।
आत्मनि यत् सुखम् विन्दति
- मानिसले आफ्नो अन्तःकरणमा जुन अखण्ड प्रसन्नताको अनुभव लिन्छ, त्यसमा ऊ अखण्ड रम्छ । बाहिरको सुख जसको पछाडि हामी दौडिन्छौँ, त्यो पराधीन हुन्छ । संसारका दृश्यहरू बदलिनाले बाहिरको सुख कहिलेकाहीँ बदलिन्छ, वा त्यसले हामीलाई निरन्तर सुख दिँन सक्तैन । तर यो सुख चाहीँ अखण्ड एकरस सुख हो, जसलाई हामी आनन्द भन्छौँ । त्यो स्वाधीन सुख, असीम सुख उसले प्राप्त गर्छ ।
स ब्रह्मयोगयुक्तात्मा
- जसको अन्तःकरण चारैतिरबाट त्यो परमात्मासँग टाँसिएको छ । त्यो ब्रह्म अर्थात् आफ्नो स्वरूपसँग निरन्तर जोडिएको छ भने अक्षयम् सुखम् अश्नुते- उसको प्रसन्नता कहिल्यै घट्दैन । उसले कहिल्यै क्षय नहुने अक्षय सुख प्राप्त गर्छ । उ अनन्त ऊर्जाको स्रोतसँग जोडिन्छ ।
5.22
ये हि संस्पर्शजा भोगा, दुःखयोनय एव ते ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (5, 22, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=aFcdLpMQ0gQ', '2026-03-22', 'यी इन्द्रिय र विषयका संयोगले उत्पन्न हुने सम्पूर्ण भोगहरूको आदि र अन्त्य छ, यद्यपि विजयी पुरूषहरूलाई सुखरूपी आभास हुन्छन्, तिनीहरू नै दुःखका कारण हुन् र अनित्य छन् । अतः हे कौन्तेय! बुद्धिमान् विवेकी पुरुष तिनमा रमाउँदैनन्‌ ।
सलाई यो संसारको स्वभाव थाहा भइसकेको हुँदा यो संसार भित्र पस्नु हुँदैन भन्ने वोध छ । त्यसैले उसले बाहिरी विषयहरूलाई बाहिरै राख्न सक्छ ।
ये हि संस्पर्शजा भोगा दुःखयोनय एव ते
- इन्द्रियहरूको विषयहरूसँग सम्पर्कबाट जुन संयोग हुन्छ, त्यसको वियोग पनि निश्चित छ । जसरी हामी कुनै पद, बस्तु वा सुख पाउँछौँ त्यो सधैँ हामी सँग रहँदैन; त्यसरी नै संयोग र वियोगका यी दुवै कुरा भईरहन्छन् । संसारको कुनै पनि पद वा भोगले निरन्तर सुख दिन सक्दैन । त्यसैले इन्द्रियहरूको आफ्नो विषयहरूसँग स्पर्श हुनाले उत्पन्न हुने यी भोगहरूको
आद्यन्तवन्तः
- आदि (सुरुवात) छ, त्यसको अन्त पनि छ । अहिले सुखदायक छन् भने कहिलेकाहीँ ती दुःखदायक हुन्छन् ।
गर्मी मौसममा हामीलाई कुलरले सुख दिन्छ भन्ने लाग्छ, तर यसले हामीलाई जाडो मौसममा सुख दिँदैन त्यतिबेला हामीलाई कम्बल र स्वेटर चाहिन्छ । आज जुन कुराले सुख दिन्छन् भोली हामीलाई तिनले दुःख दिन्छन् । त्यसैले विषयहरूमा सुख छैन । जब ती विषय हाम्रा लागि अनुकूल हुन्छन्, तब मात्र सुखदायक हुन्छन् । ज्ञानीले यो कुरा ध्यानमा राख्छ कि यस्ता विषय सृजित सुखको आदि पनि छ र अन्त पनि छ ।
न तेषु रमते बुधः
- ज्ञानी त्यसमा अल्झिँदैन । उसले आनन्द लिँदैन भन्ने होइन, तर ऊ त्यसमा लिप्त । सुख आयो भने भोग्छ, तर सबैका सामु त्यसको प्रदर्शन गर्दैन । दुःख आयो भने पचाउँछ, तर त्यो दुःखका कारण आफ्नो जीवनलाई प्रभावित हुन दिँदैन ।
5.23
शक्नोतीहैव यः(स्) सोढुं(म्), प्राक्शरीरविमोक्षणात् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (5, 23, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=aFcdLpMQ0gQ', '2026-03-22', 'जो पुरुष यस मनुष्य शरीरमा, शरीरको नाश हुनुभन्दा पहिले नै कामक्रोधद्वारा उत्पन्न हुने वेगलाई सहन गर्न समर्थ हुन्छ, त्यही पुरुष योगी हो र उही सुखी हो ।
इहैव यः सोढुं प्राक्शरीरविमोक्षणात्
- यो शरीर छोड्नु भन्दा पहिले नै जसले यी कुराहरू बुझ्दछ,
कामक्रोधोद्भवं वेगं
- काम र क्रोधको आवेगलाई ।
सोढुं शक्नोति
- जो सहनका लागि समर्थ हुन्छ, स
नरः युक्तः स सुखी
– त्यही मानिस परमात्मासँग निरन्तर अन्तर्युक्त छ, उनीसँगै जोडिएको छ भनेर बुझ्नुपर्छ र उसैले अखण्ड सुख प्राप्त गर्छ । त्यो सुख कहिल्यै नष्ट हुँदैन ।
भगवान् यहाँ व्याख्या गर्नुहुन्छ सुखी उही हुन्छ जो नित्य युक्त छ र जसले यो काम र क्रोधबाट उत्पन्न हुने आवेगलाई सहन सक्छ । एउटा भनाइ छ- रोगले भन्दा मानिसहरू वेगले धेरै मर्छन् । मानिसहरूमा वेगप्रति ठुलो आकर्षण छ । यी काम र क्रोधका पनि वेग र आवेग हुन्छन् जसले हाम्रो सत्संगत विवेक बुद्धिलाई ढाकिदिन्छन् । हाम्रा कतिपय कामनाहरू पुरा नहुँदा हामीमा क्रोध आउँछ । हाम्रो कामना पुरा गर्ने बाटोमा अवरोध गर्ने परिस्थिति वा व्यक्तिसँग क्रोध आउँछ ।
काम क्रोधोद्भवं वेगं सयुक्तः स सुखी नरः
- लाई जसले बुझेर सहन सिक्यो उसैले मात्र निरन्तर सुख प्राप्त गर्न सक्छ ।
5.24
योऽन्तःसुखोऽन्तरारामः(स्), तथान्तर्ज्योतिरेव यः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (5, 24, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=aFcdLpMQ0gQ', '2026-03-22', 'जो पुरुष अन्तरात्मामा नै आनन्दको अनुभूति गर्दछ, अन्तरआत्मामा नै रमण गर्दछ र जो आत्मज्ञानले प्रकाशित छ, त्यस्ता साङ्ख्ययोगी पुरुषले ब्रह्मनिर्वाणरूप (मोक्ष) अर्थात् शान्त ब्रह्मलाई प्राप्‍त गर्दछ ।
यो अन्तःसुखो अन्तरारामस्तथा अन्तर्ज्योति
- जसले अन्तःसुखको अनुभव लिन्छ । जसले त्यो अन्तरात्मामा स्थित परमात्मा तत्त्वको, कहिल्यै खण्डित नहुँने, अक्षय सुखको आनन्द लिन्छ ।
अन्तःसुख
- यसको एकपटक लत लागेपछि वा यसको अनुभूति भएपछि मानिस त्यही मात्र चाहना राख्छ । एक क्षणका लागि पनि यसको अनुभूति भयो भने बढ्छ । जसरी गीताजीले हामीलाई त्यहाँ जोड्नुहुन्छ, हामी बारम्बार त्यसलाई पढ्न चाहन्छौँ, सुन्न चाहन्छौँ । त्यसको गहिराइमा जान चाहन्छौँ, त्यसको चिन्तन सुन्न चाहन्छौँ र अर्थ जान्ने प्रयास गर्छौँ । त्यो अन्तःसुख हो, बढ्ने सुख हो ।
अन्तरारामः
- आफ्नो भित्रको आत्माराममा रम्नु अर्थात् आफ्नो अन्तरङ्गमा रामको अनुभूति पाउनु । । भनिन्छ- राम विश्राम, राममा नै त्यो आराम छ, त्यो विश्राम छ । अहिले हाम्रा रामजीकै नवरात्रि चलिरहेको वर्तमान अवस्थामा उहाँ अन्तराराम- हाम्रै भित्र विश्रान्ति वा आरामको रूपमा स्थित हुनुहुन्छ । हामी कसैलाई भेट्दा राम-राम भन्छौँ, यसको अर्थ हो मेरो भित्रको राम र तपाईंको भित्रको राम- दुवैको मिलाप भयो ।
अन्तर्ज्योति
- ज्ञानको ज्योति पनि भित्रै छ । बाहिरका यी सबै उपाधिहरू, बाहिरका यी सबै शास्त्रहरू जुन हामी पढ्छौँ, ती भित्रको त्यो ज्ञानको अनुभूतिका लागि हुन् जुन यी सबै आवरणले ढाकिएको छ ।
स्वामी विवेकानन्दजीले भन्नुभएको थियो– शिक्षा भित्री ज्ञानको अभिव्यक्ति हो (Education is manifestation of knowledge present within) । हामी सबैमा स्थित ढाकिएको भित्री ज्ञानको अनुभूतिका लागि शिक्षाको आवश्यकता पर्छ ।
ब्रह्मभूतो योगी ब्रह्मनिर्वाणम् अधिगच्छति
- त्यो व्यक्तिले ब्रह्मको निर्वाण अर्थात् शान्ति प्राप्त गर्छ, शान्त ब्रह्मलाई प्राप्त गर्छ । यसै प्रकारले तुलसीदासजी भन्नुहुन्छ-
नमामीशमीशान निर्वाणरूपं, विभुं व्यापकं ब्रह्म वेदस्वरूपं।
निजं निर्गुणं निर्विकल्पं निरीहं, चिदाकाशमाकाशवासं भजेहं॥
निराकार ओंकार मूलं तुरीयं, गिरा ज्ञान गोतीतमीशं गिरीशं।
करालं महाकाल कालं कृपालं, गुणागार संसारपारं नतोहं॥
भगवान् भन्नुहुन्छ- यस प्रकार जो अन्तःकरणको त्यो परमात्मा तत्त्वमा नित्य स्थित योगी छ, उसको जीवनमा अन्तःसुख, अन्तर्ज्योति, अन्तराराम, ब्रह्मनिर्वाण प्राप्त गर्दछ ।
5.25
लभन्ते ब्रह्मनिर्वाणम्, ऋषयः क्षीणकल्मषाः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (5, 25, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=aFcdLpMQ0gQ', '2026-03-22', 'जसका सबै पापहरू नष्ट भएर गएका छन्, जो सम्पूर्ण प्राणीहरूको भलो चिताउँछ, जसका सम्पूर्ण शङ्काहरू ज्ञानका माध्यमले निवृत्त भएर गएका छन्, जसको जितिएको मन निश्चलभावले परमात्मामा स्थित छ, त्यस्ता ब्रह्मवेत्ता ज्ञानी पुरुषले ब्रह्मनिर्वाणरूप (मोक्ष) अर्थात् शान्त ब्रह्मलाई प्राप्‍त गर्दछ ।
यस श्लोकमा भगवान्‌ले परमावस्थालाई प्राप्त गर्न सक्ने ऋषिमुनीहरूको गुणको वर्णन गर्नुभएको छ ।
क्षीण-कल्मषाः
- जसका अशुद्धिहरू नष्ट भएका छन् । सबै पाप, नकारात्मक प्रवृत्ति, र मनका अशुद्धिहरू (कल्मष) क्रमशः कर्मयोग, भक्ति, र ज्ञानद्वारा हटाइन्छन् । मन शुद्ध र पारदर्शी हुन्छ ।
छिन्न-द्वैधाः
- जसका शंका र द्वन्द्वहरू काटिएका छन् । सबै आन्तरिक द्वन्द्व, भ्रम, र शंका (संशय) निवारण भएका छन् । यो-त्यो, ठिक-बेठिक, लाभ-हानी जस्ता विरोधी विचारहरूमा मन डुल्दैन । उनीहरूको दृष्टि स्पष्ट र एकीकृत भएको हुन्छ ।
यतात्मानः
- जसले मनलाई जितेका छन् । अनुशासन र अभ्यासद्वारा इन्द्रिय र मन नियन्त्रणमा ल्याउँछन्, आवेगद्वारा नभई, ज्ञानद्वारा निर्देशित हुन्छन् ।
सर्व-भूत-हिते रताः
- जसले सबै प्राणिहरूको हितमा आनन्द पाउँछन्, केवल आफ्ना लागि बाँच्दैनन्, सम्पूर्ण अस्तित्वको एकत्वलाई अनुभूत गर्छन् र स्वाभाविक रूपमा सबैको कल्याणका लागि कार्य गर्छन् । करुणा, सेवा, र समता जस्ता अनुभूति स्वतः उत्पन्न हुन्छन् । उनिहरूमा कुनै स्वार्थ हुँदैन - केवल एकत्वको प्राकृतिक अभिव्यक्ति मात्र हुन्छ ।
यी गुणहरू हुँदा-
लभन्ते ब्रह्म-निर्वाणम्
- उनीहरूले ब्रह्म प्राप्त गर्छन्, परम् शान्तिको अवस्थामा पुग्छन् । यो नै आध्यात्मिक यात्राको पराकाष्ठा हो - जहाँ बन्धनबाट मुक्ति, परमात्मासँग ऐक्यभाव, र शाश्वत शान्तिमा स्थिरता रहन्छ । यस श्लोकले आध्यात्मिक अनुभूति केवल आन्तरिक अनुभव मात्र होइन, बाह्य रूपमा करुणा र सेवाका रूपमा पनि प्रकट हुन्छ भन्ने एउटा गहिरो सत्यलाई प्रकाश पार्छ । साँचो ब्रह्मज्ञानीहरू आन्तरिक रूपमा शुद्ध हुन्छन्, शंकाबाट मुक्त हुन्छन्, आत्मनियन्त्रित हुन्छन् र सबै प्राणिहरूको हितमा सक्रिय हुन्छन् । यसरी सम्पूर्ण आन्तरिक अस्तित्वको रूपान्तरण र निःस्वार्थ सेवाले ब्रह्मसम्मको मार्ग निर्धारण गर्छ ।
5.26
कामक्रोधवियुक्‍तानां(य्ँ), यतीनां(य्ँ) यतचेतसाम् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (5, 26, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=aFcdLpMQ0gQ', '2026-03-22', 'कामक्रोधबाट सर्वथा रहित, मनलाई जित्ने आत्मसंयमी र परब्रह्म परमात्मालाई साक्षात्कार गरेको ज्ञानी पुरुषका लागि सम्पूर्ण दृष्टिले शान्त परब्रह्म परमात्मा नै परिपूर्ण हुन्छ ।
कामक्रोधवियुक्तानाम्
- जसले काम र क्रोध यी दुबैको आवेगबाट आफ्नो चित्तलाई वियुक्त (मुक्त) गरेका छन् । युक्त भनेको जोडिनु, वियुक्त भनेको अलग हुनु हो । आवेगले हाम्रो सत्-असत् विवेक बुद्धि नष्ट हुन्छ । आवेगको सम्बन्धमा एउटा प्रसङ्ग - एकजनाले भर्खरै किनेको स्क्रिन गार्ड पनि नराखिएको महँगो एप्पल मोबाइल उसको छोराको हातमा पर्‍यो । छोराले त्यसलाई भुइँमा खसालेर स्क्रिन फुट्यो । त्यतिबेला उसले केही नसोची छोरालाई जोडसँग गालामा चड्कन हान्यो, छोराको चश्मा फुट्यो र आँखामा काँचका टुक्रा पसे । यो क्रोधको आवेग हो । कामनामा कसैले अवरोध गरेमा वा आफ्नो बस्तु खोसिँदैछ भन्ने लागेमा यस्तो आवेग उत्पन्न हुन्छ । यो काम र क्रोधले हाम्रो जीवनलाई तनावग्रस्त बनाउँछ । हामीलाई अधोगतितर्फ लैजान्छ ।
यतचेतसा
- जसले आफ्नो चित्त, अन्तःकरण, क्रियामा नियन्त्रण ल्याउँछन् । विधितात्मनाम्- उनीहरूले परमात्माको साक्षात्कार पाउँछन् ।
यतीनाम्
- ज्ञानीजनहरू चारैतिर परमात्माको अनुभूतिमा जीवन बिताउँछन् । उनीहरू निर्वाणको शान्ति अनुभव गर्छन् ।
5.27
स्पर्शान्कृत्वा बहिर्बाह्यांश्, चक्षुश्चैवान्तरे भ्रुवोः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (5, 27, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=aFcdLpMQ0gQ', '2026-03-22', 'जसले बाहिरका विषयभोगहरूलाई बाहिर नै त्याग गरेर र आखाँको दृष्टिलाई भृकुटी अर्थात् आँखीभौँका बीचमा केन्द्रित गरी नासिकामा विचरण गर्ने प्राण र अपान वायुलाई सम राख्दछ, उसले सदासर्वदा मुक्त नै प्राप्‍त गर्दछ ।
5.27 writeup
5.28
यतेन्द्रियमनोबुद्धि:(र्), मुनिर्मोक्षपरायणः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (5, 28, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=aFcdLpMQ0gQ', '2026-03-22', 'जसको इन्द्रिय, मन र बुद्धि आफ्नो वशमा छ तथा जो इच्छा, भय र क्रोधबाट सर्वथा रहित छ, त्यस्ता मोक्ष परायण मुनि सदासर्वदा मुक्त नै हुन्छ ।
हामीलाई काम-क्रोधबाट वियुक्त हुन र निरन्तर अखण्ड प्रसन्नता अन्तःकरणमा स्थित गराउने उपाय बताउँदै भगवान्‌ भन्नुहुन्छ-
भ्रुवोर्मध्य
- आँखीभौँको बिचमा चक्षु- नजर राखी, प्राण-अपानलाई समान बनाउँदै
नासाभ्यन्तर
- दुबै नासिकाको सहायताले मनलाई एकाग्र गर्दै मोक्षपरायण मुनिहरू प्राणायाम गर्छन् । जसरी पानी जेमा मिसायो, त्यसैको रूप लिन्छ । त्यसरी नै मन पनि जोसँग जोडिन्छ, त्यसैको गुण ग्रहण गर्छ । जब मनलाई श्वासमा लगाउँछौं, प्राणायाम गर्छौं तब मन वायुसँग एकाकार हुन्छ । वायु विशाल छ, गगनसँग मिल्छ । त्यसैले मन पनि विशाल हुन्छ । वासनाहरू हटेर जान्छन् । ज्ञानेश्वर महाराज भन्नुहुन्छ-
तैसी वासनांतराची विवंचना ।
मग आपैसी पारुखे अर्जुना ।
जे वेळीं गगनीं लयो मना ।
पवनें कीजे ॥
मन वायुसँग जोडिँदा वासनाबाट अलग हुन्छ । आकाशसँग मिल्दा मन व्यापक हुन्छ । संसारको चित्र मनमा अंकित हुन्छ । तर जब मन विशाल हुन्छ, सांसारिक चिन्तन हट्छ, परमात्माको दर्शन हुन्छ ।
5.29
भोक्‍तारं(य्ँ) यज्ञतपसां(म्), सर्वलोकमहेश्वरम् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (5, 29, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=aFcdLpMQ0gQ', '2026-03-22', 'जुन पुरुषले मलाई सबै यज्ञ र तपहरूको भोग गर्ने, सम्पूर्ण लोकहरूको अधिपति (ईश्वर) तथा सम्पूर्ण प्राणीहरूको सुहृद् अर्थात् स्वार्थरहित, दयालु, प्रेमी र भलो चाहने मित्रको रूपमा तत्त्वपूर्वक जान्दन्छ, उसले नै शान्ति प्राप्‍त गर्दछ ।
भगवान् भन्नुहुन्छ- यज्ञ, तप आदि कर्मबाट हुने कार्यको भोक्ता म हुँ । सबै प्राणीहरूको सुहृद म हुँ । जसले यसरी मलाई चिन्छ, उसले परमशान्ति प्राप्त गर्छ । कृष्णको दिव्य मित्रता प्राप्त गर्छ । त्यसपछि अशान्ति हट्छ । सत्-चित्-आनन्द परमात्माको अनुभूति हुन्छ ।
प्रश्नोत्तर
प्रश्नकर्ताः
- डा. आर. पी. पटेल दाजु
प्रश्न:-
मन कसरी बन्दछ र मृत्यु पछि मन के हुन्छ?
उत्तर:-
हामीले यो पङ्क्तिमा चिन्तन गर्यौँ- तो मनोरूप पट फाटे- संसार प्रक्षेपित भएको मानसिक पर्दा च्यातिन्छ । मन (मनस्) स्थिर वस्तु होइन; यो सङ्कल्प (उद्देश्य) र विकल्प (सन्देह वा विकल्पहरू) द्वारा आकार लिइरहने निरन्तर प्रवाह हो । यो मूलतः विचार, छाप र प्रतिक्रियाहरूको क्षेत्र हो । भगवान्‌ले अध्याय ७ मा भन्नुभएको छ-
भूमिरापोऽनलो वायु: खं मनो बुद्धिरेव च ।
अहङ्कार इतीयं मे भिन्ना प्रकृतिरष्टधा ॥ ७.४ ॥
यहाँ मन, बुद्धि, र अहङ्कारलाई प्रकृतिको अङ्गका रूपमा वर्णन गरिएको छ । त्यसैले मन आत्मा होइन, तर एउटा उपकरण हो जुन सूक्ष्म, शक्तिशाली, र निरन्तर परिवर्तनशील हुन्छ । मनले विगतका कर्म, अनुभव, र सङ्गतिबाट बनेका संचित संस्कारहरू (छापहरू) द्वारा आकार लिन्छ । यी संस्कारहरूले हाम्रो प्रवृत्ति, रुचि, र प्रतिक्रिया निर्धारण गर्छन् । मन अत्यन्त सूक्ष्म छ यसलाई सजिलै बुझ्न सकिँदैन, किनकि यो सधैं परिवर्तनशील र दुर्लभ छ ।
मन प्रकृतिको अङ्ग भएकाले यो शरीरसँगै नष्ट हुँदैन । यो संस्कारहरू बोकेर सूक्ष्म शरीरको अङ्गका रूपमा निरन्तर रहन्छ । यी संस्कारहरूले भविष्यका अनुभव र यात्राहरूलाई आकार दिन्छन् । तर आध्यात्मिक जीवनको उद्देश्य केवल मन बुझ्नु मात्र होइन, यसलाई शुद्ध, परिष्कृत, र अन्ततः अतिक्रमण गर्नु हो । भक्तिले यस रूपान्तरणमा महत्त्वपूर्ण भूमिका खेल्छ जसले- यो मनलाई शुद्ध गर्छ, अशान्तता घटाउँछ, मनलाई भगवान्‌तर्फ उन्मुख बनाउँछ । मनको स्वभाव यस्तो हुन्छ कि यसले सङ्गतिलाई अनुकरण गर्छ- मन सांसारिक विचलनको सङ्गतिमा अशान्त र छरपस्ट हुन्छ तथा दिव्य सङ्गतिमा शान्त, शुद्ध, र स्थिर हुन्छ । त्यसैले हामीले- मनलाई श्रेष्ठ विचारतर्फ मार्गदर्शन गर्नु, भगवान्‌को स्मरणमा लगाउनु, सत्सङ्ग, शास्त्र र सेवासँग जोडिराख्नु पर्छ ।
जब मन क्रमशः शुद्ध हुन्छ, यसको अशान्तता घट्छ । जब वासनाहरू कमजोर हुन्छन्, यसको प्रक्षेपणहरू हराउँछन् । जब मानसिक पर्दा नै विलीन हुन्छ, आत्माको सत्य स्वरूप प्रकट हुन्छ । यसैले मनलाई दबाउन संघर्ष नगर्नुहोस्- यसलाई पवित्र बनाउनुहोस्, उच्च बनाउनुहोस्, र भगवान्‌सँग मिलाउनुहोस् । त्यही मिलनमा नै स्वतन्त्रता छ ।
प्रश्नकर्ताः
- दर्शन अमिन दाजु
प्रश्नः
- भगवद्गीता महर्षी वेदव्यासले रचना गर्नुभएको महाभारतको अङ्गको रूपमा रहेको छ र जसलाई भगवान्‌ गणेशले लिपिबद्ध गर्नुभएको हो । यो अद्भुत कृतिले विशाल ब्रह्माण्डीय शक्तिलाई प्रतिबिम्बित गर्छ । के आज पनि त्यस्ता आध्यात्मिक शक्तिशाली व्यक्तित्वहरू अस्तित्वमा छन्?
उत्तर-
: निश्चय नै, यस्ता उच्च आत्माहरू सबै समयमा अस्तित्वमा रहेका हुन्छन्, यद्यपि तिनीहरू सधैं व्यापक रूपमा पहिचान गरिँदैनन् । त्यस्ता एक उदाहरण हुन्- प्रज्ञाचक्षु गुलाबराव महाराज । बाल्यकालदेखि नै दृष्टिहीन भए पनि, उनले १३४ भन्दा बढी गहन आध्यात्मिक ग्रन्थहरू लेखे । उनको ज्ञान बाह्य दृष्टिबाट होइन, गहिरो आन्तरिक अनुभूति बाट आएको थियो । यस्तो प्रतिभामा सामान्य बुद्धि होइन, दिव्य अन्तर्दृष्टि र आध्यात्मिक शक्ति हुन्छ । आफ्नो आध्यात्मिक शक्तिबाट उनले आफ्ना शिष्यहरूलाई उच्च अस्तित्वका झलकहरू देख्न र हिमालयमा बस्ने महान् योगीहरूलाई अनुभव गर्न सक्षम बनाएका थिए भन्ने भनाई छ । यस्ता महात्माहरू विद्वानमात्र नभई भगवान्‌सँग चेतना मिलेका ब्रह्माण्डीय ऊर्जा अर्थात् परमात्मासँगको गहिरो सम्बन्ध प्राप्त प्राणीहरू हुन् ।
आज पनि यस्ता साक्षात्कार प्राप्त आत्माहरू छन् । तर उनीहरू प्रायः - साधारण देखिने, प्रचारप्रसारबाट टाढा रहने, शान्त रूपमा साधकहरूलाई मार्गदर्शन गर्ने प्रवृत्तिका हुन्छन् । तिनीहरूको उपस्थिती बाह्य रूपमा सधैं देखिँदैन, तर प्रभाव गहिरो हुन्छ । आध्यात्मिक महानता कुनै युगमा मात्र सीमित छैन । जहाँ गहिरो साक्षात्कार, मनको शुद्धता, र भगवान्‌सँगको मिलन हुन्छ, त्यहाँ यस्ता अद्भुत व्यक्तित्वहरू निरन्तर प्रकट भइरहन्छन् ।
﻿
प्रश्नकर्ताः-
धनश्री दिदी
प्रश्नः
- हामीले आफन्तहरू लाई राम्रो गर्न ईमानदारीपूर्वक प्रयास गर्दागर्दै पनि अपेक्षा अनुसार जस पाउँदैनौँ । हामी यसलाई भाग्यको खेल ठान्दछौँ । यस्ता परिस्थितिसँग कसरी सामना गर्ने? कसरी वैराग्य विकास गर्ने?
उत्तरः
- यो अत्यन्तै भावनात्मक र व्यावहारिक प्रश्न हो । पहिले हामीले हाम्रो सम्बन्धको बुझाइमा परिवर्तन गर्नुपर्छ । हाम्रा प्रियजनहरू पूर्ण अर्थमा “हाम्रा” होइनन् - उनीहरू भगवान्‌का हुन्, जसरी सम्पूर्ण सृष्टि उहाँको हो । हामीलाई केवल तिनीहरूको हेरचाह गर्ने भूमिका दिइएको हो, किनकि भगवान्‌ले हामीलाई उनीहरूसँग जोड्नुभएको छ । जब हामी सम्बन्धलाई यस दृष्टिले हेर्छौं, हाम्रो दृष्टिकोण स्वामित्वबाट जिम्मेवारीतर्फ बदलिन्छ ।
वैराग्य कठिन हुन्छ । विशेष गरी आमाहरूका लागि झन् कठिन हुन्छ, किनकि उनीहरूले आफ्ना सन्तानलाई जन्म दिन्छन् र पालनपोषण गर्छन् । भावनात्मक सम्बन्ध गहिरो र प्राकृतिक हुन्छ । यहाँ वैराग्यको अर्थ प्रेमको अभाव होइन - यो आसक्ति र चिन्ताबाट मुक्ति हो । हामीले यसरी विचार गर्नुपर्छ- मैले आफ्नो क्षमताभित्र सर्वोत्तम प्रयास गरेको छु, परिणाम मेरो हातमा छैन,भगवान्‌ नै साँचो पालक हुन् । जब मेरा प्रियजनहरू भगवान्‌का हुन् भन्नेमा हाम्रो विश्वास दृढ हुन्छ । त्यसपछि चिन्ताको बोझ घट्न थाल्छ । यो मेरो, यो तिम्रो, मेरो परिवार, मेरो जिम्मेवारी, मेरो नियन्त्रण भन्नुको साटो “हे भगवान्‌, उनीहरू तपाईंका हुन् । तपाईंले मलाई उनीहरू सुम्पनुभएको छ । म आफ्नो सर्वोत्तम क्षमताले सेवा गर्नेछु ।” भन्ने भावना उठ्नु एक शक्तिशाली आन्तरिक परिवर्तन हो । यसले आसक्तिलाई सेवामा रूपान्तरण गर्छ । जब “यो संसार म र मेरो होइन, तिमी र तिम्रो हो ।” भन्ने बुझाइ गहिरो हुन्छ । तब- प्रयासहरू ईमानदार रहन्छन्, प्रेम शुद्ध रहन्छ, चिन्ता घट्छ, स्वीकार्यता बढ्छ । यसैले वैराग्य भनेको अलग्गिनु होइन - यो जिम्मेवारीसहितको समर्पण हो । जब हामी निरन्तर पूर्ण हेरचाह र प्रेमसहित कार्य गर्छौं, तर परिणाम भगवान्‌को हातमा छोड्छौं, तब त्यस समर्पणमा नै साँचो शान्ति हुन्छ ।
ॐ तत्सदिति श्रीमद्भगवद्गीतासु उपनिषत्सु ब्रह्मविद्यायां(य्ँ) योगशास्त्रे श्रीकृष्णार्जुनसंवादे कर्मसन्न्यासयोगो नाम पञ्चमोऽध्याय: ।।५।।
यसप्रकार ॐ तत्सत्- यी भगवान्‌का नामहरूको उच्चारणपूर्वक ब्रह्मविद्या र योगशास्त्रमय श्रीमद्भगवद्गीताको उपनिषद्‌रूपी श्रीकृष्ण र अर्जुनको संवादस्वरूप ‘कर्मसन्न्यासयोग’ नाम भएको पाँचौँ अध्याय पूर्ण भयो ।
यो विवेचन पढेर तपाईँलाई अवश्य पनि राम्रो लाग्यो होला भन्ने हामीलाई विश्वास लागेको छ । कृपया तल दिएको लिङ्क प्रयोग गरी हामीलाई आफ्नो प्रतिक्रियाहरू दिनुहोला ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (12, 2, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=DBuI7vNg06E', '2026-03-21', 'श्रीभगवान् भन्नुहुन्छ- जो भक्तहरू अतिशय श्रेष्ठ श्रद्धाले युक्त भएर, ममा मनलाई एकाग्र गरेर, नित्य-निरन्तर मेरो भजन ध्यान गरेर, म सगुणस्वरूप परमेश्वरलाई भज्दछन्, ती मेरा लागि योगीहरूमा पनि अति उत्तम योगी मानिन्छन् ।
जब अर्जुनले श्रेष्ठताको प्रश्न गरे तब भगवान्‌ले उत्तर दिँदै भन्नुभयो- "जो भक्त आफ्नो मनलाई ममा प्रतिष्ठित गर्छ, जो मेरो अलावा अन्य कुनै विषयको चिन्तन गर्दैन, त्यही भक्त मलाई परम् प्रिय लाग्छ।"
यो स्थिति त्यस नाबालकको समान छ, जसले संसारमा आफ्नो आमाबाहेक अरू कसैलाई चिन्दैन । उसलाई आफ्नो बुबाको पनि महसुस हुन्न, उसलाई त केवल आफ्नै आमा मात्र चाहिन्छ । ठीक त्यसैगरी, जो भक्त एकनिष्ठ भएर सदैव भगवान्‌लाई नै आफ्नो अन्तःकरणमा धारण गर्दछ, ऊ त्यस अबोध बालक जस्तै हो, जो आफ्नो आमालाई एकक्षणको लागि पनि ओझेल हुन दिन्न ।
भगवान् भन्नुहुन्छ कि- यस्तो भक्त जो नित्य-निरन्तर ममा नै युक्त भएर मेरो उपासना गर्दछ र परम् श्रद्धाभावले ओत-प्रोत भएर मेरो भजन गर्दछ, ऊ नै मेरो दृष्टिमा सर्वोत्तम योगी हो । ऊ ममा पूर्णतः समाहित हुन्छ । तर जसरी आमाको लागि उसको जेठो छोरो पनि उत्तिकै प्रिय लाग्छ, त्यस्तै भगवान्‌ले आउने श्लोकमा यसै भावलाई सन्तुलित गर्नुभएको छ ।
वहाँले अर्जुनलाई स्पष्टसँग भन्नुभयो कि यस्तो कदापि होइन कि केवल सगुण-साकारको भक्ति गर्नेले मात्रै मलाई प्राप्त गर्दछ । यद्यपि जो साधक आफ्नो इन्द्रियहरूलाई वशमा राखेर त्यस निर्गुण-निराकार र अव्यक्त ब्रह्मको उपासना गर्दछ, ऊ पनि अन्ततः मसम्म नै पुग्दछ ।
12.3
ये त्वक्षरमनिर्देश्यम्, अव्यक्‍तं(म्) पर्युपासते ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (12, 3, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=DBuI7vNg06E', '2026-03-21', 'तर, जुन पुरुषले आफ्नो इन्द्रियहरूलाई राम्रोसित वशमा राखी मन-बुद्धिदेखि पर, सर्वव्यापी, अचल, नित्य, निराकार र अविनाशी सच्चिदानन्दघन ब्रह्मलाई निरन्तर एकभावले ध्यान गर्दै भज्दछन् ।
12.4
सन्नियम्येन्द्रियग्रामं(म्), सर्वत्र समबुद्धयः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (12, 4, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=DBuI7vNg06E', '2026-03-21', 'ती सम्पूर्ण भूतहरूको हितमा संलग्न, अकथनीयस्वरूप र सदा एकरस रहने, समान बुद्धभाव भएका योगीले मलाई नै प्राप्‍त गर्दछन् ।
भगवान्‌ले दोस्रो श्लोकमा सगुण भक्तको श्रेष्ठताको प्रतिपादन गर्नुभयो । तेस्रो र चौथो श्लोकमा उहाँले त्यस गम्भीर सत्यलाई सन्तुलित गर्नुभएको छ । उहाँ अर्जुनलाई भन्नुहुन्छ कि यस्तो कदापि होइन कि निराकारको उपासना गर्ने मलाई प्रिय छैन भनेर ।
यदि निर्गुण-निराकारको तपस्या गर्ने हो भने आफ्ना इन्द्रियहरूको कठोर नियमको अनुशासनमा बाँधिनु पर्नेछ । यो शरीर नौवटा ढोका भएको एउटा पिण्ड हो, जसमा दुईवटा आँखा, दुईवटा नाकको प्वाल, दुईवटा कान, छाला, एउटा जिब्रो र मन छ । यी समस्त इन्द्रियहरूमाथि जसले पूर्णतः संयम राख्दछ उही यस मार्गमा अग्रसर हुन सक्दछ ।
यसक साथै, साधकको बुद्धि सर्वत्र समबुद्धयः हुनुपर्दछ । उसको मनमा सबैको लागि समताको भाव हुनुपर्छ, जहाँ आफ्नो र अरूको, चीसो र तातो जस्तो कुनै भेद बाँकी नरहोस् । सर्वत्रगमचिन्त्यं(ञ्) च- सबै ठाउँमा परिपूर्ण उहाँ निराकार ब्रह्म अनिर्देश्यम् हुनुहुन्छ, जसलाई औँलाले निर्देश गरेर देखाउन सकिन्न । उहाँ कूटस्थम् हुनुहुन्छ अर्थात् निर्विकार उहाँ अचल हुनुहुन्छ, जसरी ध्रुव तारा आफ्नो स्थितिमा सदैव स्थिर रहन्छ ।
यस्तो अचल, अक्षर र अव्यक्त स्वरूप परमात्मालाई, जसले पर्युपासते अर्थात् उपासना गर्दछ, त्यस्तो योगी समस्त प्राणीहरूको हितको नै चिन्ता गर्ने हुन्छ, अन्ततः उनीहरूले मलाई नै प्राप्त गर्दछन् । भगवान् स्पष्टसँग भन्नुहुन्छ कि यद्यपि सगुण भक्त मेरो हृदयको नजिक छ तर यो निर्गुण उपासक पनि, जो सबैजनाप्रति समदृष्टि राख्दछ, अन्ततः मलाई नै प्राप्त गर्दछ । यो त त्यस्तै नै कुरा भयो कि आमालाई कान्छो छोरो अत्यन्त प्रिय हुन्छ किनकि ऊ पूर्णतः आश्रित हुन्छ तर यसको अर्थ कदापि यो होइन कि ऊ आफ्नो जेठो छोरोलाई माया नै गर्दैन ।
12.5
क्लेशोऽधिकतरस्तेषाम्, अव्यक्‍तासक्‍तचेतसाम् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (12, 5, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=DBuI7vNg06E', '2026-03-21', 'ती सच्चिदानन्दघन निराकार ब्रह्ममा आसक्त चित्त भएका पुरुषहरूलाई आफ्नो साधनामा धेरै परिश्रम लाग्दछ किनकि देहाभिमानीहरूलाई अव्यक्त-विषयक गति दुःखपूर्वक मात्र प्राप्‍त हुन आउँछ ।
भगवान्‌ले पाँचौँ श्लोकमा एउटा व्यावहारिक सत्यको उद्घाटन गर्नुभएको छ । वहाँ अर्जुनलाई भन्नुहुन्छ-
क्लेशोऽधिकतरस्तेषाम्, अव्यक्तासक्तचेतसाम्
- त्यस्ता साधकहरूको साधनामा क्लेश अर्थात् कष्ट र वाधाहरू धेरै हुन्छन् जसको चित्त त्यस अव्यक्त निराकार ब्रह्ममा आसक्त हुन्छ ।
यस मार्गमा हिँड्नको लागि इन्द्रियहरूमा वज्र जस्तो नियन्त्रण हुनु अनिवार्य छ । आफ्नो जिब्रोमाथि संयम राख्ने, के बोल्ने के नबोल्ने, के सुन्ने के नसुन्ने, के हेर्ने के नहेर्ने र यी सबैमा निरन्तर सजग रहनुपर्नेछ । आजको युगको उदाहरण हेर्‍यौँ भने जब हामी मोबाइमा इन्स्टाग्रामका रील्स हेर्न थाल्यौँ भने समय गएको पत्तै पाउँदैनौँ । निर्गुणको उपासनाका लागि आफ्नो आँखामाथि नियन्त्रणको यस्तो कठोर सङ्कल्प लिनुपर्छ कि अनुचित दृश्यहरू हेर्नुअघि नै आँखा बन्द गर्ने । यस्तो कठोर संयमताविना निराकारको साधना सम्भव हुँदैन ।
देहवद्भिरवाप्यते
- यसको साथै जो जीव देहाभिमानी हुन्छ अर्थात् जो यस शरीरसँग एकाकार भएर संसारमा आएको हो, उसका लागि त्यस निराकार सत्तालाई बुझ्नु अत्यन्त दुष्कर छ जसको कुनै आकृति पनि छैन । जबसम्म हामी स्वयंलाई यस शरीरबाट अलग अनुभव गर्दैन, तबसम्म त्यस अशरीरीय परमात्माको साक्षात्कार कसरी सम्भव छ? यसकारण भगवान् भन्नुहुन्छ कि शरीरधारीहरूका लागि अव्यक्तको गति अत्यन्त क्लेशपूर्ण हुन्छ । भगवान्‌ले स्पष्ट पारिदिनुभएको छ कि त्यस अव्यक्तको उपासना र त्यसको गतिलाई बुझ्न अत्यन्त कष्टदायक छ । यो मार्ग त्यति सरल छैन जति देखिन्छ; यसलाई धेरै नै कठिन र कठोर तपस्याद्वारा मात्र प्राप्त गर्न सकिन्छ ।
निर्गुण मार्गको यात्री उही हुन्छ, जसले यो निश्चय गर्छ कि म आफ्नो ज्ञानको शक्ति र आफ्नो पुरुषार्थको बलले यस संसार-रूपी भवसागरलाई तरेर पार गर्नेछु । कल्पना गर्नुहोस् त, कुनै विशाल र अनन्त समुद्रको एक किनाराबाट अर्को किनारासम्म जानको लागि कसैले पानीमा हाम्फालोस् । के ऊ सजिलै गन्तव्यसम्म पुग्न सक्ला त? अवश्य सक्दैन । बाटोमा थकान हुन्छ, उग्र छालहरू आउँछन् र ऊ बीचैमा कतै डुब्न सक्छ । यसको विपरीत ऊ भक्त हो र उसले एउटा कुशल पानीजहाज चालक भेट्टाएको छ र पूर्ण श्रद्धाका साथ उसलाई भरोसा गरेर उसको जहाजमा बसेको छ । अब विचार गर्नुहोस् त, एकपटक जब यात्री जहाजमा बस्छ, गन्तव्यसम्म पुर्‍याइदिने उत्तरदायित्व कस्को हुन्छ? निश्चितरूपमा अब त्यो उत्तरदायित्व त्यस पानीजहाज चालकको हुन्छ । यात्रीलाई सुरक्षित पारी पुर्‍याइदिनु अब चालकको धर्म हुन्छ । सगुण-साकारको उपासनाको अर्थ पनि यही हो- श्रीभगवान्‌माथि पूर्ण विश्वास गरेर उनकै कृपाको जहाजमा शान्तिसँग बसेर यात्रा गर्ने ।
त्यो सोझो भक्तले तर्क गर्दैन, ऊ त यति नै भन्छ, "हे भगवान्! म केवल तपाईँको हुँ, बस् मलाई आफ्नो काखमा राख्नुहोस्।" यो श्रीभगवान्‌को करुणा हो र उहाँको वचन पनि हो कि जो उहाँमा आश्रित हुन्छ, उसलाई किनारामा पुर्‍याइदिने अब उहाँको आफ्नो उत्तरदायित्व हुन्छ । जो आफ्नो क्षमतामा समुद्र पारी जाने चेष्टा गर्दछ, ऊ भुमरीमा पर्न सक्छ । तर जो श्रीभगवान्‌को शरणमा आउँछ, उसलाई स्वयं योगेश्वरले नै यस भवसागरबाट तारिदिनुहुन्छ ।
एउटा अति सुन्दर कथाको प्रसङ्ग रामायणमा आउँछ-
जब भगवान् वनवासका लागि अयोध्याबाट निस्कनुभयो तब बाटोमा गङ्गाजी तर्नुपर्ने थियो । किनारामा एउटा डुङ्गा थियो, जसमा केवट निषादराज बसिरहेको थियो । श्रीराम, लक्ष्मणजी र सीता मातासहित केवटनजिक पुगेर बडो विनम्रताका साथ प्रार्थना गर्दछन्- "हे केवट! हामीलाई यस पावन गङ्गाजीको पारी पुर्‍याइदिनुहोस्।" केवटले उहाँलाई तलदेखि माथिसम्म हेर्दै भन्छ- "तपाईँ को हुनुहुन्छ? कतै तपाईँ श्रीराम त हुनुहुन्न? मैले सुनेको थिएँ कि अयोध्याबाट श्रीराम, आफ्ना भाइ लक्ष्मण र जानकी माताको साथमा मुनिको भेश धारण गरी वनबासमा निस्कनु भएको छ रे। तपाईँको मुखमण्डलको यस्तो अनुपम तेज देखेर मेरो अन्तर्मनले त यही भन्छ कि तपाईँहरू त्यही राम, लक्ष्मण र सीता हुनुहुन्छ।" श्रीभगवान्‌ले मन्द मुस्कानका साथ भन्नुभयो, "हो केवट! हामी उही राम, लक्ष्मण र सीता हौँ। के तिमी हामीलाई आफ्नो डुङ्गाबाट पारी पुर्‍याइदिन सक्छौ?"
तब केवटले एकदम चातुर्यता र अटूट प्रेमका साथ भने, "प्रभु! म हजुरहरूलाई पारी त पुर्‍याइदिउँला, तर मेरो एउटा शर्त छ।" प्रभुले अचम्म मान्दै भन्नुभयो, "शर्त? तिमीलाई के चाहियो र?"
केवटले भने- "प्रभु! मलाई हजुरसँग धन या कुनै वस्तु पनि चाहिन्न तर मैले एउटा पुरानो घटना सुनेको छु । हजुर जब महर्षि गौतमको आश्रममा जानुभयो तब हजुरको पाउको धूलोको स्पर्श पाउनासाथ एउटा ढुङ्गा अहिल्याको रूपमा परिवर्तित भइन् रे । मलाई त यही कुराको डरले सताएको छ कि यदि हजुर मेरो यस काठको डुङ्गामा टेक्नुभयो र हजुरको पाउको धूलोको स्पर्शले यो डुङ्गा पनि कतै नारीमा परिवर्तन त हुने होइन? त्यसो भयो भने त म गरिबले के गर्ने? अहिले मलाई एउटा श्रीमती पाल्न त कठिनाई भइरहेको छ । मसँग न त पुग्दो आय छ र न नै त्यति शक्ति कि म दुईवटी श्रीमतीको भार उठाउन सकूँ। यदि हजुरको पाउको धूलोले यो डुङ्गा नारी बनिन् भने मेरो यो आजीविकाको एकमात्र साधन पनि खोसिनेछ र म सङ्कटमा पर्नेछु।"
केवट आफ्नो मुख्य कुरा अगाडि सार्दै भन्छ- "यसकारण मेरो यो शर्त छ कि म पहिले हजुरको पावन चरणलाई पहिले पखाल्छु । म त्यसलाई माडीमाडी एकदम राम्रोसँग धुन्छु ता कि हजुरको खुट्टाको त्यो सबै धूलो निस्कियोस् । त्यसपश्चात् मात्र म हजुरलाई आफ्नो डुङ्गामा विराजमान गराउनेछु । यदि हजुरलाई मेरो यो शर्त मञ्जुर छ भने मात्र हजुर मेरो डुङ्गामा बस्न सक्नुहुन्छ ।"
गङ्गाजीको पारी पुग्नु त निश्चित नै थियो, श्रीरामले भन्नुभयो- "जस्तो तिम्रो इच्छा छ तिमी त्यस्तै गर । हुन्छ मेरो खुट्टा धोऊ।" जब भगवान्‌ले केवटको शर्त स्वीकार गर्नुभयो तब केवटको खुशीको कुनै सीमाना रहेन । ऊ आत्मविभोर हुँदै, पागल जस्तै दौडेर आफ्नो घर पुगे । त्यहाँ गएर आफ्नी श्रीमती र बच्चाहरूसँग एकदम खुशीहुँदै भन्न लागे- "अरे! तिमीहरू पनि सबै छिटो हिँड, हेर हाम्रो भाग्य चम्केको छ । आज साक्षात् भगवान् श्रीराम गङ्गा किनारामा आउनुभएको छ । हिँड्दै-हिँड्दै स्वयं भाग्य हाम्रो ढोकासम्म आएको छ । मैले उहाँहरूलाई गङ्गा पारी लिएर जानु छ र भगवान् श्रीरामले कृपापूर्वक मलाई आफ्नो पाउ पखाल्ने अनुमति पनि दिनुभएको छ ! हिँड ढिलो नगर, घरमा जति पनि खाली भाँडाहरू छन् ती सबै लिएर मसँग कुदिहाल ।"
केवट त्यसबेला एकदम खुशीका कारण होसमा थिएन । ऊ सबैलाई लिएर गङ्गा किनारतर्फ दौडे। त्यहाँ भगवान् बडो शान्तसँग आफ्नो भक्तको प्रतीक्षा गरिरहेका थिए । केवट सपरिवार त्यहाँ पुगे। उसकी श्रीमतीले गङ्गाजीको पवित्र पानी गाग्रीमा भरेर ल्याई । केवटले प्रभुको श्रीचरणमुनि एउटा भाँडा राखे र अत्यन्त आनन्दभावले उहाँको पाउहरूलाई बिस्तारै माडेर धुन लागे । जसै त्यो भाँडो पानीले भरियो, त्यसलाई हटाएर तुरन्तै दोस्रो भाँडो खुट्टामुनि राखिदियो । फेरि तेस्रो, फेरि चौथो, उसको घरको भएभरको भाँडा भगवान्‌को चरणामृतले भरियो । केवट बीच-बीचमा त्यो पवित्र जल आफ्नो शिरमा पनि छर्कन्थ्यो र आनन्दको सागरमा डुब्थ्यो ।
त्यस दृश्यको कल्पना गर्नुहोस् त! केवट बडो आनन्दकासाथ श्रीभगवान्‌को श्रीचरण पखालिरहेका र त्यो पवित्र जल भाँडाहरूमा जम्मा भइरहेको । ऊ त्यस चरणामृतलाई आफ्नो शिरमाथि छर्किरहेको छ, मानौँ साक्षात् परम् तीर्थ उसको सामुन्ने अवतरित भएको होस् । ऊ आनन्दित भएर पुकारिरहेको छ - "आज त गङ्गा मैया पनि धन्य हुनुभयो ! साक्षात् परमेश्वरको पाउको स्पर्श पाएर यो गङ्गाजल पनि परम पवित्र भएको छ । यो भन्दा बढी सौभाग्य के नै हुन सक्छ र? अरे! यो पवित्र जललाई लिएर जाऊ र घरको कुना-कुनामा छर्किदेऊ।"
केवट बच्चा झैँ खुशीले नाचिरहेको छ, त्यस पवित्र जललाई चारैतिर छर्किरहेको छ र आनन्दित भएर बढीभन्दा बढी भाँडाहरू भरिरहेको छ । त्यहाँ सँगै उभिएका लक्ष्मणजी त्यस दृश्यलाई देखेर गहिरो आश्चर्यमा पर्नुभएको छ। उनी विचार गरिरहेका छन्- "यो कस्तो आश्चर्य हो? मेरो दाजु, जो कसैलाई यति सहजरूमा आफ्नो चरण स्पर्श गर्न दिनुहुन्न वहाँ आज एक साधारण केवटलाई यतिका बेरसम्म आफ्नो चरण पखाल्न दिइरहनु भएको छ ! सीता माता पनि अचम्म मानिरहनु भएको छ, वहाँ उनै श्रीराम हुन् जसले मिथिलापुरीमा महाराज जनकलाई पनि वर-पूजनको बेलामा आफ्नो चरण धुने अवसर दिनुभएको थिएन । यो दृश्य अद्भुत छ, अकल्पनीय छ !
जब केवटको इच्छा पूरा भयो तब उसले बडो प्रेमले आफ्नो हात दिएर तीनैजनालाई डुङ्गामा बसाए र डुङ्गा चलाउन लागे । गङ्गाजीको लहरहरूमा डुङ्गा ढलमल ढलमल गर्दै अगाडि बढे । साक्षात् गङ्गाजीले देख्नुभयो कि उहाँको आराध्य प्रभु डुङ्गामा विराजमान हुनुहुन्छ । गङ्गाजीको मनमा तीव्र उत्कण्ठा जाग्यो कि "प्रभु त डुङ्गाभित्र हुनुहुन्छ, म कसरी उनको पावन चरणहरूको स्पर्श गरूँ?" अतः गङ्गाजीले आफ्नो लहरलाई बेला-बेलामा उछालेर डुङ्गाभित्र जाने प्रयास गर्न लागिन् ताकि उनी श्रीभगवान्‌को श्रीचरण धुन सकून् । यसले गर्दा डुङ्गा कहिले अगाडि कहिले पछाडि जान्थ्यो । तर यस कौतुहलताको पछाडि त्यस सोझो केवटको एउटा चलाखी पनि हुनसक्थ्यो । त्यो भक्त हृदयले सोच्दो हो- "यदि मैले छिट्टै नै डुङ्गालाई पारी लिएर गएँ भने त भगवान् राम उत्रेर गइहाल्नुहुन्छ । मेरो यो परम सौभाग्य चाँडै नै समाप्त हुनेछ!" त्यसकारण उसले जानी-जानी डुङ्गालाई कहिले अगाडि बढाउँथ्यो र कहिले पछाडि तान्थ्यो ।
डुङ्गा डगमगाएको हुँदा भगवान् केवटलाई सोध्नुहुन्छ, "केवट भाइ! यो तिमी के गरिरहेका छौ? कहिले डुङ्गा अगाडि लैजान्छौ कहिले पछाडि तान्छौ।" तब त्यो सोझो केवट बडो प्रेमले उत्तर दिन्थ्यो, "प्रभु! यसमा मेरो कुनै दोष छैन, म के गरूँ? यी त साक्षात् गङ्गा मैया हुनुहुन्छ जो यस्तो कौतुक गरिरहनु भएको छ।" महाराष्ट्रमा एउटा गीत लेखिएको छ, एकदमै प्यारो । त्यो केवट गङ्गा मैयालाई भन्दैछ- "हे गङ्गा मैया! रोक्नुहोस्, एकपल्ट रोकिदिनुहोस् यो डुङ्गालाई पहिले म पारी पुर्‍याइदिन्छु।"
नकोस नौके परत फिरूंग नकोस गङ्गे ऊर भरूं
श्रीरामांचे नाम गात या श्रीरामाला पार करूं
जय गङ्गे जय भागिरथी
जय जय राम दाशरथी
जय गङ्गे
केवट गङ्गा मैयालाई अनुनय-विनय गर्न लागे, "हे गङ्गा मैया! एकपटक शान्त त भइदेऊ, अलिकति धैर्य राख, एकैछिन त पर्ख । जब म पारी पुग्छु, तब म प्रभुलाई सिधै किनारामा लाँदिन बरू तपाईँको पावन जल (पात्र) मा नै उतारिदिनेछु ताकि तपाईँलाई पनि उहाँको श्रीचरणको स्पर्श प्राप्त होस् । तबसम्मको लागि धैर्य गरिदिनूहोला।"
यसरी केवटले डुङ्गालाई गङ्गा पारी लिएर गए । आफ्नो वचन अनुसार उसले प्रभुलाई सिधा सुख्खा भूमिमा नउतारिकन गङ्गाको पानीमा नै खुट्टा टेक्नुपर्ने गरी तल उतारिदिनुभयो । यसो गर्दा गङ्गा मैयालाई पनि भगवान्‌को चरण स्पर्श गर्ने परम् सौभाग्य प्राप्त भयो । त्यस पावन किनारामा एउटा अद्भुत दृश्य थियो । तल गङ्गा मैया मात्र बहिरहेकी थिइनन् त्यहाँ त केवटका दुवै आँखाबाट प्रेमका आँसुहरू पनि अविरल बहिरहेको थियो । केवट पूर्णतः कृतार्थ थिए । ऊ आफ्नो भाग्यमाथि मनमनै आनन्दित भइरहेको थियो कि मैले केवटको रूपमा जन्म लिन पाएँ, मेरो त आज भाग्य नै खुल्यो ।
भगवान्‌को मनमा यस्तो विचार आयो कि मलाई गङ्गा पार गरिदिनेलाई पारिश्रमिक दिनुपर्छ । वहाँ केवटलाई कुनै आभूषण दिन चाहन्थे तर वहाँलाई सम्झना भयो कि सबै आभूषण त उनले अयोध्या छोड्ने बेलामा नै फुकालेर आएका थिए । यस समय वहाँको अङ्गमा एउटा पनि अलङ्कार बाँकी थिएन । प्रभुको यस्तो दुविधा माता सीताले तुरन्त चाल पाउनुभयो र उहाँले आफ्नो एक बहुमूल्य औँठी निकालेर श्रीभगवान्‌को हातमा राखिदनुभयो । जब श्रीभगवान्‌ले त्यो बहुमूल्य औँठी केवटको हातमा राखिदिन खोज्नुभयो त केवट अचानक पछि हट्यो ।
उसले भन्यो, "प्रभु! हजुर यो के गर्दै हुनुहुन्छ? म यसलाई कदापि लिन सक्दिनँ।" भगवान्‌ले बडो प्रेमसँग सम्झाउनु भयो, "हेर केवट, यो त तिम्रो व्यवसाय हो । तिमीले परिश्रम गरेर हामीलाई गङ्गा पारी ल्याइदियौ । त्यसैले तिमीले यो पारिश्रमिक त लिनै पर्छ । केवटले हात जोडेर विन्ती गर्न लागे, "होइन भगवान्! मलाई पनि आफ्नो मर्यादा मै रहनदिनुहोला, म यो लिन सक्दिनँ।" तब श्रीरामले सोध्नुभयो, "तर किन? आखिर तिमी यो पारिश्रमिक लिन किन मानिरहेका छैनौँ? केही कारण त होला, मलाई भन।"
केवटको आँखामा एउटा विशेष चमक आयो । उसले भन्यो, "प्रभु! हजुर मबाट यो किन भन्न लगाइरहनु हुन्छ? तर यदि हजुर जान्न नै चाहनु हुन्छ भने सुन्नुहोस् । संसारको रीत नै यस्तो छ कि जब एउटै व्यवसाय गर्ने दुई व्यवसायी एक-अर्कालाई सहयोग गर्छन् भने पारिश्रमिक लिँदैनन् । उनीहरूलाई त एक-अर्काको मदत गरेर केवल खुशी मिल्दछ । हामी दुवैको व्यवसाय त एउटै नै हो।" जब केवटले भन्यो कि हामी दुवैको व्यवसाय एउटै हो, तब श्रीभगवान्‌ले सोध्नुभयो, "केवट भाइ! हाम्रो काम एउटै कसरी भयो? म त अयोध्याको राजकुमार हुँ, क्षत्रिय हुँ, र तिमी एउटा माझी हौ, जो डुङ्गा चलाएर आफ्नो जीविकोपार्जन गर्छौ । मेरो र तिम्रो काम कसरी एउटै हुनसक्छ?"
केवटको आँखामा प्रेमका आँसुका धारा बगे । उसले हात जोडेर भने, "प्रभु! हामी दुवैले त डुङ्गा चलाउने हौँ। म यो सानो काठको डुङ्गाले मानिसहरूलाई यो गङ्गा तारिदिन्छु भने हजुर सम्पूर्ण जगतका जीवहरूलाई भवसागरबाट तारिदिनुहुन्छ । एकदिन त्यो समय पनि आउनेछ जब म हजुरको द्वारमा आउनेछु, त्यस दिन मलाई यस भवसागरबाट तारिदिनुहोला । म त एक साधारण र अज्ञानी मानिस हुँ; त्यतिबेला मेरो साथमा तपाईँलाई दिने केही हुनेछैन । आज मैले हजुरलाई गङ्गा पार गराइदिएँ त्यस दिन हजुर मलाई भवसागर पार गराइदिनुहोला । जसरी आज मैले हजुरसँग केही पारिश्रमिक लिइनँ त्यसरी नै त्यो दिन हजुरले पनि मसँग केही अपेक्षा नराख्नुहोला प्रभु।" भगवान्‌को आँखाबाट पनि आँसु बग्यो । भगवान्‌ले त्यो औँठी सीता मातालाई फिर्ता दिनुभयो ।
यदि यस संसाररूपी भवसागरबाट पार हुनु छ भने भगवान्‌माथि अटूट भरोसा राख्नुपर्दछ । हामीलाई भगवान्‌को त्यो डुङ्गामा बस्नुपर्दछ र त्यही ड्ङ्गाले हामीलाई भवसागरबाट पार गराइदिनुहुन्छ । जो भक्त यसप्रकारले सगुण भक्ति गर्दछ, उसले आफ्नो सम्पूर्ण भरोसा केवल भगवान्‌माथि नै राख्दछ । ऊ अरू केही जान्दैन; केवल श्रीभगवान्‌लाई मात्र जान्दछ र बाँकी सब भगवान्‌नै जानून् । यस्तो अटूट भरोसा भक्तको अन्तर्मनमा जागृत हुन्छ भने ऊ भगवान्‌को अनन्य उपासक बन्दछ ।
12.6
ये तु सर्वाणि कर्माणि, मयि सन्न्यस्य मत्पराः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (12, 6, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=DBuI7vNg06E', '2026-03-21', 'तर, ममा परायण रहने भक्तजनहरू सम्पूर्ण कर्महरूलाई ममा अर्पण गरी, म सगुणरूपी परमेश्वरलाई नै अनन्य भक्तियोगले निरन्तर ध्यान गर्दै मेरो उपासना गर्ने गर्दछन् ।
जो भक्त आफ्नो सम्पूर्ण कर्महरूलाई श्रीभगवान्‌समक्ष अर्पित गर्दछ र अनन्य भावले केवल श्रीभगवान्‌को नै ध्यान तथा उपासना गर्दछ, उसको बारेमा भगवान् स्वयं चिन्ता गर्नुहुन्छ । यस्तो अनन्य उपासकहरूको लागि भगवान् नै सर्वस्व बन्नुहुन्छ ।
12.7
तेषामहं(म्) समुद्धर्ता, मृत्युसंसारसागरात् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (12, 7, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=DBuI7vNg06E', '2026-03-21', 'हे पार्थ! त्यस्ता ममा चित्त लगाउने ती प्रेमी भक्तहरूलाई म मृत्युमय संसाररूपी सागरबाट शीघ्र नै उद्धार गर्ने गर्दछु ।
मय्यावेशितचेतसाम्
- जो भक्त आफ्ना सम्पूर्ण चित्त ममा नै एकाग्र गर्दछ,
तेषामहं(म्) समुद्धर्ता
- ती मनुष्यहरूको म समुचित उद्धार गरिदिन्छु ।
मृत्युसंसारसागरात्
- यस मृत्युरूपी संसार सागरबाट,
भवामि नचिरात्पार्थ
- म उनीहरूलाई यथाशीघ्र तारिदिन्छु ।
भगवान् स्वयं भन्नुहुन्छ कि जसको मन निरन्तर ममा नै सञ्चित रहन्छ, जो केवल मेरो नै अभीष्ट चिन्तन गर्दछ, उसको उद्धारको उत्तरदायित्व म स्वयं लिनेछु । जो भक्त आफ्ना पूर्ण चित्त श्रीभगवान्‌मा नै लगाउँछन्, उनको उद्धार भगवान् अविलम्ब गर्नुहुन्छ ।
चौध वर्षको वनवास पूरा गरेर श्रीराम, सीता माता र लक्ष्मणजी जब अयोध्या फर्कनुभयो तब भरतजीले भन्नुभयो कि अब विलम्ब नगरी भोलि नै राज्याभिषेक गर्नुपर्छ । भोलिपल्ट सम्पूर्ण अयोध्या नगरी दिव्यरूपले सजाइयो । चारैतिर उत्सवको वातावरण बन्यो । भरतजीले आमन्त्रित अतिथिहरूको सूची श्रीभगवान्‌को सम्मुख राखी निवेदन गर्नुभयो कि सबै राजा-महाराजाहरूलाई निमन्त्रणा पठाइसकेको छु, यदि कोही छुटेको छ भने हेर्नुहोला । श्रीभगवान्‌ले भन्नुभयो कि म त यतिका वर्षदेखि यहाँ थिइनँ तिमीले जुन व्यवस्था गरेको छौ त्यो उचित नै होला । आधा रातमा श्रीभगवान्‌को आँखा खुल्दछ । वहाँले तत्काल भरतजीलाई बोलाएर भन्नुहुन्छ कि एक अति प्रियजनलाई बोलाउन छुटेछ ।
भरतजीले सोध्नुभयो कि कसलाई बोलाउन छुट्यो? तब श्रीभगवान्‌ले भन्नुभयो कि त्यस केवटलाई बोलाउन छुटेछ, जसले हामीलाई गङ्गा पार गराइदिएको थियो । ऊ दिन-रात मेरो नै चिन्तन गर्दछ । राज्याभिषेकको त्यस महोत्सवमा यदि कोही श्रीभगवान्‌को आफ्नो व्यक्तिगत अतिथि थियो भने त्यो केवल केवट नै थियो । अन्य सबै त केवल औपचारिकता निभाउनका लागि मात्र आएका थिए तर हृदयको सच्चा निमन्त्रणा त त्यस निषादराज केवटका लागि थियो ।
जसरी श्रीभगवान्‌ले केवटको स्मरण गर्नुभयो, त्यसैगरी जो भक्त आफ्ना सम्पूर्ण चित्त श्रीभगवान्‌मा नै लगाउँछ, उसको उद्धारको सङ्कल्प स्वयं श्रीभगवान्‌ले लिनुहुन्छ । यस मृत्युरूपी संसार सागरबाट तारिदिने उद्धारकर्ता भगवान् स्वयं बन्नुहुन्छ, यो कुरा यस प्रसङ्गबाट राम्ररी बुझ्न सकिन्छ ।
12.8
मय्येव मन आधत्स्व, मयि बुद्धिं(न्) निवेशय ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (12, 8, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=DBuI7vNg06E', '2026-03-21', 'तिमीले ममा नै मन लगाऊ र ममा नै बुद्धि पनि लगाऊ । त्यसपछि तिमी अवश्य नै ममा निवास गर्नेछौ भन्ने कुरामा कुनै शङ्का गर्नुपर्दैन ।
यस श्लोकमा भगवान् अति महत्त्वपूर्ण र अनिवार्य शर्तहरू राख्नुहुन्छ, जसलाई बुझ्न हाम्रो लागि अत्यन्त आवश्यक छ । यहाँ
आधत्स्व
को अर्थ हो- स्थापित गर्नु ।
मय्येव मन आधत्स्व
- आफ्नो मनलाई ममा नै स्थापित गरिदिनु । दोस्रो शब्द छ
निवेशय
, जसको अर्थ हो- प्रविष्ट गर्नु ।
जसरी हामी बैंकमा धन निक्षेप गर्दछौँ, त्यसलाई सुरक्षितसँग राख्दछौँ, त्यसरी नै यहाँ आफ्नो बुद्धि श्रीभगवान्‌मा निक्षेप गर्नुपर्दछ । जो भक्त आफ्नो मनलाई श्रीभगवान्‌मा स्थापित गर्दछ र आफ्नो बुद्धि उहाँमा प्रविष्ट गर्दछ, ऊ अन्ततः श्रीभगवान्‌मा नै निवास गर्दछ, यसमा कणमात्र पनि शङ्का छैन ।
समस्या यहाँ उत्पन्न हुन्छ कि हामी मनबाट त समर्पित हुन्छौँ तर बुद्धि निक्षेप गर्न हामीलाई साह्रै गाह्रो हुन्छ । बुद्धि तर्क गर्छ, प्रश्न गर्छ- "के यस पत्थरको मूर्तिमा पनि श्रीभगवान्‌ हुनुहुन्छ र? के वहाँले वास्तवमा नै मेरो उद्धार गर्नुहुन्छ त?" जहाँ मनमा श्रद्धा र भरोसा हुन्छ त्यहीँ नै बुद्धिले आफ्नो तर्कहरूको जालो बुन्न थाल्छ ।
यस सन्दर्भमा राजस्थानका सरदार शहरको एउटा मार्मिक संस्मरण स्मरणीय हुन्छ ।
त्यहाँ कसैको भेट परम पूज्य स्वामी रामसुखदासजी महाराजसँग भयो, जसले आफ्नो गुरु स्वामी शरणानन्दजी महाराजको एउटा अद्भुत घटना सुनाए । स्वामी शरणानन्दजी प्रज्ञाचक्षु थिए; उनको भौतिक आँखा त थिएन तर अन्तर्दृष्टि भने पूर्णतः जाग्रत अवस्थामा थियो । वहाँ प्रतिदिन साँझ भ्रमणमा निस्कनुहुन्थ्यो र आफ्नो लौरोको सहाराले हिँड्नुहुन्थ्यो । साथमा केही भक्तहरू पनि हुन्थे ।
एकदिन एउटा वृक्षको फेदमा विश्राम गर्दा उहाँले एउटा सानो ढुङ्गा उठाउनुभयो र त्यसलाई बडो प्रेमले सहलाउनुभयो । वहाँले त्यस ढुङ्गासँग कुरा गरिरहनुभयो । जानेबेलामा उहाँले त्यस ढुङ्गालाई भन्नुभयो- "म भोलि फेरि आऊँछु, तिमी मेरो प्रतीक्षा गर ल।" त्यहाँ उपस्थित एउटा भक्तले यो सबै कौतूहलपूर्वक हेरिरहेको थियो । उसले त्यो ढुङ्गालाई ध्यानपूर्वक हेर्‍यो, जसमा एउटा सेतो रेखा अङ्कित थियो । भोलिपल्ट जब महाराज पुनः त्यही ठाउँमा पुगे र त्यही ढुङ्गा उठाएर सहलाउन थाले । श्रीभगवान्‌मा मनदेखि समर्पित भएता पनि त्यो भक्तको बुद्धिमा शङ्का उत्पन्न भयो । उसले सोच्यो कि सम्भवतः महाराज आफ्नो पाइला गनेर त्यहाँ पुग्नुहुन्छ ।
आफ्नो बुद्धिको तर्कको परीक्षा लिन त्यस भक्तले त्यो ढुङ्गालाई त्यहाँबाट उठाएर केही पाइला पर दाहिनेतिर एउटा अर्कै वृक्षको फेदमा राखिदियो । ऊ हेर्न चाहन्थ्यो कि भोलि महाराजले अब त्यो ढुङ्गा कसरी भेट्टाउनुहुन्छ । भोलिपल्ट त चमत्कार नै भयो ! शरणानन्दजी महाराज देब्रेतिर मोडिनुको सट्टा दाहिनेतिर मोडिएर त्यही ठाउँमा गएर उभिए जहाँ त्यो ढुङ्गा हिजो त्यो भक्तले राखिदिएको थियो । वहाँले त्यस ढुङ्गालाई उठाउनुभयो र भन्नुभयो- "अरे! हिजो त तिमी त्यहाँ थियौ, आज यहाँ कसरी आयौ?"
त्यो भक्त लज्जित भएर महाराजको श्रीचरणमा नतमस्तक परेर क्षमा माँग्दै सोध्न लागे कि हजुरलाई यो कसरी थाहा भयो? शरणानन्दजी महाराजले बडो सुन्दर कुरा भन्नुभयो- "यस चराचर सृष्टिको प्रत्येक कणमा उनै भगवत् तत्त्व व्याप्त छ । मैले प्रेमले सहलाएर त्यस ढुङ्गाभित्र रहेको त्यो तत्वलाई जाग्रत गरिदिएको थिएँ । त्यसको स्पन्दन-लहरहरुले नै मलाई त्यसतर्फ तानेर लग्यो।"
यदि दुईपटक प्रेमले सहलाउँदैमा एउटा तुच्छ ढुङ्गाको भगवत् तत्व जाग्रत हुन सक्छ भने पण्डरपुरका विठोबाका चरणमा कति दिव्य चेतना जाग्रत होला? पण्डरपुरमा विराजमान भगवान् विठ्ठलका श्रीचरणमा हजारौँ भक्त ''विठ्ठल-विठ्ठल'' को कीर्तन गर्दै पुग्दछन् । विचार गर्नहोस् त, त्यस निरन्तर चरण-स्पर्शबाट र अनगिन्ति भक्तहरूको निधारको स्पर्शले, त्यस भक्तिको अनन्य भावले, त्यस पत्थरको मूर्तिमा कुन स्तरको दिव्य चेतनाको जागरण भएको होला, यसको हामी कल्पना पनि गर्न सक्दैनौँ।
समस्या तब आउँछ जब हाम्रो बुद्धिले प्रश्न गर्न थाल्दछ, त्यसैले भगवान् भन्नुहुन्छ-
मयि बुद्धिं(न्) निवेशय
- बुद्धिको कुतर्कलाई विश्राम दिएर जो समर्पित भावले मेरो उपासना गर्दछ,
अत ऊर्ध्वं(न्) न संशयः
- उसको प्रगति र उसको उद्धार निश्चित छ, यसमा कणमात्र पनि शङ्का छैन।
यसको लागि केवल श्रद्धाको जागरणको आवश्यकता पर्दछ । हामी नित्य युक्त हुनुपर्दछ अर्थात् प्रतिपल, प्रतिदिन र प्रतिक्षण श्रीभगवान्‌सँग जोडिइरहनु पर्दछ । हाम्रो मुख्य बाधा यही हो कि हामी केवल पाँच मिनटको लागि श्रीभगवान्‌सँग हुन्छौँ र बाँकी सम्पूर्ण दिन संसारको हुन्छौँ । प्रातःकालमा हामी भगवान्‌को नाम जप गर्दछौँ र साँझ पर्न-पर्न लाग्दा पाप कर्ममा प्रवृत्त हुन्छौँ; यसले भक्तिको मार्ग प्रशस्त गर्दैन । यदि प्रातःकालमा जप गर्छौँ भने त्यो जप दिनभरी हाम्रो श्वास सँगसँगै चलिरहनुपर्दछ । हामीसँग भेटिने प्रत्येक व्यक्तिमा भगवद्-रूप नै प्रतीत लाग्न थाले भने बुझ्नुहोस् कि तपाईँ सही मार्गमा प्रवेश गर्दै हुनुहुन्छ । जब अन्तःकरणमा निरन्तर मानस-पूजा चलिरहन्छ तब वास्तविक कल्याण सम्भव हुन्छ ।
पाँच मिनटको पूजा त सहज होला तर चौबीसै घण्टा यो कसरी सम्भव होला? यो मार्ग हामीलाई कठिन प्रतीत हुन्छ । जब अर्जुनको आँखामा पनि यही भाव झल्क्यो कि दिनभर श्रीभगवान्‌मा मनलाई स्थापित गर्न र बुद्धिलाई निक्षेप गर्न कष्टकर छ, तब श्रीभगवान्‌ले करुणापूर्वक भन्नुभयो- "यदि यो कठिन लाग्छ भने केही छैन, अब एउटा अरू सरल मार्ग सुन।"
12.9
अथ चित्तं(म्) समाधातुं(न्), न शक्नोषि मयि स्थिरम् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (12, 9, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=DBuI7vNg06E', '2026-03-21', 'यदि तिमी मनलाई ममा स्थिर गरेर राख्न समर्थ छैनौ भने, हे धनञ्जय! अभ्यासरूपी योगद्वारा तिमी मलाई पाउने प्रयत्न गर ।
भगवान् भन्नुहुन्छ- "हे धनञ्जय! यदि तिमी आफ्नो चित्तलाई ममा स्थिर गर्न समर्थ छैनौ भने योग अभ्यासद्वारा मलाई प्राप्त गर्ने इच्छा राख।"
यहाँ भगवान्‌ले अर्जुनलाई धनञ्जय भनेर सम्बोधन गर्नुभएको छ, जुन अत्यन्त अर्थपूर्ण छ । जब खाण्डव वनमा आगलागी भयो र इन्द्रप्रस्थ नगर निर्माण गर्न ठूलै धनराशिको आवश्यकता पर्‍यो तब अर्जुन एक्लैले आफ्नो पराक्रमले राजाहरूलाई जितेर त्यो धन अर्जित गरे, त्यसैले अर्जुनलाई धनञ्जय भनिएको हो । जसरी धन आर्जित गर्नका लागि पुरुषार्थ र कठोर परिश्रमको आवश्यकता पर्दछ त्यसरी नै श्रीभगवान्‌लाई जित्नको लागि पनि मन र बुद्धिद्वारा पुरुषार्थ गर्नुपर्दछ । यसका लागि निरन्तर अभ्यास अर्थात् चेष्टा, प्रयत्न र साधना अनिवार्य छ ।
हाम्रो भक्तिको अवस्था कस्तो छ?
हामी दिनभरीमा पाँच-दस मिनट पूजाका लागि निकाल्छौँ, त्यसमा पनि हाम्रो ध्यान मोबाइलमा गइरहेको हुन्छ । भगवान्‌लाई पवित्र भाँडामा स्नान गराउने बेलामा पानीको धारा बगिरहेको हुन्छ, भगवान् जलमग्न भइरहेको हुन्छ र त्यति नै बेला मोबाइलको घण्टी बज्छ । हामी भगवान्‌लाई स्नान गराउन रोकेर तत्काल त्यो मोबाइल उठाउँछौँ र कुराकानीमा व्यस्त हुन्छौँ जबकि वहाँ साक्षात् भगवान्‌को सेवा भइरहेको हुन्छ । यस्तो खण्डित भक्तिबाट कार्य सिद्धि निश्चय नै हुँदैन । छोटै समय भए पनि जुन तपाईँ भगवान्‌का लागि निर्धारित गर्नुहुन्छ, त्यसमा पूर्ण एकाग्रता र एकरूपता हुनुपर्दछ ।
मन्दिरहरूमा घण्टीको नाद यसकारण गरिन्छ ताकि त्यसले तपाईँलाई सावधान गरोस् । त्यो भगवान्‌लाई जगाउनको लागि होइन, वहाँ त सदैव जाग्रत स्थितिमा हुनुहुन्छ र तपाईँको प्रतीक्षा गरिरहनुहुन्छ कि तपाईँ एक कदम अगाडि बढाउनुहोस् वहाँ दस कदम दौडेर आऊन् तर हाम्रो मन संसारकै विचारहरूमा यसरी अल्झेर बस्छ कि पाँच मिनट पनि स्थिर रहन सक्दैनौँ । अभ्यासको अर्थ यही हो कि श्वाससँगै मन्त्र पनि चलोस्-
श्रीकृष्णः शरणं मम
। श्वास भित्र लिँदा र बाहिर छोड्दा केवल त्यही एक नाम होस् । जप मालाको एक-एक मनका तपाईँको श्वास र मन्त्रका साथ एकाकार होस् । यस्तो चेष्टा र यस्तो प्रयास आजैबाट आरम्भ गर्नुपर्छ ।
विचार गर्नुहोस् त, यदि प्रधानमन्त्रीले तपाईँलाई भेट गर्नका लागि आमन्त्रित गरे भने तपाईँ एक घण्टा पहिले नै त्यहाँ पुग्नुहुन्छ र आफ्नो मोबाइलको स्वीच अफ गर्नुहुन्छ ताकि त्यस भेटमा कुनै बाधा अड्चन नआओस् । त्यसो हो भने जगतका स्वामीसँग तपाईँको पाँच मिनटको भेटमा, के वहाँको लागि नियमहरूको पालना गर्नु कुनै आवश्यक नै छैन र? त्यस समय संसारबाट पूर्णतः विच्छेद भएर केवल भगवान्‌सँग जोडिनु नै वास्तविक अभ्यास हो । अभ्यासबाट नै भगावन् प्राप्तिको इच्छा सम्भव हुन्छ, अन्यथा हुन्न ।
जब भगवान्‌ले अर्जुनको आँखामा देखे कि उनलाई यो अभ्यास पनि कठिन प्रतीत भइरहेको छ, तब भगवान्‌ले एउटा अर्को सरल मार्ग प्रशस्त गर्नुभयो ।
12.10
अभ्यासेऽप्यसमर्थोऽसि, मत्कर्मपरमो भव ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (12, 10, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=DBuI7vNg06E', '2026-03-21', 'यदि तिमी अभ्यासरूपी योग गर्न पनि असमर्थ छौ भने केवल मेरा लागि भगवद् कर्महरू (यज्ञ, दान, तप आदि) गर्न तत्पर होऊ । यसरी, मेरा निमित्त भगवद् कर्महरू गरिरहँदा पनि तिमीले मेरो प्राप्‍तिरूप सिद्धिलाई नै प्राप्‍त गर्नेछौ ।
भगवान्‌ले अर्जुनको मनःस्थितिलाई बुझेर त्यो भन्दा पनि सरल मार्ग बताउँदै भन्नुहुन्छ- "हे अर्जुन! यदि तिमी अभ्यास गर्नमा पनि आफूलाई असमर्थ पाइरहेका छौ भने जे जति कर्म तिमी गर्छौ त्यसलाई मेरो नै कर्म सम्झेर गर, तिमी मेरो लागि कर्म गर्ने बन । आफ्नो कर्महरूलाई ममा अर्पित गर तिमीलाई परमसिद्धि प्राप्त हुनेछ ।" यहाँ भगवान् दृष्टिकोण बदल्ने कुरा गर्दै हुनुहुन्छ । आजसम्म जुन कर्म तपाई आफ्नो लागि या परिवारको लागि गरिरहनु भएको थियो, अब त्यसलाई भगवान्‌का लागि गर्न आरम्भ गरिदेऊ ।
यदि आमाहरू भान्सामा भोजन बनाउँदै हुनुहुन्छ भने यो भाव मनमा जगाउनुहोस् कि तपाईँ केवल परिवारको लागि पकाइरहनु भएको छैन अपितु भगवान्‌को भोगको लागि प्रसाद बनाउँदै हुनुहुन्छ । घरमा कुचो लगाउँदै हुनुहुन्छ भने यस्तो भाव राख्नुहोस् कि यो साधारण घर होइन, भगवान्‌को मन्दिर हो र म भगवान्‌को आगमनको लागि यो घर सफा गर्दैछु । जब तपाईँ स्नान गर्दै हुनुहुन्छ भने तब स्मरण गर्नुहोस् कि यो शरीर भगवान्‌को मन्दिर हो किनकि वहाँ परमात्माको रूपमा मेरो हृदयमा विराजमान हुनुहुन्छ । भोजन ग्रहण गर्ने बेलामा पनि यो भाव रहोस् कि म अन्तःकरणमा बसेर श्रीभगवान्‌लाई आहुति दिइरहेको छु, जसले मेरो भोजन पनि यज्ञ-कर्म बनोस् ।
यदि तपाईँ व्यवसायी हुनुहुन्छ भने ग्राहकहरूमा पनि उनै श्रीभगवान्‌को दर्शन गर्नुहोस् । यदि व्यापार भगवान्‌का लागि हुने हो भने न तपाईँले ग्राहकसित कहिले अनुचित मूल्य लिनुहुन्छ र न कसैलाई ठग्नुहुन्छ ।
तपाईँको प्रत्येक गतिविधि भक्ति बन्न सक्छ । यदि तपाईँ हिँडिरहनु भएको छ भने त्यो भगवान्‌को प्रदक्षिणा हो भने यदि तपाईँ निद्रामा हुनुहुन्छ भने त्यो समाधिको स्थिति हो । भगवान् भन्नुहुन्छ कि हे अर्जुन! दिनभरीमा जे पनि काम गरिरहेका हुन्छौ त्यो ममा अर्पण गर्दै जाऊ । मेरो लागि गरिरहेको हो भन्ने यस्तो भाल सोच्दै जाऊ-
जीवों का कलरव जो दिनभर सुनने में मेरे आवे
तेरा ही गुणगान जान मन प्रमुदित हो अति सुख पावे।
तू ही है सर्वत्र व्याप्त हरि, तुझमें यह सारा संसार,
इसी भावना से अन्तर भर, मिलूं सभी से तुझे निहार।।
प्रतिपल निज इंद्रिय समूह से जो कुछ भी आचार करो,
केवल तुझे रिझाने को बस तेरा ही व्यवहार करूं ।
कर प्रणाम तेरे चरणों में लगता हूँ अब तेरे काज ।
पालन करने को आज्ञातव मैं नियुक्त होता हूँ आज ।
प्रातःकाल भगवान्‌को सामू बसेर यो सङ्कल्प लिनू-
कर प्रणाम तेरे चरणों में लगता हूँ अब तेरे काज
करने को आज्ञा तव मैं नियुक्त होता हूँ आज।
भगवान्‌को सामू बसेर यस प्रकारको भाव राख्नू कि अब म तपाईँको कामको लागि नियुक्त भएको छु, मलाई शक्ति प्रदान गर्नुहोस् । जब तपाईँ त्यहाँबाट उठेर हिँड्नुहुन्छ तब भगवान्‌को प्रदक्षिणा शुरू हुन्छ । तपाईँको कानमा गुन्जिने कोलाहल पनि श्रीभगवान्‌को भजन प्रतीत हुनेछ । जगद्गुरु आदि शङ्कराचार्यजीले ''
शिवमानसपूजा
'' मा यस्तै दिव्य भावलाई सजाएका छन्, उहाँद्वारा रचित श्रीशिवमानसपूजाको जुन मन्त्र छ, अति नै सुन्दर छ-
आत्मा त्वं गिरिजा मतिः सहचराः प्राणाः शरीरं गृहं
पूजा ते विषयोपभोगरचना निद्रा समाधिस्थितिः ।
सञ्चारः पदयोः प्रदक्षिणविधिः स्तोत्राणि सर्वा गिरो
यद्यत्कर्म करोमि तत्तदखिलं शम्भो तवाराधनम् ॥
हे शम्भो! मेरो आत्मा तपाईँ हुनुहुन्छ, मेरो बुद्धि पार्वतीजी हुनुहुन्छ, मेरो प्राण तपाईँको गण हो र यो शरीर तपाईँको मन्दिर हो । यो सम्पूर्ण विषयहरूको उपभोग तपाईँको पूजा हो, मेरो निद्रा समाधि हो, मेरो हिँडाइ तपाईँको प्रदक्षिणा हो र मेरो वाणी तपाईँको स्तोत्र हो । म जे-जे कर्म गर्छु, ती सबै तपाईँको आराधना नै हो ।
बस् यति भाव परिवर्तन मात्रले पनि हामीलाई योगवित्तम बनाइदिनेछ तर जब श्रीभगवान्‌ले अर्जुनको अनुहारमा हेर्नुभयो, त्यहाँ अझै पनि केही शङ्का बाँकी थियो । यदि यो मार्ग पनि कठिन प्रतीत हुन्छ भने श्रीभगवान्‌ यो भन्दा पनि सरल उपाय बताउनुहुन्छ तर त्यसको चर्चा आगामि सप्ताहको विवेचनमा गरिनेछ ।
प्रश्नोत्तर
प्रश्नकर्ता
- कमलावती दीदी
प्रश्न-
मैले श्लोकको अडियो आफ्नो समूहमा पठाउन पाएकी छैन, के म अर्को लेभलमा जान सक्छु?
उत्तर
- अडियो/भिडियो पठाउन अनिवार्य छैन । तपाईँ अर्को लेभलमा स्वतः जानुहुन्छ तर अडियो/भिडियो कसैको सहयोगबाट आफ्नो समूहमा पठाउने प्रयास गर्नुहोला, यो राम्रो हुनेछ ।
प्रश्नकर्ता-
अमरेश दाजु
प्रश्न
- आजको विवेचन फेरि सुन्नु परे कसरी सुन्न सकिन्छ?
उत्तर
- तपाईँको समूहमा विवेचनको यूट्यूब लिङ्क पठाइदिएको हुन्छ, त्यस लिङ्कमा गएर तपाईँ यो विवेचन फेरि सुन्न सक्नुहुन्छ ।
प्रश्नकर्ता-
अशोक दाजु
प्रश्न
- कसैलाई देखेर मनमा नराम्रो विचार आए भने के त्यो पाप हुन्छ?
उत्तर-
पाप र पुण्यको निर्धारण त श्रीचित्रगुप्तजी महाराजले गर्नुहुन्छ । हाम्रो मनमा कसैप्रति नराम्रो विचार आउनु हाम्रो स्वास्थ्यको लागि हानिकारक हुन्छ । यसले हामीलाई तनाव गराउँछ, यसले उच्च रक्तचाप र मधुमेह जस्ता रोगहरू निम्त्याउँछ । काम, क्रोध, मद, मत्सर आदिले हामीलाई नरकतिर लैजान्छ । मन, वाणी र कर्मबाट हुने सबै कार्य हामीतिरै फर्केर आउँछ । अतः यसमा सतर्कता अपनाउनुपर्छ ।
प्रश्नकर्ता
- रीना दीदी
प्रश्न
- भगवान् आदि शङ्कराचार्यले अद्वैतको कुरा भन्नुभएको छ, तर गीतामा द्वैतको कुरा आउँछ ।
उत्तर
- त्यस्तो होइन, गीतामा द्वैत र अद्वैत दुवै कुराको चर्चा छ, हामी गीताजीको अध्ययनबाट द्वैत र अद्वैतको यात्राबारे जान्न सक्छौँ । आरम्भमा हामीभित्र मात्र म को भावना हुन्छ । पुनः जब हामी अगाडि बढ्छौँ म र तिमी (परमात्मा) को कुरा बुझ्दछौँ । अन्तमा मात्र परमात्मा बाँकी रहन्छ । यो क्रमशः घटित हुँदै जान्छ ।
प्रश्नकर्ता
- योगेश दाजु
प्रश्न-
गीता प्रेसको गीता र गीता परिवारको सरल पठनीय गीतामा धेरै ठाउँमा भिन्नता देखिन्छ किन?
उत्तर-
गीता परिवारको सरल पठनीय गीता नयाँ साधकहरूको लागि पढ्न सरल होस् भन्ने ध्यानमा राखेर उपलब्ध गराएको हो । कठिन र लामो शब्दहरूलाई टुक्र्याएर छोटो छोटो र सरल रूपमा राखिएको छ । यस्तो गर्नेबेलामा व्याकरणका नियमहरू र छन्दको अनुशासनलाई पूर्णरूपमा पालना गरिएको छ । विद्वानहरू र सन्तहरूको सहमतिबाट मात्रै यस्तो गरिएको हो । तपाईँ शङ्कारहित भएर यसको अध्ययन गर्नुहोस् ।
प्रश्नकर्ता
- शीला दीदी र गुंजन दीदी
प्रश्न
- विवेचन पुस्तकको रूपमा उपलब्ध छ?
उत्तर
- विवेचन लिखित रूपमा समूहमा राखिएको हुन्छ, तपाईँहरू त्यो पढ्न सक्नुहुन्छ ।
प्रश्नकर्ता
- मोनिका दीदी
प्रश्न
- म दुर्गा सप्तशतीको पाठ गर्छु । गीता कक्षामा श्लोकहरूको उच्चारण सिकेपछि थाहा पाएँ कि अहिलेसम्म मैले अशुद्ध पढिरहेकी थिएँ । के मेरो भूल भएको हो?
उत्तर-
यस्तो मान्नु हुन्न, श्रीभगवान्‌ स्वयं भन्नुहुन्छ- श्रद्धया परयोपेता:(स्), श्रद्धाले हामी जे पनि कार्य गर्छौँ त्यो वहाँलाई प्रिय लाग्छ । जसरी आमा-बुबालाई साना बच्चाहरूको त्रुटिपूर्ण उच्चारण पनि राम्रो लाग्छ र प्रसन्न हुन्छ, त्यस्तै नै भगवान् हाम्रो श्रद्धापूर्ण त्रुटिहरू पनि स्वीकार गर्नुहुन्छ र प्रसन्न हुनुहुन्छ ।
प्रश्नोत्तर सत्रपश्चात् श्रीहनुमान चालीसाको पाठका साथै आजको यस विवेचन सत्रको यहीँ विश्राम गरियो ।
यो विवेचन पढेर तपाईँलाई अवश्य पनि राम्रो लाग्यो होला भन्ने हामीलाई विश्वास लागेको छ । कृपया तल दिएको लिङ्क प्रयोग गरी हामीलाई आफ्नो प्रतिक्रियाहरू दिनुहोला ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 2, 'ŚRĪ SRINIVAS WARNEKAR JI', 'https://www.youtube.com/watch?v=3mLmUl31XyU', '2026-03-14', 'एवमेतद्यथात्थ त्वम्, आत्मानं(म्) परमेश्वर ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 3, 'ŚRĪ SRINIVAS WARNEKAR JI', 'https://www.youtube.com/watch?v=3mLmUl31XyU', '2026-03-14', 'भक्तको यो आर्त पुकार सुनेर करुणामय भगवान्‌ले अर्जुनलाई भन्नुहुन्छ, “हे पार्थ! मेरो असंख्य दिव्य रूपहरू छन्, विभिन्न रंग, आकृति र अद्भुत स्वरूपहरू, ती सबैलाई सामान्य आँखाले देख्न सम्भव हुँदैन । त्यसैले म तिमीलाई दिव्य दृष्टि दिन्छु, जसको माध्यमबाट तिमी मेरो विराट रूप देख्न सक्नेछौ” । भगवान्‌ले अर्जुनमाथि कृपा गर्नुभयो । उहाँले अर्जुनलाई दिव्य दृष्टि दिनुभयो र आफ्नो ज्ञानको ढोका खोलिदिनुभयो । मानिसले सामान्यतया संसारलाई पाँच ज्ञानेन्द्रिय- आँखा, कान, नाक, जिब्रो र छालाबाट अनुभव गर्छ । तर परमात्माको विराट स्वरूप यी सामान्य इन्द्रियहरूले देख्न सकिँदैन । त्यसका लागि विशेष आध्यात्मिक दृष्टि आवश्यक हुन्छ । भगवान्‌ले अर्जुनलाई त्यही दिव्य दृष्टि प्रदान गर्नुहुन्छ ।
त्यसपछि अर्जुनले भगवान्‌को विराट स्वरूप देख्छन्, जसमा सम्पूर्ण ब्रह्माण्ड समाहित छ- असंख्य देवता, ऋषि, लोक, सृष्टि र विनाशका सबै रूपहरू एउटै विराट स्वरूपमा देखिन्छन् । यो दृश्य देखेर अर्जुन अचम्मित हुँदै डराउँछन् । उनले भगवान्‌को महिमा स्वीकार गर्दै अत्यन्त विनम्रतापूर्वक नमस्कार गर्छन् र स्तुति गर्न थाल्छन् । यसप्रकार एघारौँ अध्यायमा भगवान्‌को विश्वरूप दर्शनको अद्भुत वर्णन गरिएकोछ, जसले परमात्माको अनन्त शक्ति र व्यापकता देखाउँछ ।
अब अर्जुन विराट स्वरूपको साक्षात्कार गर्दैछन्, अर्जुनका ईश्वरप्रति अत्यन्त श्रद्धा र भक्ति भएकाले भगवान्‌को विशेष कृपाले उनलाई त्यो अद्भुत अनुभव प्राप्त भयो । भगवान्‌को अनेकाअनेक रूपहरूमा उनले विश्वब्रह्माण्डको झलक देखे र त्यसले उनको अन्तःकरण द्रवित भयो र हृदय आनन्दले भरियो ।
एवमुक्त्वा ततो राजन्, महायोगेश्वरो हरिः।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 9, 'ŚRĪ SRINIVAS WARNEKAR JI', 'https://www.youtube.com/watch?v=3mLmUl31XyU', '2026-03-14', 'सञ्जय भन्छन्, “हे राजन् ! महायोगेश्वर भगवान् श्रीकृष्णले अर्जुनलाई यसरी आफ्नो परम ऐश्वर्ययुक्त दिव्यरूप देखाउनुभयो” ।
अनेकवक्त्रनयनम्, अनेकाद्भुतदर्शनम् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 10, 'ŚRĪ SRINIVAS WARNEKAR JI', 'https://www.youtube.com/watch?v=3mLmUl31XyU', '2026-03-14', 'त्यो रूपमा असंख्य मुख र आँखाहरू थिए, असंख्य अद्भुत दृश्यहरू थिए, दिव्य आभूषणहरूले सुशोभित थियो र अनेक प्रकारका दिव्य अस्त्र-शस्त्रहरू धारण गरिएको थियो ।
दिव्यमाल्याम्बरधरं(न्), दिव्यगन्धानुलेपनम् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 11, 'ŚRĪ SRINIVAS WARNEKAR JI', 'https://www.youtube.com/watch?v=3mLmUl31XyU', '2026-03-14', 'त्यो रूप दिव्य मालाहरू र वस्त्रहरूले सजिएको थियो, दिव्य सुगन्धले लेपित थियो, अद्भुत चमत्कारले भरिएको थियो, अनन्त थियो र सबैतिर मुख भएको थियो ।
11.12
दिवि सूर्यसहस्रस्य, भवेद्युगपदुत्थिता ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 12, 'ŚRĪ SRINIVAS WARNEKAR JI', 'https://www.youtube.com/watch?v=3mLmUl31XyU', '2026-03-14', 'आकाशमा हजारौँ सूर्यहरू एकैसाथ उदय हुँदा जुन प्रकाश उत्पन्न हुन्छ, त्यो पनि त्यस विश्वरूप परमात्माको प्रकाशसमान सायदै होला ।
सञ्जय धृतराष्ट्रसँग त्यो अलौकिक दृश्यको वर्णन गर्दै भन्छन् कि हे राजन्! कल्पना गर्नुहोस्, यदि गगनमा सहस्रौँ सूर्य एकैचोटि एकाएक उदित भए भने, त्यस समयमा जुन प्रचण्ड प्रकाश पुञ्ज उत्पन्न हुनेछ, सम्भवतः त्यो भगवान्‌को यस विश्वरूपको दिव्य प्रकाशसँग केही हदसम्म त्यस्तै हुनेछ ।
विचार गर्नुहोस्, जब मध्याह्नको आकाशमा एउटा सूर्यको प्रभालाई हाम्रा यी चर्मचक्षुले सहन गर्न सक्दैनन्, तब सहस्रौँ सूर्यहरूको त्यो संयुक्त प्रकासलाई हामी कसरी देख्न सक्नेछौँ? एकैचोटि उदित हुने ती सहस्रौँ सूर्यहरू जस्तै त्यो देदीप्यमान विश्वरूपको प्रकाशलाई हामी केवल कल्पना मात्र गर्न सक्छौँ ।
ज्ञान र विज्ञानको यस आधुनिक युगमा सूचना प्रविधिको माध्यमबाट एउटा रोचक प्रसङ्गको उल्लेख पाइन्छ । भनिन्छ कि अणु बम निर्माण गर्ने वैज्ञानिकले जब त्यसको भीषण विस्फोटलाई प्रत्यक्ष देखे, तब उनलाई पनि श्रीमद्भगवद्गीतामा वर्णित यही प्रकारको विश्वरूपको प्रकाशको स्मरण भएको थियो । यद्यपि यस वृत्तान्तको पूर्ण सत्यताको विषयमा हामी निश्चित रूपमा केही भन्न सक्दैनौँ, तर यो भगवान्‌को त्यस अनन्त तेजको व्यापकतालाई बुझ्ने एउटा माध्यम अवश्य हुन सक्छ ।
सञ्जय धृतराष्ट्रसँग त्यो अलौकिक अनुभूतिको वर्णन गर्दै भन्छन् कि हे राजन्! त्यो परम पुरुषको विश्वरूपबाट उत्सर्जित हुने त्यो दिव्य प्रकाश सम्पूर्ण ब्रह्माण्डलाई आफ्नो असीम प्रकासले प्रकासित गरिरहेको थियो । सञ्जयले धृतराष्ट्रलाई बोध गराए कि उनले साक्षात् त्यो परम् प्रकाशको साक्षात्कार गरेका छन् । सञ्जय अब धृतराष्ट्रको सामु त्यस विराट स्वरूपका ती रहस्यहरू प्रकट गर्छन्, जसलाई अर्जुनले आफ्नो दिव्य दृष्टिबाट देखेका थिए ।
11.13
तत्रैकस्थं(ञ्) जगत्कृत्स्नं(म्), प्रविभक्‍तमनेकधा ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 13, 'ŚRĪ SRINIVAS WARNEKAR JI', 'https://www.youtube.com/watch?v=3mLmUl31XyU', '2026-03-14', 'पाण्डुपुत्र अर्जुनले त्यतिबेला अनेक प्रकारले विभक्त भएका अर्थात् अलग-अलग सम्पूर्ण जगत्‌लाई देवताहरूका पनि देवता भगवान् श्रीकृष्णको शरीरमा एकै ठाउँमा स्थित भएको देखे ।
एकै स्थानमा, भगवान्‌को एउटै दिव्य श्रीविग्रहमा सम्पूर्ण जगत् र यो अनन्त विश्व समाहित छ । विचार गर्नुहोस्, त्यो विश्व कस्तो छ? के विश्वको केवल एउटै सीमित रूप मात्र छ? कदापि छैन । यसमा विशाल पर्वतमालाहरू छन्, सघन वनहरू छन्, नदीहरू छन् र नजाने कति अद्भुत रचनाहरू छन् । यो सम्पूर्ण चराचर जगत्, नभमण्डलका अनन्त नक्षत्रहरू, सूर्य र चन्द्रमा, वनस्पति, सम्पूर्ण भूतप्राणी, मनुष्य तथा विभिन्न प्रकारका पशुपक्षी र कीटपतङ्ग, यी सबै कुरा त्यही एउटै परम तत्त्वमा अन्तर्निहित छन् । यद्यपि हाम्रो दृष्टिमा यी सबै अलगअलग रूपले देखिन्छन्, तथापि पाण्डुपुत्र अर्जुनले यी सम्पूर्ण विविधताहरू भगवान्‌को एकैशरीरमा, एकैचोटि, एकैसमयमा देखे ।
देवहरूको देव, योगेश्वर भगवान्‌को त्यही एउटै विग्रहमा अर्जुनले यस सम्पूर्ण विभक्त र विविधताले भरिएको ब्रह्माण्डलाई एकाकार भएर स्थित भएको देखे । जसरी हामी कुनै विशाल वटवृक्षलाई अवलोकन गर्छौँ, जसका अनगिन्ती शाखाहरू, सहस्रौँ पातहरू, विस्तृत जरा र तिनमा बसेका अनेकौँ पक्षीहरू हुन्छन्; यी सबै विस्तार भएर पनि अन्ततः त्यो एउटै वृक्ष नै हुन्छ । ठीक त्यसैगरी, अर्जुनले परमेश्वरको दिव्य शरीरमा सम्पूर्ण ब्रह्माण्डलाई स्थित देखे ।
तेह्रौँ श्लोकमा यस अलौकिक दृश्यको अद्भुत वर्णन गरिसकेपछि, अब सञ्जय भगवान्‌ अगाडी बसेका अर्जुनको अवस्थाको चित्रण गर्दैछन् । त्यो विराट र विस्मयकारी रूपलाई देखेर अर्जुनको अवस्था कस्तो भयो, उनका भित्र कस्ता भावहरूको ज्वार उम्लियो, यसको सजीव चित्रण सञ्जय गर्छन् ।
11.14
ततः(स्) स विस्मयाविष्टो, हृष्टरोमा धनञ्जयः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 14, 'ŚRĪ SRINIVAS WARNEKAR JI', 'https://www.youtube.com/watch?v=3mLmUl31XyU', '2026-03-14', 'भगवान्‌को विश्वरूपलाई देखेर चकित र पुलकित भई रोमाञ्चित भएका ती अर्जुनले प्रकाशमय विश्वरूप परमात्मालाई श्रद्धाभक्तिले शिरले प्रणाम गरी हात जोडेर बिन्ती गर्न लागे ।
सञ्जय त्यो दिव्य अवस्थाको वर्णन गर्दै भन्छन् कि पाण्डुपुत्र अर्जुन विष्मयले चकित भएका छन् र आश्चर्यको महासागरमा डुबेका छन् । कल्पना गर्नुहोस्, यदि हामी र तपाईँ अर्जुनको नजिक उभिएर त्यस दृश्यको मानसिक चिन्तन मात्र पनि गर्‍यौँ भने, हाम्रो अन्तःकरणमा कति ठूलो विष्मय जागृत हुनेछ । त्यही आश्चर्य र चकित भाव अर्जुनको मुखमण्डलमा सञ्जय स्पष्ट देखिरहेका छन् । भगवान्‌को यस असीम ऐश्वर्यमय रूपलाई हेर्दै अर्जुन रोमाञ्चित भएका छन् ।
यदि साक्षात् परमेश्वर हाम्रो सामु प्रकट हुनुभयो भने, हाम्रो पहिलो स्वाभाविक प्रतिक्रिया के हुनेछ? हृदयबाट पहिलो भाव के निस्कनेछ? निश्चय नै, हामी श्रद्धाले नतमस्तक हुनेछौँ र साष्टाङ्ग प्रणाम गर्नेछौँ । अर्जुनले पनि त्यही गरे; उनले भगवान्‌को चरणमा ढोगे । उनले अत्यन्त विनम्रताका साथ हात जोडेर उहाँलाई नमन गरे । भगवान्‌को यस तेजोमय विग्रहलाई देखेर उनले शिर झुकाए र प्रार्थना मुद्रामा भगवान्‌को स्तुति गर्न थाले ।
अहिलेसम्म अर्जुन भगवान्‌सँग सखा भावमा संवाद गरिरहेका थिए र विनीत प्रार्थना गरिरहेका थिए कि यदि म तपाईँको त्यो अलौकिक रूपलाई देख्ने पात्रता राख्छु भने, कृपा गरेर मलाई त्यसका दर्शन गराइदिनुहोस् । तर जसै अर्जुनले त्यस विराट विश्वरूपको साक्षात्कार गरे, उनको चेतना परिवर्तन भयो; उनले दण्डवत् प्रणाम गरे र स्तुति प्रारम्भ गरे । अर्जुन यति धेरै विस्मित र चकित भए कि उनका संवादको शैली र भाषाको स्वरूप नै परिवर्तन भयो ।
11.15
अर्जुन उवाच
पश्यामि देवांस्तव देव देहे,
सर्वांस्तथा भूतविशेषसङ्घान् ।
ब्रह्माणमीशं(ङ्) कमलासनस्थम्,', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 15, 'ŚRĪ SRINIVAS WARNEKAR JI', 'https://www.youtube.com/watch?v=3mLmUl31XyU', '2026-03-14', 'अर्जुनले विन्ती गरे- हे देव! मैले हजुरको शरीरमा सम्पूर्ण देवताहरूलाई तथा अनेक प्राणीहरूको समुदायहरूलाई, कमलको आसनमा विराजित ब्रह्माजीलाई, शङ्करजीलाई, सम्पूर्ण ऋषिहरूलाई र दिव्य सर्पहरूलाई पनि देखिरहेको छु ।
अर्जुन भावविभोर भएर भन्छन्- "हे देवाधिदेव! म तपाईँको यस दिव्य विग्रहमा सम्पूर्ण देवहरूको दर्शन गरिरहेको छु । तपाईँको यस अनन्त शरीरमा एकातिर सृष्टिका आदि रचयिता प्रजापति ब्रह्मदेव विराजमान हुनुहुन्छ, भने अर्कोतिर कैलाशपति महादेव पनि तपाईँमै प्रतिष्ठित हुनुहुन्छ । म ब्रह्मा र महादेवसँगै सम्पूर्ण ऋषि र मुनिहरूलाई पनि तपाईँमै समाहित देखिरहेको छु” ।
सनत्कुमार: सनक: सनन्दन: सनातनोऽप्यासु
सनक, सनन्दन, सनातन र सनत्कुमार आदि परम सिद्ध ऋषिगण पनि मैले तपाईँको यस दिव्य देहमै लीन देखेकोछु । जब धेरै वस्तुहरू एउटै स्थानमा देखिन्छन्, तब कसको बारेमा भनौँ र के बताऔँ भन्ने अवस्था हुन्छ । यदि हाम्रो सामु असङ्ख्य वस्तुहरू एकैचोटि राखिए र सोधियो कि तपाईँ केके देखिरहनुभएको छ, भने तिनको कुनै निश्चित क्रम रहँदैन । मानिसका लागि ती सबैको स्मरण राख्नु कठिन हुन्छ । ठीक त्यसैगरी, जब अर्जुन भगवान् भित्र सम्पूर्ण ब्रह्माण्डलाई एकैचोटि देखिरहेका छन्, तब उनी अचम्मित भएर भन्छन् कि उनलाई यस रूपभित्र सम्पूर्ण संसार, भूतहरूको समुदाय, सम्पूर्ण चराचर जीवजन्तु, ऋषिगण र यहाँसम्म कि दिव्य सर्पहरू पनि दृष्टिगोचर भइरहेका छन् ।
बाल्यकालमा एकाग्रता र स्मरणशक्तिको विकासका लागि हामी एउटा खेल खेल्ने गर्थ्यौँ । एउटा टेबलमा साना-ठूला धेरै वस्तुहरू सजाइन्थे र हामीले केही समयका लागि ती वस्तुलाई ध्यानपूर्वक हेर्नु पर्थ्यो । त्यसपछि हामी अर्को कोठामा गएर ती सबै वस्तुहरूको सूची बनाउनु पर्थ्यो । त्यसबेला जुनजुन वस्तु स्मृतिमा आउँथ्यो, हामी त्यसलाई लेख्दै जान्थ्यौँ- जस्तै सियो, धागो, पुस्तक, कलम, ऐना, थाली आदि । जुन वस्तु दृष्टिमा पर्थ्यो, त्यसलाई सम्झेर हामी लिपिबद्ध गर्थ्यौँ ।
अर्जुनको अवस्था पनि त्यस्तै छ । उनले अनेक दिव्य दृश्यहरू एकै क्षणमा देखिरहेका छन् । कमलासनमा विराजमान पितामह ब्रह्मा देखापरिरहनुभएको छ, भने त्यहीँ साक्षात् महादेव पनि हुनुहुन्छ । उनी भन्छन् कि म ब्रह्मदेवलाई देखिरहेको छु, महादेवलाई देखिरहेको छु, दिव्य ऋषिहरूलाई देखिरहेको छु । चराचर प्राणीहरूका विभिन्न समुदाय, वृक्षहरूको समूह र सम्पूर्ण भूतमात्राहरू त्यहाँ एकैचोटि देखिएका छन् । यहाँसम्म कि दिव्य सर्पहरू पनि त्यस विराट देहमा शोभायमान छन् ।
अर्जुन फेरी त्यस विस्तारको वर्णन गर्छन् । कल्पना गर्नुहोस्, यदि सम्पूर्ण सृष्टि एउटै देहमा समेटिएको भए यही भावका साथ विश्वरूपलाई बुझ्न चाहन्छौँ, भने हामीले पनि त्यो दिव्य दर्शन गर्ने प्रयास गर्नुपर्छ । आउनुहोस्, हामी पनि आफ्नो अन्तरात्माबाट अर्जुनको भूमिकामा प्रवेश गरौँ र मनमनै कुरुक्षेत्रको त्यो पावन समराङ्गणमा पुगौँ । त्यहाँ भगवान्‌को सामु नतमस्तक भएर त्यो दिव्य रूपको झाँकीको अनुभव गर्ने प्रयास गरौँ । जब हामी यस दिव्य वर्णनलाई श्रवण गर्छौँ, तब त्यो परम तेजस्वी स्वरूप हाम्रो हृदयमा पनि प्रतिबिम्बित हुन थाल्छ- त्यो स्वरूप जसमा सम्पूर्ण सृष्टि समाहित छ ।
11.16
अनेकबाहूदरवक्त्रनेत्रं(म्),
पश्यामि त्वां(म्) सर्वतोऽनन्तरूपम् ।
नान्तं(न्) न मध्यं(न्) न पुनस्तवादिं(म्),', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 16, 'ŚRĪ SRINIVAS WARNEKAR JI', 'https://www.youtube.com/watch?v=3mLmUl31XyU', '2026-03-14', 'हे विश्वरूप! हे विश्वेश्वर! हजुरलाई मैले अनेकौँ हात, पेट, मुख र आँखाहरूले युक्त भएको तथा सबैतिरबाट अनन्तरूपवाला देख्दैछु । मैले हजुरको न आदि देख्छु, न मध्य र न अन्त नै देखिरहेको छु ।
अर्जुन भन्दछन्- मैले असंख्य (गन्न र भन्न नसकिने) हात, मुख, पेट, आँखा भएका जीवहरू देखिरहेको छु, जसको शुरू मध्य र अन्त कहाँ कसरी भएको छ भन्न सकिने अवस्था छैन त्यसको पुन उदय कहाँ हुन्छ कहाँ भयो त्यो पनि ज्वाजल्य प्रकाशका कारण एकिन गरी ठम्याउन सकिएको छैन । ती सबै अवस्था विश्वरूप विश्वेश्वर भगवान्‌मा देखिएको छ ।
11.17
किरीटिनं(ङ्) गदिनं(ञ्) चक्रिणं(ञ्) च,
तेजोराशिं(म्) सर्वतो दीप्तिमन्तम् ।
पश्यामि त्वां(न्) दुर्निरीक्ष्यं(म्) समन्ताद्-', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 17, 'ŚRĪ SRINIVAS WARNEKAR JI', 'https://www.youtube.com/watch?v=3mLmUl31XyU', '2026-03-14', 'मैले हजुरलाई किरीटयुक्त (मुकुटयुक्त), गदायुक्त र चक्रयुक्त तथा कठिनतासाथ हेर्नुपर्ने सबैतिरबाट प्रकाशमान तेजका पुञ्ज, प्रज्ज्वलित अग्नि र सूर्यसमान ज्योतियुक्त र सबैतिरबाट अप्रमेयस्वरूपलाई देख्दैछु ।
अर्जुन भन्छन्, "हे भगवान्! म तपाईँको मस्तकमा किरीट (मुकुट) का स्पष्ट दर्शन गरिरहेको छु, जसले मेरो यो विश्वास दृढ बनाउँछ कि मेरो सामु साक्षात् तपाईँ नै विराजमान हुनुहुन्छ । तपाईँको गदा, करकमलमा सुशोभित तेजोमय सुदर्शन चक्र प्रत्यक्ष देखिरहेको छु । यी तपाईँका साक्षात् स्वरूपका अनुपम चिन्हहरू हुन्, जसका आधारमा म पूर्ण निष्ठाका साथ भन्न सक्छु कि हे भगवान्! तपाईँ नै मेरा आराध्य हुनुहुन्छ" । सम्पूर्ण दिशाहरूलाई प्रकासमय बनाउँदै, तेजःपुञ्जले ढाकिएको तपाईँको यो तेजस्वी स्वरूप मेरो सामु प्रकट छ । यस्तो लाग्छ मानौँ अनन्त प्रज्वलित अग्निहरूको पुञ्ज हो अथवा सहस्रौँ सूर्यहरूको प्रचण्ड प्रकाश; सूर्यजस्तै देदीप्यमान तपाईँको यो आभा चराचर जगत्मा व्याप्त भएको छ । तपाईँको श्रीविग्रहको यो तेज यति प्रखर छ कि मेरो दृष्टिले यसको पूर्ण निरीक्षण गर्न आफूलाई असमर्थ पाउँछ । यस अलौकिक रूपको साक्षात्कार गर्नु अत्यन्त कठिन छ, किनकि यो नयनलाई विस्मित पार्ने र पूर्ण रूपमा दुर्निरीक्ष्य छ ।
यो रूप कति विशाल र अनन्त छ! गणितमा प्रमेय त्यसलाई भनिन्छ जसलाई सिद्ध गर्न सकिन्छ र जसको समाधान प्राप्त हुन्छ, तर सृष्टिमा केही यस्ता तथ्यहरू पनि छन् जसको गणना मानवीय बुद्धिको क्षमताभन्दा बाहिर हुन्छ । जस्तै गणितको एउटा सिद्धान्त भन्छ कि समानान्तर रेखाहरू अनन्तमा गएर मिल्छन् । वास्तवमा यसको गूढ अर्थ यही हो कि ती कहिल्यै एकअर्कासँग मिल्दैनन्, तर गणितीय शब्दावलीमा यसलाई ‘अनन्तमा मिल्नु’ भनिन्छ, किनकि त्यो अनन्ततासम्म न कोही पुग्न सक्छ र न त त्यसलाई कसैले मापन गर्न सक्छ ।
जसलाई मापन गर्न सकिन्छ अथवा जसको परिधि निश्चित गर्न सकिन्छ, त्यो प्रमेय हो; तर जुन प्रत्येक मापन प्रक्रियाभन्दा पर हो र जसको गणना सम्भव छैन, त्यही ‘अप्रमेय’ हो ।
अर्जुन भावविभोर भएर भन्छन्, “हे भगवान्! तपाईँको यस विश्वरूपको विस्तार कहाँदेखि कहाँसम्म छ, यो जान्नु पूर्ण रूपमा असम्भव छ । त्यसैले तपाईँको यो दिव्य स्वरूप पूर्णतः अप्रमेय छ” । सम्पूर्ण विश्वलाई भगवान्‌ले आफ्नो देदीप्यमान तेजःपुञ्जले व्याप्त गर्नुभएको छ । भगवान्‌को त्यो अलौकिक स्वरूप अर्जुनको सामु प्रत्यक्ष छ, जसको दर्शन गर्नु पनि अत्यन्त कठिन छ । यस्ता अद्भुत र भव्य विश्वरूपको स्तुति अर्जुन अब श्रद्धापूर्वक गान गर्न प्रारम्भ गर्छन् ।
11.18
त्वमक्षरं(म्) परमं(व्ँ) वेदितव्यं(न्),
त्वमस्य विश्वस्य परं(न्) निधानम् ।
त्वमव्ययः(श्) शाश्वतधर्मगोप्ता,', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 18, 'ŚRĪ SRINIVAS WARNEKAR JI', 'https://www.youtube.com/watch?v=3mLmUl31XyU', '2026-03-14', 'हजुर नै जान्नयोग्य परम अक्षर (अक्षरब्रह्म) अर्थात् परब्रह्म परमात्मा हुनुहुन्छ, हजुर नै सम्पूर्ण जगत्‌का परम आश्रय हुनुहुन्छ, हजुर नै आदि (सनातन) धर्मका रक्षक हुनुहुन्छ र हजुर नै अविनाशी सनातन पुरुष हुनुहुन्छ भन्ने मेरो मत छ ।
वेद शब्दको अर्थ हो जान्नु, ज्ञान । जसलाई जान्नुपर्छ अथवा जो जान्न योग्य हुन्छ, त्यसलाई
वेदितव्यं
भनिन्छ ।
वेदितव्यं(न्)
अर्थात् तपाईँ वेदितव्य हुनुहुन्छ । अर्जुन भगवान्‌को स्तुति गर्दै भन्छन् कि मेरो लागि जो परम वेद हो, त्यो तपाईँ नै हुनुहुन्छ । अक्षरको अर्थ हो जसको कहिल्यै क्षरण हुँदैन, जसको व्यय हुँदैन र जसको कहिल्यै नाश हुँदैन । निधानको अर्थ हो त्यो आधार वा आश्रय, जसमा यो सम्पूर्ण जगत् विश्राम पाउँछ ।
हामीले द्वितीय अध्यायमा आत्मतत्त्वको चिन्तन गरेका थियौँ कि त्यो अविनाशी, अव्यय र अक्षर हो । त्यो परब्रह्म अक्षर स्वरूप हो । त्यसैले अर्जुन भन्छन् कि तपाईँ नै त्यो परमात्मा हुनुहुन्छ, तपाईँ नै परब्रह्म हुनुहुन्छ र तपाईँ नै त्यो अक्षर तत्त्व हुनुहुन्छ । तपाईँ यस विश्वका परम निधान हुनुहुन्छ ।
जसरी हामी आफ्नै घरको आश्रयमा बस्छौँ, त्यसैगरी यो प्रश्न उठ्छ कि यो विशाल विश्व कहाँ बस्छ? यो सम्पूर्ण विश्व परमात्माकै आश्रयमा स्थित छ र उहाँमै समाहित छ; त्यसैले यस जगतका परम आश्रयस्थान भगवान् नै हुनुहुन्छ । हाम्रो घर पृथ्वीको आश्रयमा अडिएको छ र पृथ्वीले नै यसलाई धारण गरिरहेको छ, तर पृथ्वीलाई कसले धारण गरेको छ? पृथ्वी त अन्तरिक्षमा सूर्यको परिक्रमा गरिरहेको छ । वैज्ञानिकहरू भन्छन् कि सूर्यको गुरुत्वाकर्षण शक्तिले पृथ्वीलाई धारण गरिरहेको छ, जसका कारण ऊ आफ्नो निश्चित मार्गमा घुमिरहेको छ र आफ्नो पथबाट यताउता भड्किँदैन । त्यसपछि यो विचार आउँछ कि सूर्य कसको आश्रयमा स्थित छ? यस्ता त असङ्ख्य सूर्य र असङ्ख्य ग्रह मण्डलहरू छन् । अर्जुनले देखे कि यो अनन्त आकाश र खगोल जुन परम शक्तिको आश्रयमा अडिएको छ, त्यो भगवान् नै हुनुहुन्छ । त्यसैले अर्जुन भन्छन् कि तपाईँ नै यस विश्वका परम निधान हुनुहुन्छ । तपाईँले नै यस सम्पूर्ण विश्वलाई धारण गरिरहनुभएको छ ।
यदि कुनै क्षण परमात्माले यो विचार गर्नुभयो कि उहाँले यस विश्वलाई किन धारण गर्ने, भने सबै कुरा तत्काल समाप्त हुनेछ । तर यस्तो हुँदैन, किनकि उहाँ परम दयालु परमात्मा हुनुहुन्छ । उहाँले आफ्नो महान् कृपाले हामी सबैलाई र यस सम्पूर्ण ब्रह्माण्डलाई धारण गरिरहनुभएको छ ।
वेदहरूको उत्पत्ति कहिले भयो, यो कसैलाई थाहा छैन, किनकि ती अनादि कालदेखि विद्यमान छन् । सन्त ज्ञानेश्वर महाराज भन्नुहुन्छ कि वेदहरूको मूल स्वरूपको वर्णन गर्नु पनि वाणीभन्दा परको कुरा हो । वेद कहिलेदेखि अस्तित्वमा छन्, यसको कसैलाई ज्ञान छैन र ती वेदहरू पनि तपाईँलाई नै खोजिरहेका छन् भने तपाईँको रहस्य कसरी थाहा पाउन सकिन्छ?
शाश्वत
- जो अनादि र जसको कुनै आदि छैन; यो कहिलेदेखि चलिरहेको छ, यसको कसैलाई ज्ञान छैन । यस्तो यो सनातन धर्म अनादिकालदेखि प्रवाहित छ । अर्जुन भगवान्‌लाई
शाश्वत धर्म गोप्ता
भनेर सम्बोधन गर्छन्, जसको अर्थ हो कि तपाईँ नै यस सनातन धर्मका रक्षक हुनुहुन्छ त्यसैले यो धर्म सनातन कालदेखि अविरल रूपमा चलिरहेको छ । जबजब मानिस धर्मको मार्गलाई बिर्सन थाल्छ, तब भगवान् फेरि त्यसलाई स्थापित गर्नुहुन्छ, जसरी उहाँले चतुर्थ अध्यायमा भन्नुभएको छ-
धर्मसंस्थापनार्थाय सम्भवामि युगे युगे ॥४.८॥
भगवान् भन्नुहुन्छ म प्रत्येक युगमा आउँछु र सनातन धर्मलाई स्थापित गर्छु । यसै कारण यो सनातन धर्म शाश्वत छ ।
पुरुष को अर्थ त्यो चैतन्य आत्मतत्त्व हो, जसका विषयमा हामीले सप्तम अध्यायमा विस्तृत रूपमा पढेका छौँ । त्यो आत्मतत्त्व र त्यो परमात्मा स्वयम् तपाईँ नै हुनुहुन्छ । यद्यपि म यसलाई पूर्ण रूपमा र स्पष्टसँग जान्दिनँ, तर तपाईँको यस दिव्यरूपको दर्शन गरेपछि मेरो मनले यही भन्छ कि त्यो तपाईँ नै हुनुहुन्छ । यस चराचर विश्वका स्रष्टा, धारणकर्ता र संहारकर्ता केवल तपाईँ नै हुनुहुन्छ; अब यो मेरो दृढ मत भइसकेको छ ।
11.19
अनादिमध्यान्तमनन्तवीर्यम्,
अनन्तबाहुं(म्) शशिसूर्यनेत्रम् ।
पश्यामि त्वां(न्) दीप्तहुताशवक्त्रं(म्),', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 19, 'ŚRĪ SRINIVAS WARNEKAR JI', 'https://www.youtube.com/watch?v=3mLmUl31XyU', '2026-03-14', 'हजुरलाई आदि, मध्य र अन्तले रहित, अनन्त प्रभावशाली, अनन्त सामर्थ्यले युक्त, अनन्त भुजाहरू भएका, चन्द्रसूर्यरूपी नेत्रहरू भएका, प्रज्वलित अग्निरूपी मुखहरू भएका र आफ्नो तेजले यस जगत्‌लाई सन्तप्‍त गरिरहनुभएको देख्दैछु ।
हामी यो राम्रोसँग जान्दछौँ कि श्रीमद्भगवद्गीता भगवान् र अर्जुनविचको एक पावन संवाद हो । जब कुनै संवाद अथवा परस्पर वार्तालाप हुन्छ, तब केही कुरा दुईपटक वा तीनपटक पनि भनिन सक्छन्; तिनमा पुनरावृत्ति हुनु स्वाभाविक हो । यदि हामी कुनै निबन्ध अथवा शोधप्रबन्ध लेख्छौँ भने, त्यहाँ पुनरुक्तिलाई दोष मानिन्छ, तर संवादमा जुन कुरा हृदयलाई प्रिय लाग्छ, त्यसलाई बारम्बार दोहोर्‍याउन सकिन्छ । अर्जुन पनि यहाँ त्यही गरिरहेका छन् । उनी भगवान्‌को त्यो अलौकिक रूप देखेर यति धेरै विस्मित र चकित भएका छन् कि उनका मुखबाट त्यही कुरा बारम्बार निस्किरहेका छन् । उनको अन्तःकरण त्यो अद्भुत दृश्यको प्रभावले भरिएको छ, त्यसैले उनी फेरि ती नै अनन्त विशेषताहरूको वर्णन गर्न थाल्छन् ।
तपाईँको आदि, मध्य र अन्त छैन- यो कुरा अर्जुन विस्मयका कारण फेरि भन्छन् । तपाईँको सामर्थ्य र तपाईँको शक्ति अनन्त छ । के हामी भगवान्‌को शक्तिको कल्पना गर्न सक्छौँ? यदि हामी विज्ञानको दृष्टिले विचार गर्‍यौँ भने, एउटा परमाणुको निर्माणका लागि जति शक्ति आवश्यक हुन्छ, त्यसलाई नष्ट गर्न पनि त्यत्तिकै शक्ति लाग्छ । जब एउटा परमाणुलाई विभाजित गरिन्छ, तब त्यसबाट निस्कने ऊर्जा हामी परमाणु बमको रूपमा देख्छौँ ।
आल्बर्ट आइंस्टाइनले यसको समीकरण दिएका छन्-
E = mc²
E = energy ऊर्जा
m = matter द्रव्यमान
c = velocity of light प्रकाशको गति (३ लाख किलोमिटर प्रति सेकेन्ड)
यो ऊर्जा कति विशाल हुन्छ? कुनै पदार्थको निर्माणका लागि जति ऊर्जा चाहिन्छ, त्यो त्यस पदार्थको द्रव्यमान र प्रकाशको गतिको वर्गको गुणनफल बराबर हुन्छ । प्रकाशको गति तीन लाख किलोमिटर प्रति सेकेन्ड हो । यदि त्यस गतिको वर्गसँग कुनै वस्तुको द्रव्यमानलाई गुणा गरियो भने, जुन मान प्राप्त हुन्छ, त्यत्तिकै ऊर्जा एउटा सूक्ष्म पदार्थ बनाउन लाग्छ । हाम्रो शरीरमा कति परमाणुहरू होलान्? यस सम्पूर्ण विश्वमा कति परमाणु र कति पदार्थ छन्? यस सम्पूर्ण संसारको निर्माणका लागि कति ऊर्जा आवश्यक परेको होला? यो सबै परमात्माकै असीम ऊर्जाबाट प्राप्त भएको हो । यति विशाल ऊर्जा प्रयोग गरेर सृष्टि निर्माण गरेपछि पनि भगवान्‌को ऊर्जा अक्षय नै रहन्छ । जसरी समुद्रबाट दुई बाल्टिन पानी निकाल्दा पनि समुद्रमा कुनै कमी आउँदैन, त्यसैगरी यो अनन्त विश्व निर्माण गरेपछि पनि परमात्मा पूर्ण र अपरिवर्तित रहनुहुन्छ । त्यसैले हे भगवान्! तपाईँको सामर्थ्य र तपाईँको शक्तिको हामी कल्पना पनि गर्न सक्दैनौँ ।
अर्जुन थप्दछन् कि तपाईँका भुजाहरू अनन्त छन् । यस संसारमा भइरहेको हरेक कार्य तपाईँकै भुजाहरूबाट सम्पन्न भइरहेको छ । मलाई यस्तो लाग्छ कि सूर्य र चन्द्रमा तपाईँका नेत्र हुन् । सूर्यरूपी नेत्रबाट भगवान् सम्पूर्ण संसारलाई ऊर्जा, प्रकाश र शक्ति प्रदान गर्नुहुन्छ, जबकि चन्द्रमारूपी नेत्रबाट उहाँ जगतलाई शान्ति, शीतलता र प्रेम दिनुहुन्छ ।
स्वतेजसा विश्वमिदं तपन्तम् ।
अर्जुन त्यस विराट रूपको एक अत्यन्त प्रभावशाली र केही भयावह स्वरूप देखिरहेका छन् । उनी भन्छन्, “म देखिरहेको छु कि तपाईँका मुखारविन्द प्रज्वलित अग्निजस्तै दन्किरहेका छन् । यस्तो लाग्छ मानौँ साक्षात् कालाग्नि तपाईँका मुखबाट प्रकट भइरहेको हो । तपाईँ आफ्नो यस प्रचण्ड तेजले सम्पूर्ण चराचर विश्वलाई तप्त गरिरहनुभएको छ” ।
ग्रीष्मऋतुमा जब सूर्यको ताप अलिकति मात्र बढ्छ, तब हामी व्याकुल हुन्छौँ । हामी त्राहि-त्राहि हुन्छौँ कि भीषण गर्मी छ । जब एउटा सूर्यका किरणहरूले हामीलाई यति धेरै तताउन सक्छन्, तब जहाँ सहस्रौँ सूर्यहरूको ऊर्जा एकैचोटि एकाकार भएको छ, त्यस तेजले यो सारा विश्व धेरै संतप्त भइरहेको होला । अर्जुन प्रत्यक्ष देखिरहेका छन् कि भगवान्‌को त्यो तेजोमय स्वरूपले आफ्नो ऊर्जाबाट केवल सम्पूर्ण ब्रह्माण्डलाई प्रकाशित मात्र गरिरहेको छैन र त्यसलाई तप्त पनि बनाइरहेको छ ।
11.20
द्यावापृथिव्योरिदमन्तरं(म्) हि,
व्याप्तं(न्) त्वयैकेन दिशश्च सर्वाः ।
दृष्ट्वाद्भुतं(म्) रूपमुग्रं(न्) तवेदं(म्),', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 20, 'ŚRĪ SRINIVAS WARNEKAR JI', 'https://www.youtube.com/watch?v=3mLmUl31XyU', '2026-03-14', 'हे महात्मन्! यो स्वर्ग र पृथ्वी बीचको सम्पूर्ण आकाश तथा सम्पूर्ण दिशाहरू एकमात्र हजुरबाट नै परिपूर्ण छन् भने हजुरका यी अलौकिक, अद्भुत र भयङ्कर रूपलाई देखेर तीनै लोक अत्यन्त व्यथित (व्याकुल) भइरहेका छन् ।
द्यावा
- आकाश,
पृथिव्यो
- पृथ्‍वी,
अन्‍तरम्
- अन्‍तरिक्ष ।
व्‍याप्‍त
- ढाकेको,
त्‍वयैकेन
- तपाईँ एक्लैले,
दिशश्च सर्वाः
- सबै दिशा, दशै दिशा ।
दृष्ट्वाद्भुतम्
- अद्‍भुत देखिन्‍छ,
रूपमुग्रन्
- उग्ररूप,
तपेदम
– देखेर, जानेर ।
लोकत्रयम्
- तिनैलोक (स्वर्ग, मर्त्‍य र पाताल)।
प्रव्यथितम्
- व्‍यथाले, व्‍यथित, डरले कापिरहेको, महात्‍मन्- हे महात्‍मा, हे महापुरुष । हे महात्‍मा! देखिएको स्वर्ग, मर्त्‍य र अन्‍तरिक्षका साथै सबै (दशै ) दिशाहरू तपाईँले नै ढाकेर रहनु भएकोछ । तपाईँको अद्भुत वा अलौकिक र भयङ्कर रूपलाई देखेर तिनै लोक व्‍यथाले व्यथित भइरहेको (डरले काँपिरहेको) छ ।
11.21
अमी हि त्वां(म्) सुरसङ्घा विशन्ति,
केचिद्भीताः(फ्) प्राञ्जलयो गृणन्ति ।
स्वस्तीत्युक्त्वा महर्षिसिद्धसङ्घा:(स्),', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 21, 'ŚRĪ SRINIVAS WARNEKAR JI', 'https://www.youtube.com/watch?v=3mLmUl31XyU', '2026-03-14', 'तिनै देवताहरूको समुदाय हजुरमा प्रवेश गरिरहेका छन् भने तिनीहरूमध्ये कोही त भयभीत भएर हात जोड्दै हजुरका नामहरू र गुणहरूको उच्चारण गरिरहेका छन् । साथै, महर्षिहरू र सिद्धपुरुषहरूको समुदायले ‘कल्याण होस्! मंगल होस्!’ भन्दै उत्तम-उत्तम स्तोत्रहरूले हजुरको स्तुति गरिरहेका छन् ।
शहरको कोलाहल, विद्युतको उज्यालो छोडेर शान्त वनजञ्गलमा घनघोर अध्यारो रातको समयमा गएर आकाशतर्फ हेर्‍यौँ भने आकाशमा अनगिन्ती ताराहरू चम्कीरहेका देख्छौँ । कुनै कुनै ताराबाट पृथ्वीमा प्रकाश आउन लाख प्रकाश वर्ष पनि लाग्‍न सक्छ । कुनै ताराहरू लाख प्रकाश वर्ष अगाडि नै लोप भैसकेका हुन सक्छन् । प्रकाश वर्ष भन्नाले- प्रकाश एक सेकेण्डमा ३ लाख किमि दुरी पार गर्छ । यही हिसाव‌ले १ मिनेट, १ घण्टा, १ दिन, १ वर्ष गर्दै लाख प्रकाश वर्ष जसको गणना हाम्रो कल्पना भन्दा बाहिर छ ।
यहाँ अर्जुन भगवानसँग भन्छन् कि म यो के देखिरहेको छु । ति सबै देवताहरू समुहका समुह भएर तपाईँमा प्रवेश गरिरहेका छन् । कोही डराएर हात जोडी तपाईँको स्तुति गरिरहेका छन्, प्रार्थना गरिरहेका छन् । महर्षि, सिद्धहरू ‘कल्याण होस्, कल्याण होस्’ भर्दै उत्तम स्तोत्रहरूले तपाईँको स्तुती गरिरहेका छन् । यस्तो अवस्थामा हामी पनि भगवान्‌को स्तोत्र पाठ गरिरहेका हुन्छौ । गीता पनि भगवान्‌को स्तोत्र नै हो ।
सर्वे भवन्तु सुखिनः सर्वे सन्तु निरामया । सर्वे भद्राणि पश्यन्तु मा कश्चित् दुःखभाग् भवेत् ।।
11.22
रुद्रादित्या वसवो ये च साध्या-
विश्वेऽश्विनौ मरुतश्चोष्मपाश्च ।
गन्धर्वयक्षासुरसिद्धसङ्घा,', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 22, 'ŚRĪ SRINIVAS WARNEKAR JI', 'https://www.youtube.com/watch?v=3mLmUl31XyU', '2026-03-14', 'जो एघार रुद्र, बाह्र आदित्य, आठ वसु, बाह्र साध्यगण, दश विश्वदेव र दुई अश्विनीकुमार, उनन्पचास मरुद्‌गण र सात पितृगणहरूको समुदाय तथा गन्धर्व, यक्ष, राक्षस र सिद्धहरूका समुदाय छन्, ती सबै आश्चर्यचकित भएर हजुरलाई नै हेरिरहेका छन् ।
रुद्र
- एकादश रुद्र,
आदित्य
- द्वादश आदित्‍य,
वसु
- अष्‍टवसु,
साध्या
- साध्यगण ।
अश्‍विनि-
दुई अश्‍विनि कुमार,
मरुत
- उनान्‍चास वायु, वायुगण,
उष्मपा
- पितृगण (३ अमुर्त, ४ मुर्त गरी ७ गण) ।
वीक्षन्ते
- हेर्दछन्,
विस्मिता
- छक्‍क परेर । अर्जुन भन्दछन्, “हे प्रभु! मैले देखिरहेको छु कि एकादश रुद्र, द्वादश आदित्य, अष्‍टवसु, साध्य गणहरू, विश्वदेव, दुबै आश्‍विनी कुमार, उनन्‍चास वायु, पितृगण साथै गन्धर्व, यक्ष, राक्षस र सिद्धहरूको समुदाय सबै छक्क परेर तपाईँलाई नै हेरिरहेका छन् । कर्मयोगको आचरणले चित्त सुद्ध हुन जान्छ । चित्त शुद्ध हुन गयो भने आफ्नै आत्मामा विश्वरूप परमात्माको दर्शन हुन्छ ।
प्रश्‍नोत्तर
प्रश्नकर्ताः-
उपेन्द्र दाजु
प्रश्नः-
कुटस्थको अर्थ भनिदिनुहोस् ।
उत्तरः-
कुटस्थ
- पर्वतको शिखर समान संसारको विषयबाट अप्रभावित । जसरी आकाशबाट परेको पानि पर्वतको शिखरमा पर्नासाथ बगेर जान्छ, त्यसरीनै इन्द्रियका विषयले जसलाई प्रभावित पार्दैनन् ।
विजितेन्द्रिय
- इन्द्रिय विजयी भन्दा पर ।
प्रश्नकर्ताः-
प‌द्मिनी दिदी
प्रश्नः
- वसुको प्रकार भनिदिनुहोस् ।
उत्तरः
-
वसु
- अग्नि । वसुका प्रकार आठ (अष्‍ठ वसु) । भीष्मपितामह आठौँ वसु थिए । वैश्वानर अग्नि खाना पचाउन हाम्रो पेटभित्र पनि छ ।
प्रश्‍नकर्ताः-
विद्यासागर दाजु
प्रश्न १-
वायु उनन्‍चास भनिन्छ, काँहा बाट आयो?
उत्तरः-
वायु ४९ प्रकारका हुन्छन्, जसलाई हामी अनुभव गर्न सक्दैनौँ । जस्तै हामीले मोबाइल‌मा सुनिने शब्दहरू धेरै टाढाबाट आउँछन् । त्‍यो शब्द सुन्न सकिन्छ तर ध्वनि प्रवाह देख्‍न सकिदैन । त्यस्तै वायुलाई पनि दख्‍न र छुट्‌याउन सकिदैन ।
प्रश्न २-
अध्याय-९ को श्लोक २१ अनुसार स्वर्गबाट खसेपछि कुन योनिमा जन्म हुन्छ ?
उत्तर:
- हामिले गर्ने हरेक कर्ममा पापपुण्यको हिसाब हुन्छ । पापपुण्य कै कारण अर्को जन्म प्राप्त हुन्छ । पुण्यको फल सुख र पापको फल दुःख हुन्छ । चित्रगुप्तको हरेक हिसाब वास्तविक हुन्छ । त्यहाँ पुण्यवाट पाप घटाएर राखिने होइन । पुण्य र पापको फल छुट्टाछुट्टै भोग्नुपर्छ । पुनः जन्म हुन्छ, पुन कर्म गर्छ, पुनः पाप र पुण्य फल प्राप्त भै रहन्छ । जुन दिन कर्म अकर्म बन्छ, कर्मफल भोगि सक्छ त्यसै दिन जीव मुक्त हुन्छ । कर्मफल बाँकी रहे जन्ममृत्युको चक्करमा परिरहन्छ ।
प्रश्नकर्ताः-
सिमा दिदी
प्रश्नः-
श्रीमद्‌को अर्थ के हो?
उत्तरः
- श्रीयुक्‍त भगवान्, भगको अर्थ-
ऐश्वर्यस्य समग्रस्य धर्मस्य यशसश्श्रियः । ज्ञानवैराग्ययोश्चैव षण्णां भग इतीरणा ।।
(विष्णु पुराण ६।५।७४)
ईश्वरीय गुण, धर्म, यश, श्री (सम्पति) भएकोले श्रीमद्भगवद्‌गीता (भगवान्‌ले गाएको गीत) भनिएको हो ।
प्रश्नकर्ताः-
ममता दिदी
प्रश्नः-
भगवान्‌ले आफ्नो रूप देखाउनु भयो कि दिव्यदृष्टिको कारणले अर्जुनलाई अनुभव भयो?
उत्तरः-
जसरी एक्सरेबाट शरिर भित्रका हड्डी देखिन्छन् त्यसरी नै यो त अनुभव गर्ने विषय हो । जब ज्ञान प्राप्त हुन्छ तब सर्वत्र भगवान् देखिन्छ र भेद दृष्टि हट्छ । यो सम्पूर्ण ब्राह्मण्ड नै परमात्माको स्वरूप हो ।
तावड महाराज काशिबाट गंगाजल लिएर रामेश्वरमा जाँदै हुनु‌हुन्थ्यो । रामेश्वर शिवलिङ्गभन्दा आलि वरै एक गधा प्यासले मर्न आटेको देखेर ॐ नमः शिवाय भनि गंगाजल गधाको मुखमा हालिदिनु भयो । अरुले उनलाई भने कहाँ शिवलिङ्गमा चढाउने जल गधालाई खुवाएको तब महाराजले भन्नुभयो मैले त यस गधामानै शिव देखेँ ।
यो विवेचन पढेर तपाईँलाई अवश्य पनि राम्रो लाग्यो होला भन्ने हामीलाई विश्वास लागेको छ । कृपया तल दिएको लिङ्क प्रयोग गरी हामीलाई आफ्नो प्रतिक्रियाहरू दिनुहोला ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (5, 1, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=QyMg-m-l-2E', '2026-03-14', 'अर्जुन भन्छन्- हे कृष्ण! हजुर कर्महरूको परित्याग गर्ने र फेरि कर्मयोगको प्रशंसा पनि गर्नुहुन्छ । अतः यी दुईमध्ये मेरालागि कुनचाहिँ उचित र निश्चितरूपमा कल्याणकारक साधन हो, त्यो मलाई बताइदिनुहोस् ।
भगवान्‌ले चतुर्थ अध्यायको अन्तमा विभिन्न यज्ञहरूको बारेमा बताउँदै अनेक सिद्धान्तहरू र धर्म जोगाउन भगवान्‌ कसरी अवतार लिएर आउनुहुन्छ भन्ने बारेमा वर्णन गर्नुभयो । त्यस्तै सृष्टि सञ्चालन प्रक्रिया र
चातुर्वर्ण
व्यवस्था स्थापना भई कार्य सञ्चालन कसरी भइरहेको हुन्छ ।
कर्म, अकर्म र विकर्म
र के हो बताउँदै अन्त्यमा
श्रद्धावाँल्लभते ज्ञानं
भन्दै ज्ञानको महिमा गाउनु भएको छ । उहाँ भन्नुहुन्छ- जसको मनमा श्रद्धा छ उसले मात्र लौकिक अध्यात्म ज्ञान प्राप्त गरी आत्मतत्वसम्म पुग्न सक्छ । त्यसैले भगवान् अर्जुनलाई जागृत होऊ र आफ्नो कर्तव्य कर्मको लागि तत्पर होऊ भन्दै हुनुहुन्छ-
तस्मादज्ञानसम्भूतं, हृत्स्थं ज्ञानासिनात्मन:
छित्त्वैनं संशयं योगम्, आतिष्ठोत्तिष्ठ भारत ।।४.४२।।
स्वामी विवेकानन्दले पनि त- उठ ,जाग, आ-आफ्नो स्वकर्ममा रमाउ र आफ्नो लक्ष्य प्राप्त गर भन्नुभएको छ । हामी सबैको गन्तव्य पनि लक्ष्यमा पुग्नु नै हो । भगवान् कहिले कर्म गर भन्नुहुन्छ, कहिले कर्म भन्दा ज्ञान श्रेष्ठ हो, ज्ञानी बन भन्नुहुन्छ । ज्ञानी बन्नलाई सबै कर्म छोडेर एकचित्त भएर लाग्नुपर्छ होइन र! भन्दै अर्जुन द्विविधामा पर्छन् । भगवान् कहिले
कर्मणाम् सन्यासम्
- कर्महरूको परित्याग गर्ने त कहिले
पुनर्योगं च शंससि
- कर्मयोगको तारिफ गर्ने गर्नुहुन्छ । त्यसैले अर्जुन
एतयो: यत् एकम्
- यी दुईमध्ये एक
तन्मे ब्रूही सुनिश्चितम्
- मेरो लागि निश्चित गरेर बताइदिनुहोस्, भन्छन् । अर्जुन
शिष्यस्तेऽहं शाधि मां त्वां प्रपन्नम्
- भगवान्‌ म हजुरको शरणमा आएको छु,मलाई शिष्य बनाउनुहोस् र मेरा लागि के श्रेयकर छ त्यो आज्ञा गर्नुहोस् भन्दै उहाँमा शरणागत हुन्छन् । हरेक व्यक्तिको श्रेय फरक हुन्छ । एकको लागि हितकारक अर्काको लागि अहितकारक हुन सक्छ । कोही बाहिरी परिश्रम ज्यादा गर्न सक्छन्, कोही अध्यात्म ज्यादा गर्न सक्छन् । सबैको क्षमता र रुचि फरक-फरक हुन्छन् । त्यसैले परमात्मासँग जोडिने योगमार्ग पनि फरक-फरक हुन सक्छ । प्रत्येक अध्यायको अन्तमा बोलिने पुष्पिकामा भने जस्तै परमात्मासँग जोडिने हुँदा यसलाई एउटा योगको संज्ञा दिएको छ । त्यसैले अर्जुन आफ्नो लागि के श्रेयस्कर छ भगवान्‌मा शरणागत हुँदै बताइदिनुहोस् भन्दछन् । अर्जुनको द्विविधामा भगवान् भन्नुहुन्छ, तिमीले कुरा सही रूपमा बुझिरहेका छैनौ तिमीलाई लाग्छ कि यी दुई बाटोहरू अलग छन् तर वास्तवमा त्यसो होइन । ज्ञानको बाटो र कर्मको बाटो अन्ततः विरोधाभासी छैनन्, बरु दुबैले एउटै सत्यतर्फ डोऱ्याउँछन् । अर्जुनको परिस्थितिले हाम्रो आफ्नै जीवनलाई प्रतिबिम्बित गर्छ । हामी प्रायः सोच्दछौँ कि आध्यात्मिक बाटो केवल ती मानिसहरूका लागि हो जसले आफ्नो घर व्यवहार सबै छोड्छन् । तर त्यसो होइन, उनीहरू सबैलेले न घर व्यवहार छोड्छन् न त सक्छन् नै । हाम्रो जीवन एकपछि अर्को कर्तव्यहरूले पछ्याई रहेको हुन्छ । हामी जीवनको जुनसुकै चरणमा भए पनि, हाम्रा जिम्मेवारीहरू कहिल्यै समाप्त हुँदैनन् । पहिला मातापिताको हेरविचार, छोराछोरीको पालनपोषण, पढाइ लेखाई र विवाहको जिम्मेवारी हुन्छ । त्यसपछि नातिनातिनाहरूप्रति कर्तव्यको भावना आउँछ । यसरी, जीवनको हरेक चरणमा निरन्तर नयाँ कर्तव्यहरू उत्पन्न हुन्छन् ।
यस्तो अवस्थामा हाम्रो मनमा स्वाभाविक रूपमा प्रश्नहरू उठ्न सक्छन् कि कर्तव्यहरू गर्दै ज्ञान प्राप्त गर्ने पनि उपायहरू के होलान्? यस सन्दर्भमा ज्ञानेश्वर महाराज एउटा सुन्दर उदाहरण दिनुहुन्छ -
काका अपुला ठाव न सांडिता, आलिंगी जे चंद्र प्रकटता।
हा अनुरागु भोगिता, कमलिनी जाणे॥
अपुला ठाव न सांडिता, आलिंगी जे चंद्र प्रकटता।
हा अनुरागु भोगिता, कमलिनी जाणे॥
जसरी कमलले चन्द्रमा उदाउँदा आफ्नो स्थान नछोडिकन चन्द्रमाको प्रकाशको आनन्द लिन्छ, त्यसरी नै, मानिसहरूले आफ्नो स्थानमा रहँदा र आफ्नो कर्तव्यहरू पूरा गर्दै भगवत्‌ तत्त्वको अनुभव गर्न सक्छन् ।
भगवद्गीता एक अतुलनीय मार्ग हो जसले हामीलाई आफ्नो स्थान नछोडिकन परमात्मासँग जोडिने बाटो देखाउँछ । यसले हामीलाई दैनिक जीवन यापन गर्दै, हामी अध्यात्ममा जोडिन सक्छौँ र आफ्ना हृदयमा उहाँको साँचो, आनन्दमय स्वरूपको आनन्द अनुभव गर्न सक्छौँ भनेर मार्ग निर्देश गर्छ ।
भगवान् अर्जुनलाई उनले आफूले भनेको कुरा बुझ्नु भन्दा आफ्नै अनुमानहरू लगाएर छट्पटाइरहेका छौ भन्नुहुन्छ । हाम्रो जीवनमा यस्ता घटना धेरै पटक हुन्छन् । एक व्यक्तिले प्रश्न सोध्छ, तर भित्री रूपमा, उत्तर पहिले नै पूर्व-निर्धारित हुन्छ । ऊ चाहन्छ कि अर्को व्यक्तिले पनि उसको मनमा भएकै उत्तर देओस् ।
अर्जुनको अवस्था पनि त्यस्तै छ । भित्री रूपमा, अर्जुन युद्ध त्याग्न चाहन्छन् । पहिलो अध्यायमा, हामी अर्जुनले युद्ध नगर्न धेरै तर्क र कारणहरू प्रस्तुत गरेको देख्छौँ । उनी बारम्बार युद्ध त्याग्नु सही काम हो भनेर प्रमाणित गर्ने प्रयास गर्छन् । वास्तविकतामा, यो सबै उनको भित्री द्वन्द्व र भ्रमको प्रतिविम्ब हो । यदि उनले युद्ध नलडेको भए पनि, त्यहाँ के भयो होला भनि त्यसैको परिणामको चिन्तामा जलिरहेका हुन्थे । यस्ता परिस्थितिहरू सबैको जीवनमा धेरै पटक हुन्छन्, र प्रत्येक क्षणमा, हाम्रो बुद्धिले हामीलाई हाम्रो कर्तव्यको सम्झना गराउँछ ।
भगवान् अर्जुनलाई भन्नुहुन्छ, “तिमीलाई कर्मयोग र ज्ञानयोग फरक-फरक मार्ग हुन् लाग्छ, तर वास्तवमा ती होइनन् । प्रत्येक व्यक्तिको स्वभाव फरक हुन्छ- कोही बढी विचार-उन्मुख हुन्छन्, कोही बढी कार्य-उन्मुख हुन्छन्” । त्यसैले, ज्ञानयोग कसैको लागि उपयुक्त हुन्छ र कसैको लागि कर्मयोग बढी उपयोगी हुन्छ । कर्मयोगको सार भनेकै कर्म गर्दैगर्दा पनि ती कर्महरू भगवान्‌प्रति समर्पणको भावले गर्नु हो । व्यक्तिले आफ्ना कर्महरू भगवान्‌मा समर्पित गरेर गर्‍यो भने त्यो कर्मयोग बन्छ ।
जब हामी औषधि लिन फार्मेसी जान्छौँ । धेरै औषधिहरूमध्ये डाक्टरले जुन औषधिको नाम पुर्जीमा लेख्छन् त्यही औषधि लिएर आउछौँ । आफ्नो मन खुसीले जुन पायो त्यही औषधि लिँदैनौँ किनकि डाक्टरले हाम्रो हितअनुसार औषधि लेखेका हुन्छन् । त्यसरी हाम्रो जीवनमा हाम्रो लागि के हितकारक छ आफूभन्दा ठूला, मातापिता, गुरुजनहरूसँग सल्लाह लिएर गर्छौँ । अर्जुन भगवान्‌बाट त्यही आशा गरिरहेका छन् ।
यस सन्दर्भमा एउटा उदाहरण-
एक पटक, देवता, दानव र मानव सबै जना ब्रह्माकहाँ गएछन् र बिन्ती गरेछन्, “प्रभु, हामीलाई हाम्रो जीवनको कल्याणको लागि केही सल्लाह दिनुहोस्” । ब्रह्मा सम्पूर्ण ब्रह्माण्डका सृष्टिकर्ता सबैलाई समान दृष्टिले हेर्ने हुँदा, तीनैजनालाई एउटा मात्र अक्षर “द” दिनुभयो । ब्रह्माजीले के भन्न खोज्नुभएको कसैले केही बुझेनन् । त्यसपछि उहाँले व्याख्या गर्नुभयो-
मानिसहरूको लागि, “द” को अर्थ दान हो, जसको अर्थ अरूलाई मद्दत गर्नु हो ।
दानवहरूको लागि, “द” को अर्थ दया हो, किनभने उनीहरूमा कठोरता र हिंसा बढी हुन्छ, दयाको भावना जगाउन पर्छ ।
देवताहरूको लागि, “द” को अर्थ दमन हो, जसको अर्थ आफ्ना इन्द्रियहरू र इच्छाहरूमाथि नियन्त्रण राख्नु हो किनकि उनीहरू समृद्ध र सबै सुविधाले सम्पन्न छन् ।
जसरी “द” एउटा अक्षर भएपनि व्यक्तिपिच्छे यसको अर्थ फरक भयो । त्यसरी नै, आध्यात्मिक मार्गमा हाम्रा विचारहरू, रुचिहरू स्वभावअनुसार फरक हुन सक्छन् । हामीले सही मार्ग पछ्याउन सक्नुपर्छ । भगवान्‌ले देखाउनुभएका अलगअलग मार्गहरूमा द्विविधा हुँदै अर्जुन भगवान्‌संग मार्ग देखाउनुहोस् भनि बिन्ती गर्छन् ।
5.2
श्रीभगवानुवाच
सन्न्यासः(ख्) कर्मयोगश्च, निःश्रेयसकरावुभौ ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (5, 2, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=QyMg-m-l-2E', '2026-03-14', 'श्रीभगवान् भन्नुहुन्छ- कर्मसन्यास र कर्मयोग- यी दुवै कल्याणकारक छन् तर यी दुईमध्ये पनि कर्मसन्यासभन्दा कर्मयोग साधना नै बढी सुगम र श्रेष्ठ छ ।
भगवान्‌ भन्नुहुन्छ, “हे अर्जुन! तिमीले बुझिरहेका छैनौ, चाहे कर्मयोग होस् वा ज्ञानयोग- कुनै पनि योगका लागि अन्तःकरणको नि:संगता (आसक्तिरहित हुनु) आवश्यक छ ।
सन्यासःकर्मयोगश्च
- सन्यास (कर्म छोड्नु) र कर्मयोग (कर्म गर्नु) । यहाँ सन्यासको अर्थ सम्यक न्यास हो जसले त्याग गर्नु वा कर्मलाई त्याग्नु भन्ने बुझउँछ । कर्मयोग अर्थात् कर्म गर्दागर्दै भित्रैबाट परमात्मा प्रतिको भावलाई जागृत राख्नु, म उहाँकै लागि कर्म गर्दैछु र कर्मका माध्यमबाट परमात्मासँग जोडिन्छु भन्ने भावना राख्नु पनि सन्यास नै हो । सन्यास र कर्मयोग दुवै मानिसको कल्याण गर्ने मार्ग हुन् ।
अभ्युदय र निश्रेयस-
अभ्युदय भनेको हाम्रो भौतिक उन्नति र प्रगति हो, भने निश्रेयस भनेको आत्मिक शान्ति, आत्मज्ञान र अन्तिम कल्याण हो । यो धर्ममा सवार भएर मानिसले भौतिक प्रगति पनि प्राप्त गरोस् र अन्तिम कल्याण अर्थात् आत्मिक शान्ति पनि पाओस् । मानिस भौतिक प्रगतिको मात्र पछि लाग्दा अन्ततः ऊ अशान्त हुन पुग्छ । त्यसैले धर्मको व्याख्या यसरी गरिएको छ-
यतोऽभ्युदयनि:श्रेयससिद्धि: स धर्म:
।
सन्यास र कर्मयोग दुवैले मानव जीवनको अन्तिम गन्तव्य वा अन्तिम कल्याणसम्म पुर्‍याउँछ । तर
तयोस्तु कर्मसंन्यासात्कर्मयोगो विशिष्यते
- यहाँ दुवैमध्ये पूर्णरूपमा कर्म त्याग्नुभन्दा कर्मयोग नै बढी श्रेयस्कर छ । तेस्रो अध्यायमा भनिएको छ-
नियतं कुरु कर्म त्वं कर्म ज्यायो ह्यकर्मणः
आफ्नो निर्धारित कर्म गर, किनकि कर्म त्याग्यौ भने शरीरको यात्रा (जीवन निर्वाह) पनि चल्ने छैन । श्वास फेर्नु, सुन्नु, देख्नु, बस्नु-यी सबै नै कर्म हुन् । त्यसैले मानव शरीरमा रहुन्जेल केही न केही कर्म गरिरहनु पर्छ ।
हामीले आफ्नो साधनको सुगमता र क्षमता अनुसार मार्ग चयन गर्नुपर्छ । जस्तै, कसैलाई दिल्ली जानु छ भने उसले आफ्नो क्षमता अनुसार साधन रोज्छ र ऊ पैदल, बस, रेल वा जहाजबाट जान सक्छ । यस विषयमा ज्ञानेश्वर महाराज भन्नुहुन्छ- मार्ग दुईवटा देखिए पनि अन्त्यमा ती एउटै हुन् । जस्तै-
सिद्ध-भोजन
र
साध्य-भोजन
।
ज्ञानयोग सिद्ध
-भोजन(पकाएको) जस्तै हो भने कर्मयोग साध्य-भोजन(कच्चा अन्नबाट पकाउनु पर्ने) जस्तै हो । जसको थालमा सिद्ध-भोजन पस्किएको छ, उसले पहिले कर्मयोगको मार्गबाटै त्यसलाई साध्य गरेको हुन्छ । कर्मयोगको अनुसरण गरेर नै मानिस ज्ञान मार्गमा पुग्छ ।
5.3
ज्ञेयः(स्) स नित्यसन्न्यासी, यो न द्वेष्टि न काङ्क्षति ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (5, 3, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=QyMg-m-l-2E', '2026-03-14', 'हे महाबाहो! जुन पुरुषले न कसैसित द्वेष गर्दछ र न कसैको अभिलाषा नै राख्दछ; त्यस्तो कर्मयोगी नित्य सन्यासी नै मान्न योग्य हुन्छ किनकि रागद्वेषादि द्वन्द्वहरूले रहित पुरुष सुखपूर्वक सांसारिक बन्धनबाट मुक्त हुन्छ ।
भगवान् भन्नुहुन्छ- त्याग्नु नै सन्यास हो अर्थात् सम्यक् न्यास हो ।
ज्ञेयः स नित्यसंन्यासी यो न द्वेष्टि न काङ्क्षति
- यो अन्तःकरणको कुरा हो । केवल वस्त्र परिवर्तन गरेर सन्यास हुँदैन । यो गेरुवा वस्त्र लगाउने, टीका लगाउने, गलामा रुद्राक्षको माला भिर्ने वा घरबार छोड्ने कुरा मात्र सन्यास होइन । सन्यासीपन आन्तरिक वृत्तिमा भर पर्छ ।
यो न द्वेष्टि
- जसले कसैको द्वेष गर्दैन र कोही आफूभन्दा अगाडि बढ्यो भने पनि उसको मनमा मत्सर(डाह) पनि हुँदैन । मत्सर ‘मभन्दा अगाडि नजाओस्’ भन्ने भावले पैदा हुने डाहयुक्त विकार हो ।
न काङ्क्षति
- आफ्नो लागि कुनै आकांक्षा राख्दैन । यसर्थ अरुको प्रगतिमा डाह नगर्ने र आफ्नो लागि कुनै आकांक्षा नराख्ने व्यक्ति नै नित्य सन्यासी हो ।
यहाँ
नित्य सन्यास
- शब्द निकै महत्वपूर्ण छ । एउटा हुन्छ क्षणिक वैराग्य, जसलाई हामी श्मशान वैराग्य- भन्छौँ जहाँ केही बेरका लागि ‘मलाई केही चाहिँदैन’ भन्ने लाग्छ । तर मानिसको मन यस्तो हुन्छ कि केही समयपछि पुनः ‘मलाई यो चाहियो, त्यो चाहियो’ भन्ने वृत्तिहरू जाग्न थाल्छन् । नित्य सन्यासमा एकपटक हटेको आकाङ्क्षा फेरि फर्किँदैन । एउटा उदाहरण- हामी जब कुनै काँचो फल हाँगाबाट चुँडाल्छौँ, तब भेट्नोबाट एउटा चोप (रस) निस्किन्छ जसले हाँगा र फल दुवैलाई टाँसिरहेको हुन्छ । त्यो चोप संसारको आसक्ति हो । जबर्जस्ती टिपिएको फलमा त्यो चोप टाँसिएको हुन्छ । तर जब फल पाक्छ (परिपक्व हुन्छ), तब त्यो आफैँ झर्छ । न त्यो हाँगामा टाँसिन्छ, न फलमा कुनै चोप रहन्छ । त्यसैगरी अन्तःकरणबाट परिपक्व भएर आकाङ्क्षा छुट्नु नै नित्य सन्यास हो ।
नित्य सन्यासीको अन्तःकरणको अवस्था निर्द्वन्द्व- हुन्छ । द्वन्द्व भनेको हाम्रो मनमा उठ्ने विपरीत विचारहरू हुन्- गरूँ कि नगरूँ?, यो गरूँ कि त्यो गरूँ? मेरो-तेरो, लाभ-हानि, यश-अपयश, मान-अपमान आदि सबै मनका द्वन्द्व हुन् । तर नित्य सन्यासी यी सबैभन्दा माथि निर्द्वन्द्व हुन्छ । ऊ राग र द्वेषबाट मुक्त हुन्छ । आफ्नो अनुकूल हुँदा राग (आसक्ति) र प्रतिकूल हुँदा द्वेष गर्ने वृत्तिबाट ऊ टाढा हुन्छ ।
हामीले भगवान्‌ले वर्णन गर्नुभएको सन्यासीको अन्तःकरण र हाम्रो अन्तःकरण बीचको भिन्नता बुझ्न सक्यौँ भने मात्र हामी शुद्धतातर्फ अघि बढ्न सक्छौँ । यस्तो निर्द्वन्द्व सन्यासी संसारका सारा बन्धनबाट सजिलै मुक्त हुन्छ । उसले बन्धन तोडेर जानु पर्दैन, ऊ भित्रैबाट मुक्त भइसकेको हुन्छ ।
हाम्रा कर्मका तीनवटा बन्धन छन्-
कर्तृत्व
- मैले गरेँ भन्ने अहंकार,
भोक्तृत्व
- म फल भोग्न चाहन्छु भन्ने इच्छा, र
कर्मासक्ति
- मलाई मनपर्ने कर्म मात्र गर्छु भन्ने जिद्दी । नित्य सन्यासी यी तीनै बन्धनबाट मुक्त हुन्छ । ऊ अत्यन्त सुखपूर्वक मुक्त हुन्छ, जसरी पाकेको फल आफैँ झर्छ ।
तिमी अझै यिनै कुरामा अल्झिएका छौ । त्यसैले तिम्रोलागि युद्ध गर्नु अनिवार्य छ, तर तिमीले आफ्नो अन्तःकरणको भावना बदल्नुपर्छ । संसारका सबै काम गर्दा ‘म परमात्माको काम गर्दैछु’ भन्ने भाव राख्नुपर्छ । ‘यो घर मेरो होइन उहाँको हो, यो परिवार मेरो होइन उहाँको हो, म मेरो होइन उहाँको हो’ भन्ने वृत्ति जब परिपक्व हुन्छ, तब तिमी आफैँ बन्धनबाट छुट्नेछौ । अहिले त तिमी ‘यी मेरा हुन्, मेरा आफन्त हुन्, पितामह भीष्म हुन्, गुरु द्रोण हुन्’ भन्ने मोहमा अल्झिएका छौ ।
ज्ञानेश्वर महाराजले यस नित्य सन्यासको बारेमा यसरी व्याख्या गर्नुभएको छ:
मी माझ याची आठवण,
विसरले जयाचे अंतकरण।
पार्थ तो सन्यासी जाण, निरंतर ॥
जसको अन्तःकरणले म र मेरो भन्ने सम्झना नै बिर्सियो, उही नै वास्तविक र निरन्तर सन्यासी हो । ऊ बाहिरबाट कर्म गरिरहेको देखिन्छ, तर उसको अन्तःकरणमा कर्मको कुनै लेप लाग्दैन । ऊ यो संसार परमात्माको हो भन्ने स्मृतिमा रहन्छ र आफूलाई एउटा सानो पानीको फोका जस्तै ठान्छ । हामी कसैलाई केही वस्तु दान दिँदा पनि बिर्सन सक्दैनौँ । कुनै महिलाले अर्की महिलालाई साडी उपहार दिइन् भने पछि सोध्छिन्- “त्यो साडी लगायौ ?” जुन साडी अझै उनको मनबाट हटेको हुँदैन । तर ‘यो संसार मेरो हो’ भन्ने भाव नै भुल्नु पर्छ । गंगामा पैसा चढाएपछि त्यो कसले पायो वा त्यसको के भयो? भन्ने कुरा मनमा रहनु हुँदैन । नर्मदे हर- भन्नुको अर्थ पनि मेरो अहंकार हरण गरिदेऊ भन्ने नै हो । अर्जुन! तिमीले विद्वानका जस्ता कुरा त धेरै गर्यौ, तर अझैसम्म ज्ञानको त्यो उचाइ प्राप्त गर्न सकेका छैनौ ।
5.4
साङ्ख्ययोगौ पृथग्बालाः(फ्), प्रवदन्ति न पण्डिताः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (5, 4, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=QyMg-m-l-2E', '2026-03-14', 'साङ्ख्ययोग र कर्मयोगलाई मुर्खहरूले अलग-अलग फल दिने भन्दछन्, तर पण्डितहरू यस्तो मान्दैनन्; किनकि यी दुईमध्ये एउटैमा पनि सम्यक् प्रकारले स्थित पुरुषले दुवैको फलरूपी परमात्मालाई नै प्राप्‍त गर्दछ ।
भगवान भन्नुहुन्छ, “हे अर्जुन!
साङ्ख्ययोगौ पृथग्बालाः प्रवदन्ति न पण्डिताः
।
बालाः -
जसको मन सानो छ वा बाल बुद्धि भएका, जसको बुद्धि विकसित भएको छैन, उनीहरू साङ्ख्य र योग (ज्ञानयोग र कर्मयोग) लाई फरक-फरक ठान्छन् । साङ्ख्य शब्दको अर्थ ज्ञानयोग हो । कपिलमुनिले बताइएका तत्त्वहरूको गहिराइमा हामी अहिले नजाऔँ । यसमा प्रकृति र पुरुष-अर्थात् जड र चेतन-यी दुईको संयोगबाट सारा कार्य चल्छ भन्ने मानिन्छ । हाम्रो विज्ञानले पनि यसलाई स्वीकार गर्छ- E=mc‌2, जहाँ शक्ति (Energy) र पदार्थ (Matter) को सम्बन्ध देखाइएको छ । यसले स्थूल र सूक्ष्म, दुवै मिलेर सृष्टि चल्छ भन्ने साङ्ख्य दर्शनमा रहेको ज्ञानयोगको कुरा हो ।
जब कुनै व्यक्ति शान्त हुन्छ (मृत्यु हुन्छ), उसको चैतन्य हराउँछ । हामी भन्छौँ- उहाँ अब रहनुभएन तर शरीर त त्यहीँ हुन्छ । यहाँ ‘उहाँ हुनुहुन्न’को अर्थ- उहाँभित्रको चैतन्य तत्व नै उहाँको वास्तविक रूप थियो अब त्यो छैन भन्ने हो । यसरी बुद्धिले तर्क गर्दै स्थूल शरीरबाट सूक्ष्म तत्वसम्म पुग्नु नै साङ्ख्य योग वा ज्ञानयोग हो । बाल-बुद्धि भएकाहरूले मात्र ज्ञानयोग र कर्मयोगलाई अलग ठान्छन्, पण्डितहरूले होइन ।
एकमप्यास्थितः सम्यगुभयोर्विन्दते फलम्
- जसले एउटै मार्गमा पनि राम्रोसँग पाइला टेक्यो र त्यसमा स्थिर भयो भने उसले दुवैको फल प्राप्त गर्छ । कर्मयोगको सिँढीबाट नै ज्ञानको उदय हुन्छ । जो आज ज्ञानयोगको उचाइमा पुगेका छन्, उनीहरूले पहिले आफ्नो जीवनमा कर्मयोगकै आचरण गरेका थिए ।
न हि ज्ञानेन सदृशं पवित्रमिह विद्यते
- ज्ञान समान पवित्र वस्तु यो संसारमा अरू केही छैन । कसैले हामीलाई हाम्रो सही पहिचान गराउँछ भने त्यो नै सर्वोपरि ज्ञान हो । भगवानले १३औँ अध्यायमा पनि भन्नुभएको छ कि
अध्यात्मज्ञान नित्यत्वम्
- आफ्नो वास्तविक पहिचान पाउनु नै ज्ञान हो । जर्मनीका प्रसिद्ध दार्शनिक इमानुएल कान्ट (Immanuel Kant) एक पटक सडकमा हिँड्दै सोच्दै थिए- “म को हुँ? के म यो शरीर हुँ? यदि म शरीर हुँ भने, यी मेरा आँखा हुन्, यी मेरा कान हुन्, यी मेरा हात-खुट्टा हुन् भनेर भन्ने ‘म’ चाहिँ को हो? र बाल्यावस्था, युवावस्था र वृद्धावस्थालाई साक्षी भावले हेर्ने भित्रको त्यो तत्त्व को हो?” यसरी गहिरो चिन्तनमा डुबेर हिँडिरहँदा उनले बाटोमा कसैलाई ठक्कर दिए । ठक्कर खाने व्यक्ति रिसायो र उनको हात समातेर भन्यो, “को होस् तँ? किन बाटो नहेरी हिँडेको?” कान्टले तुरुन्तै उसका दुवै हात समाते र भने, “मित्र! म को हुँ भन्ने कुरा नै त म अहिलेसम्म खोजिरहेको छु । के तपाईं मलाई बताउन सक्नुहुन्छ कि म को हुँ?” जसले यसरी आफ्नो खोजी गर्छ, उही ज्ञान मार्गमा पुग्छ । तर यसका लागि पहिले कर्मयोग गर्नुपर्छ ।
तत्स्वयं योगसंसिद्धः कालेनात्मनि विन्दति
- कर्मयोगको अनुसरण गरेपछि मात्र सही समयमा परमात्मासँग योग (मिलन) हुन्छ । जब हामी ईश्वरार्पण बुद्धिले कर्म गर्छौँ, तब हामी उहाँलाई निरन्तर सम्झिरहन्छौँ । जसलाई हामी सधैँ सम्झन्छौँ र जससँग हाम्रो मन एकाकार हुन्छ, हामी उसैको रहस्य बुझ्न थाल्छौँ । जस्तै- परिवारको कुनै सदस्यसँग हामी जति नजिक रहन्छौँ, उसको स्वभाव र मन उति नै राम्ररी चिन्छौँ । नियम यही हो- हामी परमात्मासँग जति नजिक रहन्छौँ, उति नै उहाँलाई चिन्छौँ र उहाँलाई चिन्नु नै आफूलाई चिन्नु हो, किनकि उहाँ नै हामीभित्र प्रतिविम्बको रूपमा हुनुहुन्छ । त्यसैले पण्डितहरू यी दुई मार्गलाई अलग मान्दैनन् । उनीहरूलाई थाहा छ कि कर्मयोगकै जगमा ज्ञानको महल खडा हुन्छ ।
संसारमा चार प्रकारका मानिस हुन्छन्:
जसलाई कर्म गर्नु पर्छ, तर पनि गर्दैन ।
जसलाई कर्म गर्न पर्छ र गरिरहेका पनि छन् ।
जसलाई अब कर्म गर्न आवश्यक छैन, त्यसैले गर्दैनन् ।
जसलाई कर्म गर्न कुनै आवश्यकता छैन, तैपनि गरिरहेका छन् ।
हाम्रा ज्ञानी महापुरुषहरू ज्ञानको चरम उचाइमा पुगेर पनि कर्मठ देखिन्छन् । उनीहरूलाई आफ्नो लागि केही गर्नु छैन, तैपनि सारा सृष्टिको कल्याणका लागि उनीहरू निरन्तर कर्म गरिरहन्छन् ।
5.5
यत्साङ्ख्यैः(फ्) प्राप्यते स्थानं(न्), तद्योगैरपि गम्यते ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (5, 5, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=QyMg-m-l-2E', '2026-03-14', 'साङ्ख्ययोगीहरूद्वारा जुन परमधाम प्राप्‍त गर्ने काम गरिन्छ, कर्मयोगीहरूद्वारा पनि त्यही धाम प्राप्‍त गर्ने काम गरिन्छ । यसर्थ, जुन पुरुषले साङ्ख्ययोग र कर्मयोगलाई फलरूपमा समान देख्दछ, उसैले यथार्थ (वास्तविक तत्त्व) देख्दछ ।
भगवान्‌ भन्नुहुन्छ- जुन स्थान ज्ञानको मार्गमा चल्ने ज्ञानीले प्राप्त गर्दछ, त्यही स्थान कर्मयोगको अनुसरण गर्ने व्यक्तिले पनि प्राप्त गर्दछ । सांख्य योग र कर्म योग हेर्दा दुईवटा मार्ग जस्ता देखिन्छन्, तर वास्तवमा यी दुवै एकै हुन् । जसरी एउटा सिँढी चढ्दै जाँदा अर्को तहमा पुगिन्छ, त्यसरी नै कर्मयोगको सिँढी चढ्दै जाँदा नै ज्ञानयोग प्राप्त हुन्छ । जसले यी दुवैलाई एकै देख्छ, उसले मात्र यथार्थलाई देख्छ ।
सामान्य आँखाले देख्नु मात्र हेर्नु होइन; जसरी माइक्रोस्कोपबाट हेरेर वस्तुको गहिराइ बुझिन्छ, त्यसरी नै वास्तविक द्रष्टाले यी दुवै मार्गको एकतालाई बुझ्दछ । यही कर्मयोगको जगबाट नै ज्ञानको उदय हुन्छ । गुरुदेवले भगवद्‌गीताको व्याख्या गर्दै भन्नुभएको छ-
ज्ञानाधिष्ठित सत्कर्मशील भक्तिमय दिव्य जीवन योग
। ज्ञानको आधारमा रहेर, असल कर्म गर्दै र परमात्माप्रति प्रेम (भक्ति) राख्दै जुन योग प्राप्त हुन्छ, त्यही दिव्य जीवन योग भगवद्‌गीताले हाम्रा लागि प्रवाहित गरेको छ । भगवान्‌ले भन्नुभएको छ- दुवै मार्गबाट एउटै गन्तव्य प्राप्त हुन्छ । कसैलाई दिल्ली पुग्नु छ भने ऊ चाहे रेलबाट जाओस्, सडकबाट जाओस्, बस वा जहाजबाट ढिलो चाँडो ऊ त्यहीँ पुग्छ । तर कर्मलाई नत्यागी वा कर्मलाई कर्मयोगमा नबदली सिधै संन्यास लिनु (काम छोड्नु) दुःखको कारण बन्न सक्छ ।
5.6
सन्न्यासस्तु महाबाहो, दुःखमाप्तुमयोगतः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (5, 6, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=QyMg-m-l-2E', '2026-03-14', 'परन्तु हे महाबाहो! कर्मयोगविना सन्यास अर्थात् मन, इन्द्रिय र शरीरद्वारा हुने सम्पूर्ण कर्महरूमा कर्तापनको त्याग गर्न मुस्किल पर्दछ, तर भगवत्स्वरूपलाई मनन गर्ने कर्मयोगीले भने परब्रह्म परमात्मालाई शीघ्र नै प्राप्‍त गर्दछ ।
भगवान् भन्नुहुन्छ – अब मलाई यो संसारदेखि वैराग्य जाग्यो,
श्मशान वैराग्य
- क्षणभरको वैराग्य आयो र केही चाहिँदैन भन्दै घरबार छोडियो, तर अन्तरआत्मादेखि परमात्मासँग जोडिएन वा कर्मयोग गरिएन भने, त्यो जीवनमा दुःखको कारण बन्छ ।
सुखं बन्धात् प्रमुच्यते
- सन्यास सुखदायक हुनुपर्छ, यसमा दुःख हुनुहुँदैन । कर्मयोग नगरीकन लिएको सन्यास अयोगतः सन्यासः हो जुन दुःखदायक हुन्छ । आफ्ना कर्महरू परमात्मालाई अर्पण नगरी, कर्मलाई कर्मयोगमा परिणत गर्ने कुरा नबुझी वा त्यसको अनुभूति नलिई जसले शरीर, इन्द्रिय र मनका कर्महरू जबरजस्ती छोडिदिन्छ, उसको लागि त्यो सन्यास निकै कठिन छ । पहिले कर्मलाई नै कर्मयोग बनाउनुपर्छ, त्यसपछि मात्र सन्यास लिंदा हुन्छ । सन्यास आफैँ घटित हुनुपर्छ, जसले अन्तरात्मालाई स्वतः मुक्त गरिदेओस ।
योगयुक्तो मुनिर्ब्रह्म नचिरेणाधिगच्छति
- जसले अन्तर हृदयदेखि चिन्तन गरेको छ, जसले यन्त्रवत् साधन नगरी मनन गर्दै आफ्ना कर्मलाई कर्मयोगमा परिणत गरेको छ र परमात्मासँग कर्मलाई जोडेको छ, त्यस्तो
योगयुक्त व्यक्तिले नचिरेण
- निकै चाँडो ब्रह्म प्राप्त गर्दछ । ब्रह्म शब्दको अर्थ हो- यो सम्पूर्ण सृष्टिलाई सञ्चालन गर्ने शक्ति, जो हामीभित्र पनि छ ।
यत् पिण्डे तत् ब्रह्माण्डे
- जे शरीरमा छ, त्यही ब्रह्माण्डमा छ । त्यो शक्ति हामीभित्र कसरी कार्यरत छ र ऊसँग हाम्रो सम्बन्ध के छ भन्ने सिक्दैछौँ । जो योगयुक्त छ, उसले तुरुन्तै त्यो परब्रह्म परमात्मालाई प्राप्त गर्दछ । यो कुरा हामीले बुझ्न पर्छ ।
ज्ञानेश्वर महाराज भन्नुहुन्छ- हामी केही कुरा छोड्ने कुरा गर्छौँ, तर छोड्नका लागि पहिले त्यो कुरा हामीसँग हुनु त पर्यो नि ! एकपटक एक भिखारी स्वामी विवेकानन्दकहाँ गएर भन्यो- स्वामीजी, तपाईंले गेरुवा वस्त्र लगाउनुभयो, म पनि लगाउन चाहन्छु र संसार त्याग्न चाहन्छु । स्वामीजीले भन्नुभयो- तिमी के छोड्न चाहन्छौ ? तिम्रो गोजीमा एउटा फुटेको कौडी पनि छैन । तिमीले न कुनै उच्च शिक्षा पायौ, न कुनै विद्या । तिमीसँग छोड्नका लागि के छ ? कसैले भन्यो- मैले ताजमहल त्याग गरिदिएँ । के त्यो तिम्रो थियो र ? हामी त्यही कुरा मात्र त्याग गर्न सक्छौँ, जुन हामीसँग छ । त्यसैले केही त्याग गर्नु छ भने पहिले त्यसलाई प्राप्त पनि गर्नुपर्छ । जब प्राप्त गरिन्छ, तब मात्र त्याग गर्न सकिन्छ ।
त्यसैले यो अत्यन्तै महत्त्वपूर्ण कुरा हो कि कर्मयोगको सिँढीबाट नै ज्ञानयोगको प्राप्ति हुन्छ । पहिले कर्म गरेर
अभ्युदय
- सांसारिक उन्नति प्राप्त गर्ने र त्यसपछि मात्र
निश्रेयस
- मोक्ष प्राप्त हुनेछ, जब हामी कर्मलाई परमात्मामा अर्पण गर्छौँ तबमत्र ज्ञानको उदय हुन्छ ।
5.7
योगयुक्‍तो विशुद्धात्मा, विजितात्मा जितेन्द्रियः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (5, 7, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=QyMg-m-l-2E', '2026-03-14', 'जसको इन्द्रियहरू आफ्ना वशमा छन्, जसको अन्तःकरण निर्मल छ, जो जितेन्द्रिय छ र सम्पूर्ण प्राणीहरूको आत्मारूपी परमात्मा नै जसको आत्मा छ, त्यस्तो कर्मयोगी पुरुष कर्म गरिरहँदा पनि कर्ममा लिप्‍त हुँदैन ।
भगवान् भन्नुहुन्छ- योगयुक्त व्यक्तिको अन्तःकरण सबै बन्धन र विकारहरूबाट मुक्त हुन्छ । यसका लागि उहाँले चारवटा लक्षणहरू बताउनुभएको छ: विशुद्धात्मा, विजितात्मा, जितेन्द्रिय र सर्वभूतात्मभूतात्मा ।
कुर्वन्नपि न लिप्यते- यस्तो योगयुक्त व्यक्तिले कर्म गर्दागर्दै पनि ऊ त्यसमा लिप्त हुँदैन । उसले कर्म त गरिरहेको हुन्छ, तर उसमा ‘म गर्दैछु’ भन्ने कर्तृत्वको भावना, फलको इच्छा वा कर्मप्रतिको आसक्ति- यी तीनै प्रकारका बन्धनका लेपहरू हुँदैनन् ।
विशुद्धात्मा-
जसको अन्तःकरण अत्यन्त शुद्ध भएको छ । मन, बुद्धि, चित्त र अहंकार- यी चारै कुरामा कुनै लौकिक अभिलाषा वा स्वार्थको वृत्ति बाँकी छैन । जसले आफ्नो सम्पूर्ण अन्तःकरण परमात्मामा समर्पित गरिदिएको छ, ऊ नै विशुद्धात्मा हो ।
विजितात्मा-
जसले आफ्नो अन्तःकरणमाथि पूर्ण विजय प्राप्त गरेको छ र जसको मन आफ्नै नियन्त्रणमा छ ।
जितेन्द्रिय-
जसले आफ्ना सबै इन्द्रियहरूलाई वशमा पारेको छ । उसका आँखाहरूले त्यही देख्छन् जो देख्नुपर्ने हो र कानले त्यही सुन्छन् जो सुन्नु उचित छ । उसले आफ्नो मन, परब्रह्म तत्वको निर्देशन अनुसार मात्र इन्द्रियका विषयहरू ग्रहण गर्छ ।
सर्वभूतात्मभूतात्मा
- जसले आफू भित्रको चैतन्यलाई अनुभूति गर्छ र यो पनि बुझ्छ कि मेरो अन्तःकरणमा जुन चैतन्य तत्व छ, त्यही सबैमा छ । आफु भित्रको राम र अरु भित्रको राम दुवै एउटै हुन् भन्ने कुरा जसको अनुभवमा छ, ऊ नै सर्वभूतात्मभूतात्मा हो ।
यो केवल शब्दको ज्ञान (परोक्ष ज्ञान) होइन, बरु अनुभवको ज्ञान (अपरोक्ष ज्ञान) हो । जसरी एक्सरे वा एमआरआईले शरीरभित्रको कुरा देखाउँछ, अध्यात्मको यो ‘सुपर एक्सरे’ ले अरूको मन, बुद्धि र अहंकारका विकारहरूलाई छेडेर सिधै उसको आत्मतत्वसम्म पुग्छ । जब हामी गुरुको सामिप्यमा पुग्छौँ, उहाँहरूले हामीलाई केही क्षणका लागि त्यो अनुभूतिको झलक दिनुहुन्छ, किनकि उहाँहरू सबैको अन्तरात्मासँग जोडिनुभएको हुन्छ । हामी मुखले त भन्छौँ, तर व्यवहारमा उतार्न सक्दैनौँ । जब एकनाथ महाराज काशीबाट गङ्गाजल लिएर रामेश्वरम जाँदै हुनुहुन्थ्यो, बाटोमा तिर्खाले छटपटाइरहेको एउटा गधालाई देख्नुभयो र उहाँले आफूसँग भएको पवित्र गङ्गाजल त्यसको मुखमा हालिदिनुभयो । मानिसहरूले भने- यो त गधा हो, मर्ने वाला नै थियो । तर एकनाथ महाराजले त्यही गधामा साक्षात् रामेश्वरको दर्शन गर्नुभयो । यो उहाँको ‘अनुभूति’ थियो । सन्तहरूको यस्तो कार्यको नक्कल गरेर मात्र हुँदैन, उनीहरूको अन्तःकरण बुझ्नुपर्छ ।
जसले सबैमा एउटै चेतना देख्छ, उसको अन्तःकरण कर्मको बन्धनबाट मुक्त हुन्छ । ज्ञानेश्वर महाराज- हे विश्वचि माझे घर सारा विश्वलाई नै आफ्नो घर मान्नुहुन्छ । जसले सबैमा त्यही एउटै परमात्मा कार्यरत हुनुहुन्छ भन्ने अनुभूति गर्छ, उसको अन्तःकरण कर्मका सबै बन्धनबाट मुक्त भएर शुद्ध हुन्छ ।
5.8
नैव किञ्चित्करोमीति, युक्‍तो मन्येत तत्त्ववित् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (5, 8, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=QyMg-m-l-2E', '2026-03-14', 'योगयुक्त तत्त्ववेत्ता पुरुषले हेर्दा, सुन्दा, स्पर्श गर्दा, सुँघ्दा, हिँड्दा, खाँदा, सुत्दा, श्वास लिँदा, बोल्दा, मलमूत्र त्याग गर्दा, ग्रहण गर्दा, आँखा खोल्दा र चिम्लँदा पनि सबै इन्द्रियहरू आ-आफ्ना विषयहरूमा प्रवृत्त भइरहेका हुन्छन् भन्ने विचार गरेर ''म स्वयं केही पनि गर्दिनँ'' भनी अनुभव गर्छ ।
5.8 writeup
5.9
प्रलपन्विसृजन्गृह्णन्, नुन्मिषन्निमिषन्नपि ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (5, 9, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=QyMg-m-l-2E', '2026-03-14', 'योगयुक्त तत्त्ववेत्ता पुरुषले हेर्दा, सुन्दा, स्पर्श गर्दा, सुँघ्दा, हिँड्दा, खाँदा, सुत्दा, श्वास लिँदा, बोल्दा, मलमूत्र त्याग गर्दा, ग्रहण गर्दा, आँखा खोल्दा र चिम्लँदा पनि सबै इन्द्रियहरू आ-आफ्ना विषयहरूमा प्रवृत्त भइरहेका हुन्छन् भन्ने विचार गरेर ''म स्वयं केही पनि गर्दिनँ'' भनी अनुभव गर्छ ।
भगवान् भन्नुहुन्छ -
नैव किञ्चित् करोमिति, युक्तो मन्येत तत्त्ववित्
- संसारको परिणामबाट, संसारका सारा संघर्षबाट, घट्ने घटनाहरूबाट, उठ्ने वृत्तिहरूबाट, जे पनि भइरहेको छ त्यसबाट तत्त्वज्ञानीहरूको अन्तरङ्ग मुक्त हुन्छ । अन्तरङ्गमा त्यसको प्रभाव पर्दैन किनभने ‘म आत्मतत्त्व हुँ ।’ भन्ने अनुभूतिसम्म उनीहरू पुगेका हुन्छन् ।
जो तत्त्ववित् (ज्ञानी) व्यक्ति युक्त- नित्य परमात्मासँग चारैतिरबाट जोडिएको हुन्छ, उसले निःसन्देह म केही पनि गरिरहेको छैन, मेरो शरीरले गरिरहेको छ, मेरो मनले गरिरहेको छ, म मन होइन भन्ने बिचार गर्छ ।
पश्यन्
(देख्दै),
शृण्वन्
(सुन्दै),
स्पृशन्
(स्पर्श गर्दै),
जिघ्रन्
(सुँघ्दै/गन्ध लिँदै), अश्नन् (खाँदै), गच्छन् (हिँड्दै), स्वपन् (सुत्दै), श्वसन् (साँस लिँदै), प्रलपन् (बोल्दै), विसृजन् (त्याग गर्दै), गृह्णन् (ग्रहण गर्दै), उन्मिषन् निमिषन् (आँखा झिम्काउँदै) । आदि देहका क्रियाहरू पनि मैले होइन बरु इन्द्रियाणी इन्द्रियार्थेषु वर्तन्ते- इन्द्रियहरूले आफ्नो-आफ्नो ढङ्गले आ-आफ्नालागि काम गरिरहेका छन् भन्ने सम्झन्छन् । आफूले देखेका दृष्य र सुनेका कुराहरूलाई- मैले होइन आँखाले देखिरहेको छ, मैले होइन कानले सुनिरहेको छ, भन्ने भाव आउनु तर त्यसको प्रभाव अन्तरङ्गमा नहुनु नै तत्त्वज्ञानीका लक्षण हुन् ।
भगवान्ले हामीलाई ‘द्रष्टा’ (साक्षी) बन्ने कला सिकाउँदै हुनुहुन्छ । आकाशमा सूर्य उदय हुन्छ, पानीको बाफ बन्छ, बादल बन्छ, अनि वर्षा हुन्छ । सूर्य र आकाशको यससँग के सम्बन्ध छ? आकाशमा घट्ने सारा घटनाहरू सूर्यकै कारण भइरहेका छन्, तर सूर्यमा त्यसको कुनै लेप लाग्दैन । आकाशमा पनि त्यसको कुनै लेप लाग्दैन । त्यसै गरी शरीरका यी सारा क्रियाहरूको आफ्नो चित्तमा कुनै परिणाम हुँदैन । चित्तलाई यस परिणामबाट मुक्त गर्नु गर्नु नै द्रष्टा भाव हो । कानले कहिले निन्दा सुन्छ, कहिले स्तुति । हामीले निन्दा सुन्यौँ भने हाम्रो मनमा क्रोधको आवेग वा द्वेष उत्पन्न हुन्छ । स्तुति सुन्यौँ भने हामी स्तुति गर्ने सँग प्रशन्न हुन्छौँ । यस्ता कुराको परिणाम अन्तःकरणमा परिरहन्छ । जीवनमा यी दुवै कुरा घटिरहन्छन्-कहिले मन अनुकूल त कहिले प्रतिकूल । त्यसैले दुवै कुराको परिणामबाट अन्तःकरणलाई मुक्त गर्नुपर्दछ । यहि कुरालाई भगवान्‌ आदि शङ्कराचार्यले निर्वाण षटकम्‌ स्तोत्रमा यसप्रकार भन्नुभएको छ-
मनो बुद्ध्यहंकार चित्तानि नाहं
न च श्रोत्रजिह्वे न च घ्राणनेत्रे
न च व्योम भूमिर्न तेजो न वायुः
चिदानन्दरूपः शिवोऽहम् शिवोऽहम्।
म त चैतन्य तत्व हुँ- म न मन हुँ न बुद्धि, न चित्त, न अहङ्कार, न पाप, न पुण्य, न सुख, न दुःख, न गुरु, न शिष्य हुँ। म त्यो आत्मतत्व हुँ, शिव हुँ । यस प्रकारले उहाँ त्यो उचाईसम्म पुग्नुभयो । हाम्रो आत्मतत्त्व ती सारा कुराहरूबाट मुक्त नै हुन्छ । तर हामी त्यसमाथि मयल जम्मा गरिदिन्छौँ र त्यो आत्मतत्त्वको दर्शन हुँदैन । जसरी घरमा ‘सर्ट सर्किट’का कारण आगो लाग्यो भने हामी पहिले त्यो स्वीच बन्द गरेर करेन्ट संग सर्किटलाई अलग गरिदिन्छौँ । त्यसैगरी भगवान्ले पनि यो संसारको परिणामबाट हाम्रो अन्तरङ्गलाई मुक्त(अलग) गरिदिनुहुन्छ जसले मानिसहरूको व्यवहारका कारण हामीमा देखिने परिणामबाट हाम्रो अन्तःकरण मुक्त हुनेछ
