INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (5, 10, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=QyMg-m-l-2E', '2026-03-14', 'जो पुरुष सम्पूर??ण कर्महरूलाई परमात्मामा अर्पण गरेर र आसक्तिलाई त्याग गरेर कर्म गर्दछ, त्यो पुरुष पानीमा कमलका पत्रहरू लिप्‍त नभए जस्तै पापमा लिप्‍त हुँदैन ।
भगवान्‌ भन्नुहुन्छ-
ब्रह्मण्याधाय कर्माणि-
जसले ब्रह्म परमात्मामा आफ्ना सारा कर्महरू अर्पण गरिदियो र
सङ्गं त्यक्त्वा
- त्यसको आसक्तिबाट ऊ अलग भयो । उसलाई अलग हुने त्यो कला आयो । यः करोति-जसले यसरी कर्म गर्छ,
न स पापेन लिप्यते
- उसलाई पाप लाग्दैन ।
पद्मपत्रमिवाम्भसा
- जसरी कमलको पात (पद्मपत्र) पानीमा रहन्छ तर पानीले त्यसलाई भिजाउँदैन, त्यसै गरी संसारमा रहँदा पनि संसारका परिणामबाट उसको अन्तःकरण मुक्त रहन्छ । कुनै पनि दोषले उसको अन्तःकरण सङ्क्रमित हुँदैन । संसारका विकारहरू उसको अन्तःकरणमा प्रवेश गर्दैनन् । ज्ञानेश्वर महाराज भन्नुहुन्छ-
तो कर्म करी सकळ ।
परि कर्मबंधना न कळे ।
जैसें न जळे । पद्मपत्र ॥
जसरी कमलको पात जलमा रहेर पनि निर्लिप्त रहन्छ, पानीमा भएर पनि पानी त्यसको भित्र जाँदैन, त्यसै गरी जो व्यक्ति सांसारिक विकारहरू बाट अलग भयो, जसले संसारसँगको र अन्तःकरणको सम्बन्ध विच्छेद गरिदियो, ऊ दिनरात संसारको कर्ममा रहेर पनि कमलको पात झैँ निर्लिप्त रहन्छ । त्यसैले गुरुदेव पनि वैदिक कार्य, राष्ट्रिय कार्य, भगवत् कार्य गरिरहनु भएको छ । उहाँको भन्नुहुन्छ- पहिले सनातन धर्मको रक्षण हुनुपर्छ । “माई नेशन फर्स्ट, माई मिशन नेक्स्ट, माईसेल्फ नेभर” । उहाँले पहिल देश, त्यसपछि आफ्नो लक्ष्यलाई मान्नुहुन्छ तर आफूलाई कहिल्यै महत्व दिनुहुदैन । गुरुदेवले आफ्नो लागि आफूलाई कतै देख्नुहुन्न, तर मेरो राष्ट्र, मेरो सनातन धर्म, मेरो मातृभूमिको रक्षा हुनुपर्छ भन्ने सोच्नुहुन्छ । यस प्रकारले भारत मात्र होइन, विश्वभरि नै विचरण गर्नुहुन्छ-अविश्रान्त (कुनै थकाइ नमानी), अविराम (नरोकिई) उहाँका पाइलाहरू निरन्तर चलिरहन्छन् ।
ज्ञानेश्वर महाराज भन्नुहुन्छ-
बाहेरी कर्मला, भीतरी ज्ञान उजळला
बाहिरबाट कर्म गरिरहेको देखिए पनि यो महान् योगी भित्रबाट ज्ञानको आभाले आलोकित हुन्छ ।
विवेकानन्दको अन्तःकरण पनि यस्तै थियो । उहाँले शिकागोमा आयोजित र सर्वधर्म परिषद्‌मा दिएको ऐतिहासिक भाषणमा भन्नुभयो कि सबै मार्गहरू त्यहीँ पुग्नका लागि हुन् । सबै मानिसहरू आफ्नो धर्मलाई सर्वोपरी देखाइरहेका थिए, तर विवेकानन्दजीले भन्नुभयो- सबैले बाटो देखाएको बाटो एउटै हो । यो सुनेर उहाँका धेरै अनुयायीहरू भए । एक पटक उहाँले आफ्ना अनुयायीहरूलाई हामी संसारको परिणामबाट आफ्नो अन्तःकरणलाई कसरी मुक्त गर्न सक्छौँ भनेर सम्झाउँदै हुनुहुन्थ्यो । यो बुझाउन उहाँले शिष्यहरूलाई सागरको किनारमा लैजानुभयो । त्यहाँ एउटा पानीजहाज देखाएर भन्नुभयो- यो जहाज किन तैरिरहेको छभने यसको भित्र पानी छैन । यदि यसको मुनि प्वाल पर्‍यो र भित्र पानी पस्न थाल्यो भने यो डुब्छ । त्यसै गरी यो संसार हाम्रो अन्तःकरणमा प्रवेश गर्‍योभने यसले हामीलाई आफ्ना विकारहरूमा डुबाइदिन्छ । तसर्थ संसारका विकारको प्रभावबाट मुक्त रहनु नै संसारबाट तर्ने यो एकमात्र उपाय हो ।
एउटा भित्तामा किलाले केही लेखियो भने त्यो अङ्कित हुन्छ । तर गङ्गा जलमा किलाले लेख्यो भने केही लेखिन्न । त्यसै गरी ज्ञानीको अन्तःकरण परमात्माको रसले यसरी परिपूर्ण हुन्छ कि संसारका सारा परिणामहरूबाट उसको अन्तःकरण मुक्त हुन्छ । गङ्गाजल समान पवित्र अन्तःकरण र आत्मतत्त्व आफ्नो आभाका साथ प्रदीप्त हुन्छ । व्यक्तिले आफ्नो जीवनमा त्यो ‘परम निर्वाण’ प्राप्त गर्दछ । हाम्रा सारा सन्त महात्मा र गुरुदेवको जीवनमा हामी यही देख्छौँ ।
प्रश्नोत्तर
प्रश्नकर्ता-
अनुपमा दिदी
प्रश्न
- कर्मयोगमा भनेजस्तो कर्तृत्व, भोक्तृत्व र फलासक्तिको सन्दर्भमा, हामीले कुन प्रकारका कर्म बुझ्नुपर्छ? त्यस सन्दर्भमा हामी कसरी कर्मयोगी हुने ? भगवान्‌ले भने झैँ सबै कर्महरू उहाँलाई कसरी समर्पण गर्ने?
उत्तर-
हरेक कर्मलाई कर्मयोगमा परिणत गर्नु हाम्रो लागि सधैँ सम्भव हुँदैन, किनकि हामी सामान्य मानिस हौँ । तर भगवान् भन्नुहुन्छ कि कर्मयोगको मार्गमा हिँड्न सुरु गर । यसको अर्थ यो हो कि मैले कुनै कर्म भगवानलाई अर्पण गर्न सक्छु । हामीले केही सानै भए पनि राम्रा काम गर्न सक्छौँ । कहिलेकाहीँ कर्म गर्दा फलको आशा वा कर्तृत्व (मैले गरेको) भन्ने अहङ्कार पनि हाम्रो मनमा आउँछ । त्यस्तो बेला हामीले केही निस्वार्थ कर्म गर्नुपर्छ । जस्तै तुलसीलाई पानी चढाउनु, भोकाएको व्यक्तिलाई खाना दिनु वा अनाथ आश्रममा गएर दान गर्नु । यस्तो काम गर्दा त्यसको बदलामा केही पनि चाहना राख्नु हुँदैन, आफुले गरेको कामको प्रचार पनि गर्नुहुँदैन । हामीले दिनभरिमा कम्तीमा एउटा सानो कर्म भए पनि भगवान्‌को लागि गर्‍यौँ भने कर्मयोग सुरु गर्न सकिन्छ । गर्मीको समयमा पंछीहरूका लागि पानी राख्नु र मनमा भगवान्‌लाई भन्नु कि सम्पूर्ण सृष्टि तपाईँको हो र यो पनि तपाईँलाई अर्पण गरेको हो । त्यसपछि मैले गरेको भनेर सम्झिरहनु हुँदैन, परमात्माले मबाट गराउनुभएको हो भन्ने भावना राख्नुपर्छ । यसरी गर्दा हाम्रो अन्तःकरण पनि शुद्ध र हल्का हुन्छ । कहिलेकाहीँ हामीले राम्रो काम गर्दा ‘मैले गरेँ’ भन्ने अहङ्कार आउँछ र सफल भएमा घमण्ड तथा असफल भएमा हीन भावना आउन सक्छ । भगवान्‌ हामीलाई यस्ता भावनाबाट मुक्त गराउन चाहनुहुन्छ । यसरी निस्वार्थ भावले गरिएको सानो कर्मबाट नै कर्मयोग सुरु हुन्छ । हामीले गरेका सबै कर्म परमात्मालाई अर्पण गर्न सक्दैनौँ । जस्तै- कसैले गोल्ड मेडल पायो भने त्यो मेडल भगवान्‌को मूर्ति अगाडी राखिदिने होईन बरु परमात्माले दिएको शक्तिले गर्दा यो प्राप्त भयो, प्रेरणा र शक्ति पनि उहाँकै हो भन्ने भावना राख्दै सो कर्म उहाँलाई अर्पण गर्नुपर्छ । यसो गर्दा न अहङ्कार आउँछ न हीनभाव । त्यसैले कर्म गर्दा चुपचाप गर्नुपर्छ, अरूलाई देखाउन होइन । यसरी सानै भए पनि हामीले गरेका कर्म भगवानलाई अर्पण गर्न सक्यौँ भने हाम्रो कर्मयोगको यात्रा सुरु हुन्छ, बिस्तारै ज्ञानको उदय हुन थाल्छ ।
प्रश्नकर्ता
- श्री आनन्द दाजु
प्रश्न-
हाम्रो शरीर निरन्तर साक्षी भाव तर्फ अग्रसर भइरहेको छ भन्ने कुरा जाँच्नको लागि कसको आश्रय लिनु पर्ला?
उत्तर
- यसको परीक्षण हामी आफैँले गर्न सक्छौं वा हाम्रा वरिपरिका मानिसहरूले पनि भन्न सक्छन् । हामी पहिले कस्ता थियौँ? अहिले कस्ता छौँ? अरूको व्यवहारले हामीमाथि र हाम्रो व्यवहारले अरुमाथि कस्तो प्रभाव पारिरहेको छ? संसारमा विकारहरूको चक्र त चलिरहन्छ, तर के हामी तिनले प्रभावित भइरहेका छौं? यी नै मापदण्डका सहायताले हामी आफूलाई परीक्षण गर्न सक्छौं ।
जो सन्तहरूले साक्षी भाव प्राप्त गरिसकेका छन्, तिनीहरूको जीवनका प्रसङ्गहरू पढेर तिनीहरूको अनुकरण गर्नु पनि महत्त्वपूर्ण हुन्छ । यसरी हामी बिस्तारै साक्षी भावतर्फ अगाडि बढ्न सक्छौं ।
यो विवेचन पढेर तपाईँलाई अवश्य पनि राम्रो लाग्यो होला भन्ने हामीलाई विश्वास लागेको छ । कृपया तल दिएको लिङ्क प्रयोग गरी हामीलाई आफ्नो प्रतिक्रियाहरू दिनुहोला ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 1, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=vlirUTVFpRo', '2026-03-07', 'अर्जुनले भने- केवल ममाथि अनुग्रह गर्नका लागि हजुरले जुन परम गोपनीय अध्यात्मविषयक वचन अर्थात् उपदेश दिनुभयो, त्यसबाट मेरो यो अज्ञानता नष्ट भएको छ ।
यस अध्यायमा अर्जुनको प्रश्नबाट अध्याय सुरु हुन्छ । अर्जुन भन्छन्, “ममाथि हजुरले अनुग्रह गरेर गोप्य आध्यात्मिक ज्ञान प्रदान गर्नुभयो, जसका कारणले मेरो मोह नष्ट भयो” । विश्वरूपदर्शनयोग भन्दा पहिला भगवान्‌ले अर्जुनलाई
साङ्ख्ययोग, कर्मयोग, ज्ञानयोग, आत्मसंयमयोग, ज्ञानविज्ञानयोग, विभूतियोग
आदिको बारेमा भनिसक्नुभएको थियो । श्रीमद्भगवद्गीता यस्तो शास्त्र हो, जसमा वर्णन गरिएको भगवान्‌को विराट् रूपको दर्शन देखेर आजका आधुनिक वैज्ञानिकहरू पनि छक्क पर्छन्; किनकि अन्य कुनै पनि धर्मग्रन्थहरूमा यस्तो प्रसङ्ग पाइँदैन । तसर्थ यो अध्याय विशेष छ । यस गीतालाई ज्ञानेश्वर महाराजले ९००० ओवीमा अद्भुत रस भरी समाजमा प्रस्तुत गर्नुभएको थियो । गोपनीय अध्यात्म उपदेशबाट मोह नष्ट भएका अर्जुनको मन शान्त त भएको थियो, तर उनले दिव्य स्वरूपलाई आँखाले देख्न सकेका थिएनन् । भगवान्‌मा, असल वस्तुमा र आफन्तमा मोहका साथै उनले राम्रो मान्न सक्थे, तर दुर्योधन र दुशासनजस्ता अपराधीमा पनि भगवान् हुनुहुन्छ भनेर मान्न सकेका थिएनन् । असल र खराब दुवैप्रति भगवान्‌को कृपा हुन्छ भन्ने कुरा उनले स्वीकार्न सकेका थिएनन् । तर भगवान्‌बाट प्राप्त अध्यात्म उपदेशपछि मात्र उनको मोह नष्ट हुन पुगेको थियो ।
यो भगवद्गीता ज्ञान, भक्ति र कर्मको त्रिवेणी हो । जसरी प्रयागमा गङ्गा, यमुना र सरस्वती को सङ्गम छ, त्यसै गरी गीतामा पनि ज्ञान र कर्म प्राप्त हुन सक्छ, तर भक्तिलाई भने अन्तरहृदयमा खोतल्नुपर्छ; जसरी त्रिवेणीमा सरस्वती लाई खनेर निकाल्नुपर्छ । यस गीताको एघारौँ अध्यायमा अर्जुन भन्छन् कि म, मेरो, देह, राज्य, दाजुभाइ, काका, मामा, छोरा, भतिजा र यो युद्धको जङ्घा एवं आफ्ना गुरुसँग कसरी युद्ध गरौँ भन्ने मोह नष्ट भयो, अब तपाईँ जे भन्नुहुन्छ म त्यही गर्छु ।
नष्टो मोहः स्मृतिर्लब्धा त्वत्प्रसादान्मयाच्युत ।
स्थितोऽस्मि गतसन्देहः करिष्ये वचनं तव ॥१८.७३।।
11.2
भवाप्ययौ हि भूतानां(म्), श्रुतौ विस्तरशो मया ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 2, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=vlirUTVFpRo', '2026-03-07', 'किनकि हे कमलनेत्र! सम्पूर्ण प्राणीहरूको उत्पत्ति तथा विनाश मैले विस्तारपूर्वक हजुरबाट नै सुनेँ र हजुरको अविनाशी महिमा पनि सबै सुनिसकेँ ।
भवाप्ययौ
- संसारको उत्पत्ति र प्रलय ।
कमलपत्रायक्ष-
कमलपत्र समान नेत्र भएका (कमल हिलोमा फुल्छ तर हिलोको गुण लिँदैन), निर्मल, इर्ष्या र द्वेष हटाउने, पवित्र दृष्टि दिने एवं दुर्गुण हटाइदिने ।
भूतानाम्-
पञ्चमहाभूत ।
श्रुतौ
- सुनेँ ।
विस्तरशः
- विस्तारमा, राम्रोसँग ।
माहात्म्यमपि-
महिमा पनि ।
अव्ययम्-
नष्ट नहुने, ननासिने । यो देखिएको भौतिक जगत्, जीव आदि भूतहरूको उत्पत्ति र अन्त्यका बारेमा मैले राम्रोसँग सुनेँ । यसका साथै हे कमलपत्र समान भगवान् हजुरको अपरम्पार महिमा पनि विस्तारमा मैले सुनेँ । विभूतियोगमा हजुरले भनेझैँ मलाई हजुरको त्यो दिव्य विश्वरूप हेर्ने इच्छा छ ।
11.3
एवमेतद्यथात्थ त्वम्, आत्मानं(म्) परमेश्वर ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 3, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=vlirUTVFpRo', '2026-03-07', 'हे परमेश्वर! हजुर आफूलाई जस्तो भन्नुहुन्छ, यो वास्तवमा ठ्याक्कै उस्तै छ । हे पुरुषोत्तम! हजुरको ज्ञान, शक्ति, बल, वीर्य र तेजयुक्त ऐश्वर्यरूपलाई म प्रत्यक्ष देख्न चाहन्छु ।
अर्जुन भन्दछन्- भगवान् श्रीकृष्णको मुखबाट उहाँको अव्यय (अविनाशी) महिमा श्रवण गरेपछि अर्जुनको अन्तःकरणमा श्रीभगवान्‌को विश्वरूप हेर्ने तीव्र इच्छा जागृत भयो। अर्जुनले श्रीभगवान्‌लाई दुई विशिष्ट सम्बोधनले अलङ्कृत गर्नुभयो- ‘परमेश्वर’ र ‘पुरुषोत्तम’ ।
‘परमेश्वर’
को तात्पर्य त्यो परम ईश वा नियन्तासँग छ, जसले समस्त सृष्टिको नियमन सञ्चालन गर्नुहुन्छ। यही नियामकताका कारण नै ग्रह-नक्षत्रहरू आफ्ना निश्चित कक्षा र गतिमा गतिमान रहन्छन्। कवि कृष्णकुमार चौबेका पङ्क्तिहरूले यस सत्यलाई रेखाङ्कित गर्दछन्:
क्या धरा हमने बनायी या बुना हमने गगन ।
क्या हमारी ही वजह से बह रहा सुरभित पवन ॥
या गगन के हम हैं स्वामी नियन्ता जलधार के ।
या जगत के सूत्रधार नियामक संसार के ॥
पन्ध्रौँ अध्यायमा पुरुषोत्तमको जुन वर्णन प्राप्त हुन्छ, त्यो यसभन्दा पछि आएको छ। क्षर र अक्षर- यी दुवै पुरुषभन्दा पर रहेका पुरुषोत्तमको वर्णन गर्दै भनिएको छ:
द्वाविमौ पुरुषौ लोके क्षरश्चाक्षर एव च।
क्षरः सर्वाणि भूतानि कूटस्थोऽक्षर उच्यते॥१५.१६।।
अर्जुनले श्रीभगवान्‌लाई यहाँ पुरुषोत्तम भनेर सम्बोधन गर्दै भन्नुहुन्छ- “हे परमेश्वर! तपाईंले आफ्नो विषयमा जे भन्नुभएको छ, त्यो सबै उचित छ” । अक्षर (जसको विनाश हुँदैन) र क्षर (जसको विनाश हुन्छ)- तपाईँ यी दुवैभन्दा पर हुनुहुन्छ। यो केवल सुन्ने र भन्ने कुरा मात्र नभएर अनुभूतिको विषय पनि हो। अर्जुनले पुरुषोत्तमसँग त्यो परम अनुभूति प्रदान गर्न प्रार्थना गर्दै भन्नुहुन्छ:
द्रष्टुमिच्छामि ते रूपमैश्वरं पुरुषोत्तम।
अर्थात्, हे पुरुषोत्तम! तपाईंको त्यो परम ऐश्वर्ययुक्त रूप, जसको तपाईंले वर्णन गर्नुभयो, म प्रत्यक्ष हेर्ने इच्छा राख्दछु । अखिल ब्रह्माण्डका नियन्ता र सारथीका रूपमा रहेका प्रभुसँग अर्जुन प्रश्न गर्नुहुन्छ, के उनले त्यो दिव्य रूपको दर्शन गर्न सक्छन्? अगाध महिमा भएका प्रभुसँग उनी कृपाको याचना गर्छन् । चराचर जगत् जसमा समाहित छ, त्यो दिव्य रूप हेर्ने तीव्र इच्छा उनको अन्तःकरणमा प्रस्फुटित भइरहेको छ। यस सन्दर्भमा ज्ञानेश्वर महाराज भन्नुहुन्छ:
तुझें विश्वरूपपण आघवें, माझिये दिठीसि गोचर होआवें ।
यसको तात्पर्य हो “हे प्रभु! तपाईंको जुन विश्वरूप छ, त्यो मेरो आँखाको अगाडि प्रत्यक्ष हुनुपर्छ” । अर्जुनको इन्द्रियहरूद्वारा त्यो रूपको अनुभूति प्राप्त गर्ने तीव्र आकाङ्क्षा छ। यही आशा र उत्कट इच्छा उनको अन्तःकरणमा व्याप्त छ ।
11.4
मन्यसे यदि तच्छक्यं(म्), मया द्रष्टुमिति प्रभो ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 4, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=vlirUTVFpRo', '2026-03-07', 'हे प्रभु! यदि हजुरलाई मैले हजुरको त्यो परम ऐश्वर्यरूप हेर्न सक्छु जस्तो लाग्छ भने, हे योगेश्वर! मलाई त्यस अविनाशी स्वरूपको दर्शन गराउनुहोस् ।
अर्जुन भगवान्‌सँग भन्दछन्, “हे प्रभु! हजुरको त्यो विशाल रूप हेर्न म योग्य छु भने बालकलाई नयाँ ज्ञान दिएजस्तै कृपा गरेर मलाई दर्शन गर्ने अवसर प्राप्त होस्” । यसरी अर्जुन भगवान्‌सँग प्रार्थना गर्दछन् । हजुरको वास्तविक रूप हेर्ने मेरो लालसा छ । संसारका महान् व्यक्तिहरूले पनि भगवान्‌को वास्तविक स्वरूप हेर्ने सौभाग्य पाएका छैनन् । यशोदा मैया यो अवसर पाएको त्यो विराट् स्वरूप यदि मलाई हेर्न सक्ने क्षमता प्रदान हुन्छ भने मेरो आत्माले त्यो अविनाशी स्वरूप हेर्ने उत्कट अभिलाषा राखेको छ भनेर बिन्ती गर्दछन् ।
11.5
श्रीभगवानुवाच
पश्य मे पार्थ रूपाणि, शतशोऽथ सहस्रशः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 5, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=vlirUTVFpRo', '2026-03-07', 'श्रीभगवान् भन्नुहुन्छ- हे पार्थ! अब तिमीले मेरा अनेक प्रकारका वर्णहरू तथा आकृतिहरू भएका सयौँ अनि हजारौँ दिव्य अलौकिक रूपहरूलाई हेर ।
आफ्नो परम भक्तले यसरी करुणामय भावले अनुनय गर्दा भगवान् अत्यन्त उत्साहित हुँदै प्रसन्न भएर भन्नुहुन्छ, “हेर त पार्थ! यी मेरा सयौँ हजारौँ रूपहरू छन्” । यसमा विभिन्न प्रकारका छोटा, मोटा, अग्ला, पुड्का, नेप्टा, चेप्टा, थेप्चा, पराक्रमी, काँतर, बाल, वृद्ध, अनेक जीव, जन्तु, चैतन्य र जड वस्तुहरू छन् । यहाँ हावा, पानी, हुरी, बतास, घाम, छाया, जल, थल, आकाश, पहाड, हिमाल र फाँटलगायतका दिव्यस्वरूपहरू देखिन्छन् । यी सबैलाई विभिन्न प्रकारले वर्णन गर्न सकिन्छ ।
11.6
पश्यादित्यान्वसूनरुद्रान्, अश्विनौ मरुतस्तथा ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 6, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=vlirUTVFpRo', '2026-03-07', 'हे भरतवंशी अर्जुन! तिमीले ममा आदित्यहरूलाई अर्थात् अदितिका बाह्र पुत्रहरूलाई, आठ वसुहरूलाई, एघार रुद्रहरूलाई, दुवै अश्विनीकुमारहरूलाई र उनन्पचास मरुद्‌गणहरूलाई हेर । यस्तै अरू पनि तिमीले पहिले कहिल्यै नदेखेका धेरै नै आश्चर्यमय रूपहरूलाई पनि हेर ।
श्रीभगवान् भन्नुहुन्छ, “हे भारत! हे भरतवंशी अर्जुन! सर्वप्रथम अदितिका बाह्र पुत्र अर्थात् बाह्र आदित्य हरूलाई हेर, तत्पश्चात् एघार रुद्र (शङ्करजीका एघार रुप), आठ वसु । नश्वर लोकमा गङ्गा माताको गर्भबाट जन्म लिएपछि, गङ्गा माताले उनीहरूलाई मोक्ष प्रदान गर्नुभयो । वसु (अर्थात् देवव्रत वा भीष्म पितामह आठौँ वसु हुन्), दुई अश्विनहरू र उनान्चालीस मरुत हरू हेर । यीबाहेक अरू धेरै अद्भुत दृश्यहरू हेर, जुन तिमीले पहिले कहिल्यै देखेका छैनौ ।
11.7
इहैकस्थं(ञ्) जगत्कृत्स्नं(म्), पश्याद्य सचराचरम् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 7, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=vlirUTVFpRo', '2026-03-07', 'हे गुडाकेश (निन्द्रालाई जित्नेवाला) अर्जुन! अब मेरो यो शरीरमा एकै ठाँउमा स्थित चराचरसहित सम्पूर्ण जगत्‌लाई हेर र यसका अतिरिक्त अरू पनि जे-जति तिमी हेर्न चाहन्छौ, ती पनि हेर ।
यहाँ भगवान् कृष्णले अर्जुनलाई गुडाकेश भनेर सम्बोधन गर्नुहुन्छ । गुडाकेश शब्दको अर्थ निद्रामा निपुणता हासिल गरेको व्यक्ति हो । अर्जुन रातदिन जागा बसेर धनुर्विद्याको अभ्यास गर्थे । उनमा कुनै पनि असुविधाजनक समयमा पनि निद्रालाई वसमा राख्न सक्ने क्षमता थियो । तर यहाँ अर्जुन भ्रमपूर्ण निद्रामा छन् । यस निद्राबाट जगाउन भगवान् उहाँलाई गुडाकेशको नामले सम्बोधन गर्नुहुन्छ । भगवद्गीता एक मनोवैज्ञानिक ग्रन्थ हो । यहाँ भगवान् कृष्ण अर्जुनका गुरु हुनुहुन्छ । एक आदर्श गुरुजस्तै उहाँले अर्जुनको क्षमतालाई जगाउदै मानसिक तनावबाट मुक्तितर्फ डोऱ्याउँदै उनको मनोबल बढाउनुभयो ।
मन के हारे हार है, मन के जीते जीत
भगवान् भन्नुहुन्छ, “हे गुडाकेश! मेरो शरीरमा एकै ठाउँमा रहेको सम्पूर्ण गतिशील र अचल ब्रह्माण्डलाई हेर । यदि तिमी अरू केही हेर्न चाहन्छौ भने त्यो पनि हेर” । तर अर्जुनको अनुहार र आँखाले ब्रह्माण्ड देखेको अनुभूति देखाउँदैन ।
एक पटक एक गाउँले सहर गए । पसल बाहिर राखिएको चस्माको तस्बिर देखेर उनी पसलमा गए र भने, “मलाई पढ्नको लागि चस्मा चाहिन्छ” । पसलेले उनलाई एक जोडी चस्मा र कागजको टुक्रा दियो र कागजमा के लेखिएको छ पढ्न भन्यो । गाउँलेले भने, “तर म पढ्न जान्दिन” । यदि तपाईंलाई पढ्न आउँदैन भने चस्माको के काम? तपाईंले पहिले पढ्न सिक्नुपर्छ । जब अर्जुनले देख्ने क्षमता प्राप्त गर्छन्, तब मात्र उनले ब्रह्माण्डको रूप देख्न सक्नेछन् । त्यसका लागि उनले भगवान्‌बाट दिव्य दृष्टि प्राप्त गर्नुपर्छ ।
हामीले पनि सद्गुरुहरूबाट सही दृष्टिकोण प्राप्त गरेपछि मात्र भगवान्‌को दिव्य रूप अनुभव गर्न सक्नेछौँ । ठाकुर रामकृष्ण परमहंसले सुनाएको एउटा सुन्दर कथा छ । एउटी गर्भवती बघिनी थिई । नजिकै बाख्राको बथान देखेर उनी सिकार गर्न उफ्रिइन् । हाम फाल्दा लागेको झड्काले गर्दा उनको बच्चा जन्मियो र अत्यधिक रक्तस्राव भएर बघिनीको मृत्यु भयो । बाघको त्यो बच्चा अब बाख्रासँगै बस्न थाल्यो । बाख्राको आवाज निरन्तर सुनेर उसले आफ्नो स्वभाव बिर्सियो । उसले बाख्राजस्तै घाँस खान थाल्यो । एक दिन त्यहाँ एउटा ठूलो बाघ आयो । उसले त्यो बच्चालाई “तिमी बाख्रा होइन, बाघ हौ” भनेर बुझाउनुपर्ने महसुस गर्यो । रात पर्नेबित्तिकै बाघले गोप्य रूपमा बच्चालाई उठाएर तालको किनारमा लग्यो । तालको पानीमा आफ्नो प्रतिबिम्ब देखेर बच्चाले आफू बाख्रा होइन, बाघ हुँ भन्ने महसुस गर्यो । उसले आफ्नो शक्ति चिन्यो । ज्ञानेश्वर महाराज भन्नुहुन्छ:
ते ज्ञानप्रकाशे पाहिलें जे मोहन्धकार जाईल।
जे सद्गुरु कृपा होईल पार्थागा॥
गुरुको कृपा हुँदा मात्र भ्रमको अन्धकार हट्नेछ र ज्ञानको प्रकाशमा आफ्नो वास्तविक रूप स्पष्ट रूपमा देखिनेछ । यसरी भ्रमको अन्धकार हराएपछि गुरुकृपा हुनेछ र मानिसले महसुस गर्नेछ कि “म शरीर होइन केवल आत्मा हूँ” । जबसम्म प्रत्यक्ष अनुभूति हुँदैन, तबसम्म ज्ञान केवल जानकारी मात्र हो ।
11.8
न तु मां(म्) शक्यसे द्रष्टुम्, अनेनैव स्वचक्षुषा ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 8, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=vlirUTVFpRo', '2026-03-07', 'तर तिमीले त्यो आफ्नो प्राकृतिक चक्षुहरूले नि:सन्देह मलाई हेर्न सक्दैनौ, त्यसैले म तिमीलाई दिव्य अर्थात् अलौकिक चक्षु (आँखा) दिन्छु, जसबाट तिमीले मेरो ईश्वरीय अलौकिक शक्तिलाई हेर ।
अर्जुन आफ्नो सीमित भौतिक दृष्टिका कारण सत्य देख्न असमर्थ थिए र त्यस समय उनको मनोभाव अत्यन्त विह्वल थियो । भगवान् भन्नुहुन्छ, आफ्ना यी सामान्य चर्मचक्षु वा देहको दृष्टिले तिमी मलाई देख्न सक्दैनौ, यसका लागि ज्ञानको नेत्र उदित गराउनु आवश्यक हुन्छ । दुवै आँखीभौँको बीचमा स्थित मानिएको यो ज्ञान-नेत्र गुरुले ज्ञान कर्म र योग साधनाको माध्यमबाट खोली दिनुहुन्छ । भगवान् शिवको तेस्रो आँखा पनि यही ज्ञान-नेत्रको प्रतीक हो । अर्जुन भौतिक दृष्टिले हेर्न असमर्थ भएकोले श्रीभगवान्‌ले उनको क्षमतालाई उन्नत गर्दै “म तिमीलाई दिव्य चक्षु प्रदान गर्दछु” भन्नुभयो ।
ज्ञानेश्वर महाराजका अनुसार त्यस समय अर्जुनको स्थिति कस्तो थियो भने मानौँ कसैले अन्धोलाई ऐना देखाइरहेको छ वा कान नसुन्नेको अगाडि गायन गरिरहेको छ । जहाँ द्रष्टा, देखाउनेवाला र दृश्य सबै महान् हुन्छन्, त्यहाँ ज्ञानको दृष्टि पश्चात् दिव्य दृष्टिको उदय हुन्छ । दृष्टिका विभिन्न स्तरहरू यस प्रकार छन् :
१. सामान्य दृष्टि:
यसलाई चर्मचक्षु भनिन्छ, जसले देह-बुद्धिका कारण भेदभाव उत्पन्न गर्छ ।
२. प्रज्ञा दृष्टि:
यो ज्ञानको दृष्टि हो ।
३. वैज्ञानिक दृष्टि:
जस्तै सूक्ष्मदर्शक यन्त्रमार्फत पदार्थको आन्तरिक स्वरूप, परमाणुको संरचना, प्रोटोन, न्युट्रोन र इलेक्ट्रोनको गतिलाई बुझ्नु ।
४. दिव्य दृष्टि:
यो प्रज्ञा दृष्टिभन्दा पनि पर छ, जसबाट अनन्तताको अनुभव हुन्छ ।
द्रष्टा, दर्शन
र
दृश्य
को यो त्रिपुटीको रहस्य शुद्ध चैतन्यमा मात्र स्फुटित हुन्छ । यस प्रकार स्वप्न कालमा स्वप्न-द्रष्टा, स्वप्न देख्ने क्रिया र स्वप्नका वस्तुहरू यी तीनै कुरा द्रष्टाको मनको विवर्त अर्थात् भ्रम वा स्वरूप परिवर्तन मात्र हुन्, त्यसै गरी जाग्रत अवस्थामा पनि यो त्रिपुटी त्यही एक शुद्ध चैतन्यमा कल्पित छ । जब श्रीभगवान्‌ले अर्जुनलाई यो दिव्य दृष्टि प्रदान गर्दै मेरो योग एश्वर्य हेर भन्नु भयो, तब सञ्जयले त्यसको वर्णन गर्दछन् ।
11.9
सञ्जय उवाच
एवमुक्त्वा ततो राजन्, महायोगेश्वरो हरिः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 9, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=vlirUTVFpRo', '2026-03-07', 'सञ्जयले भने- हे राजन्! यस्तो भनेर महायोगेश्वर तथा सबै पापलाई नाश गर्ने भगवान् श्रीकृष्णले अर्जुनलाई परम ऐश्वर्यले युक्त विराट स्वरूप (दिव्य स्वरूप) देखाउनु भयो ।
भगवान् वेदव्यासले धृतराष्ट्रलाई “म तिमीलाई दिव्य दृष्टि दिन्छु” भन्दा धृतराष्ट्रले नै “मैले अहिलेसम्म केही पनि देखेको छैन, म युद्ध कसरी हेरूँ” भनेर लिन नमानेपछि सारथि सञ्जयलाई दिव्य दृष्टि दिनुभएको थियो । हामीले अहिले मोबाइलबाट संसार देखेको जस्तै गरी सञ्जयले पाएको दिव्य दृष्टि मार्फत सम्पूर्ण घटना देखिरहेका थिए । यहाँ कुनै खेल हेर्दा कमेन्ट्री गरेको जस्तै गरेर अब सञ्जय वर्णन गर्दैछन् ।
एवमुक्त्वा ततो राजन्महायोगेश्वरो हरिः ।
दर्शयामास पार्थाय परमं रूपमैश्वरम् ॥
हे राजन्! यहाँ महायोगेश्वर हरि देखिनुभएको छ, उहाँ जताततै हुनुहुन्छ । हरि अर्थात् सबैको पापलाई हरण गर्नेवाला ।
एवमुक्त्वा
- भन्दै र बताउँदै । भगवान् पार्थलाई आफ्नो ऐश्वर्ययुक्त विश्वरूपको दर्शन दिनुभयो । सञ्जयले भगवान्‌को रूपको वर्णन गर्न थाल्नुभयो । यही विषयमा ज्ञानेश्वर महाराज भन्नुहुन्छ, “कस्तो प्रेम हो यो कृष्ण र अर्जुनको”! भगवान्‌ले आफ्नो सम्पूर्ण अन्तरङ्ग खोल्नुभयो । आफ्नो सम्पूर्ण ज्ञान दिँदै आफ्नो ऐश्वर्ययुक्त रूप अर्जुनलाई देखाउनुभयो । ज्ञानेश्वर महाराज भन्नुहुन्छ,
हा कोपे कीं निवांतु साहे, हा रुसे तरी बुझावीत जाये,
नवल पिसें लागलें आहे, पार्थाचें देवा ॥
भगवान् श्रीकृष्ण अर्जुनका लागि यसरी विह्वल हुनुहुन्छ कि यदि अर्जुन क्रोधित हुन्छन् भने पनि उहाँले त्यसलाई शान्त भावले सहनुहुन्छ । यदि अर्जुन रुष्ट भएर बस्छन् भने उहाँले उनलाई फकाउनुहुन्छ र मनाउनुहुन्छ । भक्त र भगवान्‌को यो सम्बन्ध अत्यन्त अद्वितीय छ, जहाँ भगवान्‌ले आफ्नो भक्तका लागि आफ्नो सम्पूर्ण ऐश्वर्य र ज्ञान अर्पित गरिदिनुभयो ।
यही विषयमा ज्ञानेश्वर महाराज भन्नुहुन्छ, “अर्जुन बन र अर्जुनको पङ्क्तिमा बस, भगवान्‌ले हामीलाई त्यहीँ आएर ज्ञान दिनुहुनेछ” । भगवान् पार्थको लागि प्रेमीजस्तै हुनुभयो र अर्जुनको लागि उहाँले आफ्नो सम्पूर्ण ज्ञानका द्वारहरू खोल्नुभयो ।
11.10
अनेकवक्त्रनयनम्, अनेकाद्भुतदर्शनम् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 10, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=vlirUTVFpRo', '2026-03-07', 'अनेक मुख र नेत्रहरूले युक्त, अनेक अद्भुत दर्शनीय, प्रशस्त अलौकिक दिव्य आभूषणहरूले युक्त र अनेकौँ दिव्य शस्त्रहरूलाई हातहरूमा लिनुभएका ।
11.11
दिव्यमाल्याम्बरधरं(न्), दिव्यगन्धानुलेपनम् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 11, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=vlirUTVFpRo', '2026-03-07', 'गलामा दिव्य मालाहरू र अलौकिक वस्त्रहरूलाई धारण गर्नुभएका एवं निधार तथा सारा शरीरमा दिव्य गन्धको लेप घस्नुभएका, सबै प्रकारका आश्चर्यहरूले युक्त, सीमारहित सबैतिर मुखहरू भएका विराटस्वरूप परमदेव परमेश्वरलाई अर्जुनले दर्शन गरे ।
ज्ञानेश्वर महाराज भन्नुहुन्छ, “दिव्य दृष्टि प्राप्त गरेपछि अर्जुनको ज्ञानचक्षु खुल्यो” । अर्जुनले भगवान्‌को
अनेकवक्त्रनयनम्
अर्थात् अनेक मुख र अनेक आँखा भएका,
अनेकाद्भुतदर्शनम्
अर्थात् जसमा अनेक अद्भुत दृश्यहरू देखिने र
अनेकदिव्याभरणम्
अर्थात् दिव्य आभूषणहरूले युक्त स्वरूपको दर्शन गरिरहेका छन् । त्यस्तै
दिव्यानेकोद्यतायुधम्
अर्थात् हातमा अनेकौँ दिव्य आयुध वा शस्त्रहरू धारण गर्नुभएको छ ।
दिव्यमाल्याम्बरधरं दिव्यगन्धानुलेपनम् ।
सर्वाश्चर्यमयं देवमनन्तं विश्वतोमुखम् ॥
भगवान्‌ले दिव्य माला र वस्त्र धारण गर्नुभएको छ, शरीरमा
दिव्यगन्धानुलेपनम्
अर्थात् अत्यन्त सुगन्धित लेप लगाउनुभएको छ । यसप्रकार
सर्वाश्चर्यमयम्
अर्थात् आश्चर्य नै आश्चर्यले युक्त र
अनन्तं विश्वतोमुखम्
अर्थात् जसको कुनै अन्त्य छैन, त्यस्तो विराट् रूप अर्जुनले देख्दछन् । सञ्जय धृतराष्ट्रलाई भन्दछन, “हे महाराज! भगवान्‌को त्यो रूप कस्तो थियो भने मानौँ हजारौँ सूर्य एकैसाथ आकाशमा उदय भएका हुन्” ।
11.12
दिवि सूर्यसहस्रस्य, भवेद्युगपदुत्थिता ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 12, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=vlirUTVFpRo', '2026-03-07', 'आकाशमा हजारौँ सूर्यहरू एकैसाथ उदय हुँदा जुन प्रकाश उत्पन्न हुन्छ, त्यो पनि त्यस विश्वरूप परमात्माको प्रकाशसमान सायदै होला ।
दिविसूर्यसहस्रस्य-
एकसाथ आकाशमा हजारौँ सूर्य प्रकाशमय हुँदा,
भा भवेत्-
जुन प्रकाश हुन्छ ।
सा स्याद्भासस्तस्य महात्मनः
- यस प्रकारको दृश्य म देखिरहेको छु, जसलाई उपमा दिन सम्भव नै छैन । सञ्जय यस अवस्थाको वर्णन गर्दै भन्दछन्, “हे राजन् धृतराष्ट्र! म पनि यो दिव्य रूप देखिरहेको छु” । यहाँ उपमा दिन कठिन छ, उपमाका माध्यमबाट बुझाउने प्रयास गरिएको छ । यदि आकाशमा हजारौँ सूर्यहरू एकैसाथ उदय भए भने जस्तो प्रकाश हुन्छ, त्यस परमात्माको प्रकाश पनि त्यस्तै छ ।
सञ्जय भन्दछन् कि मानौँ हजारौँ सूर्यहरू एकैसाथ आकाशमा उदित भएका छन्, तपाईँ त्यति नै प्रकाश सम्झनुहोस् । जब ओपेनहावरले १६ जुलाई १९४५ मा दोस्रो विश्वयुद्धका दौरान पहिलो परमाणु बमको विस्फोट देखे, तब उनलाई श्रीमद्भगवद्गीताको यही श्लोकको स्मरण भएको थियो । उनले त्यस प्रकाशको तुलना यसै श्लोकसँग गरेका थिए । यसपश्चात् अर्जुनले जे–जति दिव्यताहरू देखे, त्यसको वर्णन उनी स्वयम्‌ गर्नेछन् । अर्जुन नतमस्तक भए । उनी व्याकुल भएर मधुर वाणीमा बोल्न थाले । उनी आश्चर्यमा डुबे, उनका हातहरू जोडिए र शिर झुक्यो । त्यसपछि भगवान‌्को‌ स्तुति गर्दै अर्जुन भन्नुहुन्छ :
पश्यामि देवांस्तव देव देहे सर्वान्स्तथा भूतविशेषसङ्घान् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (11, 15, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=vlirUTVFpRo', '2026-03-07', 'यो वर्णन अर्जुनको मुखबाट प्रस्फुटित भइरहेको छ । यस भन्दा पछि अर्जुन विश्वरूप दर्शनको बर्णन गर्दछन् ।
प्रश्नोत्तर
प्रश्नकर्ता:-
अनन्त दाजु
प्रश्न:-
गीताजीमा जुन सञ्जयको नाम आउँछ, हामीलाई सञ्जयजीका आमाबुबाका बारेमा बताइदिनुहोस् । उनीको थिए र उनका आमाबुबा को थिए ?
उत्तर:-
सञ्जय निकै ठूला विद्वान् थिए । उनका आमाबुबाको विषयमा त मलाई कुनै जानकारी छैन । उनी सारथि थिए र निकै शिक्षित थिए । पहिलेको समयमा राजाहरूले विद्वान् व्यक्तिहरूलाई आफूसँगै राख्ने गर्दथे । सञ्जयले पनि धृतराष्ट्रलाई समय-समयमा विद्वत्तापूर्ण सल्लाहरू दिने गर्दथे । उनी केवल सारथि मात्र थिएनन्, बरु समय-समयमा धृतराष्ट्रलाई सल्लाह पनि दिने गर्दथे । धृतराष्ट्रले पनि सञ्जयलाई निकै विश्वास गर्थे । सञ्जयले गएर पाण्डवहरूलाई सम्झाएका पनि थिए कि, “धृतराष्ट्रका पुत्रहरू त उनको भनाइमा छैनन्, तर तपाईंहरू युद्ध नगर्नुहोस्, तपाईंहरू त समझदार हुनुहुन्छ । तपाईंहरू युद्धका लागि इन्कार गरिदिनुहोस्” । सञ्जय धृतराष्ट्रको दूत बनेर पाण्डवहरूलाई भेट्न गएका थिए । यसरी हामी देख्छौँ कि महाभारत मा सञ्जयका फरक-फरक भूमिकाहरू छन् ।
अन्तमा, हरि कीर्तन र हनुमान चालिसा श्रवण गर्दै एघारौँ अध्यायको पहिलो खण्डको विवेचन समापन भयो ।
यो विवेचन पढेर तपाईँलाई अवश्य पनि राम्रो लाग्यो होला भन्ने हामीलाई विश्वास लागेको छ । कृपया तल दिएको लिङ्क प्रयोग गरी हामीलाई आफ्नो प्रतिक्रियाहरू दिनुहोला ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (4, 32, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=0agtvtsQmFs', '2026-03-07', 'यी र अन्य विभिन्न प्रकारका यज्ञहरू वेदका वाणीहरूमा विस्तारपूर्वक वर्णन गरिएको छ । तिनलाई तिमीले मन, इन्द्रिय र शरीरका क्रियाहरूद्वारा सम्पन्न हुन्छ भन्ने ठान । यसलाई तत्त्वसाथ जानेर तिनको अनुष्ठान गर्‍यौ भने तिमी कर्मबन्धनबाट पूर्णतः मुक्त हुनेछौ ।
गीताको उद्देश्य हो– सम्पूर्ण संसार गीताको अर्थले भरियोस् र प्रत्येक कणमा परमात्मा हुनुहुन्छ भन्ने अनुभूति हामी सबैलाई होस् । यसैले हामीहरू कर्मयोग गर्दै, ज्ञानयोगतर्फ अघि बढौँ र अन्तमा भक्ति प्राप्त गर्नुलाई गन्तव्य ठानौँ ।
गीतामा भगवान्‌ले बताउनुभएको विभिन्न प्रकारका यज्ञहरूको वर्णन वेदहरूमा पनि गरिएको छ । ती सबै यज्ञमध्ये ज्ञानयज्ञ नै सबैभन्दा श्रेष्ठ हो । ज्ञानयज्ञसम्म पुग्नका लागि हामीले जीवनमा सबैप्रकारका विद्या आर्जन गर्नु आवश्यक छ । ज्ञानयज्ञमा ज्ञान बाँड्नुपर्छ । हामी श्रम, समय र वृत्ति सबैलाई बाँड्छौं; धेरैकुरा बाँड्दा घट्छन् तर ज्ञान यस्तो हो जसलाई बाँड्दा अझ बढ्छ । ज्ञानलाई आफ्नैमा राखेर कुण्ठित गर्न हुँदैन ।
4.33
श्रेयान्द्रव्यमयाद्यज्ञाज्, ज्ञानयज्ञः(फ्) परन्तप ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (4, 33, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=0agtvtsQmFs', '2026-03-07', 'हे परन्तप अर्जुन! द्रव्यमय यज्ञभन्दा ज्ञानमय यज्ञ अत्यन्त श्रेष्ठ हुन्छ । हे पार्थ! सम्पूर्ण किसिमका कर्महरू र पदार्थहरू तत्त्वज्ञानमा नै आएर समाप्‍त हुन्छन् ।
भगवान्‌बाट अनेक प्रकारका यज्ञहरूका बारेमा थाहा पाएपछि, अर्जुन यी मध्ये कुन यज्ञ उनका लागि बढी श्रेयस्कर छ त? भन्ने जिज्ञासा राख्दछन् । अर्जुनको जिज्ञासा मेटाउँदै, भगवान्‌ द्रव्य खर्च गरिएको यज्ञभन्दा पनि उत्तम ज्ञानयज्ञ हुन्छ भन्नुहुन्छ । द्रव्य, धन, सम्पत्ति खर्च गरेर गरिएको यज्ञमा केही समयपछि सबै सकिन थाल्छन्, त्यसको मात्रामा कमी हुँदै जान्छ तर ज्ञानयज्ञमा ज्ञान बाँडिने हुँदा ज्ञान झन्-झन् बढ्दै जान्छ । यो कहिल्यै खर्चेर सकिँदैन । हामीले जे जति कर्महरू गर्छौँ ज्ञानको समीपमा आएपछि सबै बिलिन भएर जान्छन्, सबै कर्महरू अकर्म भएर जान्छन् । जसरी सुरु सुरुमा सवारी साधन सिक्न लाग्दा ह्यान्डल, ब्रेक,क्लच,एक्सिलेरेटरमा मात्र ध्यान दिइराख्नुपर्ने हुन्छ तर सिकिसकेर अब्बल भएपछि कतै केही चलाए जस्तो लाग्दैन, दिमागले सबै काम आफैँ केही कष्ट नलगाई गर्छ । त्यस्तै ज्ञानमार्गमा पनि सुरुसुरुमा कष्टकर कर्महरू गर्नुपर्छ तर पछि सबै यति सहज लाग्छन् हामीले केही गरिरहेकै छैनौँ जस्तो अनुभव हुन्छ । ज्ञानयज्ञमा न पदार्थको आवश्यकता पर्दछ न त क्रियाकै आवश्यकता पर्छ, यसमा त केवल ज्ञानमात्र हुनु आवश्क छ । ज्ञानको बारेमा स्वामी रामदास महाराज भन्नुहुन्छ -
पाहवे आपणासी आपण, ह्या नावे ज्ञान ।
सबैभन्दा ठूलो ज्ञान आफूले आफूलाई जान्नु, म को हुँ? भनेर स्वयंलाई जान्नु, आत्मज्ञान हुनु हो । आफू केवल देह हुँ या मन हुँ या बुद्धि हुँ या आँखा, नाक, कान इन्द्रियहरू हुँ या यी सबैभन्दा भिन्दै म अरू नै केही हुँ त? यही सबै जीव ,जगत र जगदीश्वर बीचको पारस्परिक सम्बन्ध गहिराईबाट जान्नु नै वास्तविक ज्ञान हो । आफूले आफूलाई जान्नु नै सर्वश्रेष्ठ ज्ञान हो । कहिलेकाहीँ हामी परीक्षा दिन जाँदा प्रश्नपत्रमा सोधिएको हुन्छ- प्रश्न १ अनिवार्य, बाँकी नौ मध्ये जम्मा पाँचवटाको उत्तर दिनुहोस् । पाँच प्रश्न छान्न पाउने हुँदा कहिलेकाहीँ छानेर उत्तर लेख्दा लेख्दै अनिवार्य प्रश्नको उत्तर लेख्नै छुट्छ । यो सांसारिक जीवन पनि त्यस्तै हो । महत्वपूर्ण कुराहरू हामीबाट छुटिरहेको हुन्छ, अन्यमै हामी अल्मलिरहेका हुन्छौँ र एक दिन शरीर छोड्ने बेला आइपुग्छ ।
आफूले आफूलाई थाहा पाउन नसक्नु । आफ्ना आँखाले देख्न जरुरी छैन तर स्वयंले स्वयंलाई नै जान्नु एकदम महत्वपूर्ण छ । जसरी भिडमा जाँदा बालकलाई एउटी आमाले हात समातेर कहिल्यै छोड्दिनन् र हराउन दिँदिनन् त्यसैगरी भगवतद्गीताले पनि हामीलाई हराउन नदिन, र आफूलाई आफूसँग परिचित गराउन खोज्नुहुन्छ । हामी केवल देह/शरीर होइनौँ । यो क्षीण हुने हुनाले देह बुद्धिले तेरो र मेरो भन्ने भावना मात्र बढाउँछ । भगवद्गीतामा सुरुमै धृतराष्ट्रले मेरा र पाण्डुका पुत्रहरू भनेर भेद गर्ने कुरा गर्दछन् किनकि उनी अन्धा हुनुको साथै अज्ञानी पनि थिए, उनमा देह बुद्धि अत्यन्त बढी थियो । त्यसैले भगवान्ले- आत्मज्ञानी हुनुपर्छ तर आत्मज्ञान यत्तिकै प्राप्त नभई सद्गुरुको समीपमा रहेर मात्र प्राप्त गर्न सकिन्छ भन्नुहुन्छ ।
4.34
तद्विद्धि प्रणिपातेन, परिप्रश्नेन सेवया ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (4, 34, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=0agtvtsQmFs', '2026-03-07', 'त्यस तत्त्वज्ञानलाई तिमी तत्त्वदर्शी ज्ञानीमहापुरुषहरूका सामिप्यमा गएर सिक । उनीहरूलाई उचित तरिकाले साष्टाङ्ग दण्डवत् प्रणाम गर्नाले, उनीहरूको सेवा गर्नाले र कपट त्यागेर सरलतापूर्वक प्रश्न गर्नाले परमात्मारूपी तत्त्वलाई विशिष्ट किसिमले जानेका ती तत्त्वदर्शी ज्ञानीमहापुरुषहरूले तिम्रो भक्तिदेखि प्रसन्न भएर तिमीलाई तत्त्वज्ञानको उपदेश प्रदान गर्नेछन् ।
भगवान्‌ आत्मज्ञान प्राप्त गर्न कस्तो पात्रताको आवश्यकता पर्दछ भन्ने बताउँदै हुनुहुन्छ-
तत् विद्धि
- साथमा रहेर जान ।
प्रणिपातेन
- उनको साथमा रहेर, दण्डवत् प्रणाम गरेर र समर्पित भएर ।
सेवया
- यथायोग्य सेवा गरेर
परिप्रश्नेन
- सरल मनले नजानेका कुराहरू छलकपट नगरी सोधेर ।
शिष्य दुई प्रकारले बन्न सकिन्छ । एक
संसनात्
शिष्य बनेर अर्को
शासनात्
शिष्य बनेर । पहिलो आफ्ना मनभित्रका संशय निवारण गरेर अर्को गुरुको शासन शिरोधर गर्दै आज्ञापालक शिष्य बनेर ज्ञान प्राप्त गर्न सकिन्छ ।
ते तत्त्वदर्शिन: ज्ञानिन:
ती ज्ञानी महात्माहरूले
ज्ञानम् उपदेक्ष्यन्ति
तत्व ज्ञानको उपदेश तिमीलाई दिनुहुनेछ । ती सबै विषयहरूको ज्ञाता, अनुभवी महात्माहरूले मात्र ज्ञान दिन सक्नुहुनेछ । हुन त हिजो आज हरेक प्रश्नको उत्तर गुगलमा भेट्न सकिन्छ, अनलाइन बसेर ज्ञान लिन सकिन्छ । तर गुरुको समीपमा रहेर, गुरुको सेवा गर्दै, उहाँका आज्ञा पालन गर्दै, भावनात्मक मनको अनुभव लिँदै, ज्ञान सिकिन्छ त्यो अतुलनीय हुन्छ । यस्तो ज्ञान लिनको लागि गुरु पनि शास्त्र ज्ञानमा प्रवीण, तत्वदर्शी, अनुभवी ज्ञानी नै चाहिन्छ । भगवत् साक्षात्कार गुरुले नै शिष्यलाई भगवान्‌को साक्षात्कार गराउन सक्नुहुनेछ अन्यले सक्दैनन् ।
एक दिन गुरुकुलमा गुरु आफ्ना शिष्यहरूलाई ज्ञान दिइरहनु भएको थियो । त्यसै बीचमा रहेका एक शिष्यले गुरुलाई सोध्छन् – गुरुज्यू! हजुरसँग अनेकौँ शिष्यहरू आउँछन् केही समयपछि उनीहरू मध्ये कोही पूर्ण रूपान्तरित पनि भएर जान्छन् । एकै शिक्षा दिँदा पनि उनीहरूको रूपान्तरण किन फरक फरक भएको? जवाफमा गुरुज्यू भन्नुहुन्छ - उनीहरूको रूपान्तरण मैले गरेर नभई उनीहरूको आफ्नै समर्पणले भएको हो । जो जति समर्पित हुन सक्छ त्यही अनुसार रूपान्तरित हुने हो भन्नुहुन्छ । अब यसरी रूपान्तरण गराउन सक्ने, चरणमा समर्पित हुन जान लायक, तत्त्व ज्ञानी सद्गुरु कसरी भेट्टाउने भन्ने जिज्ञासा हुन सक्छ । यस विषयमा ज्ञानेश्वर महाराज भन्नुहुन्छ -
तैसें स्मरतेनि आदरें, सबाह्य सात्विकें भरे।
जंव काठिणपण विरे, अहंभावाचे ॥
विषयांचा विसरु पडे, इंद्रियांची कसमस मोडे।
मनाची घडी घडे, हृदयामाजीं ॥
जसरी भगवान्‌को मूर्ति अगाडि उभिएर दर्शन गर्दा हामीभित्र कुनै अहंकार नरही नतमस्तक हुन्छौँ । त्यसरी नै गुरु यस्तो हुनुपर्छ जसको स्मरण मात्रले पनि मनले सात्विकताको अनुभूति गरोस् अहंकार र विषयहरू तिर ध्यानै नजाओस् । त्यस्ता गुरुहरूको सामिप्यमा रहँदा इन्द्रियहरूको कारण विषय भोग प्रतिको छट्पटाहट क्षीण भएर जान्छ र चञ्चल मन शान्त हुन्छ, सद्गुरुको पहिचान यसरी गर्न सकिन्छ । गुरुको पहिचान गरिसकेपछि गुरुप्रति शरणागति कसरी हुने भन्ने सन्दर्भमा सन्त महात्माले सुन्दर मार्गदर्शन गराउनुभएको छ -
तनु-मनु जीवे तयाच्या चरणी लागावे
अगर्वता करावे दास्य सकळ ।
गुरुको चरणमा यसरी तनमन लगाएर समर्पित हुनु जहाँ गर्व, अहङ्कारलाई त्यागेर आफ्ना मनका शङ्काहरू निवारण गर्दै ज्ञान प्राप्त गर्नुपर्छ । यसरी नै आत्मज्ञानी बन्न सकिन्छ । भगवान्‌ले अर्जुनलाई तिमीमा यति धेरै ज्ञान हुँदाहुँदै पनि मोहका कारणले यति धेरै छट्पटाहट भई धनुष भुइँमा राखेका हौ भन्नुहुन्छ ।
4.35
यज्ज्ञात्वा न पुनर्मोहम्, एवं(य्ँ) यास्यसि पाण्डव ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (4, 35, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=0agtvtsQmFs', '2026-03-07', 'हे पाण्डव! त्यस तत्त्वज्ञानलाई प्राप्‍त गरेपछि तिमी अहिलेको जस्तै फेरि मोहमा पर्नेछैनौँ । जुन तत्त्वज्ञानद्वारा निःशेषभावले सम्पूर्ण प्राणीहरूलाई तिमीले सर्वप्रथम ''आफ्नो अन्तरआत्मामा'' देख्नेछौ र त्यसपछि ''म सच्चिदानन्द वासुदेव परमात्मा परमेश्वरमा'' देख्नेछौ ।
भगवान्‌ले भन्नुहुन्छ- आत्मज्ञान प्राप्ति पश्चात आफूभित्रको सबै द्वन्द समाप्त भई सबै प्रकारका मोहबाट मुक्त भइन्छ । ज्ञानद्वारा नि:शेष भावले यो पञ्चमहाभूतले बनेको हाम्रो शरीर पशुपंक्षी सबै योनीहरू सबैलाई आफैँमा पाउनेछौ र म भित्र पनि स्वयंलाई नै देख्नेछौ । तिमी र म भिन्न नभएकोले सबैमा परमात्मा तत्व नै देख्नेछौ भन्नुहुन्छ । महाभारतमै यक्षले युधिष्ठिरलाई कुन दिशा सर्वश्रेष्ठ भनी प्रश्न गर्दा युधिष्ठिरले सन्तोदिक- सन्तले देखाउनुभएको मार्ग भनी उत्तर दिएका थिए र भाइहरूलाई फेरि जीवित बनाउन सफल भएका थिए । सन्तको शरणमा बसेर ज्ञान प्राप्त गर्दा, गुरु कृपाद्वारा आत्मज्ञान प्राप्त भई सबैलाई भगवान्‌कै स्वरूपमा देखिन्छ र मोहरूपी अन्धकारबाट मुक्त भइन्छ । यसै सन्दर्भमा ठाकुरवाणीमा एउटा कथा छ –
एक दिन एउटी गर्भिणी सिंहिनीले सिकार गर्ने क्रममा बाख्राको हुलमा आक्रमण गर्छे । माथिबाट हाम फालेर आक्रमण गर्दा असामान्य शरीरले गर्दा भुइँमा बजारिन पुग्छे । बजारिँदा चोट लागेर घाइते हुन्छे । त्यसको केही समयमा त्यहीँ एउटा डमरुलाई जन्म दिएर मर्छे । त्यसरी जन्मिएको डमरु बाख्रासँग हुर्किन्छ । बाख्रा जस्तै कराउन लाग्छ र घाँस खान पनि सिक्छ । जो जस्तोमा जन्मियो, हुर्कियो त्यही सिक्ने हो । केही समय पश्चात् एउटा बाघले बाख्राको हुलमा घाँस खाइरहेको डमरु देख्छ । राति उक्त डमरुलाई चोरेर आफ्ना समूहमा लैजान्छ र हामी घाँस खाने नभई मासु खाने जात हो भनेर उसको पहिचान गराउँछ । हो त्यस्तै हाम्रो जीवनमा पनि हामीले आफूले आफूलाई भित्रबाट चिन्न सकेका हुँदैनौँ सद्गुरुको आवश्यकता पर्दछ । आत्मतत्वको बोध हुन गुरु कृपा चाहिन्छ आत्मा तत्वद्वारा हाम्रा जीवनका अवरोधहरू जसलाई हामी पाप-दोष भन्छौँ लाई सजिलै पन्छाउन सक्छौँ ।
4.36
अपि चेदसि पापेभ्यः(स्), सर्वेभ्यः(फ्) पापकृत्तमः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (4, 36, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=0agtvtsQmFs', '2026-03-07', 'यदि तिमी अन्य सम्पूर्ण पापीहरूभन्दा पनि धेरै पापी छौ भने पनि तिमी ज्ञानरूपी डुङ्गाको सहाराले निःसन्देह समस्त पापरूपी सागरबाट राम्रैसँग पार हुन सक्नेछौ ।
चेत सर्वेभ्य: पापेभ्य अपि-
यदि तिमी पापी भन्दा पनि पापी छौ र यदि गलत मार्गमा हिँडेका छौ भने पनि
ज्ञानप्लवेन एव
- ज्ञानरुपी डुङ्गाको सहाराबाट
सर्वं वृजिनं सन्तरिष्यसि
- यो पापको समुद्र, संसार सागर जसमा निकै फोहर छ, उथलपुथल छ यसबाटपार पाउन सकिन्छ । जसरी रत्नाकर डाँकु कोटी राम नामको जपले अन्त:करण शुद्ध भई महर्षी वाल्मिकी बने र रामचरित्र कथा लेखे, जसलाई हामी वाल्मीकी रामायण भन्छौँ । कुनै काम नगर्नु, कुनै व्रत नगर्नु यो पाप होइन । कसैको अन्त:करणमा ठेस पुर्याउनु, कसैको मृत्युको कारण बन्नु यी पाप हुन् । धर्मशास्त्रमा बताएका छ प्रकारका पाप मध्ये- कसैको पत्नी हरण गर्नु, कसैको घर जलाउनु, कसैको सम्पत्ति नष्ट गर्नु यस्ता पाप पनि नष्ट भएर जान्छ । सुखदेवजी महाराज भन्नुहुन्छ, “प्रायश्चित गरेर, नियम धारण गर अनि भगवत् नामको जपबाट पाप,दोष मेटिन्छ” ।
मनुष्य गलती का पुतला है, जो अक्सर हो ही जाती है।
जो कर ले ठीक गलती को, उसे इन्सान कहते हैं।
यदि आफ्नो गल्तीको महसुस भयो र खराब बानी छोड्नुपर्छ- भन्ने भावना जाग्यो भने मात्र हाम्रा पापहरू ज्ञानको अग्निमा भस्म हुन्छन् ।
4.37
यथैधांसि समिद्धोऽग्नि:(र्), भस्मसात्कुरुतेऽर्जुन ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (4, 37, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=0agtvtsQmFs', '2026-03-07', 'हे अर्जुन! जसरी बलेको अग्निले दाउरालाई जलाएर भस्म गरिदिन्छ, त्यसरी नै ज्ञानरूपी अग्निले सम्पूर्ण कर्महरूलाई भस्म गरिदिन्छ ।
भगवान् भन्नुहुन्छ-
यथा समिद्ध अग्नि एदांसी भस्मसात् कुरुते-
जसरी प्रज्वलित अग्नि सबै दाउराहरूलाई तुरुन्तै जलाउँछ त्यसैगरी तथा
ज्ञानाग्निः सर्वकर्माणि भस्मसात्कुरुते
- ज्ञानको अग्निमा सारा कर्म जल्दछन् । जसरी कुनै आगोमा भुटेको बीऊमा अंकुरण आउन सक्दैन त्यसैगरी यो ज्ञानाग्नीको कारण खराब कर्महरू पोलिएको बिऊ-
दग्धबिज
जस्तै हुन्छ । अनि हाम्रो जुन पाप र पुण्य छ उसको सारा परिणामबाट त्यो जीव मुक्त भएर जान्छ । कर्म तीन प्रकारका हुन्छन्- प्रारब्ध, सञ्चित कर्म, कृयमाण कर्म । हाम्रो सञ्चित कर्म अथवा हामीले धेरै जन्महरूमा गरेका छौँ तर त्यसको फल अहिलेसम्म भोगेका छैनौँ । अब ती सञ्चित कर्म फल दिन तयार भएर प्रारब्ध बन्दछ । यी सबै ज्ञानको अग्निमा भष्मसात भएर जान्छ । ज्ञानको महिमा गाँउदै भगवान् भन्नुहुन्छ, “ यो पावन ज्ञान कसरि पाईन्छ त?”
4.38
न हि ज्ञानेन सदृशं(म्), पवित्रमिह विद्यते ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (4, 38, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=0agtvtsQmFs', '2026-03-07', 'निःसन्देह यो संसारमा ज्ञानका समान पवित्र पार्ने अर्को कुनै साधन छैन । जसले योगद्वारा भलिभाँती किसिमले सिद्धि प्राप्‍त गरिसकेको छ, त्यस्तो कर्मयोगी पुरुषले समय आएपछि स्वयं आफैँ नै आफ्नो आत्माको अनुभूति गर्नेछ ।
भगवान् ज्ञानको महिमा बताउँदै भन्नुहुन्छ, “यो ज्ञान भन्दा माथि, यो ज्ञान भन्दा पवित्र (सबै ज्ञान पवित्र हुँदैनन्) कुनै अरु ज्ञान छैन । यो सम्पूर्ण समस्याको समाधान गर्ने ज्ञान हो । भगवान् १३ अध्यायमा भन्नुहुन्छ –
अध्यात्मज्ञाननित्यत्वं(न्), तत्त्वज्ञानार्थदर्शनम्।
एतज्ज्ञानमिति प्रोक्तम्, अज्ञानं(य्ँ) यदतोन्यथा॥१३.११॥
अध्यात्म-अधिआत्म
- आफूभित्र जानु, आफुलाई चिन्नु । अध्यात्म भनेको ठूला ठूला शास्त्रहरू ग्रन्थहरू पढ्नु मात्र नभइ शास्त्र सम्मत व्यवहार अवलम्बन गर्नु पनि हो आफ्नो आत्माभित्र हेर्नु, आफैभित्र प्रवेश गर्नु, भित्रको सारा मैला, फोहोर धोएर पूर्वाग्रह नष्ट गर्दै त्यहाँसम्म पुग्नु हो । भगवान् भन्नुहुन्छ- इह ज्ञानेन सदृशं पवित्रं हि न विद्यते यो ज्ञानभन्दा पवित्र ज्ञान सृष्टिमा अर्को छैन । आफ्नो चिनारी परिचय दिइरहेको छ यो ज्ञानले ।
न विद्यते
- ‘यो कहिले भेटिन्छ त’ ? यसमा हतार गरेर हुँदैन ।
तत्कालेन योग संसिद्ध स्वयं आत्मनि विन्दति कालेन
- यसको लागि केही समय कुर्नुपर्छ । त्यो मार्गमा हिँडिरहनुपर्छ । हामी सांसारिक कार्यहरूमा अलमलिरहेका हुन्छौँ । संसारको सारा काम, क्रोध, मद, मात्सर्य, लोभ मोह हामीभित्र प्रवेश गर्छ । किनकि संसार विकारहरूले भरिएको छ तर परमात्मा अविकारी र दोषरहित हुनुहुन्छ । अविकारीको ज्ञान लिनु छ भने विकारबाट मुक्त हुनुपर्दछ । तुलसीदासजी भन्नुहुन्छ, “भगवान् तपाईँ म भित्र आउनुभो भने सबै बिकार हटेर जान्छ” ।
इति वदति तुलसीदास शंकर
शेष मुनि मन रंजनं ।
मम् हृदय कंज निवास कुरु
कामादि खलदल गंजनं ॥
तुलसीदास सहित हाम्रा सन्तहरूलेको मत छ- भगवान् अविकारी हनुहुन्छ, उहाँ हामी भित्र प्रवेश गर्नुभयो भने हाम्रा सारा विकार हटेर जान्छन् ।
काले न योग सिद्ध
: - समय क्रममा योग सिद्ध हुन्छ । कुनै निश्चित समय सम्म त्यो मार्गमा हिँड्दै गरेपछि हुन्छ आफूलाई चिनिन्छ । एक पटक नारदजीसँग दुईजना शिष्यहरू आए । एक शिष्यले सोधे- हामी निकै आराधना, जप, तप गरिरहेका छौँ । भगवान् हामीलाई कहिले दर्शन दिनुहुन्छ? कसरी हामीभित्र अवस्थित हुनुहुन्छ? कुन कारण ढाकिनुभएको छ ? कति वर्ष लाग्छ? नारदजी भन्नुहुन्छ- यो रुखमा जति पात छन् त्यति वर्ष र त्यति जन्म लाग्छ । शिष्यले भने- त्यसो भए त म अब जप-तप गर्न छाडिदिन्छु । यो कहिले हुने हो थाहा नै छैन । अनि दोस्रो शिष्यलाई प्रश्न गर्दा पनि त्यही उत्तर पाए । उनले भने- ठिक छ कुनै दिन त भेटिन्छ, गर्दै जाऊ । भगवान् १०औँ अध्यायमा भन्नुहुन्छ-
तेषामेवानुकम्पार्थमहमज्ञानजं तमः।
नाशयाम्यात्मभावस्थो ज्ञानदीपेन भास्वता ।।१०.११।।
हे अर्जुन ! म उसँग हिँडिरहेको हुन्छु, उस माथि अनुकम्पा गर्नको लागि म स्वयं उसको अन्तकरणमा आत्मदीप जलाउँछु । एउटा बच्चाले आफ्नी आमालाई भन्यो- आमा! मैले बिउ रोपेको १०/१२ दिन भयो तर त्यो अहिलेसम्म उम्रिएको छैन । आमाले- पानी राखिरहेको छौ भनेर सोधिन् । उसले भन्यो- दिनदिनै पानी राख्छु अनि उम्रियो कि उम्रिएन भनेर निकालेर हेर्छु । यसरी दिनदिनै निकाल्दै हेर्दै गरेपछि अङ्कुरित हुन पाउँदैन र उम्रिदैँन ।
काले न योग संसिद्ध:
- उसलाई समय दिनुपर्छ । बच्चा जन्मनको लागि पनि नौ महिनाको समय आवश्यक हुन्छ । समय पनि हरेकको क्षमता र वेग अनुसार हुन्छ । वेग कस्तो हुन्छ त!- एकपटक एक व्यक्ति कुनै गाउँमा पुग्यो र त्यहाँको मानिससँग यहाँ मन्दिर कति टाढा पर्छ?, कति बेरमा पुग्न सकिन्छ? भनेर सोध्यो । त्यो गाउँको मानिसले उसलाई- मेरा अगाडि हिँडेर देखाउ भन्यो । उसले सोध्यो, “हिँडेर देखाउने?” मैले बुझिन । त्यो व्यक्तिले भन्यो, “तिम्रो हिडाइको वेग कति छ हिँडेर देखाउ अनि मात्र तिमी कति समयमा मन्दिर पुग्छौ म भन्न सक्दछु” । त्यसैले भगवान् भन्नुहुन्छ- तत्काले न योग संसिद्ध: स्वयं आत्मनि विन्दति ।।
4.39
श्रद्धावाँल्लभते ज्ञानं(न्), तत्परः(स्) संयतेन्द्रियः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (4, 39, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=0agtvtsQmFs', '2026-03-07', 'जो जितेन्द्रिय तथा साधनापरायण एवं श्रद्धावान् छ, त्यस पुरुषले ज्ञान प्राप्‍त गर्दछ र ज्ञान प्राप्‍त गरेपछि उसले तत्काल भगवत् प्राप्‍तिरूपी परमशान्तिलाई प्राप्त गर्दछ अर्थात् मुक्ति पाउँदछ ।
भगवान् भन्नुहुन्छ-
श्रद्धावान् लभते ज्ञानं तत्परः संयतेन्द्रियः
। जसमा श्रद्धा छ, उसैले मात्र ज्ञान पाउनेछ । दोस्रो कुरा हो, फेरि आफ्ना सद्गुरुका चरणहरूमा श्रद्धा, शास्त्रहरूमा श्रद्धा, शास्त्रका वचनहरूमा श्रद्धा, सनातन धर्ममा श्रद्धा । अब सनातन धर्मबाहेक अरू मानिसहरू पनि ज्ञान पाउन चाहन्छन् होला, उनीहरूलाई पनि आफूले मानेको को जे-जे छ त्यसमा र सद्गुरुमा श्रद्धा आवश्यक पर्दछ । त्यसका साथसाथै भगवान् भन्नुहुन्छ-
संयतेन्द्रियः
अर्थात् इन्द्रियहरूमा संयम र साधनमा पनि तत्परता देखाउने । तत्परता, संयतेन्द्रिय र श्रद्धा तीनवटा कुरा भयो भने मात्र त्यो ज्ञान प्राप्त हुनेछ ।
हामी श्रद्धाको ढोँग गर्दैनौँ ।
श्रद्धया सत्यमाप्यते
- अर्थात् श्रद्धाबाट नै सत्यको अनुभूति हुन्छ । भगवान् भन्नुहुन्छ-
ज्ञानं लभते श्रद्धावान् लभते ज्ञानं संयतेन्द्रियः तत्परः
। श्रद्धावान्‌ले नै त्यो ज्ञान प्राप्त गर्न सक्छ । त्यो ज्ञान प्राप्त गरेपछि के हुन्छ?
ज्ञानं लब्ध्वा
- ज्ञान प्राप्त गरेपछि,
अचिरेण परां शान्तिमधिगच्छति
- कुनै विलम्ब नगरी, तत्कालै उसले यस्तो परम शान्ति प्राप्त गर्दछ कि अब अशान्ति उसकहाँ फर्केर पनि आउँदैन । तुलसीदासजी भन्नुहुन्छ- जो रामजीको सगुण साकार स्वरूपको आराधना गर्नेहरू छन्, उनीहरूका लागि-
नमामीशमीशान निर्वाणरूपं
विभुं व्यापकं ब्रह्मवेदस्वरूपम् ।
निजं निर्गुणं निर्विकल्पं निरीहं
चिदाकाशमाकाशवासं भजेऽहम् ॥
अब यो ज्ञान केवल सैद्धान्तिक ज्ञान होइन । यो व्यावहारिक ज्ञान हो ।
नमामीशमीशान
- अनुभूतिको ज्ञान हो । जस्तै रसवरीको ज्ञान- रसवरी के हो, कस्तो हुन्छ? भन्ने जान्नु पर्यो भने हामी इन्टरनेटमा खोज्छौँ उसले ‘त्यो सेतो हुन्छ, त्यो गोलो हुन्छ, त्यसलाई चिनीबाट बनेको चास्नीमा डुबाइन्छ, र त्यो गुलियो हुन्छ’ भन्ने बताइदिन्छ । यो सबै सैद्धान्तिक ज्ञान भयो । त्यसबाट हामी अनुभव लिन सक्दैनौँ तर कसैले आएर त्यो रसवरी हाम्रो जिब्रोमा राखिदियो भने अनुभूतिको ज्ञान प्राप्त हुन्छ । यसलाई अपरोक्ष ज्ञान भनिन्छ । यो अपरोक्ष ज्ञान सैद्धान्तिक भन्दा भिन्न हुन्छ । त्यसैले भगवान् भन्नुहुन्छ- त्यो अपरोक्ष ज्ञान प्राप्त भएपछि अशान्ति मेटिएर परम शान्ति प्राप्त हुन्छ । त्यो आत्मज्ञानको छट्पटी अन्तरमनमा निर्माण भएपछि ज्ञानेश्वर महाराजले भनेझैँ-
आत्मसुखाचिया गोडिया
विटे जो या सकल विषया
जयाचा इंद्रिया मानु नाही ।
त्यो जसले यी सबै विषयहरूलाई पन्छाउन सक्छ, त्यो आत्मसुखका लागि छट्पटाउँछ ।
तया तेच गिवसत ज्ञान पावे सुनिश्चित जयाचीनी अचुंबित शांतसी ।
उहाँ भन्नुहुन्छ-
त तेच गिवसत
- त्यो ज्ञान उसलाई खोज्दै आउँछ । ते ज्ञान पावे सुनिश्चित- त्यो ज्ञान अवश्य पाउँछ । त्यो ज्ञान प्राप्त हुनुको लक्षण
जयाचे अचुंबित शांत से
- यसबाट यस्तो शान्ति प्राप्त हुन्छ कि त्यो शान्तिलाई कसैले चोट नै पुर्‍याउन सक्दैन, अशान्तिमा बदल्नै सक्दैन ।
4.40
अज्ञश्चाश्रद्दधानश्च, संशयात्मा विनश्यति ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (4, 40, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=0agtvtsQmFs', '2026-03-07', 'विवेकहीन र श्रद्धारहित संशययुक्त पुरुष परमार्थदेखि अवश्य पनि भ्रष्ट भएर जान्छ । यस्तो संशययुक्त पुरुषका लागि न त यो लोक हितकारक छ, न त परलोक छ; न त त्यसलाई सुख नै मिल्छ ।
भगवान् भन्नुहुन्छ- केही मानिसहरू शास्त्रका कुरा मान्न तयार नै हुँदैनन्, धेरै तर्क गर्छन् । अब हेर्नुहोस्,
श्रद्धावान् लभते
- श्रद्धा राख्ने व्यक्तिले मात्र ज्ञानको लाभ लिन सक्छन् । जस्तो कि, हाम्रा विद्वानहरू द्वारा लिखित पुस्तकका सांसारिक विषयहरू श्रद्धापूर्वक अध्ययन गर्दा हामीले त्यसबाट ज्ञान प्राप्त गर्छौँ । जब हामी विद्युतीय शास्त्रमा परमाणुको बारेमा पढ्छौँ- रदरफोर्डको परमाणुको नमुना अनुसार परमाणुको केन्द्र हुन्छ, त्यसमा धनात्मक कण र तटस्थ कण हुन्छन्, ऋणात्मक कणहरू घुम्छन् । अक्सिजनमा त्यस्ता कण कतिवटा होलान्, हाइड्रोजनमा कति होलान्? जुन हामीले देखेका हुँदैनौँ । तर श्रद्धा भएको हुनाले विश्वास गर्दछौँ । त्यसबाट ज्ञान प्राप्त गर्छौँ ।
अर्को उदाहरण, कसैले बिन्दुको व्याख्या गर्‍यो- बिन्दु एउटा यस्तो अस्तित्व हो जसको लम्बाइ, चौडाइ र मोटाइ हुँदैन । जब कुनै शिक्षकले ब्ल्याक बोर्डमा बिन्दु बनाइदिनुभयो । तब विद्यार्थीले भन्छ- यसको त लम्बाइ, चौडाइ र मोटाइ केही न केही देखिइरहेको छ । शिक्षक भन्नुहुन्छ- बिन्दु एउटा यस्तो अस्तित्व हो जुन पूर्ण रूपमा देखाउन सकिँदैन, त्यो एउटा धारणा हो । यो धारणा ब्ल्याक बोर्डमा पनि देखाउन सकिँदैन । तसर्थ उहाँहरू के भन्नुहुन्छ भने- अब तिमीले ज्यामिति पढ्नु छ, तसर्थ तिमीले बिन्दु हो भन्ने मान्नु पर्छ यसमै श्रद्धा राख । अब यसमा श्रद्धा राखे मात्र अगाडिको ज्यामिति पढ्न सक्नेछौ । रदरफोर्डको नमुनामा श्रद्धा राखे मात्र विद्युतीय शास्त्र पढ्न सक्नेछौ । तसर्थ सांसारिक ज्ञानका लागि पनि हामीले पहिलेका विद्वानहरूमा श्रद्धा राख्नुपर्छ । यो त आत्मज्ञानको कुरा हो । आत्मज्ञान सम्पन्न व्यक्तिमा श्रद्धा राख्नुपर्नेछ । श्रद्धा नभएका मानिसहरू आफूलाई नास्तिक ठान्छन् । वास्तवमा नास्तिक त कोही पनि हुँदैन । तर उनीहरू सर्वव्यापी भगवान्‌लाई पनि मान्न तयार छैनन् ।
जो अज्ञानी, विवेकरहित र अश्रद्धालु छन्, जो श्रद्धा राख्न तयार छैनन् उनीहरूको के हुन्छ? भगवान्‌ले उनीहरूलाई श्रद्धाको बारेमा नबताउनु र उनीहरूलाई भगवद्गीता पनि नपढाउनु भन्नुभयो । तर हाम्रा सन्त महात्माहरू भन्नुहुन्छ- पढाइदेऊ, हुनसक्छ उनीहरू यो मार्गमा हिँड्नेछन् ।
संशयात्मा विनश्यति
- यस्तो संशययुक्त मानिसको विनाश हुन्छ यानी उसले आफ्नै नाश गर्दछ ।
संशयात्मन नायं लोक न अस्ति न पर च सुखम
- जो मानिसहरू स्वयंको पहिचान गर्न तयार हुँदैनन् उनीहरूलाई यो लोक र परलोकमा पनि शान्ति हुँदैन । जो देह बुद्धिले जीवन बिताउँछन् तिनीहरूमा आत्मबुद्धि अलिकति पनि विकसित हुँदैन । आत्मप्रकाश प्राप्त गर्दैनन् ।
‘भगवान् छैनन्’ भन्नेहरूका लागि ठाकुर रामकृष्ण देवले भन्नुहुन्छ- के तिमीहरूले भगवान्‌लाई खोज्यौ त? उहाँ भन्नुहुन्छ- हामी भान्सामा राखिएका सबै डब्बाहरूमा खोज्यौँ र चिनी कतै फेला पारेनौँ भने मात्र ‘हाम्रो घरमा चिनी छैन’ भनेर भन्छौँ । त्यस्तै हामीले ईश्वर नखोजेरै ‘ईश्वर छैन’ भनिरहेका छौँ । खोज्नाले भेटिन्छ, खोज्नाले साथ चल्छ, खोज्नाले अनुभूति आउँछ र खोज्नाले ईश्वरसँग सम्बन्ध बन्छ ।
जेथे जातो तेथे तू मांगाती सालविशहाती धरोनिया
जहाँ म जान्छु, त्यहाँ तिमी मेरो साथमा हुन्छौ । देखियोस् नदेखियोस्, ईश्वरले मेरो हात समातेर मलाई हिँडाउनुहुन्छ । यो हाम्रा सन्त महात्माहरू भन्नुहुन्छ किनभने ऊहाँहरूलाई यसको अनुभूति हुन्छ । भगवान् भन्नुहुन्छ- जो श्रद्धावान्, अध्ययनशील र ज्ञानवान् हुन्छन् उनीहरू प्रकृति र पुरुषको ज्ञानमा ‘नेति-नेति’ गरेर पुग्छन्, तर जसलाई स्वयंको पहिचान गर्ने इच्छा छैन, भक्तिको, योगको र ज्ञानको मार्गमा हिँड्नेलाई नकार्छन् उनीहरूले सुख-शान्ति पाउँदेनन् ।
4.41
योगसन्न्यस्तकर्माणं(ञ्), ज्ञानसञ्छिन्नसंशयम् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (4, 41, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=0agtvtsQmFs', '2026-03-07', 'हे धनञ्जय! जसले कर्मयोगको विधिले समस्त कर्महरूलाई परमात्मामा अर्पण गरिदिएको छ र जसले विवेकद्वारा समस्त शंशयहरूको नाश गरिदिएको छ, त्यस्तो आत्मज्ञानी वा अन्तःकरण भएको पुरुषलाई कर्महरूले बाँध्न सक्दैन ।
भगवान् भन्नुहुन्छ- “हे अर्जुन! तिमी यस कर्मको परिणामबाट मुक्त हुन चाहन्छौ तर तिमी युद्धको कर्म र त्यसको परिणामबाट डराइरहेका छौ, त्यसैले तिमीले धनुष राख्यौ” । हामी पनि कहिलेकाहीँ डरका कारण आफ्ना कर्तव्य कर्महरू बिर्सन्छौँ । परिणामको भयले गर्दा एउटा विद्यार्थी परीक्षा दिन डराउँछ, अन्तर्वार्ताका लागि डराउँछ । तर यो सबै छट्पटी ज्ञानले समाप्त हुनेछ ।
योगसंन्यस्तकर्माणम्
- कर्मयोगद्वारा आफ्ना सम्पूर्ण कर्महरू परमात्मामा अर्पण गर्नु ।
कर्मयोग
- कर्ममार्फत ईश्वरसँग जोडिनु । जब हामी कर्म अर्पण गर्छौँ, तब परमात्मा र हामी बीच एउटा योग बन्दछ । यदि हामीले हाम्रा धेरैभन्दा धेरै राम्रा कर्महरू- ‘मैले उहाँको लागि गरेँ, उहाँले गराउनुभयो’ भन्दै अर्पण गर्न थाल्यौँ भने उहाँसँग एउटा सम्बन्ध निर्माण हुन्छ । तब त्यो शक्ति हामीसँगै चल्न थाल्छ र त्यही शक्तिले हामीबाट कार्य गराउन थाल्छ । त्यसपछि हामीलाई ‘यो मैले होइन, उहाँले गराइरहनुभएको छ । मेरो त यति क्षमता नै थिएन!’ भन्ने अनुभूति हुन्छ । यसैलाई भनिन्छ कर्मयोग । कर्मद्वारा उहाँसँगको सम्बन्ध प्राप्त गर्नु, उहाँलाई कर्म अर्पण गर्नु र उहाँसँग जोडिनु । यहाँ अर्जुनको विषाद धर्म र राष्ट्रका लागि थियो, तर हाम्रो पनि कुनै पनि प्रकारको विषाद (दुःख) छ भने त्यसैमार्फत हामी परमात्मालाई पुकार्न सक्छौँ, त्यो पनि उहाँसँग जोडिने ‘योग’ बन्न सक्छ ।
ज्ञानसञ्छिन्नसंशयम्
- कर्मयोगबाटै विवेक जागृत हुन्छ । ज्ञानयोग, कर्मयोग, राजयोग र भक्तियोग यी अलग-अलग कुरा होइनन् बरु एउटै फूलका पत्रहरू हुन् । गीता एउटा यस्तो पुष्प हो जसमा यी योगहरूलाई एक-अर्काबाट अलग गर्न सकिँदैन नत्र फूलको सौन्दर्य नै नष्ट हुन्छ । जसले विवेकपूर्ण ज्ञानद्वारा आफ्ना सम्पूर्ण संशय (शंका) हरूलाई ‘छिन्न-भिन्न’ पारिदिएको छ र जो ‘आत्मवान्’ छ, त्यस्ता व्यक्तिलाई कर्मले बन्धनमा पार्दैन । यसरी भगवान्‌ले भक्ति, ज्ञान र कर्मको सुन्दर मिलाप गराउनु भएको छ । ज्ञानपछिको भक्ति (ज्ञानोत्तर भक्ति) त्यहीँबाट प्रस्फुटित हुन्छ । कर्तव्य कर्म- गृहिणीको भान्साको काम, शिक्षकको पढाउने, कापी जाँच्ने र भोलिको तयारी आदि । त्यसैले भगवान्‌ भन्नुहुन्छ- आफ्ना कर्तव्य कर्महरूमा जुट र ज्ञानको प्रकाश लेऊ ।
4.42
तस्मादज्ञानसम्भूतं(म्), हृत्स्थं(ञ्) ज्ञानासिनात्मन: ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (4, 42, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=0agtvtsQmFs', '2026-03-07', 'यसर्थ, हे भरतवंशी अर्जुन! तिमीले हृदयमा स्थित यस अज्ञानजनित आफ्नो शंशयलाई विवेक ज्ञानरूपी तरवारले काटेर समत्त्वरूपी कर्मयोगमा स्थित होऊ र युद्ध गर्नका लागि उठ ।
भगवान्‌ भन्नुहुन्छ - हे भारत उठ!
योगमतिष्ठ
- योगमा स्थित भएर उठ ।
उत्तिष्ठ
- उठ, जाग र आफ्नो लक्ष्य प्राप्ति नभएसम्म नरोकियौ । यो स्फूर्तिदायक वाक्य
उत्तिष्ठ जाग्रत प्राप्य वरान्निबोधत
- अर्थात् उठ, जाग र श्रेष्ठ पुरुषहरूका सान्निध्यमा गएर ज्ञान प्राप्त गर ।
भगवान्‌ अर्जुनलाई यहाँ अत्यन्तै ऊर्जावान् हुँदै भन्नुहुन्छ- अब उठ! किनभने- तस्मात्- त्यसैले, हे भारत (अर्जुन)! तिम्रो हृदयमा अज्ञानका कारण उत्पन्न भएको यो संशयलाई ज्ञानरूपी तरबारले काटेर नष्ट गरिदेऊ । आफ्नो अज्ञान र शङ्कालाई चटक्कै काटेर
योगमतिष्ठ
- निष्काम कर्मयोगमा स्थित होऊ र
उत्तिष्ठ
- युद्धका लागि तयार होऊ । तिम्रो लागि अहिले कर्मयोग नै उपयुक्त छ । यो युद्ध पनि तिमीले त्यस परमात्माका लागि, सृष्टि कर्ताका लागि, एउटा कर्तव्यका रूपमा र धर्म स्थापनाका लागि गरिरहेका छौ भन्ने भावना लिएर उठ । यो सन्देश अर्जुनका लागि मात्र होइन, हामी सबैका लागि हो । आ-आफ्नो कर्ममा रमाउनु, एकाग्र हुनु र भगवान्‌को यो सुन्दर स्फूर्तिदायक आज्ञा मानेर सबै संशयहरूलाई त्याग्दै कर्ममा जुट्नु पर्छ । हामी जहाँसुकै जाऔँ, हिमालयनै किन नहोस्, तर त्यहाँ हिँड्दै गर्दा पनि - म कहाँ जाँदै छु? म कहाँ छु? मेरो यात्रा के हो? त्यो गोरेटोमा मेरा पाइलाहरू स्थिर छन् कि छैनन्? यी कुराहरू महत्त्वपूर्ण हुन्छन् । सारा शास्त्र पढेर पनि अन्त्यमा हामीले गर्ने कुरा भगवान्‌ले यहाँ अर्जुनको माध्यमबाट हामीलाई सम्झाउनुभएको छ ।
प्रश्नोत्तर
प्रश्नकर्ता-
सुनील दाजु
प्रश्न-
भगवान्‌ले रावण वा औरङ्गजेब जस्ता तामसी गुण भएका व्यक्तिहरूलाई किन पैदा गर्नुभयो?
उत्तर-
भगवान्‌ले मनुष्यलाई स्वतन्त्रता दिनुभएको छ र मानिसले आफ्नै कर्मद्वारा ती गुणहरू विकसित गर्दछ । प्रकृतिमा सत्व, रज र तम तीनै गुण छन् । तमोगुण ‘क्रियाशून्यता’ का लागि चाहिन्छ । हामीलाई रातमा सुत्न पर्छ, सधैँ काम मात्र गर्न सकिदैन । त्यसैले क्रिया रोकिनु पनि पर्छ, जुन तमोगुणले गर्छ ।
रजोगुणले क्रियाशीलता दिन्छ । ज्ञान मात्रै छ तर कर्म छैन भने सृष्टि चल्दैन । सत्वगुणले ज्ञान बढाउँछ, रजोगुणले लोभ र अति-महत्वाकांक्षा बढाउँछ । त्यस्तै, तमोगुणले आलस्य, प्रमाद र अपराध बढाउँछ । जब तमोगुणको मात्रा धेरै बढ्छ, तब मानिस गलत बाटोमा लाग्छ ।
रावणमा रज र तम दुवै गुण थिए । रजोगुण (क्रियाशीलता) सत्वगुणको अधीनमा भयोभने मात्र राम्रो कार्य हुन्छ । तर यदि रजोगुण तमोगुणको अधीनमा भयो भने अपराध बढ्छ । हामी दिनरात सुत्यौँ र केही पढेनौँ भने तमोगुण आफैँ बढ्छ, यसमा भगवान्‌को दोष हुँदैन । भगवान्‌ले हाम्रो जीवनमा तबसम्म हस्तक्षेप गर्नुहुन्न जबसम्म हामी उहाँलाई पुकार्दैनौँ । जब हामी अन्धकारबाट बाहिर निस्कन पुकार गर्छौँ, तब उहाँले मार्ग देखाउनुहुन्छ । अन्यथा, सृष्टिको नियमअनुसार चल्न दिनुहुन्छ ।
प्रश्नकर्ता-
देवती दिदी
प्रश्न-
पूजाको सही क्रम के हो ॽ मन्दिर जाँदा वा घरमा पूजा गर्दा सुरुमा के गर्ने र त्यसपछि के गर्ने?
उत्तर-
पूजाको विधिवत ज्ञान त शास्त्र पढेका विद्वानहरूबाटै सिक्नुपर्छ । हाम्रो गीता साधना शिविरमा एक दिन पूर्ण पूजा विधि सिकाइन्छ । सामान्यतया पहिले संकल्प गरिन्छ, त्यसपछि ‘पञ्चायन पूजा’ (गणेश, सूर्य, दुर्गा, शिव, विष्णु/कृष्ण ) को पूजा गरिन्छ ।
पूजाका विभिन्न प्रकार हुन्छन्:
एकोपचार:
केवल प्रणाम गर्नु ।
पञ्चोपचार:
गन्ध, अक्षता, फूल, धूप र नैवेद्य अर्पण गर्नु ।
षोडशोपचार:
१६ विधिले पूजा गर्नु ।
गुरुदेव भन्नुहुन्छ - मन्दिर जानु पनि पर्छ । भगवान्‌ सबैतिर हुनुहुन्छ, तर मन्दिर जाँदा हामीले उहाँका लागि केही ‘कष्ट’ वा प्रयत्न गर्छौँ भन्ने भावना हुन्छ । घरको पूजा र मन्दिरको दर्शन दुवैको आफ्नै महत्त्व छ । शास्त्र विधि अनुसार संकल्प गरेर सहज रूपमा पूजा गर्नुहोस्, धेरै अल्झिनु पर्दैन ।
प्रश्नकर्ता-
डा. शोभाराम दाजु
प्रश्न १-
जब जीवको उत्पत्ति हुन्छ, त्यो प्रकृति र पुरुष (परमात्मा) को मिलनबाट हुन्छ । प्रकृति पञ्चमहाभूतले बनेको हुन्छ र जीवात्मा भगवान्‌को अंश हो । शरीरमा यो जीवात्माको प्रवेश कहिले हुन्छ ?
उत्तर-
यो निकै जटिल प्रश्न हो । एउटा कुरा के भन्न सकिन्छ भने, माता-पिताबाट देह निर्माणको प्रक्रिया सुरु हुन्छ । सामान्य बुझाईमा जब गर्भमा हृदयको धडकन (Heartbeat) सुरु हुन्छ, तब त्यहाँ प्राणको सञ्चार हुन्छ । जीवात्मा एउटा ऊर्जा वा तरङ्ग जस्तै हो तर देखिँदैन । जस्तै बिजुली तारबाट आउँछ तर देखिँदैन, जब प्रकाश बल्छ तब मात्र त्यसको उपस्थिति थाहा हुन्छ । भगवान्‌का ‘तारहरू’ कस्ता छन् कुन बाटोबाट कुन आमाको गर्भ खोज्दै त्यो जीवात्मा आउँछ, त्यो त उहाँलाई नै थाहा छ । यो सबै पूर्वजन्मको संस्कार र कर्म अनुसार तय हुन्छ ।
अर्को कुरा स्पर्म (Sperm) र ओभा (Ovum) पनि जीवित मानिन्छन् । भगवान्‌ले १३औँ अध्यायमा भन्नुभएको छ- ‘क्षेत्रज्ञं चापि मां विद्धि’ अर्थात् क्षेत्र र क्षेत्रज्ञ दुवै म नै हुँ । एउटा परमाणु (Atom) भित्रको इलेक्ट्रोनमा पनि त चैतन्य छ नि! त्यसैले जड र चेतन सबैमा परमात्मा हुनुहुन्छ । १५औँ अध्यायमा हामीले ‘क्षर’ र ‘अक्षर’ पुरुषबारे पढ्यौँ, त्यो देह पनि परमात्माकै एउटा रूप हो ।
प्रश्न २-
हामीले ९ ग्रहबारे त सुन्यौँ, तर शास्त्रमा भनिएका देवलोक, नरकलोक, बैकुण्ठ वा यक्षलोकहरू के कुनै ग्रहमा हुन्छन् कि यी काल्पनिक हुन्?
उत्तर-
यी काल्पनिक होइनन्, यी चेतनाका ‘स्तर’ (Levels) हुन् । यसलाई ‘वेभ मेकानिक्स’ (Wave Mechanics) बाट बुझ्न सकिन्छ । हाम्रो विचार गर्ने एउटा ‘वेभलेन्थ’ (Wavelength) हुन्छ । कसैको विचार तल हुन्छ (पाताल), कसैको माथि । बैकुण्ठ भनेको यस्तो स्तर हो जहाँ कुनै ‘कुण्ठा’ हुँदैन । वैकुण्ठ जाने भनेको शरीरै लिएर जाने मात्र होइन, हामी जीवित छँदै हाम्रा विचारलाई वैकुण्ठको स्तरसम्म पुर्‍याउन सक्छौँ । जहाँको वेभलेन्थ अनन्त हुन्छ, त्यही परमधाम हो । नरक भनेको चाहिँ यस्तो ठाउँ वा स्थिति हो जहाँ सधैँ कलह, अशान्ति र छट्पटी हुन्छ । मानिसले आफ्नै कर्म र विचारले यही पृथ्वीमा पनि नरक भोग्न सक्छ वा देह त्यागपछि उसको जीव त्यस्तै अशान्त स्तरमा जान सक्छ । जो ज्ञान र तपस्याले पवित्र हुन्छ, ऊ यही देहमा रहँदा पनि परमधामको अनुभूति गर्न सक्छ ।
प्रश्नकर्ता-
अनुराधा दिदी
प्रश्न-
के धेरै प्रश्न सोध्नु भनेको गुरुको अनादर गर्नु वा चुनौती दिनु त होइन?
उत्तर-
होइन, भगवान्‌ले परिप्रेश्नेन भन्नुभएको छ । यसको अर्थ हो- शुद्ध मनले राखिएको जिज्ञासा । कुनै प्रश्न संशय युक्त हुन्छ जसमा श्रद्धा हुँदैन, केवल गुरुको परीक्षा लिने भाव हुन्छ (वितण्डावाद), जसले विनाश निम्त्याउँछ । तर जिज्ञासा भनेको ज्ञान प्राप्त गर्ने भोक हो ।
पहिले-पहिले वादविवाद (Healthy Debate) हुन्थ्यो । जस्तै आदि शङ्कराचार्य र मण्डन मिश्र बीचको शास्त्रार्थ । त्यहाँ एउटा सर्त थियो, जो हार्छ उसले आफ्नो जीवनशैली बदल्नुपर्छ । निर्णायक मण्डन मिश्रकी पत्नी भारतीले आफ्नै पति हारेको स्वीकार गर्दै सन्यास लिन लगाउनुले हाम्रो धर्ममा नारीहरूको विद्वत्ता र निष्पक्षता कति उच्च थियो भन्ने देखाउँछ । त्यसैले, मैले कति बुझिँन, यसको अर्थ के हो? भनेर नम्रतापूर्वक सोध्नु शिष्यको लक्षण हो । तत्वदर्शी महापुरुषहरूले यस्ता निष्कपट जिज्ञासाको सधैँ समाधान गर्नुहुन्छ । लौकिक ज्ञानमा पनि यदि हामीले केही सोधेनौँ भने हाम्रो संशय कहिल्यै मेटिँदैन । त्यसैले ज्ञान पाउनका लागि नम्र भएर नै प्रश्न सोध्नु पर्छ ।
यसप्रकार ॐ तत्सत्- यी भगवान्‌का नामहरूको उच्चारणपूर्वक ब्रह्मविद्या र योगशास्त्रमय श्रीमद्भगवद्गीताको उपनिषद्‌रूपी श्रीकृष्ण र अर्जुनको संवादस्वरूप ‘ज्ञानकर्मसन्न्यासयोग’ नाम भएको चौथो अध्याय पूर्ण भयो ।
ॐ तत्सदिति श्रीमद्भगवद्गीतासु उपनिषत्सु ब्रह्मविद्यायां(य्ँ) योगशास्त्रे श्रीकृष्णार्जुनसंवादे ज्ञानकर्मसन्न्यासयोगो नाम चतुर्थोऽध्याय: ।।४।।
यसप्रकार ॐ तत्सत्- यी भगवान्‌का नामहरूको उच्चारणपूर्वक ब्रह्मविद्या र योगशास्त्रमय श्रीमद्भगवद्गीताको उपनिषद्‌रूपी श्रीकृष्ण र अर्जुनको संवादस्वरूप ‘ज्ञानकर्मसन्न्यासयोग’ नाम भएको चौथो अध्याय पूर्ण भयो ।
यो विवेचन पढेर तपाईँलाई अवश्य पनि राम्रो लाग्यो होला भन्ने हामीलाई विश्वास लागेको छ । कृपया तल दिएको लिङ्क प्रयोग गरी हामीलाई आफ्नो प्रतिक्रियाहरू दिनुहोला ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (17, 13, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=sLlwuNHGPjk', '2026-03-07', 'शास्त्रविधिले हीन, अन्नदान विहिन, विना मन्त्रको, विना दक्षिणाको र श्रद्धा विहिन यज्ञलाई तामस यज्ञ भनिन्छ ।
मन्त्रहीनम्-
जहाँ मन्त्र भनिएको छैन वा सही उच्चारण गरिएको छैन र
अदक्षिणम्
- बिना दक्षिणा । यदि कसैले शास्त्र विधिबाट रहित र अन्नदानबाट रहित यज्ञ गर्छ त्यो यज्ञ तामस यज्ञ हुन्छ । यज्ञका लागि कुनै पुरोहित आउँछ भने उसलाई उचित दक्षिणा दिनुपर्छ । उचित दक्षिणा भनेको पुरोहितले लगाएको समय र त्यस समयको उचित पारिश्रमिक दक्षिणाको रूपमा दिनुपर्छ । यदि यस्तो उचित दक्षिणा दिइएन भने पनि त्यो यज्ञ तामस यज्ञहुन्छ । श्रद्धाविरहित यज्ञं- जुन यज्ञ श्रद्धाबाट रहित हुन्छ, श्रद्धाबाट विहीन यस्तो प्रकारको यज्ञ तामसम् परिचक्षते- तामस यज्ञ कहलाउँछन् ।
अग्नि एउटा माध्यम हो र त्यस माध्यमबाट हामी देवताहरूलाई हवि उनीहरूसम्म पुर्‍याउने काम हुन्छ । भोकालाई खाना दिनुपर्छ र शिवलिङ्गमा दूध चढाउनु पर्छ । बाहिर बसेको भोकाएको भिखारीलाई खान दिनुपर्छ तर यसको अर्थ शिवलिङ्गमा दूधले अभिषेक नै नगर्नु भन्ने होइन । कसैको पण्डितलाई यति धेरै दक्षिणा किन दिनु भनेजस्तो भाव आउँछ । कर्तव्यको भावले गरिएको यज्ञ सात्त्विक कहलाउँछ र यदि तपाईँले आफ्नो कर्तव्य छोडेर पण्डित अल्छी हुन्छ भन्ने सोचेर उचित दक्षिणा दिनुभएन भने त्यो पनि तामस यज्ञ कहलाउँछ । यसरी तीन प्रकारका यज्ञ- सात्त्विक यज्ञ, राजस यज्ञ र तामस यज्ञको व्याख्या भगवान्‌ले गर्नुभयो ।
17.14
देवद्विजगुरुप्राज्ञ, पूजनं(म्) शौचमार्जवम् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (17, 14, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=sLlwuNHGPjk', '2026-03-07', 'देवता, ब्राह्मण, गुरु र ज्ञानीजनहरूको पूजन, पवित्रता, सरलता, ब्रह्मचर्य र अहिंसालाई शरीरसम्बन्धी तप वा शरीरले गर्ने तप भनिन्छ ।
देव
- देवताहरूको पूजा ।
द्विज
- दुई पटक जन्म लिने । एउटा पंछी अर्को उपनयन संस्कार गरिएका मनुष्य । पहिले अण्डाको रूपमा आउँछ र त्यसपछि अण्डा फुटेर बाहिर निस्कन्छ । अण्डाबाट निस्कने सबै जीवलाई द्विज भनिन्छ । जसल उपनयन संस्कार भयो र आफूलाई गुरुमा समर्पित गरेर ब्रह्मविद्या जान्ने प्रयास गर्‍यो, त्यस्ता सबै मानिसहरू पनि द्विज कहलाउँछन् । किनकि पहिलो पटक जब ऊ आमाको कोखबाट जन्मियो तब एउटा जन्म भयो र जब अज्ञानबाट ज्ञानतर्फ बढ्यो तब उसको दोस्रो जन्म भयो । तपाईँहरूले पनि भगवद्गीता बुझ्नका लागि Learn Gita कार्यक्रम सुरु गर्नुभएको छ, त्यसैले तपाईँहरू पनि द्विज बन्नुभयो । यसलाई दोस्रो जन्म जस्तै मान्नुपर्छ किनकि हामीले ज्ञान प्राप्तिका लागि यो प्रयास सुरु गरेका छौँ । त्यसैले द्विज ती ब्राह्मणहरूलाई भनिन्छ जो ब्रह्म जान्ने जिज्ञासासहित अघि बढ्छन् । यहाँ जन्मले होइन, कर्मले ब्राह्मण हुनेहरूको बारेमा भनिएको हो ।
एकपटक सङ्गमनेरमा परम पूज्य स्वामीजीको कथाको आयोजना गरेका थियौँ । कथा आयोजना गर्दा अन्तिम दिन ब्राह्मण भोजन हुन्छ । कम्तीमा ५०० ब्राह्मणलाई भोजन गराउने सङ्कल्प थियो । अब यति धेरै ब्राह्मण कहाँ खोज्ने भन्ने प्रश्न उठ्यो । त्यसपछि स्वामीजीलाई भनियो, “यहाँ आश्रममा केही आदिवासी बच्चाहरू छन् । ती सबैलाई गीता परिवारले १२औँ र १५औँ अध्याय सिकाएको छ र ती सबै बच्चाहरूले ठूलो स्वरमा शुद्धतासाथ ती दुई अध्याय पढ्न सक्छन् । उनीहरूलाई भोजनका लागि बोलाउन सकिन्छ”? स्वामीजीले धेरै आनन्दसाथ भन्नुभयो, “अवश्य बोलाउनुहोस्, यदि ती साना बच्चाहरूले दुई अध्याय सिकेका छन् भने उनीहरूलाई भोजनमा बोलाउनु पुण्यको काम हो । उनीहरूले त्यस दिशामा पहिलो कदम राखिसकेका छन्, १२औँ र १५औँ अध्याय कण्ठस्थ गरेका छन् भने ती बच्चाहरू जन्मले आदिवासी भए पनि द्विज कहलाउन सक्छन् । उनीहरूलाई बोलाउन कुनै आपत्ति छैन” । त्यसपछि स्वामीजीको कथाको अन्तिम दिन ती सबै आदिवासी बच्चाहरूलाई भोजन गराएर आयोजकलाई ठूलो आनन्द भयो । ब्राह्मणहरूलाई पनि भोजन गराइयो र उनीहरूको खुशी देखेर सबैको मन तृप्त भयो । यो पनि एउटा यज्ञ नै हो ।
तप-
शरिर वाणी र मन माथीको नियन्त्रण ।
गुरु-
जसलाई जीवनमा ज्ञानदाताको रूपमा स्वीकारिएको छ । एकमात्र गुरु हुनुपर्छ भन्ने छैन । दत्तात्रेयका २४ गुरु थिए । रुख, नदी, पर्वत, कमिला सहित जसबाट केही सिकिन्छ ऊ नै गुरु हो । जसबाट केही ज्ञान प्राप्त गरिन्छ तिनको सम्मान गर्नुपर्दछ ।
प्राज्ञ-
जो प्रज्ञावान् मानिसहरू छन्, जो ज्ञानवान् छन्, जसले जीवनलाई बुझेका छन् । त्यस्ता प्रज्ञावान्हरूको पनि सम्मान गर्नु पनि एउटा तप हो ।
शौचम्-
शौच अर्थात् भित्री र बाहिरी पवित्रता । मेरो शरीर स्वच्छ होस्, मेरो बुद्धि निर्मल होस्, मेरो मन पवित्र होस्, मेरो वाणी मधुर होस् ।
आर्जवम्-
वाणीको विनम्रता । मधुर तथा विनम्र वाणी र व्यवहारलाई आर्जव भनिन्छ । ब्रह्मचर्यको अर्थ हामीले धेरै समित रूपमा बुझेका छौँ । विवाहअघि मात्र ब्रह्मचारी हुन्छ भन्ने होइन । ब्रह्मचर्य भनेको पाँचै इन्द्रियको संयम हो । आँखाले म त्यही कुरा देखूँ जो देख्नुपर्छ । निरर्थक कुरा हेरेर समय बर्बाद नगर्नु । कानले त्यही कुरा सुनूँ जो सुन्नुपर्छ । निरर्थक रील हेरेर र अर्थहीन गीत सुनेर समय बर्बाद नगर्नु । के खाने र के नखाने भन्ने विवेक पनि ब्रह्मचर्य हो । के कुरा स्पर्श गर्ने र के स्पर्श निषिद्ध छ भन्ने बुझ्नु पनि ब्रह्मचर्य हो । तर प्रायः हामीले ब्रह्मचर्यलाई केवल स्पर्शसँग मात्र जोडेर बुझ्यौँ । जबकि ब्रह्मचर्य भनेको के सुँघ्ने र के नसुँघ्ने भन्नेमा पनि निर्भर हुन्छ ।
अहिँसा-
हिँसा केवल कसैको ज्यान लिनु मात्र होइन, कसैको चित्त दुखाउनु पनि हिँसा हो । मन, कर्म र वचनबाट कसैको चित्त नदुखाउनु, शरीरलाई पीडा नदिनु, वाणीबाट पनि कसैलाई पीडा नदिनु नै अहिँसा हो ।
सोह्रौँ अध्यायमा भगवान्‌ले २६ दैवी गुण सम्पत्तिको कुरा गर्नुभएको छ । ती दैवी गुणमध्ये पछाडि बसेर कसैको निन्दा नगर्नु पनि एक हो । कसैको पछाडि पनि नराम्रो कुरा गरियो भने त्यसलाई पनि हिँसा नै मानिन्छ । एक हप्ता भरि कसैको पनि नराम्रो कुरा नगरूँ भनि प्रयास गरेर हेर्नुहोस् । तब मात्रै हामी अहिँसाको मार्गमा अगाडि बढ्छौँ ।
शारीरं(न्) तप उच्यते
- यो शरीरको तप भनिएको छ । आफूलाई तपाउनु, सजग राख्नु, संयममा बस्नु, नियममा बस्नु पनि एकप्रकारको तप नै हो । म कति बजे उठूँ, म कति खाऊँ, कति कति नखाऊँ, म कति सुतूँ, कति नसुतूँ, कति व्यायाम गरूँ र कति नगरूँ, कति खेलूँ, कति नखेलूँ, कति पढूँ, कति नपढूँ, यी सबैको समत्व हामीले बुझ्नुपर्छ । यो सन्तुलन नै योग हो । समत्त्वं योग उच्यते- समत्त्व नै योग कहलिन्छ । जो आफ्नै शरीरलाई तपाएर गुरुसँग श्रद्धा भावले जोडिन्छ र गुरुको सेवा गर्छ, प्रज्ञा भएका मानिसहरूको र द्विजहरूको सम्मान गर्छ त्यो नै योगी हो ।
एकजना व्यापारी गुरुकहाँ पुगे । उनले गुरुलाई प्रणाम गरे । त्यो प्रणाम सतही मात्रै थियो । त्यसमा विनम्रता थिएन । गुरुले बुझ्नुभयो र भन्नुभयो, “किन आएका हौ? बस” । उनी बसे र भने, “मलाई केही उपदेश दिने कृपा गर्नुहोस्” । गुरुले एउटा कपमा चिया मगाउनु भयो र त्यसमा थप चिया हाल्न सुरु गर्नुभयो । चिया कप भरिएर पोखिइरहँदा पनि खन्याइ रहनुभयो र भन्नुभयो, “जब तिम्रो मन पहिले नै भरिएको छ भने नयाँ ज्ञान राख्ने कुनै ठाउँ छैन । त्यसैले जब तिमीसँग इच्छा हुन्छ तब आउनु” ।
17.15
अनुद्वेगकरं(व्ँ) वाक्यं(म्), सत्यं(म्) प्रियहितं(ञ्) च यत् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (17, 15, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=sLlwuNHGPjk', '2026-03-07', 'जो मनलाई उद्वेग (दिग्दार) नगर्ने, सत्य, प्रिय र हितकारक एवं यथार्थ वाणी (वचन) छ तथा वेदशास्त्रको पठनपाठनको र परमेश्वरको स्वाध्याय-अभ्यास (नाम, जपको अभ्यास) छ, त्यसैलाई वाणीसम्बन्धी तप वा वचनले गरिने तप भनिन्छ ।
अनुद्वेगकरं वाक्यं-
जसले कसैको मनमा उद्वेग ल्याउँछ, त्यस्तो कुरा भन्नु हुँदैन । यस्तो वाक्य बोल्नुपर्छ जसले कसैको मनमा उद्वेग नहोस् ।
सत्यं प्रियहितं च यत्
- सत्य बोल्नु, प्रिय बोल्नु र हितकारी बोल्नु । यदि हितकारी छैन भने त्यस्तो कडा कुरा नबोल्नु । यदि कुरा सत्य छ तर कडा छ भने पनि नबोल्नु ।
सत्यम प्रिय
- त्यो प्रिय हुनुपर्छ ।
एक ज्योतिषी राजाको दरवारमा गएको बेला उनलाई राजाले आफ्नो हात देखाए । हात हेरेर ज्योतिषी अचम्मित भए र भन्न लागे, “हे भगवान्‌! मैले बिहान बिहान कस्तो हात हेर्नुपर्‍यो । राजन! तपाईँ धेरै अभागी हुनुहुन्छ । तपाईँका सबै परिवारजन तपाईँको अगाडि एक-एक गरेर मर्नेछन् । यस्तो हात मैले आजसम्म हेरेको छैन” । राजा रिसाएर ती ज्योतिषीलाई जेलमा थुन्न लगाए तर यसले राजा बेचैन बनायो । कसैले राजालाई हाम्रो राज्यमा अर्का ठूला विद्वान ज्योतिषी छन् भन्ने सुनायो । राजाले उनलाई बोलाउने आदेश दिए । ती अर्का ज्योतिषीले राजाको हात हेरेर धेरै खुशी भए र भन्न लागे, “अहो! यस्तो हात त मैले कहिल्यै देखेको छैन । तपाईँ धेरै भाग्यमानी हुनुहुन्छ । तपाईँको परिवारमा सबैभन्दा लामो आयु तपाईँको छ” । कुरा एउटै थियो । पहिलोले ‘तपाईँ सबैलाई मरेको देख्नुहुनेछ । तपाईँका परिवारजनको मृत्यु तपाईँको अगाडि हुनेछ’ भने र दोस्रोले पनि त्यही कुरा भने तर तरिका फरक थियो ।
स्वाध्यायाभ्यसनं-
स्वाध्याय अर्थात् पढ्नु, लेख्नु, सुन्नु र अभ्यास अर्थात् निरन्तरता दिनु । यी दुई काम पनि वाणीको तप मानिन्छन् ।
17.16
मनः(फ्) प्रसादः(स्) सौम्यत्वं(म्), मौनमात्मविनिग्रहः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (17, 16, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=sLlwuNHGPjk', '2026-03-07', 'मनको प्रसन्नता, शान्तभाव, भगवत् चिन्तन गर्ने स्वभाव, मनको निग्रह र अन्तःकरणका भावहरूको सुन्दर पवित्रतालाई मनसम्बन्धी तप वा मनले गरिने तप भनिन्छ ।
भगवान्‌ले मनको प्रसन्नताको कुरा बारम्बार भन्नुभएको छ । यदि तपाईँ सबै दुःखहरूको अन्त्य गर्न चाहनुहुन्छ भने मनमा प्रसन्नता जगाउनु पर्छ । मन प्रसन्न रह्यो भने प्रसन्नताको झरना निरन्तर बगिरहन्छ । कुनै हलचलबाट क्रोध आयो भने बुद्धि नाश हुनसक्छ । त्यतिबेला पनि प्रसन्न नै हुनुपर्छ । यी परीक्षाका क्षण हुन् । साना-साना कुराले हाम्रो परीक्षा लिन्छ । तपाईँ परीक्षा पास हुनुभयो कि हुनुभएन, तपाईँ आफैँ जान्नुहोस् । यस्तो भाव शुद्धि रहनु पर्छ ।
भाव संशुद्धि
- यो मनको तप हो ।
17.17
श्रद्धया परया तप्तं(न्), तपस्तत्त्रिविधं(न्) नरैः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (17, 17, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=sLlwuNHGPjk', '2026-03-07', 'फलको चाहना नगरी योगी पुरूषहरूद्वारा परम श्रद्धाकासाथ गरिने ती माथि बताइएका तीन प्रकारका तपलाई सात्त्विक तप भनिन्छ ।
श्रद्धया परया
- कुनै फलको इच्छा बिना श्रद्धाका साथ तप गर्नुपर्छ ।
तपस्तत्त्रिविधं नरैः
यी तीन प्रकारका तप जुनसुकै व्यक्तिले विना आकाङ्क्षा गर्छ त्यो तप सात्त्विक तप कहलिन्छ । जसले तपाईँलाई भगवद्गीता सिकाइरहेका छन् । तपाईँलाई गीता सिकाउँदा तपाईँका साथ प्राविधिक सेवी बनेर आउँछन्, जूम म्यानेज गर्छन्, गीत, नृत्य देखाउँछन, ती सवै सेवीहरू यसरी नै निश्वार्थ भावले एक प्रकारको तप गरिरहेका छन् । मेहनत गर्छन् र धैर्य राख्छन् । उनीहरूलाई प्रणाम गर्नुपर्छ । उनीहरू नै हाम्रा गुरु हुन् ।
17.18
सत्कारमानपूजार्थं(न्), तपो दम्भेन चैव यत् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (17, 18, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=sLlwuNHGPjk', '2026-03-07', 'जुन तप आफ्नो सत्कार, मान र पूजाको लागि तथा अन्य कुनै स्वार्थवश या देखावटी भावबाट गरिन्छ भने त्यस्तो अनिश्चित एवं क्षणिक फल दिने तपलाई यहाँ राजस तप भनिएको छ ।
‘मेरो सत्कार होस्, मेरो पूजा होस्, मैले सम्मान पाऊँ’ भन्ने भावनाले गरिएको तप, स्वार्थको भावनाले गरिएको, पाखण्डपूर्वक गरिएको तप क्षणिक फलदायी हुन्छ, त्यसलाई राजस तप भनिन्छ । राजस तपबाट क्षणिक फल पाइन्छ । कसैले भागवत् कथा आयोजना गर्‍यो र यजमान बन्यो, धन दान गर्‍यो भने त्यसबाट उसमा अभिमान र अहङ्कार आउँछ भने सबैको अगाडि सबैलाई प्रणाम प्रणाम गर्छ, छाती फुलाएर हिँड्छ । यो पाखण्ड अरूलाई देखाउनका लागि गरिएको यज्ञ हो । फल त पाउँछ, राम्रो हुँदैन । त्यसलाई राजस यज्ञ भनिन्छ । तर तामस तपबाट केही पनि फल प्राप्त हुँदैन ।
17.19
मूढग्राहेणात्मनो यत्, पीडया क्रियते तपः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (17, 19, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=sLlwuNHGPjk', '2026-03-07', 'जुन तप मूढतापूर्वक हठले मन, वाणी र शरीरलाई पीडासहित अथवा अरूलाई अनिष्ट गर्ने उद्देश्यका साथ गरिन्छ भने त्यस्तो तपलाई तामस तप भनिन्छ ।
मूढतापूर्वक हठले मन, वाणी र शरीरलाई पीडा दिएर गरिने तपलाई तामस तप भनिन्छ । एउटा बूढी महिला छिमेकी महिलाको प्रगति देखेर धेरै जल्थिन् । एकदिन उनले ‘म पनि भगवान्‌को तप गरेर भगवान्‌लाई प्रसन्न पार्छु’ भन्ने सोचिन् । उसले कडा तप गरेर भगवान्‌लाई प्रसन्न पारिन् । भगवान्‌ प्रसन्न हुनुभयो । उसले भनिन्, “भगवान्‌ मलाई वरदान चाहियो” । भगवान्‌ले वरदान त पाउँछ्यौ तर तिमीलाई जे पाउँछ्यौ त्यसको दोब्बर छिमेकीले पाउँछिन् । अब ती महिला अझै चिन्तित भइन् । उनले भनिन, “भगवान्‌ मेरो एउटा आँखा फुटाइदिनुहोस्, मलाई एउटा आँखाले अन्धो बनाइदिनुहोस् ताकि छिमेकी दुवै आँखा फुटोस्” । यस्तो प्रकारको तप मूढतापूर्वक गरिएको र अरूलाई दुःख दिन गरिएको तप हो । त्यसलाई तामस तप भनिन्छ ।
17.20
दातव्यमिति यद्दानं(न्), दीयतेऽनुपकारिणे ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (17, 20, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=sLlwuNHGPjk', '2026-03-07', 'दान दिनु नै आफ्नो कर्तव्य हो भन्ने भावबाट जुन दान देश (स्थान), काल (समय) र सुयोग्य पात्र प्राप्‍त हुँदा विनाप्रतिउपकारको भावनाले दिइन्छ, त्यस्तो दानलाई सात्त्विक दान भनिन्छ ।
“यो मेरो कर्तव्य हो, मैले दान गर्नैपर्छ” भन्ने भावनाले गरिएको दान, जसमा प्रतिफलको अपेक्षा हुँदैन, चुपचाप दिइन्छ, एक हातले दिएको अर्को हातलाई पनि थाहा नहोस् र यस्तो दान जो देशको हितमा होस्, समयअनुसार होस् र योग्य पात्र वा संस्थालाई दिइएको होस्, त्यसलाई सात्त्विक दान भनिन्छ । धन दान, समय दान, नेत्रदान, अङ्गदान, गीता प्रचारमा सहयोग, समय दान आदि सबै सात्त्विक दान हुन् तर यदि प्रतिफलको भावनाले, सत्कारको आशाले, घाँटीमा माला र पत्रिकामा समाचारको कामना सहित दिएको दान राजस दान हो ।
17.21
यत्तु प्रत्युपकारार्थं(म्), फलमुद्दिश्य वा पुनः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (17, 21, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=sLlwuNHGPjk', '2026-03-07', 'तर जुन दान क्लेशपूर्वक र प्रत्युपकार(बदलामा गरिने उपकार) को प्रयोजनले अथवा फल प्राप्‍ति गर्ने उद्देश्य राखेर दिइन्छ, त्यस्तो दानलाई राजस दान भनिन्छ ।
क्लेशपूर्वक दिइएको दान वा दिनैपर्छ वा माग्नै आएर दिएको जस्ता सहयोगहरू राजस दान हुन् । गाउँका युवाहरू पसलेकहाँ आएर भने, “मशानघाट वरिपरि पर्खाल बनाउन चन्दा चाहियो” । पसलेले भने, “मशानमा के चोरी हुन्छ र कम्पाउण्ड चाहियो? यस्तो दान म दिँदिनँ” । अर्को पटक गाउँमा स्विमिङ पूल बनाउँदैछौँ, दान दिनुहोस् भनि आउँदा ति व्यापारीले बाल्टिनभरि पानी ल्याएर दिए र भने, “स्विमिङ पूलमा हाल्न यो पानी लैजानुहोस्” । यस्तो क्लेशपूर्वक दिइएको र प्रतिफलको अपेक्षाले दिइएको दान राजस दान हो । दान दिन्छु तर मण्डपमा मेरो नाम लेखिनुपर्छ, भित्तामा मेरो नाम हुनुपर्छ, यस्तो दान राजस दान हो । उपहार दिएर प्रतिफलको अपेक्षा राख्नु पनि राजस दान हो ।
17.22
अदेशकाले यद्दानम्, अपात्रेभ्यश्च दीयते ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (17, 22, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=sLlwuNHGPjk', '2026-03-07', 'जुन दान सत्कार नगरी अथवा अपहेलना (तिरस्कार) पूर्वक गरी अयोग्य देश (स्थान) र अयोग्य काल (समय) मा र कुपात्रलाई दिइन्छ, त्यो दानलाई तामस दान भनिन्छ ।
मृत्यु नजिक आएपछि ‘मैले जीवनभर दान दिइनँ, अब केही त दिनुपर्छ’ भनेर हतारमा दिइएको दान र अपात्र व्यक्तिलाई दिइएको दानको कुनै अर्थ छैन । देश, काल र पात्र विचार नगरी तिरस्कारका साथ दिइएको दान तामस दान हो । जीवनभर चोरी गरेर, अन्याय गरेर पैसा कमाएर जङ्गलमा बनाएको धर्मशाला कसैको काम लाग्दैन । यो तामस दान हो ।
17.23
ॐ तत्सदिति निर्देशो, ब्रह्मणस्त्रिविधः(स्) स्मृतः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (17, 23, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=sLlwuNHGPjk', '2026-03-07', 'शास्त्रमा ॐ, तत् र सत् - यस्ता तीन प्रकारका सच्चिदानन्दघन ब्रह्मका नाम भनेर बताइएको छ, त्यसैबाट सृष्टिको सुरुवातमा ब्राह्मण, वेद र यज्ञादि पनि उत्पत्ति गराए ।
ॐ, तत् र सत्-
यी तीन सच्चिदानन्द ब्रह्मका नाम हुन् । सृष्टिको आदिकालमा ब्राह्मण, वेद र यज्ञ आदिको रचना भयो । त्यसैले दान, तप र पूजनपछि यी शब्द उच्चारण गरेर अर्पण गरिन्छ । हाम्रो परम्परा अद्भुत छ । हामीले शब्दमा पनि ब्रह्म देख्छौँ, सुपारीमा गणपति देख्छौँ, माटोमा गणपति देख्छौँ, पत्थरमा भगवान्‌ देख्छौँ र शब्दमा पनि भगवान्‌ देख्छौँ ।
ॐ, तत् र सत्
- यी शब्द ब्रह्मका रूप हुन् ।
17.24
तस्मादोमित्युदाहृत्य, यज्ञदानतपः(ख्) क्रियाः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (17, 24, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=sLlwuNHGPjk', '2026-03-07', 'यसकारण वैदिक मन्त्रहरूको उच्चारण गर्ने श्रेष्ठ पुरुषहरूले शाश्त्रविधिले नियत गरिएका यज्ञ, दान र तपरूपी क्रियाहरू गर्दा सधैँ यो परमात्माको नाम ‘ॐ’ लाई उच्चारण गरेर मात्रै प्रारम्भ गरिन्छ ।
त्यसैले वेदमन्त्र उच्चारण गर्ने श्रेष्ठ पुरुषहरूले शास्त्रविधिअनुसार यज्ञ, दान र तपमा सधैँ
ॐ
उच्चारण गरेर आरम्भ गर्छन् ।
ॐ भूर्भुवः स्वः तत्सवितुर्वरेण्यं
…गायत्री मन्त्र,
ॐ त्र्यम्बकं यजामहे सुगन्धिम् पुष्टिवर्धनम्
… महामृत्युञ्जय मन्त्र र
ॐ नमो नारायणाय, ॐ नमो भगवते वासुदेवाय
आदि सबै मन्त्र ॐ बाट सुरु हुन्छन् । ॐ शब्द एकमात्र अनाहत नाद हो । अन्य सबै ध्वनि घर्षणबाट उत्पन्न हुन्छन् । ओठको आघातबाट प, फ, ब, भ, म, जिब्रो र तालुको घर्षणबाट ट, ठ, ड, ढ र ण दाँत र जिब्रोको घर्षणबाट त, थ, द, ध र न उच्चारण हुन्छन् तर ॐ मात्र एक नाद हो, जसमा कुनै आघात हुँदैन । त्यसैले ॐकार नाद सम्पूर्ण सृष्टिमा व्याप्त ब्रह्मको रूप मानिन्छ । तत् शब्द परमात्मा हो । “म को हुँ?” यो प्रश्नको निरन्तर साधना हुँदै आएको छ। कोऽहम्, कोऽहम्- यो जिज्ञासा उठिरह्यो । सूर्य, तारा, ब्रह्माण्ड, धातुहरू र विभिन्न वायूहरूको खोज महत्त्वपूर्ण मानिन्छ तर आत्माको खोज उच्च मानिएको छ । यस जिज्ञासाको उत्तर प्रकट भयो- सोऽहम्, सोऽहम् वा म त्यहिँ हुँ । त्यही तत् अर्थात् परमात्मा ।
17.25
तदित्यनभिसन्धाय, फलं(य्ँ) यज्ञतपः(ख्) क्रियाः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (17, 25, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=sLlwuNHGPjk', '2026-03-07', '‘तत्'' नामले चिनिने यी सबै परमात्माकै हुन् भन्ने भावले फलको इच्छा नराखेर, अरूको कल्याणको इच्छा गर्ने पुरूषहरूले अनेक प्रकारका यज्ञ, दान र तपरूपी क्रियाहरू गरिरहन्छन् ।
भगवान् भन्नुहुन्छ, “श्रेष्ठ भावनाले गरिएका कार्यहरूले जीवनलाई पवित्र र कल्याणकारी बनाउँछन्” ।
कर्मणि तथा सत् शब्दः पार्थ युज्यते
। सत्य भाव तथा श्रेष्ठ भावमा र उत्तम र कल्याणकारी कार्यहरूमा सत् शब्दको प्रयोग गरिन्छ । श्रद्धाबाट मनले शक्ति प्राप्त गर्छ । प्रार्थनाले मनलाई सुदृढ बनाउँछ । यज्ञ, दान र तप जस्ता पवित्र कर्महरू श्रद्धा र पवित्र भावसहित नै सम्पन्न गरिन्छन् । यस्तो भावनाले गरिएका कार्यहरूले जीवनलाई पवित्र र कल्याणकारी बनाउँछन् ।
17.26
सद्भावे साधुभावे च, सदित्येतत्प्रयुज्यते ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (17, 26, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=sLlwuNHGPjk', '2026-03-07', 'यसप्रकार, परमात्माको यो ‘सत्’ नाम सत्यभाव र श्रेष्ठभावमा प्रयोग गरिन्छ । हे पार्थ! उत्तम कर्ममा पनि ''सत्'' शब्दको प्रयोग गरिन्छ ।
सत्
परमात्माको नाम हो र यसलाई सत्य र श्रेष्ठ भावमा प्रयोग हुन्छ र उत्तम कर्ममा पनि प्रयोग हुन्छ ।
17.27
यज्ञे तपसि दाने च, स्थितिः(स्) सदिति चोच्यते ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (17, 27, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=sLlwuNHGPjk', '2026-03-07', 'साथै यज्ञ, तप र दानमा जुन स्थिति छ, त्यसलाई पनि ''सत्'' भनिन्छ र परमात्माका निमित्त गरिएको त्यस कर्मलाई पनि निश्चयपूर्वक ''सत्'' नै भनिन्छ ।
17.27 writeup
17.28
अश्रद्धया हुतं(न्) दत्तं(न्), तपस्तप्तं(ङ्) कृतं(ञ्) च यत् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (17, 28, 'ŚRĪ DR. SANJAY MALPANI JI', 'https://www.youtube.com/watch?v=sLlwuNHGPjk', '2026-03-07', 'हे पार्थ! विनाश्रद्धाले गरिएको हवन, दिइएको दान र तपिएको तप र जेसुकै गरिएको शुभकर्म किन नहोस्, त्यो सबैलाई ‘असत्’ भनिन्छ किनकि त्यसको फल न त यो लोकमा लाभदायक हुन्छ, न त मृत्युपर्यन्त परलोकमा नै ।
विनाश्रद्धा गरिएको हवन, दान, तप वा कुनै पनि शुभ कर्म असत् हो र यस्तो कार्य न यस लोकमा लाभकारी हुन्छ न त परलोकमा । यज्ञ, तप र दानमा जुन स्थिरता र पवित्रता हुन्छ, त्यसलाई
सत्
भनिन्छ । परमात्माका लागि गरिएको कर्म निश्चयपूर्वक
सत्
मानिन्छ । श्रद्धा बिना गरिएको कर्म निष्फल हुन्छ । प्रत्येक कार्य श्रद्धा र समर्पणका साथ गर्नु आवश्यक छ । यज्ञ, दान र तपका क्रियाहरू जीवनमा निरन्तर चलिरहनुपर्छ । यिनको त्याग कहिल्यै गर्नु हुँदैन र प्रत्येक पवित्र कर्मपछि
ॐ तत् सत्
शब्दहरूको स्मरण र उच्चारण गर्नुपर्छ । यो परम्परा अत्यन्त प्राचीन र पवित्र छ ।
ॐ तत् सत्
अर्थात् समस्त कर्म, समस्त साधना र समस्त अध्ययन त्यही परम सत्य परमात्मामा समर्पित छन् ।
प्रश्नोत्तर
प्रश्नकर्ता
- कैलाश दाजु
प्रश्न-
तेइसौँ श्लोकमा ॐ तत्सत् शब्दको अर्थ के हो?
उत्तर-
ॐ-
अनाहत नाद, ब्रह्म स्वरूप नाद, जगतको नाद ।
तत्
- परमात्मा र
सत्
- परमात्माको सत्य रूप हो ।
ॐ तत्सत्
भनेको अनाहत नाद, परमात्मा र सत्यको प्रतीक हो ।
प्रश्नकर्ता-
पुष्पा दीदी
प्रश्न १
- ऋषिकेशको गीता भवनमा मेडिटेशन गर्न चाहन्छु । यसको लागि के गर्नुपर्छ?
उत्तर
- गीता भवन गीता प्रेसको हो । नियम पालन गर्नु पर्छ । स्वामी गोविन्द देव गिरीको गुरु पूर्णिमा शिविरमा सहभागी हुन सक्नुहुन्छ । यसको जानकारी स्वामीजीका YouTube, Facebook, Instagram च्यानल वा गीता परिवारको Facebook/Instagram बाट प्राप्त हुन्छ ।
प्रश्न २-
प्राणायाम गर्दा ॐ उच्चारण गर्न मिल्छ कि मिल्दैन?
उ
त्तर-
यदि सक्षम हुनुहुन्छ भने ॐ उच्चारण गर्न पूर्ण अधिकार छ । प्राणायाम स्वास्थ्यका लागि पनि उपचारात्मक छ । यदि मन कमजोर छ र डर वा असमर्थता छ भने कुनै हिंस्रक वा उग्र अभ्यास नगर्नुहोस् । कमजोर मन भएकालाई डर वा उग्र मन्त्रको अभ्यास हानिकारक हुनसक्छ । तपाईँले बाल्यकालदेखि गरिरहनु भएको अभ्यासले कुनै समस्या छैन भने जारी राख्न सक्नुहुन्छ । श्रद्धा र प्रेमभाव साथ गरिएको कामले भगवान्‌ प्रसन्न हुनु हुन्छ ।
ॐ तत्सदिति श्रीमद्भगवद्गीतासु उपनिषत्सु ब्रह्मविद्यायां(य्ँ) योगशास्त्रे श्रीकृष्णार्जुनसंवादे श्रद्धात्रयविभागयोगो नाम सप्तदशोऽध्याय: ।।१७।।
यसप्रकार ॐ तत्सत्- यी भगवान्‌का नामहरूको उच्चारणपूर्वक ब्रह्मविद्या र योगशास्त्रमय श्रीमद्भगवद्गीताको उपनिषद्‌रूपी श्रीकृष्ण र अर्जुनको संवादस्वरूप ‘श्रद्धात्रयविभागयोग’ नाम भएको सत्रौँ अध्याय पूर्ण भयो ।
यो विवेचन पढेर तपाईँलाई अवश्य पनि राम्रो लाग्यो होला भन्ने हामीलाई विश्वास लागेको छ । कृपया तल दिएको लिङ्क प्रयोग गरी हामीलाई आफ्नो प्रतिक्रियाहरू दिनुहोला ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (4, 7, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=PBO7DjRtYRU', '2026-03-01', 'त्यसपछि सृष्टिको रचना र चातुर्वर्ण्य व्यवस्थाको वर्णन गर्दै कर्म, विकर्म र अकर्म को सूक्ष्म सिद्धान्तलाई सम्झाउनु भएकोछ ।
हामी प्रतिक्षण कर्म गरिरहेका हुन्छौँ । कुन कर्म गर्ने र कुन कर्मको त्याग (सन्न्यास) गर्ने भन्ने कुरा ज्ञानको प्रकाशमा बुझ्नु आवश्यक छ । ज्ञानेश्वर महाराज भन्नुहुन्छ- ज्ञान कर्मको आँखा हो । ज्ञानविनाको कर्म अधुरो हुन्छ । यज्ञको चर्चा गर्दै गर्दा उहाँले ती महापुरुषहरूको अन्तःकरणलाई हाम्रो अगाडि खोल्नुहुन्छ, जसले शरीरमा रहँदा रहँदै पनि परमात्मासँग नित्य सम्बन्ध स्थापित गरेर जो सधैँ तृप्त रहन्छन् ।
4.22
यदृच्छालाभसन्तुष्टो, द्वन्द्वातीतो विमत्सरः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (4, 22, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=PBO7DjRtYRU', '2026-03-01', 'जो पुरुष फलको इच्छा नगरी स्वतः प्राप्‍त भएको वस्तुमा सन्तुष्ट रहन्छ र जसमा डाह, ईर्ष्या आदि केही पाइँदैन, जो हर्षाशोकादि द्वन्द्वहरूबाट मुक्त छ; जो कुनै कार्यको सिद्धि र असिद्धि दुवैमा समान रहने कर्मयोगीहरू कुनै कर्म गरेर पनि बन्धनमा पर्दैनन् ।
भगवान् भन्नुहुन्छ,
यदृच्छालाभसन्तुष्टो
- जे आफूलाई प्राप्त भएको छ त्यसमा सन्तुष्ट रहनु । हामी आफ्नो कर्तव्य गर्दैगर्दा फल स्वरूप जे प्राप्त हुन्छ त्यसमा सन्तुष्ट रहन सक्नुपर्दछ । सुखको लागि भोग गर्न विलासी सामान जुटाउँदैमा सन्तुष्ट रहन सकिँदैन । गरिबीमा पनि जे प्राप्त भएको छ त्यसमा रमाउन सक्नु नै महानता हो । महान पुरुषहरूको जीवनी हेर्‌यौँ भने अभावमा पनि उनीहरू सन्तुष्ट रहेका देख्न सकिन्छ ।
विमत्सरः
- कसैको ईर्ष्या नगर्नु । यदि कोही आफूभन्दा अगाडि बढ्छ भने त्यसमा ईर्श्या गर्नु हुँदैन ।
द्वन्द्वातीतो
- हर्ष र शोकविच द्वन्दबाट मुक्त रहनु । हाम्रा जीवनमा केही राम्रा केही नराम्रा परिस्थितिहरू आउँछन् । जीवनमा मान-अपमान, यश-अपयश, लाभ-हानि, निन्दा-स्तुति सबै परिस्थितिहरू आउँछन् । हामीलाई जे अनुकूल छ त्यसमा आसक्ति र प्रतिकूलमा द्वेष राख्दछौँ जसले गर्दा अन्त:करणमा द्वन्द्व पैदा हुन्छ र त्यसैमा अल्मलिएर बस्छौँ । तर भगवान् यहाँ अर्जुनलाई
द्वन्द्वातीतो विमत्सरः
- राग र द्वेषलाई समान राख्दै त्यसबाट माथि उठ्नुपर्छ भन्नुहुन्छ । मनमा उठ्ने द्वन्द्वमा समान रहेर निरन्तर कर्म गर्दै जाँदा सिद्धि असिद्धिमा पनि एक समान रहन सकिन्छ जसले गर्दा कुनै पनि कर्मको बन्धनमा बाँधिनु पर्दैन ।
कृत्वापि न निबध्यते
- कर्मद्वारा बन्धनमा पर्नु नपर्ने । जसरी एउटा उच्च कोटीको गायकलाई उच्च, निम्न जुन स्केलको संगीत बजाइदिए पनि सन्तुलनमा रहेर गाउन सक्छ, त्यसरी नै हामी पनि राग, द्वेष, हर्ष, शोक, सफलता, असफलता, ईर्ष्या, घृणा, अनुकूल, प्रतिकूल जुनसुकै परिस्थितिमा आफ्नो मन र बुद्धिलाई एक समान राखेर सन्तुलित रहन सक्नुपर्छ । यसो गर्न सक्नाले निरन्तर आफ्ना कर्महरू गरिरहँदा कुनै पनि विषयले अलमलाउन सक्दैन र कहीँ रोकिनु पनि पर्नेछैन ।
4.23
गतसङ्गस्य मुक्‍तस्य, ज्ञानावस्थितचेतसः ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (4, 23, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=PBO7DjRtYRU', '2026-03-01', 'जसको आसक्ति सर्वथा नष्ट भएको छ, जो देहाभिमान र ममताले रहित भएको छ अर्थात् मुक्त भएको छ, जसको चित्त निरन्तर परमात्माको ज्ञानमा स्थित रहन्छ, यस्तो केवल यज्ञ सम्पादनको लागि कर्म गर्ने मनुष्यका सम्पूर्ण कर्महरू उचित तरिकाले नष्ट भएर जान्छन् ।
भगवान् यहाँ हामीलाई महान आत्मा परमात्मासँग एकाकार भएको आत्मज्ञानीसँग साक्षात्कार गराउँदै हुनुहुन्छ ।
गतसङ्गस्य मुक्तस्य
- सङ्गबाट मुक्त भएको । वासनादार फूल टिपेर फूलदानीमा राख्यो भने अन्य फूलहरूलाई पनि वासनादार बनाइदिन्छ, त्यो सङ्गको परिणाम हो । जस्तो स्वभावसँग सङ्गत गर्‍यो त्यसको प्रभाव वरपरको संगतिलाई पनि पर्न जान्छ । हामी जस्तो व्यक्तिको सङ्गतमा रहन्छौँ त्यसको प्रभाव अन्त:करणमा पनि पर्न जान्छ । हामी आफ्नो तारिफ गर्ने व्यक्तिप्रति आसक्ति बढाउँछौँ भने निन्दा गर्ने व्यक्तिप्रति द्वेष राख्दछौँ । आज तारिफ गर्नेले भोलि निन्दा गर्न पनि सक्छ र आज निन्दा गर्नेले भोलि तारिफ गर्न पनि सक्छ । उनीहरूको स्वभावलाई हामी नियन्त्रण गर्न सक्दैनौँ । तर हामी उनीहरूको स्वभावबाट आफ्नो अन्त:करणलाई प्रभावित हुन नदिन भने सक्दछौँ । ज्ञानी पुरुषहरूले अरूको व्यवहारले आफ्नो अन्त:करणलाई असर पर्न दिँदैनन् किनकि उनीहरूको
ज्ञानावस्थितचेतसः
- चित्त ज्ञानमा स्थित हुन्छ । साधारण मानिसको चित्त विषयभोगमा हुन्छ भने ज्ञानीहरूको चित्त ज्ञानमा स्थित हुन्छ ।
यज्ञायाचरतःकर्म
, समग्रं प्रविलीयते- त्यस्ता ज्ञानी पुरुषहरूले गरेका सबै कर्महरू यज्ञ स्वरूप हुन्छन् र ब्रह्ममा विलिन हुन पुग्दछन् । यज्ञ भन्नाले वेद पाठ अग्निमा स्वाहा स्वधा मात्र नभएर सृष्टि कल्याणको लागि गरिएका जुनसुकै सत्कर्मलाई बुझ्नुपर्दछ ।अग्नि देवतालाई गरिने स्वाहा स्वधा पनि जरूरी छ । सृष्टि सञ्चालन गर्ने सबै देवीदेवता,अधिष्ठात्री शक्तिहरू पञ्चमहाभूतादिलाई सन्तुलनमा राख्न गरिने देवयज्ञ, पितृयज्ञ, द्रव्ययज्ञ, तपोयज्ञ आदि पनि उत्तिकै जरूरी छन् । सृष्टि कल्याणको लागि गरिने कुनै पनि परोपकारी कर्महरू, घर-परिवार, समाजका लागि गरिने सबै सत्कर्महरू यज्ञमै समाविष्ट हुन्छन् । गृहस्थले गर्ने आफ्नो कर्तव्य धर्म पनि नित्ययज्ञ नै हो । त्यसैले ज्ञानेश्वर महाराज भन्नुहुन्छ-
स्वधर्मु जो बापा, तोचि नित्ययज्ञु जाणपा,
तेथें वर्ततां पापा, संशयो नाहीं ।
स्वधर्म पालन नै नित्ययज्ञ हो र स्वधर्म पालन गर्दा गरिएको सबै दुःखकष्ट पनि यज्ञ नै हुने भएकाले कुनै पाप, दोष लाग्दैन । भगवान् हामीलाई सृष्टिकर्ता देवता, अधिष्ठात्री शक्तिहरू, पञ्चमहाभूतहरूको लागि यज्ञ गर्नुको साथै आफ्नो दृष्टिकोण परिवर्तन गर्न पनि सिकाउँदै हुनुहुन्छ । दैनिक जीवनमा हामी कयौँ वस्तुहरूको उपयोग गर्छौँ । हामीलाई तिनीहरूको पूजा गर्न पनि सिकाइएको छ । दशैंमा सबै शस्त्र-अस्त्र हातहतियारहरू सफा गरेर पूजा गर्ने गर्छौँ । विश्वकर्मामा मेशिनरी औजारहरू, सवारी साधनहरु सबैको पूजा गर्छौँ । त्यस्तैगरी गौमाता, तुलसीमाता, सूर्य, चन्द्र, नदी आदिलाई परमात्मा सम्झेर पूजा गर्छौँ, सबैमा ब्रह्म देख्छौँ र सबैमा श्रद्धाभाव राख्दछौँ ।
4.24
ब्रह्मार्पणं(म्) ब्रह्म हवि:(र्), ब्रह्माग्नौ ब्रह्मणा हुतम् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (4, 24, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=PBO7DjRtYRU', '2026-03-01', 'यज्ञमा आगोमा घिउ हाल्ने काठको सुरो पनि ब्रह्म हो; हवन गर्नयोग्य द्रव्य पदार्थ तिल, जौ, घिउ आदि पनि ब्रह्म हो; ब्रह्मरूप कर्ताद्वारा ब्रह्मरूप अग्निमा आहुति दिइने हवन क्रिया पनि ब्रह्म हो; त्यस ब्रह्मकर्ममा स्थित रहने योगीद्वारा प्राप्‍त गर्न योग्य फल पनि ब्रह्म नै हो ।
अर्पणम् ब्रह्म
- म जे अर्पण गर्छु त्यो ब्रह्म हो ।
हवि:ब्रह्म
- हवन गरिने हवि नै ब्रह्म हो ।
ब्रह्मणा ब्रह्माग्नौ हुतम्
- ब्रह्मरूप कर्ताद्वारा ब्रह्मरुपी अग्निमा आहुती दिने ।
तेन ब्रह्मकर्म समाधिना गन्तव्यम् ब्रह्मैव
- त्यो ब्रह्मकर्म भावनामा स्थित रहने योगीले ब्रह्मत्वकै प्राप्ति गर्दछ । हामी, हाम्रो दृष्टिलाई विकसित गर्दै उपयोग गरिने सबैमा ब्रह्म स्वरूप देख्दै कर्तव्यमा परायण रहेर हाम्रो अन्तिम गन्तव्य (मृत्युको समय)लाई पनि ब्रह्ममय बनाउन सक्छौँ ।
विद्युत उत्पादन गर्दा विभिन्न उपकरणहरू, पानी, कोइला आदिको प्रयोग गरिएको हुन्छ । ती सबैलाई ब्रह्मस्वरूपको रूपमा लिनुपर्दछ । विद्युत उत्पादनमा लागेका प्रविधि र मानवीय संगठनहरू सबै परमात्माकै देन हुन् । हामी परमात्माबाट प्राप्त घरको सरसफाई गर्छौँ । परमात्मालाई सम्झेर भान्सामा खाना बनाउँछौँ । परमात्माबाट प्राप्त भएका चिजहरूलाई परमात्मा नै सम्झेर परमात्मा मै अर्पण गर्दछौँ जसका लागि भगवान्‌ले हामीलाई लायक सम्झेर विश्वासिलो पात्र बनाउनुभएको हुन्छ । आफ्नो घरपरिवार, समाज, देशको उन्नयनका लागि गरिएका हरेक सत्कर्मले परम् ब्रह्म प्राप्ति हुन्छ । ब्रह्म यो सृष्टि, स्थिति र अन्त्य गर्ने शक्ति हो । भगवद्गीता अध्ययनलाई ब्रह्मविद्या भनिन्छ जुन हरेक अध्यायको अन्तिम पुष्पिकामा
ब्रह्म विद्यायां योगशास्त्रे
भनेर उल्लेख गरिएको छ । विभिन्न प्रकृतिका मानिसहरू विभिन्न प्रकारका यज्ञहरू गर्दछन् ।
4.25
दैवमेवापरे यज्ञं(य्ँ), योगिनः(फ्) पर्युपासते ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (4, 25, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=PBO7DjRtYRU', '2026-03-01', 'कोही योगीजनहरू देवताहरूका पूजनरूपी यज्ञकै अनेकप्रकारले अनुष्ठान गर्दछन् भने कोही योगीजनहरू परमब्रह्म परमात्मारूपी अग्निमा अभेद दर्शनरूपी यज्ञद्वारा नै आत्मरूपी यज्ञको हवन गर्ने गर्दछन् ।‌
यज्ञको अग्निको ज्वाला सधैं माथितिर उठ्छ । त्यसैगरी, हाम्रो जीवनमा परोपकारका निमित्त गरिएको कुनै पनि सानो यज्ञिय कर्मले हाम्रो जीवनलाई उर्ध्वगामी बनाउँछ तथा हाम्रो उन्नयन गर्दछ । हामीले भारतिय राष्ट्रिय स्वयम्‌सेवक सङ्घका माधवराव गोलवलकर (श्री गुरुजी) को त्यो चित्र देखेका छौँ, जसमा उहाँ यज्ञवेदीको सामुन्ने बसेर आहुति दिइरहनुभएको छ । वास्तवमा, त्यो उहाँले-
राष्ट्राय स्वाहा, इदं राष्ट्राय न मम
। राष्ट्रकालगि दिएको आफ्नै जीवनको आहुति थियो ।
यस्ता महापुरुषहरूको जीवन यज्ञमय भावले ओतप्रोत हुन्छ । यो राष्ट्रप्रति सर्वस्व समर्पण हो किनभने जबसम्म राष्ट्र बलशाली, समृद्ध र सुरक्षित हुँदैन, तबसम्म हामी पनि सुरक्षित र बलशाली रहन सक्दैनौँ । भारतका स्वातन्त्रता सेनानी श्री विनायक दामोदर सावरकरको एक अत्यन्त सुन्दर मराठी वाक्य छ-
देह देवाकडे जाताना मधे देश लागतो ।
उनी भन्छन्- हामी भगवन्‌लाई प्राप्त गर्न चाहन्छौँ भने बीचमा राष्ट्र आउँछ । राष्ट्रको सेवा नगरी भगवान्‌सम्म पुग्न सकिँदैन । किनकि देशले नै हामीलाई जिउनको लागि सञ्जीवनी दिन्छ । त्यसैले देश सुरक्षित राख्न नितान्त जरुरी छ । अतः भगवद्गीताको माध्यमबाट आफूलाई एक नवीन दृष्टिकोण दिनु अनिवार्य छ किनभने वर्तमानमा सम्पूर्ण विश्वलाई सनातन धर्मको आवश्यकता छ । यस विश्वलाई-
वसुधैव कुटुम्बकम्को
भावनाबाट परम वैभवसम्म लैजाने सामर्थ्य केवल सनातन धर्मालम्वीहरूमा छ । त्यसैले हामी सङ्गठित हुनु आवश्यक छ ।
हामीले आफ्नो जीवनलाई यज्ञमय बनाउँदै राष्ट्रको लागि जिउनु पर्दछ । भगवान् भन्नुहुन्छ-
दैवमेवापरे यज्ञं योगिनः पर्युपासते
अर्थात् केही योगी देव-यज्ञद्वारा नै परमात्माको उपासना गर्छन् । यही हाम्रो सनातन धर्म हो । यसका अतिरिक्त, केही अन्य साधक ब्रह्माग्निमा यज्ञद्वारा नै आत्मारूपी यज्ञको हवन गर्छन् र परब्रह्मसँग एकाकार हुन्छन्- अपरे ब्रम्हाग्नौ यज्ञेन एव यज्ञं उप जुह्वती । आफ्नो जीवनलाई माथि उठाउँन बहिरङ्ग कर्म-यज्ञ र अन्तरङ्ग ज्ञान-यज्ञको समन्वय आवश्यक हुन्छ । यहाँ हामी भगवद्गीताको महायज्ञ गरिरहेकाछौँ, त्यसैले हरेक व्यक्ति आफ्नो क्षमता अनुसार एकता (सङ्घ)को भावनाले समय आहुति गरिरहेका छौँ । यस्तो कार्य सङ्घको भावनाबाटै सम्भव भएको हो । यो कार्य सङ्गठित रूपमा टीम वर्क (TEAM) मार्फत हुन्छ । T E A M को अर्थ हो, Together Everyone Achieves More ।
अनि यो यज्ञको ज्वालाले समाज, राष्ट्र, परिवार माथि उठाउँछ । हरेक परिवार एकै यज्ञकै रुपमा जीवन बिताईरहेको हुन्छ । हरेक व्यक्तिले आफ्नो-आफ्नो कर्तव्य पुरा गरेपछी परीवारको पनि उन्नयन हुन्छ । यसप्रकार यज्ञ भावनाले जीवन जिउदा आफ्ना इन्द्रियहरू माथि संयम राखेर उसको आहुती दिँदै माथि उठ्छन् ।
4.26
श्रोत्रादीनीन्द्रियाण्यन्ये, संयमाग्निषु जुह्वति ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (4, 26, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=PBO7DjRtYRU', '2026-03-01', 'कोही योगीजनहरू श्रोत्रादि समस्त इन्द्रियहरूलाई संयमरूपी अग्निहरूमा हवन गर्ने गर्दछन् भने कोही योगीजनहरू शब्दादि समस्त विषयहरूलाई इन्द्रियरूपी अग्निहरूमा हवन गर्ने गर्दछन् अर्थात् केही कुराको पनि चाहना गर्दैनन् ।
भगवान् विभिन्न यज्ञहरूको उदाहरण दिँदै भन्नुहुन्छ- हे अर्जुन! मानिसहरू आफ्ना-आफ्ना विविध आकाङ्क्षाहरूको पूर्तिका लागि यज्ञ गर्छन् । कोही देवतालाई प्रसन्न पार्ने उद्देश्यले, कोही ब्रह्मप्राप्तिका लागि र कोही आफ्नै भित्र संयमको अग्नि प्रज्वलित गरेर इन्द्रियहरूको वासनाको दमन गर्नका लागि यज्ञ गर्छन् । संयमको अग्निमा आफैलाई रोक्नको लागि पनि शक्ति चाहिन्छ । गलत कुरा गर्नबाट रोक्नु, आँखाले नराम्रो नहेर्नु, कानले नराम्रो नसुन्नु, मुखले नराम्रो नबोल्नु आदि । हाम्रा सबै इन्द्रियहरूको आहार शब्द, स्पर्श, रूप, रस र गन्ध हुन् । कानको विषय शब्द हो; छालाको विषय स्पर्श हो आँखाको विषय रूप हो; जिब्रोको विषय रस र नाकको विषय गन्ध हो । केही साधकहरूले यी पाँच विषयलाई इन्द्रियरूपी अग्निमा हवन गर्छन् । उनीहरूले निश्चित निर्धारण गर्छन्- के हेर्ने के नहेर्ने; के सुन्ने र के नसुन्ने; के बोल्ने र के नबोल्ने; के ग्रहण गर्ने र के नग्रहण गर्ने । यसरी उनीहरूले आफ्ना इन्द्रियहरूमा पूर्ण नियन्त्रण स्थापित गर्छन् । त्यस्ता साधकहरूले श्रोत्र (कान), चक्षु (आँखा), नासिका (नाक), जिह्वा (जिब्रो) र त्वचा (छाला) यी पाँच ज्ञानेन्द्रियलाई संयमरूपी अग्निमा अर्पण गर्छन् । यसरी उनीहरूको संयमाग्निमा इन्द्रियहरूको विषयहरूको हवन हुन्छ ।
बुरा मत देखो, बुरा मत सुनो, बुरा मत बोलो-
यो नै त्यस साधनाको सार हो ।
यसरी हामीलाई व्रतको माध्यमबाट संयममा रहन सिकाईन्छ । कोहि व्यक्तिहरूको बोली कडा हुन्छ । त्यो शब्द कानसम्म आउँछ र त्यही नै अग्निमा हवन हुन्छ, मनसम्म आउन पाउँदैन चाहे त्यो निन्दा होस् या स्तुति । किन यस्तो हुन्छ भने जुन शब्द हाम्रो मनमा पुगेपछि मात्र परिणाम निस्किने हो । हामी आँखालाई मनको उपकरणको रुपमा हेर्छौँ । जसरी हामि चस्मा लगाएर आँखा देख्छौ त्यतिबेला हामीले चस्माले देखेको भन्दैनौँ, आँखाले देखेको भन्छौँ । त्यस्तै आँखाले देख्दैन, मनले देख्छ । कुनै रूप, दृश्य मनमा अङ्कित हुन्छ । जबकानको सट्टा मनले सुन्छ तब निन्दा वा स्तुति मनमा अङ्कित हुन्छ र परिणाम हाम्रो व्यक्तित्वमा देखिन्छ । महात्माहरू मुखले खान्छन् तर मनले खाँदैनन् । आँखाले देखेर पनि मनले देख्दैनन् । परम सन्त वासुदेवानन्द सरस्वती (टेम्बे स्वामीजी महाराज) महान् तपस्वी हुनुहुन्थ्यो । उहाँमाथि भगवान्‌ दत्तात्रेयको विशेष कृपा थियो । उहाँलाई चातुर्मासको समयमा जे भिक्षा प्राप्त हुन्थ्यो, त्यसलाई पानीले शुद्ध गरेर चार भागमा विभाजन गर्नुहुन्थ्यो- एक भाग मन्दिरमा अर्पण, दोस्रो भाग गौमातालाई, तेस्रो भाग चरा-पक्षीलाई र चौथो भाग आफूले ग्रहण गर्नुहुन्थ्यो ।
उहाँ कसैलाई पनि पाउमा ढोग्न दिनुहुन्नथ्यो । जब मानिसहरूले यसको कारण सोध्थे तब उहाँले भन्नुभयो- केही जौका दाना ल्याएर मेरा चरणमा राख । जब उहाँका पाउमा जौका दाना राखियो, तब उहाँका चरणको तापबाट जौ डढ्थे । भनिन्छ कि त्यस्ता तपस्वीहरूको इन्द्रियहरू अग्निजस्तै तेजस्वी हुन्छन् किनभने उनीहरूको मन पूर्णतः निर्लिप्त रहन्छ । सन्त तुकाराम भन्नुहुन्छ-
तुका म्हणे आम्ही झालो अग्निरूप ।
नाही गुण-दोष अंगी येत ॥
जब साधक ज्ञानाग्निमा स्थित हुन्छ, तब गुण-दोषले उसलाई स्पर्श गर्दैनन्; सबै कुरा त्यस ज्ञानाग्निमा भस्म हुन्छ । यसरी सारा कर्मअर्पण गर्ने व्यक्तिमा कुनै गुण-दोष रहदैन र लाग्दैन पनि ।
यसैकारण सनातन धर्ममा मौन-व्रत, उपवास आदि साधनाहरूलाई विशेष महत्त्व दिइएको छ, जसले गर्दा मानिस क्रमशः आफ्ना इन्द्रियहरूलाई वशमा गरेर तिनका विषयहरूबाट आफूलाई सुरक्षित राख्न सक्छ । त्यस्ता साधकहरूले कानले शब्द सुन्छन् तर ती शब्दहरूलाई मनमा नराखि श्रोत्र-यज्ञको अग्निमा भस्म गर्छन् ।
4.27
सर्वाणीन्द्रियकर्माणि, प्राणकर्माणि चापरे ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (4, 27, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=PBO7DjRtYRU', '2026-03-01', 'कोही योगीजनहरू इन्द्रियहरूका समस्त क्रियाहरूलाई र प्राणका समस्त क्रियाहरूलाई ज्ञानद्वारा प्रज्वलित आत्मसंयमयोग रूपी (समाधियोगरूपी) अग्निहरूमा हवन गर्ने गर्दछन् ।
जसको जस्तो क्षमता र रुचि छ त्यही अनुसारको यज्ञकर्ममा उसको जीवन प्रवृत्त हुन्छ । कसैले इन्द्रियहरूको सारा कर्म (आखाले देख्नु, कानले सुन्नु ) कर्मेंद्रिय (हात खुट्टाको कर्म) र प्राण कर्माणी (श्वास लिनु र छोड्नु) ज्ञानले प्रकाशित आत्मसंयमको अग्निमा अर्पण गर्दछन् । त्यस अग्निले इन्द्रियहरूलाई अन्तरमुख गराउँदै त्यसैमा भस्म गरिदिन्छन् । स्वतन्त्रता सेनानी सावरकरको एक गीत छ -
हे मातृभूमि! तुज मन वाहियले,
वक्तृत्व-वाङ्मय-विभव तुज अर्पियले ।
तुजसाठी अर्पिली नवकविता रसाला,
लेखा प्रति विषय अनन्य तुज झाला ॥
मेरो जुन-जुन क्षमता छ, बोल्ने क्षमता, काव्य लेख्ने क्षमताका साथै मेरो मन पनि मैले मेरो मातृभूमिलाई अर्पण गर्दछु । यहाँ उनको दृष्टिकोणमा मातृभूमि नै परब्रह्म परमात्मा हुन् । मातृभूमिको लागि सबैथोक गरेपछि मातृभूमि नै परब्रह्म, परमात्मा बन्न जान्छ ।
उहाँ भन्नुहुन्छ- मातृभूमिको स्वतन्त्रता लागि म मेरो सबै कला अर्पण गर्दछु । वीरहरूले यसप्रकार सबै क्षमता/प्रतिभा एकाग्र गर्दछन्, संयमित भई मातृभूमिलाई अर्पण गर्दछन् । भगवान् भन्नुहुन्छ- यस्तै अनेक यज्ञ हामी गर्न सक्छौँ । आफ्नो क्षमता अनुसार कसैसँग द्रव्य छ, कसैसँग भौतिक सम्पत्ति छ, कसैसँग समय छ, कसैसँग बल छ उनीहरू जोसँग जे छ त्यहि अर्पण गरेर यज्ञ गर्दछन् । यो गीताको महायज्ञ हो । यसमा हामी जोसँग जे क्षमता छ त्यही प्रदान गरेका छौँ । जस्तै कसैले प्राविधिकको, कसैले प्रशिक्षकको कसैले विवेचनको, अरु पनि धेरै सेवा प्रदान गरेका छौँ र यो परिवार चलेको छ अर्थात् यो ज्ञानयज्ञ सम्पन्न हुनजान्छ ।
4.28
द्रव्ययज्ञास्तपोयज्ञा, योगयज्ञास्तथापरे ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (4, 28, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=PBO7DjRtYRU', '2026-03-01', 'कोही योजीजनहरू द्रव्यमय यज्ञ गर्ने गर्दछन्, भने कोही योगीजनहरू कठिन नियमका साथ तपस्यारूपी यज्ञ गर्ने गर्दछन् । त्यस्तै कोही अहिंसादि तीक्ष्ण व्रतहरूले युक्त यत्नशील योगीजनहरू स्वाध्यायरूपी ज्ञानयज्ञ गर्ने गर्दछन् ।
भगवान्‌ले १८औँ अध्यायमा सात्त्विक, राजसिक र तामसिक यज्ञ हुन्छ भन्ने कुरा बताउनुभएको छ, जसमध्ये यहाँ सात्त्विक यज्ञको कुरा गर्दै द्रव्य-यज्ञबारे भन्नुहुन्छ- केही मानिसहरू आफ्नो द्रव्य, आफ्नो भौतिक सम्पत्ति, आफ्नो समृद्धिको केही न केही अंश- मैले सृष्टिबाट लिएको छु र सृष्टिलाई नै दिनुपर्छ भन्ने भावनाले यज्ञमा अर्पण गर्छन्, किनकि
त्वदीयं वस्तु गोविन्द तुभ्यमेव समर्पये ।
तपाईँको चिज तपाईँलाई नै अर्पण गर्छु । यही भावनाले अर्पण गर्नु नै जीवनको ठुलो विशेषता हो । जब हामी एउटा बीऊ छर्छौँ त्यसबाट उम्रने बिरुवाले हजारौँ दानाहरू फलाउँछ । त्यो एउटा दाना पनि यज्ञमा यो तपाईँको हो भन्ने भावनाले अर्पण गर । आफूले दिँदा -
इदम् न मम
(यो मेरो होइन) भन्ने भावनाले हवन गर्दा मात्र यज्ञ हुन्छ । जस्तै- राष्ट्राय स्वाहा! इदम राष्ट्राय इदम न मम- यो मेरो होइन, राष्ट्को हो । त्यसैले भगवान् भन्नुहुन्छ- अपर द्रव्ययज्ञ, तपो-यज्ञ केही मानिसहरू आफ्नो तपको यज्ञ गर्छन् । उनीहरूको तपस्या र तेजस्विताका कारण सृष्टि पनि तेजोमय हुन्छ । केही मानिसहरू योग-यज्ञ योग रूपी यज्ञ गर्छन् - अष्टाङ्गयोग । केही मानिसहरू संशित व्रता- अर्थात् अत्यन्त कठिन व्रतहरू आफ्नो जीवनमा लिन्छन् र ती कठिन व्रत लिएर त्यसकै यज्ञ गर्छन्, आफ्नो क्षमता बढाउँछन् ।
भगवान् भन्नुहुन्छ- यसप्रकारले जो अध्ययनशील पुरुष हुन्छन्, उनीहरू स्वाध्याय ज्ञानको यज्ञ गर्छन् । हामीले गीता पाठ गरिरहेका छौँ, यो हाम्रो स्वाध्याय हो । ज्ञानयज्ञमा वाचन, अध्ययन र स्वाध्याय पर्दछन् । वाचन- हामी दिनहुँ समाचार, पत्र, पुस्तक र ह्वाट्सएप वा अन्य सामाजिक सञ्जालमा धेरै कुराहरू पढ्छौँ, जसमा हाम्रो स्थिरता हुँदैन । ती धेरै भोलाटाइल (अस्थायी) हुन्छ ।
स्वाध्याय
- मनको परिष्कार, आफ्नो अन्तरङ्गको उन्नयन र आफ्नो जीवनलाई ऊर्ध्वगामी बनाउनका लागि गरिन्छ । स्वाध्यायमा स्थिरता हुन्छ । आफ्नो अन्तःकरण शुद्ध गर्नका लागि स्वाध्याय गरिन्छ ।
अध्ययन
- हामीले स्कूल, कलेजहरूबाट जुन योग्यता हाँसिल गर्‍यौँ, यो अध्ययन हाम्रो जीविकोपार्जनका लागि हो, तर जीवनका लागि भने स्वाध्याय गर्नुपर्छ ।
भगवान्‌ले १०औँ अध्यायमा
यज्ञानां जपयज्ञोऽस्मि
- यज्ञहरूमा म जप यज्ञ हुँ भन्नुभएकोछ । भगवान्‌को नाम जप गर्नु पनि यहाँ स्वाध्यायभित्रै पर्छ । जपयज्ञ र जपका कारण हामी त्यो परमात्मासँग एकाकार हुन्छौँ ।
स्वाध्यायादिष्टदेवतासंप्रयोगः
- निरन्तर जप गर्नाले ती देवताको दर्शन हुन्छ । भगवान् यी सबै कुराहरूलाई यज्ञको संकल्पनामा समाहित गर्नुहुन्छ र हामीलाई एउटा विलक्षण र विशाल दृष्टिकोण प्रदान गर्नुहुन्छ ।
हामी जुन श्वास-प्रश्वास गर्छौँ, योगीहरू त्यसको पनि यज्ञ गर्छन् । भित्रलिएको श्वास - प्राणको हाम्रो भित्रको वायुमा त्यसको हवन गर्नु । भित्रको वायु बाहिर छोडेको श्वास- अपानको पनि प्राणमा हवन गर्नु । विचमा रोकिनु अर्थात् कुम्भक गर्नु । विचमा अन्तःकुम्भक र बाह्यकुम्भक गर्नु । श्वासलाई रोक्नु, यस प्रकारले श्वाससँग स्वयम्‌लाई एकाग्र गर्नु, किनकि यसका कारण हामी वायुसँग आफ्नो मनलाई जोड्छौँ । वायु विशाल र व्यापक हुन्छ र जब मन वायुसँग जोडिन्छ तब मन पनि व्यापक हुन्छ । यसै भावनाले भगवान् विभिन्न यज्ञहरूको बारेमा बताउनुहुन्छ ।
आफ्नो द्रव्यको सदुपयोग उत्तम कार्यहरूमा गर्नु नै द्रव्ययज्ञ हो । अन्य यज्ञहरूमा तपयज्ञ, योगयज्ञ, व्रतयज्ञ पर्दछन् । तपयज्ञ- केही मानिसहरूले तपको यज्ञ गर्छन्, यसलाई तपोयज्ञ भनिन्छ । तपस्याद्वारा उनीहरूले आफ्नो जीवनलाई तपोमय बनाउँछन् र आफ्नो तेजले समाजलाई पनि प्रेरित गर्छन् । योगयज्ञ- केही साधकहरूले योगरूपी यज्ञ गर्छन्, जस्तै अष्टाङ्गयोग, हठयोग आदि । व्रतयज्ञ- केही मानिसहरूले आफ्नो जीवनमा कठोर व्रत धारण गर्छन् र त्यसैको यज्ञ गर्छन् । शास्त्रहरूमा अनेक व्रतहरूको विधान छ । व्रत धारण गर्दा जीवन तपोमय हुन्छ, मन संयम र दृढ हुन्छ ।
4.29
अपाने जुह्वति प्राणं(म्), प्राणेऽपानं(न्) तथापरे ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (4, 29, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=PBO7DjRtYRU', '2026-03-01', 'कोही योगीजनहरू अपानवायुमा प्राणवायुलाई हवन गर्ने गर्दछन् भने कोही योगीजनहरूले प्राणवायुमा अपानवायुलाई हवन गर्ने गर्दछन् ।
अपरे अपाने प्राणं जुह्वति-
केही मानिसहरू यस प्रकार श्वास-प्रश्वास प्राणायामको यज्ञ गर्छन् ।
अपान वायु
- जुन वायु हाम्रो शरीरभित्र छ त्यो वायुमा प्राणं जुह्वति अर्थात् जुन श्वास लिन्छौँ ।
प्राण
शब्दको अर्थ केवल श्वास मात्र होइन, प्राण पनि पञ्चप्राण कहलिन्छन्: प्राण, अपान, व्यान, समान र उदान र यिनका स्थान पनि फरक-फरक छन् । ती मानिसहरू अपानमा प्राणको हवन गर्छन् र प्राणमा अपानको हवन गर्छन् ।
4.30
अपरे नियताहाराः(फ्), प्राणान्प्राणेषु जुह्वति ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (4, 30, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=PBO7DjRtYRU', '2026-03-01', 'त्यस्तै कोही नियमित आहार गर्ने प्राणायाम परायण पुरुषहरू प्राण र अपानको गतिलाई रोकेर (कुम्भक गरेर) प्राणहरूलाई प्राणहरूमा नै हवन गर्ने गर्दछन् । यी सबै प्रकारका साधकहरूले यज्ञहरूद्वारा पापहरूलाई नाश गर्ने गर्दछन् र यज्ञको महत्त्वलाई जान्दछन् ।
अपरे नियताहाराः
- केही यस्ता अन्य मानिसहरू हुन्छन् जो नियमित आहार लिन्छन् । यहाँ ''आहार'' को अर्थ केवल भोजन मात्र होइन । आद्य शङ्कराचार्यले भन्नुभएको छ कि आँखाको पनि आहार हुन्छ, कानको पनि आहार हुन्छ । जुन इन्द्रिय (ज्ञानेन्द्रीय) को जुन विषय छ, त्यो नै त्यसको आहार हो । आँखाको आहार रूप हो, कानको आहार शब्द हो, नासिकाको गन्ध हो । तसर्थ यी पञ्चेन्द्रियका पाँच आहारलाई- कति हेर्ने, कति सुन्ने, कति खाने भनी नियत गर्नु अर्थात् नियन्त्रण गर्नुपर्दछ ।
प्राणापानगती रुद्ध्वा प्राणायाम परायणाः
- यसरी नियमित र नियन्त्रित आहार लिने, प्राणायाममा परायण रहने पुरुषहरू प्राण र अपान दुवैको गति रोक्छन् र
प्राणान् प्राणेषु जुह्वति
- प्राणमै प्राणको हवन गर्छन् । यस्ता हवन वा यज्ञ गर्नेहरू
यज्ञविदो यज्ञक्षपितकल्मषाः
हुन् । किनकि यज्ञको माध्यमबाट, यज्ञको भावनाबाट क्षपित अर्थात् पापहरूको वा कल्मष अर्थात् आफ्ना दोषहरूको नाश हुन्छ । यस भावनाले जीवन जिउनेहरूको दोष नाश हुन्छ ।
4.31
यज्ञशिष्टामृतभुजो, यान्ति ब्रह्म सनातनम् ।', 'ne');
INSERT INTO learngeeta_vivechans (chapter, sloka_number, speaker, video_url, date_iso, meaning_nepali, lang) VALUES (4, 31, 'SAU VANDANA WARNEKAR JI', 'https://www.youtube.com/watch?v=PBO7DjRtYRU', '2026-03-01', 'हे कुरू श्रेष्ठ अर्जुन! यज्ञबाट बचेको अमृतलाई सेवन गर्ने योगीजनले सनातन परब्रह्म परमात्मालाई प्राप्‍त गर्दछन् । तर, यज्ञ नगर्ने पुरुषहरूका लागि त यो मनुष्यलोक पनि सुखदायक छैन भने परलोक झन् कसरी सुखदायक हुनसक्ला?
यज्ञबाट बचेको अमृत (यज्ञ-शिष्टामृत) को अनुभव लिनेहरू योगी हुन्छन् । अरूलाई दिएपछि मात्र आफूले लिने चलन हाम्रो संस्कृतिले सिकाएको छ । भोक लागेपछि खाना खानु हाम्रो प्रकृति हो तर आफूसँग भएको खाना अरूसँग बाँडेर खानु संस्कृति हो । अरूबाट खोसेर खानु विकृति हो । त्यसैले हाम्रो संस्कृति भन्छ- यज्ञ गरिसकेपछि जे बाँकी रहन्छ, त्यसलाई अमृत समान मानेर ग्रहण गर्नेहरू नै साँचो अर्थमा परमात्मा (सनातन ब्रह्म) सम्म पुग्दछन् । तर जसले आफ्नो जीवनमा यज्ञ गर्दैनन्, परोपकार वा सत्कर्म गर्दैनन्, उनीहरूले न यो लोक र न परलोकमा शान्ति पाउँछन् । भोगविलास र तृष्णामा डुबेको मन योगमा टिक्दैन । जबसम्म मन अतृप्त रहन्छ, तबसम्म मानिस अशान्त नै रहन्छ ।
भगवान्‌ले गीताको तेस्रो अध्यायमा भन्नुभएको छ कि जसले सृष्टिका साधनहरू (हावा, पानी, प्रकाश) को उपभोग त गर्छ तर बदलामा केही दिँदैन, त्यो चोर हो । हामीले प्रयोग गर्ने वायु, पानी, बाटो, पुस्तक वा अस्पताल हामीले बनाएका होइनौँ । यो अरुको श्रम र तपस्याको फल हो । त्यसैले केही अर्पण गर्ने भावनाबाट मात्र हामी ऋणबाट मुक्त हुन सक्छौँ ।
मनुष्यका चार प्रकारका ऋण हुन्छ:
१. ऋषि ऋण:
जसले आफ्नो बुद्धि र प्रज्ञाले हाम्रा लागि वेद, पुराण र ज्ञानका ग्रन्थहरू रचना गरे ।
२. देव ऋण:
प्रकृति सञ्चालन गर्ने शक्तिहरू - वायु, सूर्य, जल (वरुण देवता) आदि । जसबाट हाम्रो अस्तित्व सम्भव छ ।
३. पितृ ऋण:
हाम्रा आमा-बुबा र पुर्खाहरू, जसले कष्ट सहेर हामीलाई हुर्काए ।
४. समाज ऋण:
जुन समाजमा हामी बस्छौँ र जसका सुविधाहरू उपयोग गर्छौँ ।
यज्ञ कति ठुलो छ भन्ने कुरा प्रदर्शनले होइन, नियतले निर्धारण गर्छ । महाभारतको एउटा प्रसङ्ग छ: युधिष्ठिरको राजसूय यज्ञ सकिएपछि एउटा न्याउरी मुसो त्यहाँ आयो, जसको आधा शरीर सुनौलो थियो । ऊ यज्ञको जुठोमा यताउता पल्टिन थाल्यो तर उसको शरीर सुनको भएन । ऊ हाँस्यो र भन्यो, “यो भन्दा त त्यो गरिब ब्राह्मणको यज्ञ नै श्रेष्ठ थियो” । उसले कथा सुनायो- एक पटक अनिकालको समयमा एक गरिब ब्राह्मण परिवार १० दिनदेखि भोका थिए । कतैबाट थोरै सातु प्राप्त भएको थियो । जब खाने समय भयो, तब एउटा भोको अतिथि ढोकामा आए । ती ब्राह्मण, उनकी पत्नी र छोराछोरीले समेत आफ्नो भागको सबै सातु पालैपालो अतिथिलाई दिएर तृप्त बनाए र आफू भोकै सुते । म त्यहीँ थिएँ, ती ब्राह्मणले हात धुँदा खसेको जुठोले मेरो शरीरमा लाग्दा मेरो आधा शरीर सुनको भएको थियो । यति ठुलो राजसूय यज्ञमा पनि मेरो बाँकी शरीर सुनको हुन सकेन, किनकि यहाँ दान त छ तर त्यो त्याग र भावना छैन । भगवान्‌ले हाम्रो बाहिरी तडकभडक होइन, भित्री भाव हेर्नुहुन्छ । अर्पण गर्ने भावना नै वास्तविक यज्ञ हो ।
प्रश्नोत्तर
प्रश्नकर्ताः-
देवन्ती दिदी
प्रश्नः-
प्राणायाम गर्दा मनमा कस्तो भावना राख्ने?
उत्तरः-
अपाने जुह्वति प्राणम्- जुह्वति को अर्थ हो अर्पण गर्नु वा आहुति दिनु । हाम्रो शरीरमा पञ्चप्राण हुन्छन् । प्राणको अर्थ केवल सास फाल्ने मात्र होइन । प्राणायाम गर्दा हामी पूरक (सास तान्ने) र रेचक (सास छोड्ने) गर्छौँ । योगीहरूले अपान वायुमा प्राणको र प्राण वायुमा अपानको हवन गर्छन् । सजिलो भाषामा भन्दा, सास लिने र छोड्ने प्रक्रियामा मन एकाग्र गर्नु नै प्राणायाम हो । केहीले कुम्भक (सास रोक्ने) गर्छन् । भगवान्‌ले गीताका ७०० श्लोकहरूमा ‘गाग्रोमा सागर’ भरेर अर्जुनका माध्यमबाट हामी सबैलाई यो ज्ञान दिनुभएको छ । यदि तपाईँले कुनै भावना नराखी केवल गन्ती गरेर गर्नुभयो भने पनि फोक्सोको क्षमता बढ्छ र शरीर शुद्ध हुन्छ । तर यदि तपाईँ मन्त्रका साथ गर्नुहुन्छ (जस्तै: श्री राम जय राम जय जय राम), तब मन भगवान्‌मा लाग्छ र यसको लाभ सयौँ गुणा बढेर जान्छ । यसले चित्त शुद्ध हुन्छ, डर र निराशा हराउँछ ।
प्रश्नकर्ताः-
गीता दिदी
प्रश्नः-
म पनि मन्त्रका साथ प्राणायाम गर्छु, तर आज तपाईँले जुन ‘श्री राम जय राम जय जय राम’ को विधि बताउनुभयो, त्यसले मन अझ शान्त हुने अनुभव भयो ।
उत्तरः-
हो, यसले हरेक कोषसम्म अक्सिजन पुग्छ र नवजीवन मिल्छ । सूर्य भेदन (दायाँबाट) ले ऊर्जा दिन्छ र चन्द्र भेदन (बायाँबाट) ले शीतलता दिन्छ । यो ठूलो शास्त्र हो ।
प्रश्नकर्ताः-
सुनील दाजु
प्रश्नः-
तेस्रो, चौथो र पाँचौँ अध्यायको नाम कर्मयोग, ज्ञानकर्मसंन्यासयोग र कर्मसंन्यासयोग भनिएको छ । १८औँ अध्यायमा पनि संन्यास शब्द छ । यी सबैको अर्थ एउटै हो कि फरक छ?
उत्तरः-
अर्थ भावको हिसाबले गहिरो छ । ‘संन्यास’ को अर्थ हो- सम्यक् न्यास । न्यास भनेको छोड्नु वा त्याग गर्नु । के छोड्ने र के नछोड्ने भन्ने कुरा सोचेर त्याग गर्नु नै संन्यास हो । ज्ञानेश्वर महाराज भन्नुहुन्छ- जसले म र मेरो भन्ने भाव बिर्सियो, उही वास्तविक संन्यासी हो । गेरुवा वस्त्र लगाउनु मात्र संन्यास होइन ।
कर्मयोग भनेको कर्मलाई परमात्मामा जोड्नु हो । ज्ञानकर्मसंन्यासयोगमा ज्ञानको प्रकाशमा कुन कर्म त्याज्य छ र कुन यज्ञस्वरूप छ भन्ने बुझिन्छ । पाँचौँ अध्याय (कर्मसंन्यास) मा पुग्दा साधक यस्तो अवस्थामा पुग्छ जहाँ उसलाई लाग्छ कि- मैले केही गरिरहेको छैन, सबै इन्द्रियहरूले आफ्नो काम गरिरहेका छन् । यहाँ कर्तापन को अभाव हुन्छ । जसरी कमलको पात पानीमा भएर पनि भिज्दैन, त्यसरी नै संन्यासी संसारमा भएर पनि निर्लिप्त रहन्छ ।
यो विवेचन पढेर तपाईँलाई अवश्य पनि राम्रो लाग्यो होला भन्ने हामीलाई विश्वास लागेको छ । कृपया तल दिएको लिङ्क प्रयोग गरी हामीलाई आफ्नो प्रतिक्रियाहरू दिनुहोला ।', 'ne');